-- TOC entry 3937 (class 1255 OID 2969108)
-- Name: get_admission_analysis(date); Type: FUNCTION; Schema: adt; Owner: -
--

CREATE FUNCTION adt.get_admission_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, admission_id integer, admission_date date, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_medico_legal character, is_high_risk character)
    LANGUAGE plpgsql
    AS $$ 
begin
	return QUERY select	a.unit_id,
		a.organization_id,
		a.patient_id,
		a.admission_id,
       	ad.doa::date as admission_date,
       	a.visit_type_id,
       	a.speciality_id,
       	a.doctor_id,
      	apm.payment_entitlement_id,
      	extract(year from age(pr.dob))::integer as patient_age,
       	pr.gender_id,
       	ad.is_medico_legal,
       	ad.is_high_risk
from adt.t_admission a
join adt.t_admission_details ad using (admission_id)
join adt.t_admission_patient_mapping apm on (a.patient_id = apm.admission_patient_id)
join patient.t_patient_registration pr using(patient_id)
where	((a.updated_date::date >= p_date ::date and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date and a.created_date::date < current_date))
group by a.unit_id,
	     a.organization_id,
	     a.patient_id,
	    a.admission_id,
	   	ad.doa,
	  	apm.payment_entitlement_id,
	 	pr.dob,
		pr.gender_id,
		ad.is_medico_legal,
		ad.is_high_risk;
end;
$$;


