CREATE FUNCTION adt.get_discharge_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, admission_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, discharge_type_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_medico_legal character, is_high_risk character)
    LANGUAGE plpgsql
    AS $$ 
begin
	return QUERY select	d.unit_id,
		d.organization_id,
		a.patient_id,
		d.admission_id,
       	d.visit_type_id,
       	a.speciality_id,
       	d.doctor_id,
       	d.discharge_type_id,
      	apm.payment_entitlement_id,
      	extract(year from age(pr.dob))::integer as patient_age,
       	pr.gender_id,
       	ad.is_medico_legal,
       	ad.is_high_risk
from adt.t_admission a
join adt.t_discharge d using (admission_id)
join adt.t_admission_details ad using (admission_id)
join adt.t_admission_patient_mapping apm on (a.patient_id = apm.admission_patient_id)
join patient.t_patient_registration pr using(patient_id)
where	((d.updated_date::date >= p_date ::date and d.updated_date::date < current_date)
		or (d.created_date::date >= p_date::date and d.created_date::date < current_date))
group by d.unit_id,
	     d.organization_id,
	     a.patient_id,
	     d.admission_id,
	   	 ad.doa,
	   	 d.visit_type_id,
	  	 apm.payment_entitlement_id,
	  	 a.speciality_id,
	 	 pr.dob,
	 	 d.doctor_id,
		 pr.gender_id,
		 ad.is_medico_legal,
		 d.discharge_type_id,
		 ad.is_high_risk;
end;
$$;


