CREATE FUNCTION billing.package_consumption_item_me_cancel_log(pkg_id integer, pat_id integer, itm_id integer, v_t_id integer, visit_id integer, cr_by integer, cr_date timestamp without time zone, is_o_c integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
begin
insert
	into
		billing.t_package_consumption_service_detail_log(pacakge_consumption_service_detail_id,
		package_quantity,
		balance_package_quantity,
		is_ordered_cancelled,
		created_by,
		created_date) (
			select pcsd.pacakge_consumption_service_detail_id,
			pcsd.package_quantity,
			pcsd.balance_package_quantity,
			is_o_c,
			cr_by,
			cr_date
		from
			billing.t_package_consumption_master pcm
		inner join billing.t_package_consumption_service_detail pcsd on
			pcsd.package_consumption_master_id = pcm.package_consumption_master_id
		where
			pcm.package_id = pkg_id
			and pcm.patient_id = pat_id
			and pcm.visit_type = v_t_id
			and pcsd.item_id = itm_id);return 1;
end;
$$;


