--
-- TOC entry 3926 (class 1255 OID 2969116)
-- Name: insert_schedule_logs(); Type: FUNCTION; Schema: doctor; Owner: -
--

CREATE FUNCTION doctor.insert_schedule_logs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	
	IF NEW.add_remove=0 then --add schedule
     
	insert into	public.t_schedule_logs (table_name,	status,	date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)
	values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'INSERT','HIS',0,new.org_id);

    END IF;
   
    IF NEW.add_remove=1 then --remove/inactive schedule
    
	insert into	public.t_schedule_logs (table_name,	status,	date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)
	values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'DELETE','HIS',0,new.org_id);

    END IF;
   
    IF NEW.add_remove=2 then --activate schedule
    
	insert into	public.t_schedule_logs (table_name,	status,	date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)
	values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'ACTIVE','HIS',0,new.org_id);

    END IF;
   
    RETURN NEW;
END;
$$;


--
-- TOC entry 3939 (class 1255 OID 3758465)
-- Name: duplicate_interface_value(); Type: FUNCTION; Schema: lab; Owner: -
--

CREATE FUNCTION lab.duplicate_interface_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	
	
	update lab.t_lab_machine_interface  set status  = 'I' 
			where unit_id  = new.unit_id
			and organisation_id = new.organisation_id 
			and sample_no  = new.sample_no 
			and parameter_name = new.parameter_name 
			and machine_name = new.machine_name ;
			
    RETURN NEW;
END;
$$;


--
-- TOC entry 3944 (class 1255 OID 2969117)
-- Name: generate_sample_no(text, text, integer); Type: FUNCTION; Schema: lab; Owner: -
--

CREATE FUNCTION lab.generate_sample_no(sample_no text, sample_prefix text, width integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  sample_no_width integer;
  sample_prfix text;
  add_zero text := '';
BEGIN
sample_prfix = sample_prefix;
 sample_no_width = character_length(sample_no);
 IF (width - sample_no_width) > 0 THEN
  FOR i IN 1..(width - sample_no_width) LOOP
   add_zero := add_zero||'0';
  END LOOP;
  RETURN  sample_prfix||add_zero||sample_no;
 END IF;
 RETURN sample_prfix||sample_no;

END;
$$;


