    LANGUAGE plpgsql
    AS $$
DECLARE passed bigint;
BEGIN
       Select  sum(t_paymentmode.amount) into passed				
			FROM pharmacy.t_sale t_sale
			JOIN pharmacy.t_sale_payment_mode  t_paymentmode on t_sale.id = t_paymentmode.sale_id
			join public.m_payment_mode_master pm  on pm.payment_mode_id = t_paymentmode.payment_mode_id
		Where t_sale.id = Pid and t_paymentmode.payment_mode_id = 1;

        RETURN passed;
END;
$$;


