--
-- TOC entry 3953 (class 1255 OID 2969129)
-- Name: t_sale(); Type: FUNCTION; Schema: pharmacy; Owner: -
--

CREATE FUNCTION pharmacy.t_sale() RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, category character varying, generic_id integer, stock_count integer, is_deleted boolean, total_count integer)
    LANGUAGE plpgsql
    AS $$ declare
begin
	 Select ss.added_date::date as stock_date,
					ss.unit_id,
					ss.organization_id as hospital_id,
					ss.store_id,
					g.product_category_id,
					p.category,
					i.generic_id,
					SUM(  ss.available_qty):: integer as stock_count,
					ss.is_deleted,
					count(ss.id) as total_count 
			from inventory.t_store_stock ss 
	join inventory.t_batch b on b.id = ss.batch_id
	join public.m_item i on i.id = b.item_id
	join public.m_generic g on g.id = i.generic_id 
	join public.m_product_category p on p.id = g.product_category_id
		WHERE  ss. added_date IN (SELECT ss.added_date
                                 FROM inventory.t_store_stock ss
                                                	WHERE(ss.updated_date::DATE>='2019-01-01' OR ss.added_date::DATE>='2019-12-21')
                                                		  AND ss.is_deleted = False)
                    		                        AND ss.is_deleted = false
    	GROUP BY 
		ss.unit_id,
		ss.organization_id,
		ss.store_id,
		g.product_category_id,
		p.category,
		i.generic_id,
		ss.is_deleted,
		cast(ss.added_date as date)
	order by cast(ss.added_date as date) asc;
	
end;

$$;


--
-- TOC entry 3954 (class 1255 OID 2969130)
-- Name: t_sale(date); Type: FUNCTION; Schema: pharmacy; Owner: -
--

CREATE FUNCTION pharmacy.t_sale(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, registration_date date, city_id integer, state_id integer, country_id integer, gender_id integer, patient_category_id integer, patient_id integer, age integer, patient_statistics integer, status character)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		pd.unit_id,
		pd.organization_id,
		pr.created_date :: date registration_date ,
		pd.city_id,
		pd.state_id,
		pd.country_id,
		pr.gender_id ,
		pr.patient_category_id,
		pr.patient_id,
		extract (year
	from
		age(pr.dob)):: integer as age,
		count(distinct coalesce( pr.patient_id, 0)) :: integer as patient_statistics,
		pr.status
	from
		patient.t_patient_registration pr
	join patient.t_patient_details pd on
		pd.patient_id = pr.patient_id
	where
		((pr.updated_date::date >= p_date
		and pr.updated_date::date < current_date)
		or (pr.created_date::date >= p_date
		and pr.created_date::date < current_date))
		and pr.registration_type_id = 1
	group by
		pr.created_date,
		pd.unit_id,
		pd.organization_id,
		pd.city_id,
		pd.state_id,
		pd.country_id,
		pr.patient_id,
		pr.patient_category_id,
		pr.gender_id,
		pr.status ,
		age;
end;

$$;


--
-- TOC entry 3957 (class 1255 OID 2969131)
-- Name: get_accident_emergency_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_accident_emergency_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, is_mlc character, triage_level_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return query select
		a.unit_id::integer,
		a.organization_id::integer,
		ad.is_medico_legal::char as is_mlc,
		ad.triage_category_id::integer as triage_level_id,
		(case
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'N'
				and is_icu = 'N') then 1
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_icu = 'Y') then 2
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and tr.transfer_type_id = 2 then 3
			else 2
		end)::integer as transfer_from_er_id,
		generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,
		count(a.admission_id) as count,
		(case
			when a.status = 'A' then false::bool
			else true::bool
		end) as is_deleted
	from
		adt.t_admission a
	inner join adt.t_admission_details ad
			using(admission_id)
	inner join adt.t_transfer t
			using (admission_id)
	inner join adt.t_transfer_request tr
			using (admission_id)
	where
		((a.updated_date::date >= p_date::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
	group by
		a.unit_id,
		a.organization_id,
		ad.is_medico_legal,
		ad.triage_category_id,
		transfer_from_er_id,
		date,
		a.status;
end;

$$;


--
-- TOC entry 3958 (class 1255 OID 2969132)
-- Name: get_accident_er_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_accident_er_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, is_medico_legal character, triage_category_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	Return query 
	select s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa as date,s.count,s.is_deleted
	from (select ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,1 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),
		case
			when ta.status ilike 'A' then false
			else true
		end as is_deleted, 
		ta.created_date,
		ta.updated_date
	from adt.t_admission ta
	join adt.t_admission_details tad on ta.admission_id=tad.admission_id
	where ta.visit_type_id=2 
	and ta.admission_id in (select admission_id from adt.t_admission_note where visit_type_id=4)
	group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,ta.status,tad.doa,ta.created_date,ta.updated_date
	union
	select ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,2 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),
		case
			when ta.status ilike 'A' then false
			else true
		end as is_deleted
		,ta.created_date,
		ta.updated_date 
	from adt.t_admission ta
	join adt.t_admission_details tad on ta.admission_id=tad.admission_id
	where ta.visit_type_id=2
	and ta.admission_id in (select admission_id from adt.t_transfer where transfer_status_id=10)
	group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,tad.doa,ta.status,ta.created_date,ta.updated_date) s
	where 
	   (s.updated_date::date >= p_date::date and s.updated_date::date < current_date)
	or 
	   (s.created_date::date >= p_date::date and s.created_date::date < current_date)
	group by 
	s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa,s.count,s.is_deleted;
end;

$$;


--
-- TOC entry 3959 (class 1255 OID 2969133)
-- Name: get_admission_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_admission_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, age_group_id integer, gender_id integer, is_mlc character, is_high_risk character, count bigint, admission_date date, is_vip character, is_planned character, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		a.unit_id ::integer,
		a.organization_id ::integer,
		ad.admission_type_id ::integer,
		a.visit_type_id ::integer,
		a.speciality_id ::integer,
		a.doctor_id ::integer,
		apm.payment_entitlement_id ::integer,
		extract(year
	from
		age(pr.dob))::integer as age_group_id,
		pr.gender_id ::integer,
		ad.is_medico_legal,
		ad.is_high_risk,
		count(*),
		ad.doa::date as admission_date,
		pr.is_vip,
		(case
			when a.admission_id in (
				select admission_id
			from
				adt.t_admission_note) then 'Y'::char
			else 'N'::char
		end) as is_planned,
		(case
			when a.status = 'A' then false::bool
			else true::bool
		end) as is_deleted
	from
		adt.t_admission a
	join adt.t_admission_details ad on
		(a.admission_id = ad.admission_id)
	join opd.t_patient_sponsor_details apm on
		(a.admission_id = apm.admission_id)
	join patient.t_patient_registration pr on
		(pr.patient_id = a.patient_id)
	left join adt.t_admission_note an on
		(a.admission_id = an.admission_id)
	where
		ad.doa::date >= p_date ::date
	group by
		a.unit_id,
		a.organization_id,
		a.admission_id,
		ad.admission_type_id,
		ad.doa,
		a.visit_type_id,
		a.speciality_id,
		a.doctor_id,
		apm.payment_entitlement_id,
		pr.dob,
		pr.gender_id,
		ad.is_medico_legal,
		ad.is_high_risk,
		pr.is_vip;
end;

$$;


--
-- TOC entry 3960 (class 1255 OID 2969134)
-- Name: get_appointment_cancellation(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_appointment_cancellation(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, request_type_code character, date date, count bigint, appointment_status_code character varying, status character)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY 
	select 
		am.unit_id,
		am.organization_id,
		em.doctor_id,
		am.appointment_type_id as speciality_id,
		(case when am.appointment_status_id=2 then  am.cancelled_by when am.appointment_status_id=3 then  am.rescheduled_by end) as request_type_code,
		am.appointment_date::date as date,
		count(*)::bigint as count,
		asm.appointment_status_code,
		am.status
	from opd.m_appointment_master am
	left join opd.t_encounter_master em 
	on am.appointment_id=em.appointment_id
	left join opd.m_appointment_status_master asm
	on am.appointment_status_id=asm.appointment_status_id
	
	where 
	(am.appointment_date::date >= p_date ::date and am.appointment_date::date < current_date)  
		
		 and
		 (am.appointment_status_id=2 or am.appointment_status_id=3 or am.appointment_status_id=7)
		group by 
	am.appointment_date,
	em.doctor_id,
	am.unit_id,
	am.organization_id,
	am.appointment_type_id,
	asm.appointment_status_code,
	am.appointment_status_id,
	am.cancelled_by,
	am.rescheduled_by,
	am.status;
    --order by am.appointment_date desc;
end;

$$;


--
-- TOC entry 3961 (class 1255 OID 2969135)
-- Name: get_appointment_status(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_appointment_status(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, patient_id integer, speciality_id integer, is_cancelled boolean, is_reschedule boolean, is_overbooked boolean, date_time timestamp without time zone, status character)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY 
	select 
		am.unit_id,
		am.organization_id,
		em.doctor_id,
		am.patient_id,
		am.appointment_type_id,
		(case when am.appointment_status_id=2 then  true  else false end) ,
		(case when am.appointment_status_id=3 then  true  else false end) ,
		false,
		am.appointment_date,
		am.status
	from opd.m_appointment_master am
	left join opd.m_slot_master em 
	on am.slot_id=em.slot_id
	
	where 
	(am.appointment_date::date >= p_date ::date and am.appointment_date::date < current_date) 
		
		 and
		 (am.appointment_status_id=2 or am.appointment_status_id=3);
		
end;

$$;


--
-- TOC entry 3763 (class 1255 OID 2969136)
-- Name: get_average_length_of_stay_diagnosis_wise(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_average_length_of_stay_diagnosis_wise(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, discharge_date date, total_discharge_days_count integer, total_discharge_count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY 
	select s.unit_id,s.organization_id,s.patient_id,s.doctor_id,
s.speciality_id,s.diagnosis_id,s.discharge_time::date as discharge_date ,
(case
when s.days>0 and s.hours>0 and s.minutes>0 then s.days+1
when s.days>0 and s.hours=0 and s.minutes>0 then s.days+1
when s.days=0 and s.hours>0 then 1
when s.days=0 and s.hours=0 and s.minutes>0 then 1
when s.days >0  then s.days
else 0 end  ) as total_discharge_days_count ,
count (s.discharge_id) as total_discharge_count, false as is_deleted
from 
(select ta.unit_id,ta.organization_id,ta.patient_id,td.doctor_id,
ta.speciality_id,tca.diagnosis_id,td.discharge_time,
date_part('days',age(td.discharge_time, tad.doa))::integer as days,
date_part('hours',age(td.discharge_time, tad.doa))::integer as hours,
date_part('minutes',age(td.discharge_time, tad.doa))::integer as minutes,
td.discharge_id
from adt.t_admission ta
join adt.t_admission_details tad on ta.admission_id=tad.admission_id
join adt.t_discharge td on td.admission_id=ta.admission_id
join adt.t_complaint_admission tca on ta.admission_id=tca.admission_id
where ((ta.updated_date::date >= p_date	and ta.updated_date::date < current_date)
			or (ta.created_date::date >= p_date
			and ta.created_date::date < current_date))
group by 
ta.admission_id,
ta.unit_id,
ta.organization_id,
ta.patient_id,
td.doctor_id,
ta.speciality_id,
tca.diagnosis_id,
td.discharge_time,
td.discharge_id,
tad.doa) s
group by 
s.unit_id,s.organization_id,s.patient_id,s.doctor_id,
s.speciality_id,s.diagnosis_id,s.discharge_time::date,s.days,s.hours,s.minutes;


end;

$$;


--
-- TOC entry 3963 (class 1255 OID 2969137)
-- Name: get_avg_length_of_stay(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_avg_length_of_stay(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		s.unit_id ,
		s.organization_id,
		s.speciality_id ,
		s.doctor_id,
		s.admission_type_id,
		sum(case when diff <= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_discharge_days_count,
		count(distinct s.discharge_id):: bigint as total_discharge_count,
		generate_series(p_date::date , current_timestamp::date, '1day' )::date date,
		s.is_deleted
	from
		(
		select
			a.unit_id ,
			a.organization_id,
			a.speciality_id ,
			d.doctor_id ,
			ad.admission_type_id,
			d.discharge_id,
			extract(epoch
		from
			d.discharge_date - ad.doa)::integer / 3600 as diff,
			case
				when a.status ilike 'A' then false
				else true
			end as is_deleted
		from
			adt.t_discharge d
		join adt.t_admission a on
			d.admission_id = a.admission_id
			and a.visit_type_id in (2)
		join adt.t_admission_details ad on
			d.admission_id = ad.admission_id
		where
			(d.updated_date::date >= p_date and d.updated_date::date < current_date)
			or (d.created_date::date >= p_date	and d.created_date::date < current_date)
		group by
			a.unit_id ,
			a.organization_id,
			a.speciality_id ,
			d.discharge_date,
			d.doctor_id,
			ad.doa,
			d.discharge_id,
			a.status,
			ad.admission_type_id )s
	group by
		s.unit_id ,
		s.organization_id,
		s.speciality_id ,
		s.doctor_id,
		s.discharge_id,
		s.admission_type_id,
		s.is_deleted;
end;

$$;


--
-- TOC entry 3964 (class 1255 OID 2969138)
-- Name: get_bed_availability(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_bed_availability(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bed_type_id integer, actual_bed_count bigint, total_bed_count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		bm.unit_id,
		bedtype.organization_id,
		bedtype.bed_type_id ,
		(
		select
			count(bedmast0.bed_id) actual_bed_count
		from
			adt.m_bed_master bedmast0
		inner join adt.t_bed_log_status bedlog0 on
			bedmast0.bed_id = bedlog0.bed_id
		where
			(bedlog0.bed_status_id = 3
			or bedlog0.bed_status_id = 6)
			and bedmast0.bed_type_id = bedtype.bed_type_id
			and bedlog0.status = 'A'
			and ((bedlog0.updated_date::date >= p_date ::date
			and bedlog0.updated_date::date < current_date)
			or (bedlog0.created_date::date >= p_date::date
			and bedlog0.created_date::date < current_date)) ),
		(
		select
			count(bedmast3.bed_id) total_bed_count
		from
			adt.m_bed_master bedmast3
		inner join adt.t_bed_log_status bedlog3 on
			bedmast3.bed_id = bedlog3.bed_id
		where
			bedmast3.bed_type_id = bedtype.bed_type_id
			and bedlog3.status = 'A'
			and ((bedlog3.updated_date::date >= p_date ::date
			and bedlog3.updated_date::date < current_date)
			or (bedlog3.created_date::date >= p_date::date
			and bedlog3.created_date::date < current_date)) ),
		generate_series(bedlog.updated_date::date , current_timestamp::date, '1day')::date as date,
		case
			when bedlog.status ilike 'A' then false
			else true
		end as is_deleted
	from
		adt.m_bed_type_master bedtype
	inner join adt.m_bed_master bm on
		bedtype.bed_type_id = bm.bed_type_id
	inner join adt.t_bed_log_status bedlog on
		bm.bed_id = bedlog.bed_id
	where
		bedtype.status = 'A'
	group by
		bedtype.unit_id,
		bedtype.organization_id,
		bedtype.bed_type_id ,
		date,
		bedlog.status,
		bm.unit_id
	order by
		bedtype.bed_type_id;
end;

$$;


--
