--
-- TOC entry 3967 (class 1255 OID 2969141)
-- Name: get_death_statistics(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_death_statistics(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, is_mlc character, diagnosis_id integer, count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		d.unit_id,
		d.organization_id,
		a.speciality_id,
		d.doctor_id,
		ad.admission_type_id,
		ad.is_medico_legal as is_mlc ,
		ca.diagnosis_id ,
		count(d.discharge_id) :: bigint count,
		generate_series(d.updated_date::date , current_timestamp::date, '1day' )::date date,
		case
			when d.status ilike 'A' then false
			else true
		end as is_deleted
	from
		"adt".t_discharge d
	join "adt".t_admission a on
		d.admission_id = a.admission_id
	join "adt".t_admission_details ad on
		d.admission_id = ad.admission_id
	join adt.t_complaint_admission ca on
		ca.admission_id = a.admission_id
	where
		d.is_death = 'Y'
		and 
		d.discharge_date::date >= p_date and d.discharge_date::date < current_date
	group by
		d.unit_id,
		d.organization_id,
		ad.admission_type_id,
		d.doctor_id,
		a.speciality_id ,
		ad.is_medico_legal,
		ca.diagnosis_id,
		date,
		is_deleted ;
end;

$$;


--
-- TOC entry 3969 (class 1255 OID 2969142)
-- Name: get_discharge_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_discharge_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_mlc character, is_high_risk character, discharge_date date, count bigint, discharge_type_id integer, is_vip character, is_planned character, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		d.unit_id::integer,
		d.organization_id::integer,
		ad.admission_type_id::integer,
		d.visit_type_id::integer,
		a.speciality_id::integer,
		d.doctor_id::integer,
		apm.payment_entitlement_id::integer,
		extract(year
	from
		age(pr.dob))::integer as patient_age,
		pr.gender_id::integer,
		ad.is_medico_legal::char,
		ad.is_high_risk::char,
		d.discharge_date::date,
		count(*),
		d.discharge_type_id::integer,
		pr.is_vip::char,
		(case
			when a.admission_id in (
				select admission_id
			from
				adt.t_admission_note) then 'Y'::char
			else 'N'::char
		end) as is_planned,
		(case
			when d.status = 'A' then false::bool
			else true::bool
		end) as is_deleted
	from
		adt.t_admission a
	join adt.t_discharge d
			using (admission_id)
	join adt.t_admission_details ad
			using (admission_id)
	join adt.t_admission_patient_mapping apm on
		(a.patient_id = apm.admission_patient_id)
	join patient.t_patient_registration pr
			using(patient_id)
	where
		d.discharge_date::date >= p_date ::date
	group by
		d.unit_id,
		d.organization_id,
		ad.admission_type_id,
		d.visit_type_id,
		apm.payment_entitlement_id,
		a.speciality_id,
		pr.dob,
		d.doctor_id,
		pr.gender_id,
		ad.is_medico_legal,
		d.discharge_type_id,
		ad.is_high_risk,
		d.discharge_date,
		pr.is_vip,
		a.admission_id,
		d.status;
end;

$$;


--
-- TOC entry 3970 (class 1255 OID 2969143)
