--

CREATE FUNCTION procedure.get_discharge_analysis_mis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, bed_id integer, speciality_id integer, doctor_id integer, patient_id integer, marked_discharge boolean, ready_billing boolean, ready_discharge boolean, discharge_date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		d.unit_id,
		d.organization_id,
		ad.bed_category_id,
		ad.bed_id,
		a.speciality_id,
		d.doctor_id,
		a.patient_id,
		case
			when d.discharge_status_id = 1 then true
			else false
		end as marked_discharge,
		case
			when d.discharge_status_id = 2 then true
			else false
		end as ready_billing,
		case
			when d.discharge_status_id = 3 then true
			else false
		end as ready_discharge,
		cast(d.updated_date as date) as discharge_date,
		case
			when a.status ilike 'A' then false
			else true
		end as is_deleted
	from
		adt.t_admission a
	join adt.t_discharge d
			using (admission_id)
	join adt.t_admission_details ad
			using (admission_id)
	where
		((d.updated_date::date >= p_date ::date
		and d.updated_date::date < current_date)
		or (d.created_date::date >= p_date::date
		and d.created_date::date < current_date));
end;

$$;


