--
-- TOC entry 3972 (class 1255 OID 2969145)
-- Name: get_encounter_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_encounter_analysis(p_date date) RETURNS TABLE(encounter_count bigint, unit_id integer, organization_id integer, doctor_id integer, encounter_type_id integer, visit_type_id integer, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select 
		a.encounter_count,
		a.unit_id,
		a.organization_id,
		a.doctor_id,
		a.encounter_type_id, 
		a.visit_type_id,
		a.created_date as date,
		false as is_deleted
	from
	(
		select count(otem.encounter_id) as encounter_count,otem.unit_id,otem.organization_id,otem.doctor_id,otem.encounter_type_id,1 as visit_type_id,
			   otem.created_date::date,otem.updated_date::date
		from opd.t_encounter_master otem
		group by otem.unit_id,
				 otem.organization_id,
				 otem.doctor_id,
				 otem.encounter_type_id,
				 otem.visit_type_id,
				 otem.created_date::date,
				 otem.updated_date::date
		union
		select count(ata.admission_id),ata.unit_id,ata.organization_id,ata.doctor_id,ata.speciality_id, ata.visit_type_id ,ata.created_date::date,ata.updated_date::date
		from adt.t_admission ata
		group by ata.unit_id,
				 ata.organization_id,
				 ata.doctor_id,
				 ata.speciality_id, 
				 ata.visit_type_id ,
				 ata.created_date::date,
				 ata.updated_date::date
	)a
	where 
		(a.updated_date::date >= p_date ::date and a.updated_date::date < current_date) 
		or 
		(a.created_date::date >= p_date::date and a.created_date::date < current_date);
end;

$$;


