--
-- TOC entry 3989 (class 1255 OID 2969162)
-- Name: get_op_conversion_analysis(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_op_conversion_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, count bigint, date date, conversion_from_op_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return query select
		a.unit_id,
		a.organization_id,
		a.speciality_id,
		a.doctor_id,
		count(*) as count,
		ad.doa::date as date,
		(case
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 2) then 1
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_icu = 'Y') then 2
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 3) then 3
		end) as conversion_from_op_id,
		case
			when a.status = 'A' then false
			else true
		end as is_deleted
	from
		adt.t_admission a
	inner join adt.t_transfer t
			using (admission_id)
	inner join adt.t_admission_details ad using (admission_id)
	where
		(ad.doa::date >= p_date::date
		and ad.doa::date < current_date)
	group by
		a.unit_id,
		a.organization_id,
		a.speciality_id,
		a.doctor_id,
		conversion_from_op_id,
		date,
		a.status;
end;
$$;


