--
-- TOC entry 3991 (class 1255 OID 2969164)
-- Name: get_patient_transfer(date); Type: FUNCTION; Schema: procedure; Owner: -
--

CREATE FUNCTION procedure.get_patient_transfer(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, transfer_to_id integer, bed_category_id integer, count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		a.unit_id,
		a.organization_id,
		a.doctor_id,
		a.speciality_id,
		case
			when f_ward.is_icu = 'N'
			and t_ward.is_icu = 'N' then 1
			when f_ward.is_icu = 'N'
			and t_ward.is_icu = 'Y' then 2
			when f_ward.is_icu = 'Y'
			and t_ward.is_icu = 'N' then 3
		end as transfer_to_id,
		case
			when frombed.hierarchy_id > tobed.hierarchy_id then 1
			when frombed.hierarchy_id < tobed.hierarchy_id then 2
			when frombed.hierarchy_id = tobed.hierarchy_id then 3
		end as bed_category_id,
		count(*):: bigint as count,
		t.from_date::date as date,
		case
			when t.status ilike 'A' then false
			else true
		end as is_deleted
	from
		"adt".t_transfer t
	 join "adt".t_admission a on
		t.admission_id = a.admission_id
	 join "adt".m_ward_master f_ward on
		t.from_ward_id = f_ward.ward_id
	 join "adt".m_ward_master t_ward on
		t.to_ward_id = t_ward.ward_id
	join (
			select bcm.hierarchy_id,
			t.from_bed_category_id,
			t.admission_id
		from
			adt.t_transfer t
		join adt.m_bed_category_master bcm on
			t.from_bed_category_id = bcm.bed_category_id) frombed on
		a.admission_id = frombed.admission_id
	join (
			select bcm.hierarchy_id,
			t.to_bed_category_id,
			t.admission_id
		from
			adt.t_transfer t
		left join adt.m_bed_category_master bcm on
			t.to_bed_category_id = bcm.bed_category_id) tobed on
		tobed.admission_id = a.admission_id
	where
		(t.from_date::date >= p_date
		and t.from_date::date < current_date)
	group by
	    t.from_date,
		a.unit_id,
		a.organization_id,
		a.doctor_id,
		a.speciality_id,
		f_ward.is_icu,
		t_ward.is_icu,
		t.status,
		bed_category_id;
end;
$$;


