			when a.status ilike 'A' then false
			else true
		end as is_deleted
	from
		adt.t_admission a
	left join adt.t_complaint_admission cad
			using(admission_id)
	left join billing.m_deposit_master dm
			using (admission_id)
	join adt.t_discharge d
			using (admission_id)
	join adt.t_admission_details ad
			using (admission_id)
	join adt.t_admission_patient_mapping apm on
		(a.patient_id = apm.admission_patient_id)
	where
		((d.updated_date::date >= p_date ::date
		and d.updated_date::date < current_date)
		or (d.created_date::date >= p_date::date
		and d.created_date::date < current_date));
end;

$$;


--
-- TOC entry 3766 (class 1255 OID 2969168)
-- Name: adt_get_accident_emergency_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.adt_get_accident_emergency_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, is_mlc character, triage_level_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ 
begin
return query	 select a.unit_id::integer,
 		a.organization_id::integer,
 		ad.is_medico_legal::char as is_mlc,
 		ad.triage_category_id::integer as triage_level_id,
        (case when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and t.to_ward_id in(select ward_id from adt.m_ward_master where is_er = 'N' and is_icu = 'N') then 1
 			  when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and t.to_ward_id in(select ward_id from adt.m_ward_master where is_icu = 'Y') then 2
 			  when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and tr.transfer_type_id = 2 then 3
 			  else 2
 		 end)::integer as transfer_from_er_id,
 		 generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,
         count(a.admission_id) as count,
         (case when a.status = 'A' then false::bool else true::bool end) as is_deleted
from adt.t_admission a inner join adt.t_admission_details ad using(admission_id)
inner join  adt.t_transfer t using (admission_id)
inner join adt.t_transfer_request tr using (admission_id)
where ((a.updated_date::date >= p_date::date and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date and a.created_date::date < current_date))
group by a.unit_id,
		a.organization_id,
		ad.is_medico_legal,
		ad.triage_category_id,
		transfer_from_er_id,
		date,
		a.status;	
end;
$$;


