--
-- TOC entry 3768 (class 1255 OID 2969170)
-- Name: adt_get_bed_availability(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.adt_get_bed_availability(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bed_type_id integer, actual_bed_count bigint, total_bed_count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ 
begin
return QUERY
select
bm.unit_id,
bm.organization_id,
bedtype.bed_type_id ,
(
select count(bedmast0.bed_id) actual_bed_count
		from
		adt.m_bed_master bedmast0
		inner join adt.t_bed_log_status bedlog0 on
		bedmast0.bed_id = bedlog0.bed_id
		where
		(bedlog0.bed_status_id = 3 or bedlog0.bed_status_id = 6)
		and bedmast0.bed_type_id = bedtype.bed_type_id
		and bedlog0.status = 'A'
		and ((bedlog0.updated_date::date >= p_date ::date
		and bedlog0.updated_date::date < current_date)
		or (bedlog0.created_date::date >= p_date::date
		and bedlog0.created_date::date < current_date))
),
(
select count(bedmast3.bed_id) total_bed_count
        from
		adt.m_bed_master bedmast3
		inner join adt.t_bed_log_status bedlog3 on
		bedmast3.bed_id = bedlog3.bed_id
where
		bedmast3.bed_type_id = bedtype.bed_type_id
		and bedlog3.status = 'A'
		and ((bedlog3.updated_date::date >= p_date ::date
		and bedlog3.updated_date::date < current_date)
		or (bedlog3.created_date::date >= p_date::date
		and bedlog3.created_date::date < current_date))
),
generate_series(bedlog.updated_date::date , CURRENT_TIMESTAMP::date, '1day')::date as date,
CASE WHEN bedlog.status ilike 'A' then false
     ELSE TRUE
     END AS is_deleted
from adt.m_bed_type_master bedtype
inner join adt.m_bed_master bm on bedtype.bed_type_id=bm.bed_type_id
inner join adt.t_bed_log_status bedlog on bm.bed_id=bedlog.bed_id
where
bedtype.status = 'A'
group by bm.unit_id,
bm.organization_id,
bedtype.bed_type_id ,date, bedlog.status
order by
bedtype.bed_type_id;

end;
$$;


--
-- TOC entry 3769 (class 1255 OID 2969171)
-- Name: adt_get_bed_occupancy_rate(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.adt_get_bed_occupancy_rate(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, total_no_inpatient_count bigint, total_bed_count bigint, date date, is_deleted boolean, bed_type_id integer)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		s.unit_id,
		s.organization_id,
		s.admission_type_id,
		sum(case when diff <= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_no_inpatient_count,
		b.total_bed_count,
		generate_series(p_date::date , current_timestamp::date, '1day')::date as date,
		case
			when b.status ilike 'A' then false
			else true
		end as is_deleted,
		b.bed_type_id
	from
		(
		select
			a.unit_id ,
			a.organization_id,
			ad.admission_type_id,
			a.admission_id,
			extract(epoch
		from
			td.discharge_date - ad.doa)::integer / 3600 as diff
		from
			adt.t_discharge td
		join adt.t_admission a on
			a.admission_id = td.admission_id
			and a.visit_type_id in (2)
		join adt.t_admission_details ad on
			ad.admission_id = a.admission_id
		where
			((td.updated_date::date >= p_date
			and td.updated_date::date < current_date)
			or (td.created_date::date >= p_date
			and td.created_date::date < current_date))
			and a.status = 'A'
		group by
			a.unit_id ,
			a.organization_id,
			ad.doa,
			a.admission_id,
			ad.admission_type_id,
			td.discharge_date )s
	join (
		select
			a.admission_id,
			a.status,
			bm.bed_type_id,
			count(distinct bm.bed_id) total_bed_count
		from
			adt.t_admission a
		join adt.t_admission_details ad on
			a.admission_id = ad.admission_id
		join adt.m_bed_master bm on
			ad.bed_id = bm.bed_id
		where
			((a.updated_date::date >= p_date
			and a.updated_date::date < current_date)
			or (a.created_date::date >= p_date
			and a.created_date::date < current_date))
			and a.status = 'A'
		group by
			a.admission_id,
			a.status,
			bm.bed_type_id )b on
		s.admission_id = b.admission_id
	group by
		s.unit_id ,
		s.organization_id,
		s.admission_type_id,
		b.total_bed_count,
		date,
		b.status,
		b.bed_type_id
	limit 100;
end;

$$;


