--
-- TOC entry 3771 (class 1255 OID 2969174)
-- Name: adt_get_op_conversion_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.adt_get_op_conversion_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, count bigint, date date, conversion_from_op_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return query select
		a.unit_id,
		a.organization_id,
		a.speciality_id,
		a.doctor_id,
		count(a.admission_id) as count,
		generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,
		(case
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 2) then 1
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_icu = 'Y') then 2
			when t.from_ward_id in (
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 1)
			and t.to_ward_id in(
				select ward_id
			from
				adt.t_admission_details
			where
				visit_type_id = 3) then 3
		end) as conversion_from_op_id,
		case
			when a.status = 'A' then false
			else true
		end as is_deleted
	from
		adt.t_admission a
	inner join adt.t_transfer t
			using (admission_id)
	where
		((a.updated_date::date >= p_date::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
	group by
		a.unit_id,
		a.organization_id,
		a.speciality_id,
		a.doctor_id,
		conversion_from_op_id,
		date,
		a.status;
end;

$$;


--
-- TOC entry 3772 (class 1255 OID 2969175)
-- Name: adt_get_records_patient_transfer(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.adt_get_records_patient_transfer(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, transfer_to_id integer, bed_category_id integer, count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		a.unit_id,
		a.organization_id,
		a.doctor_id,
		a.speciality_id,
		case
			when f_ward.is_icu = 'N'
			and t_ward.is_icu = 'N' then 1
			when f_ward.is_icu = 'N'
			and t_ward.is_icu = 'Y' then 2
			when f_ward.is_icu = 'Y'
			and t_ward.is_icu = 'N' then 3
		end as transfer_to_id,
		case
			when frombed.hierarchy_id > tobed.hierarchy_id then 1
			when frombed.hierarchy_id < tobed.hierarchy_id then 2
			when frombed.hierarchy_id = tobed.hierarchy_id then 3
		end as bed_category_id,
		count(distinct a.patient_id):: bigint as count,
		generate_series(p_date::date , current_timestamp::date, '1day')::date as date,
		case
			when t.status ilike 'A' then false
			else true
		end as is_deleted
	from
		"adt".t_transfer t
	join "adt".t_admission a on
		t.admission_id = a.admission_id
	join "adt".m_ward_master f_ward on
		t.from_ward_id = f_ward.ward_id
	join "adt".m_ward_master t_ward on
		t.to_ward_id = t_ward.ward_id
	join (
			select bcm.hierarchy_id,
			t.from_bed_category_id,
			t.admission_id
		from
			adt.t_transfer t
		join adt.m_bed_category_master bcm on
			t.from_bed_category_id = bcm.bed_category_id) frombed on
		a.admission_id = frombed.admission_id
	join (
			select bcm.hierarchy_id,
			t.to_bed_category_id,
			t.admission_id
		from
			adt.t_transfer t
		join adt.m_bed_category_master bcm on
			t.to_bed_category_id = bcm.bed_category_id) tobed on
		tobed.admission_id = a.admission_id
	where
		((t.updated_date::date >= p_date
		and t.updated_date::date < current_date)
		or (t.created_date::date >= p_date
		and t.created_date::date < current_date))
	group by
		a.unit_id,
		a.organization_id,
		a.doctor_id,
		a.speciality_id,
		f_ward.is_icu,
		t_ward.is_icu,
		t.status,
		bed_category_id
	limit 100;
end;

$$;


