--
-- TOC entry 3774 (class 1255 OID 2969177)
-- Name: emergency_analysis(date, date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.emergency_analysis(f_date date, t_date date) RETURNS TABLE(admission_type_code character varying, admission_id integer, patient_id integer, triage_category_id integer, fromward character varying, toward character varying, hr integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY
select
	atm.admission_type_code,
	ad.admission_id,
	COALESCE(a.patient_id,'0') as patient_id,
	COALESCE(ad.triage_category_id,'0') as triage_category_id,
	fw.ward_name as fromWard,
	tw.ward_name as toward,
	date_part('hour',ad.created_date) as hr
from 
	adt.m_admission_type_master atm
		join
	adt.t_admission_details ad 
		on atm.admission_type_id=ad.admission_type_id
		join
	adt.t_admission a 
		on ad.admission_id=a.admission_id
		left join 
	adt.t_transfer t on a.admission_id=t.admission_id
		left join
	adt.m_ward_master fw on t.from_ward_id =fw.ward_id
		left join
	adt.m_ward_master tw on t.to_ward_id = tw.ward_id
where 
	atm.admission_type_code='EIA'
	and date(ad.created_date) between f_date and t_date;
END;
$$;


--
-- TOC entry 3775 (class 1255 OID 2969178)
-- Name: get_accident_emergency_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_accident_emergency_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, is_mlc character, triage_level_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return query select
		a.unit_id::integer,
		a.organization_id::integer,
		ad.is_medico_legal::char as is_mlc,
		ad.triage_category_id::integer as triage_level_id,
		(case
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'N'
				and is_icu = 'N') then 1
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and t.to_ward_id in(
				select ward_id
			from
				adt.m_ward_master
			where
				is_icu = 'Y') then 2
			when t.from_ward_id in (
				select ward_id
			from
				adt.m_ward_master
			where
				is_er = 'Y')
			and tr.transfer_type_id = 2 then 3
			else 2
		end)::integer as transfer_from_er_id,
		generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,
		count(a.admission_id) as count,
		(case
			when a.status = 'A' then false::bool
			else true::bool
		end) as is_deleted
	from
		adt.t_admission a
	inner join adt.t_admission_details ad
			using(admission_id)
	inner join adt.t_transfer t
			using (admission_id)
	inner join adt.t_transfer_request tr
			using (admission_id)
	where
		((a.updated_date::date >= p_date::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
	group by
		a.unit_id,
		a.organization_id,
		ad.is_medico_legal,
		ad.triage_category_id,
		transfer_from_er_id,
		date,
		a.status;
end;

$$;


--
-- TOC entry 3764 (class 1255 OID 2969179)
-- Name: get_accident_er_analysis_new(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_accident_er_analysis_new(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, is_medico_legal character, triage_category_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	Return query 
	select s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa as date,s.count,s.is_deleted
	from (select ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,1 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),
		case
			when ta.status ilike 'A' then false
			else true
		end as is_deleted, 
		ta.created_date,
		ta.updated_date
	from adt.t_admission ta
	join adt.t_admission_details tad on ta.admission_id=tad.admission_id
	where ta.visit_type_id=2 
	and ta.admission_id in (select admission_id from adt.t_admission_note where visit_type_id=4)
	group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,ta.status,tad.doa,ta.created_date,ta.updated_date
	union
	select ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,2 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),
		case
			when ta.status ilike 'A' then false
			else true
		end as is_deleted
		,ta.created_date,
		ta.updated_date 
	from adt.t_admission ta
	join adt.t_admission_details tad on ta.admission_id=tad.admission_id
	where ta.visit_type_id=2
	and ta.admission_id in (select admission_id from adt.t_transfer where transfer_status_id=10)
	group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,tad.doa,ta.status,ta.created_date,ta.updated_date) s
	where 
	   (s.updated_date::date >= p_date::date and s.updated_date::date < current_date)
	or 
	   (s.created_date::date >= p_date::date and s.created_date::date < current_date)
	group by 
	s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa,s.count,s.is_deleted;
end;

$$;


--
-- TOC entry 3776 (class 1255 OID 2969180)
-- Name: get_active_deposit_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_active_deposit_report(p_date date) RETURNS TABLE(unit_id integer, org_id integer, date_of_payment date, patient_id integer, payement_mode_id integer, amount double precision, status "char")
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY Select dm.unit_id,
					dm.org_id,
					dm.deposit_date::date  as date_of_payment,
					dm.patient_id,
					pdd.payment_mode_id,
					sum(dm.deposit_amount) amount ,
					dm.status 
			FROM billing.m_deposit_master dm
			JOIN billing.t_payment_deposit_details  pdd on pdd.deposit_id = dm.deposit_master_id 
			 WHERE dm.deposit_date::date  IN (SELECT dm.deposit_date::date 
                                 FROM  billing.m_deposit_master dm
                                                	WHERE(dm.updated_date::DATE>=p_date OR dm.created_date::DATE>=p_date)
                                                		  AND dm.status = 'A') AND dm.status = 'A'
			GROUP by 	dm.deposit_date::date,
						dm.patient_id,
						pdd.payment_mode_id,
						dm.status,
						dm.unit_id,
						dm.org_id;
						
			END;
			$$;


--
-- TOC entry 3777 (class 1255 OID 2969181)
-- Name: get_admission_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_admission_analysis(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, age_group_id integer, gender_id integer, is_mlc character, is_high_risk character, count bigint, admission_date date, is_vip character, is_planned character, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		a.unit_id ::integer,
		a.organization_id ::integer,
		ad.admission_type_id ::integer,
		a.visit_type_id ::integer,
		a.speciality_id ::integer,
		a.doctor_id ::integer,
		apm.payment_entitlement_id ::integer,
		extract(year
	from
		age(pr.dob))::integer as age_group_id,
		pr.gender_id ::integer,
		ad.is_medico_legal,
		ad.is_high_risk,
		count(distinct a.admission_id),
		ad.doa::date as admission_date,
		pr.is_vip,
		(case
			when a.admission_id in (
				select admission_id
			from
				adt.t_admission_note) then 'Y'::char
			else 'N'::char
		end) as is_planned,
		(case
			when a.status = 'A' then false::bool
			else true::bool
		end) as is_deleted
	from
		adt.t_admission a
	join adt.t_admission_details ad on
		(a.admission_id = ad.admission_id)
	join opd.t_patient_sponsor_details apm on
		(a.admission_id = apm.admission_id)
	join patient.t_patient_registration pr on
		(pr.patient_id = a.patient_id)
	left join adt.t_admission_note an on
		(a.admission_id = an.admission_id)
	where
		((a.updated_date::date >= p_date ::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
	group by
		a.unit_id,
		a.organization_id,
		a.admission_id,
		ad.admission_type_id,
		ad.doa,
		a.visit_type_id,
		a.speciality_id,
		a.doctor_id,
		apm.payment_entitlement_id,
		pr.dob,
		pr.gender_id,
		ad.is_medico_legal,
		ad.is_high_risk,
		pr.is_vip;
end;

$$;


--
-- TOC entry 3778 (class 1255 OID 2969182)
-- Name: get_admission_analysis_bed_type(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_admission_analysis_bed_type(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, date_of_admission date, no_of_admission integer, admission_type_id integer, bed_category_id integer, patient_category_id integer, payment_entitlement_id integer, speciality_id integer, doctor_id integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT		pr.unit_id,
						pr.organization_id as hospital_id ,
						ad.doa :: DATE date_of_admission,
						COUNT (DISTINCT ad.admission_id) :: integer  as no_of_admission,
						ad.admission_type_id,
						ad.bed_category_id,
						pr.patient_category_id,
						apm.payment_entitlement_id,
						a.speciality_id,
						a.doctor_id,
						a.status
		FROM "adt".t_admission a 
		JOIN "adt".t_admission_details ad ON a.admission_id = ad.admission_id  
		JOIN "patient".t_patient_registration pr  ON pr.patient_id = a.patient_id
		LEFT JOIN "adt".t_admission_note an ON an.admission_id = a.admission_id
	    LEFT JOIN "adt".t_admission_patient_mapping apm ON an.admission_note_id = apm.admission_note_id
		WHERE  ad.doa IN (SELECT ad.doa 
                                 FROM "adt".t_admission_details ad
                                                	WHERE(a.updated_date::DATE>=p_date OR a.created_date::DATE>=p_date)
                                                		  AND a.status = 'A')
                    		                        AND a.status = 'A'
		GROUP BY a.status,
				ad.doa :: DATE  ,
	            pr.unit_id,
	       		pr.organization_id,
				ad.admission_type_id,
				pr.patient_category_id,
				a.speciality_id,
				ad.bed_category_id,
				a.doctor_id,
				apm.payment_entitlement_id;   



END;

$$;


