--
-- TOC entry 3780 (class 1255 OID 2969184)
-- Name: get_age_wise_mortality_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_age_wise_mortality_report(p_date date) RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, age_group_id integer, gender_id integer, no_of_patient_expired integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	d.discharge_date :: DATE ,
						a.unit_id,
						a.organization_id as hospital_id ,
						 EXTRACT(year from age(pr.dob)):: integer as age_group_id,
						pr.gender_id,
						count(a.patient_id) :: INTEGER  as no_of_patient_expired,
						d.status
				from adt.t_discharge d 
				inner join adt.t_admission a on a.admission_id = d.admission_id 
				inner join adt.t_admission_details ad on ad.admission_id = a.admission_id
				inner join patient.t_patient_registration pr on  pr.patient_id = a.patient_id
				WHERE d.is_death = 'Y' AND  d.discharge_date IN (SELECT d.discharge_date
                                 FROM adt.t_discharge d 
                                                	WHERE(d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date)
                                                		  AND d.status = 'A') AND d.status = 'A'
				group by 	a.unit_id,
							a.organization_id,
							pr.gender_id,
							age_group_id,
							d.status,
							d.discharge_date;
							
						END;
						$$;


--
-- TOC entry 3782 (class 1255 OID 2969185)
-- Name: get_appointment_cancellation_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_appointment_cancellation_analysis(p_date date) RETURNS TABLE(encounter_date date, doctor_id integer, dept_id integer, unit_id integer, organziation_id integer, count integer, request_type_id integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY     SELECT 	em.encounter_date :: date , 
							em.doctor_id, 
							em.dept_id,
							em.unit_id,
							em.organization_id as hospital_id,
							count(DISTINCT am.appointment_id) :: integer as no_of_appoinment_cancelled,
							CASE WHEN am.cancelled_by = 'P' OR am.rescheduled_by = 'P' THEN 1  --provider
		    					 WHEN am.cancelled_by = 'C' OR am.rescheduled_by = 'C' THEN 2 --consumer
			 				END as request_type_id ,
							em.status 
				FROM opd.t_encounter_master em
				JOIN opd.m_appointment_master am on em.patient_id = am.patient_id
				WHERE -- em.encounter_date IN (SELECT em.encounter_date FROM opd.t_encounter_master em WHERE(em.updated_date::DATE>=p_date OR em.created_date::DATE>=p_date AND am.appointment_status_id = 2 OR am.appointment_status_id = 3 ) AND em.status = 'A') AND em.status = 'A'
				(em.updated_date::DATE>=p_date 
				OR em.created_date::DATE>=p_date) 
				AND (am.appointment_status_id = 2 
				OR am.appointment_status_id = 3) 
				AND em.status = 'A'
				GROUP by 	em.doctor_id, 
					 		em.dept_id,
					 		em.unit_id,
					 		em.organization_id,
						 	request_type_id,
 							em.status ,
							em.encounter_date :: date ;
 

END;

$$;


