    LANGUAGE plpgsql
    AS $$
begin
	return QUERY 
	select 
		am.unit_id,
		am.organization_id,
		em.doctor_id,
		am.patient_id,
		am.appointment_type_id,
		(case when am.appointment_status_id=2 then  true  else false end) ,
		(case when am.appointment_status_id=3 then  true  else false end) ,
		false,
		am.appointment_date,
		am.status
	from opd.m_appointment_master am
	left join opd.m_slot_master em 
	on am.slot_id=em.slot_id
	
	where 
	(am.appointment_date::date >= p_date ::date and am.appointment_date::date < current_date) 
		
		 and
		 (am.appointment_status_id=2 or am.appointment_status_id=3);
		
end;

$$;


--
-- TOC entry 3784 (class 1255 OID 2969187)
-- Name: get_average_consultation_time(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_average_consultation_time(p_date date) RETURNS TABLE(encounter_date date, consultation_start_time bigint, consultation_stop_time bigint, doctor_id integer, speciality_id integer, consultation_type_id integer, unit_id integer, hospital_id integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY  	Select 	em.encounter_date :: DATE,
						coalesce(MAX(Extract(epoch from ed.consultation_start_time):: bigint),0) as consultation_start_time, 
						coalesce(MAX(Extract(epoch from ed.consultation_stop_time):: bigint),0) as consultation_stop_time,
						em.doctor_id,
						em.dept_id as speciality_id,
						em.user_defined_visit_type_id as consultation_type_id,
						em.unit_id,
						em.organization_id AS hospital_id,
						em.status
				FROM opd.t_encounter_master em 
				JOIN opd.t_encounter_details ed on em.encounter_id = ed.encounter_id
				 WHERE -- em.encounter_date IN (Select em.encounter_date FROM opd.t_encounter_master em  WHERE (em.updated_date::DATE>=p_date OR em.created_date::DATE>=p_date) AND em.status = 'A') AND em.status = 'A' 
					(em.updated_date::DATE>=p_date 
					OR em.created_date::DATE>=p_date) 
					AND em.status = 'A'
				 GROUP BY 	em.encounter_date :: DATE,
							em.doctor_id,
							em.dept_id,
							consultation_type_id,
							em.status,
							em.unit_id ,
							em.status,
							em.organization_id
				ORDER BY em.encounter_date :: DATE;
				END;
				$$;


--
-- TOC entry 3785 (class 1255 OID 2969188)
-- Name: get_average_length_of_stay_procedure_wise(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_average_length_of_stay_procedure_wise(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		s.unit_id ,
		s.organization_id,
		s.speciality_id ,
		s.doctor_id,
		s.diagnosis_id,
		sum(case when diff <= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_discharge_days_count,
		count(distinct s.discharge_id):: bigint as total_discharge_count,
		generate_series(p_date::date , current_timestamp::date, '1day' )::date date,
		s.is_deleted
	from
		(
		select
			a.unit_id ,
			a.organization_id,
			a.speciality_id ,
			d.doctor_id ,
			ca.diagnosis_id,
			d.discharge_id,
			extract(epoch
		from
			d.discharge_date - ad.doa)::integer / 3600 as diff,
			case
				when a.status ilike 'A' then false
				else true
			end as is_deleted
		from
			adt.t_discharge d
		join adt.t_admission a on
			d.admission_id = a.admission_id
			and a.visit_type_id in (2)
		join adt.t_admission_details ad on
			d.admission_id = ad.admission_id
		join adt.t_complaint_admission ca on 
			ca.admission_id=a.admission_id
		where
			((d.updated_date::date >= p_date
			and d.updated_date::date < current_date)
			or (d.created_date::date >= p_date
			and d.created_date::date < current_date))
		group by
			a.unit_id ,
			a.organization_id,
			a.speciality_id ,
			d.discharge_date,
			d.doctor_id,
			ca.diagnosis_id,
			ad.doa,
			d.discharge_id,
			a.status,
			ad.admission_type_id )s
	group by
		s.unit_id ,
		s.organization_id,
		s.speciality_id ,
		s.doctor_id,
		s.diagnosis_id,
		s.discharge_id,
		s.is_deleted;
end;

$$;


--
-- TOC entry 3786 (class 1255 OID 2969189)
-- Name: get_avg_lenght_diagnosis_wise(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_avg_lenght_diagnosis_wise(p_date date) RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, avg_lenght_stay double precision, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
 RETURN QUERY   SELECT 	d.discharge_date :: DATE ,
 						d.unit_id ,
						d.organization_id  hospital_id,
						a.speciality_id ,
						d.doctor_id,
						ca.diagnosis_id ,
						AVG(extract(epoch from d.discharge_date - ad.doa)/3600) as avg_lenght_stay,
						d.status
				FROM adt.t_discharge d
				JOIN adt.t_admission a on d.admission_id = d.admission_id
				JOIN adt.t_admission_details ad on ad.admission_id = a.admission_id
				JOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_id
				Where  d.discharge_date IN 
								(SELECT d.discharge_date FROM "adt".t_discharge d 
            							WHERE  (d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date)
												AND d.status = 'A')
										AND d.status = 'A'
				GROUP BY 	d.unit_id ,
							d.organization_id,
							d.discharge_date :: DATE ,
							a.speciality_id ,
							d.doctor_id,
							ca.diagnosis_id,
							d.status;
 
END;

$$;


