CREATE FUNCTION procedure_old.get_avg_length_stay(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)
