			a.speciality_id ,
			d.doctor_id ,
			ad.admission_type_id,
			d.discharge_id,
			extract(epoch
		from
			d.discharge_date - ad.doa)::integer / 3600 as diff,
			case
				when a.status ilike 'A' then false
				else true
			end as is_deleted
		from
			adt.t_discharge d
		join adt.t_admission a on
			d.admission_id = a.admission_id
			and a.visit_type_id in (2)
		join adt.t_admission_details ad on
			d.admission_id = ad.admission_id
		where
			((d.updated_date::date >= p_date
			and d.updated_date::date < current_date)
			or (d.created_date::date >= p_date
			and d.created_date::date < current_date))
		group by
			a.unit_id ,
			a.organization_id,
			a.speciality_id ,
			d.discharge_date,
			d.doctor_id,
			ad.doa,
			d.discharge_id,
			a.status,
			ad.admission_type_id )s
	group by
		s.unit_id ,
		s.organization_id,
		s.speciality_id ,
		s.doctor_id,
		s.discharge_id,
		s.admission_type_id,
		s.is_deleted;
end;

$$;


--
-- TOC entry 3788 (class 1255 OID 2969191)
-- Name: get_avgerage_lenght_stay(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_avgerage_lenght_stay(p_date date) RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, disease_id integer, total_discharge integer, total_discharge_days integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY     SELECT a.dod :: date as discharge_date,
						a.unit_id,
						a.organization_id as hospital_id ,	
						a.speciality_id,
						a.doctor_id,
						a.admission_type_id,
						a.diagnosis_id as disease_id,
						
					COUNT(distinct a.discharge_id):: INTEGER as total_discharge ,
					SUM(CASE WHEN date_diff<=12 THEN 0.5 
								ELSE  (date_diff/24) + (CASE WHEN date_diff%24 = 0 THEN 0 ELSE 1 END ) 
						END)  :: integer as total_discharge_days ,
						a.status
				FROM (SELECT a.discharge_id,
								a.admission_id, 
								extract (epoch from ((dod-doa)))::integer/3600 as date_diff, 
								dod, doa,
									a.unit_id,
						            a.organization_id,	
									a.admission_id,
									a.speciality_id,
									a.doctor_id,
									a.admission_type_id,
									a.diagnosis_id,
									a.status
						FROM (select DIstinct ON							
										(a.unit_id,
						                 a.organization_id,	
										a.admission_id,
										a.speciality_id,
										a.doctor_id,
										ad.admission_type_id)
										d.unit_id,
										d.organization_id,	
										a.speciality_id,
										a.doctor_id,
										ad.admission_type_id,
										d.discharge_id,
										a.admission_id,
										ad.doa  ,
										d.discharge_date,
										d.discharge_time,
										ca.diagnosis_id,
										d.status ,
									make_timestamp(EXTRACT(year from d.discharge_date):: integer  ,
									EXTRACT(month from d.discharge_date) :: integer  ,
									EXTRACT(day from d.discharge_date) :: integer ,
									EXTRACT(hour from d.discharge_time) :: integer,
									EXTRACT(minute from d.discharge_time) :: integer ,
									EXTRACT(second from d.discharge_time)) as dod							        
					  FROM adt.t_discharge d 
					  JOIN adt.t_admission a on a.admission_id = d.admission_id AND a.visit_type_id NOT IN (3,4)
					  JOIN adt.t_admission_details ad on ad.admission_id = a.admission_id 
					  JOIN adt.t_complaint_admission ca on ca.admission_id	 = a.admission_id 
					WHERE  d.discharge_date  IN (SELECT d.discharge_date
                                                	FROM adt.t_discharge d
                                                	WHERE  (d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date)
                                                			AND d.discharge_status_id=5 AND d.is_death='N' AND d.status = 'A' )
                    		AND d.discharge_status_id=5 AND d.is_death='N' AND d.status = 'A')a)a
                    			
			GROUP BY
					a.dod :: date ,
					a.unit_id,
				    a.organization_id,	
					a.speciality_id,
					a.doctor_id,
					a.diagnosis_id,
					a.status,
					a.admission_type_id;

END;

$$;


--
-- TOC entry 3789 (class 1255 OID 2969192)
-- Name: get_bed_category_wise_billing(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_bed_category_wise_billing(p_date date) RETURNS TABLE(unit_id integer, org_id integer, bill_date_time date, bill_number character varying, doctor_id integer, speciality_id integer, patient_id integer, bed_category_id integer, bed_number character varying, sum double precision, status "char")
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY	SELECT 	a.unit_id ,
						a.organization_id,
						bm.bill_date_time::date,
						bm.bill_number,
						dsm.doctor_id,
						dsm.speciality_id,
						bm.patient_id,
						b.bed_category_id,
						b.bed_number,
						sum(bm.net_amount),
						bm.status
			from billing.m_billing_master bm
			JOIN adt.t_admission a on a.admission_id = bm.admission_id
			JOIN adt.t_admission_details ad on ad.admission_id = a.admission_id
			LEFT JOIN adt.m_bed_master b on b.bed_category_id = ad.bed_category_id
			LEFT JOIN  doctor.t_doctor_speciality_mapper dsm on dsm.doctor_id = a.doctor_id
			 WHERE bm.bill_date_time::date IN (SELECT bm.bill_date_time::date
                                 FROM  billing.m_billing_master bm
                                                	WHERE(bm.updated_date::DATE>=p_date OR bm.created_date::DATE>=p_date)
                                                		  AND bm.status = 'A') AND bm.status = 'A'
			GROUP BY 
					bm.bill_date_time::date,
					bm.bill_number,
					dsm.doctor_id,
					dsm.speciality_id,
					bm.patient_id,
					b.bed_category_id,
					b.bed_number,
					a.unit_id ,
					bm.status,
						a.organization_id;
					END;
					$$;


--
-- TOC entry 3790 (class 1255 OID 2969193)
-- Name: get_bed_occupancy_rate(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_bed_occupancy_rate(p_date date) RETURNS TABLE(bed_occupied_date date, unit_id integer, hospital_id integer, admission_type_id integer, bed_category_id integer, status boolean, total_beds bigint, available_beds bigint, occupied_beds bigint, undermaintenance_count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 
SELECT  dt.date :: date as bed_occupied_date ,
					a.unit_id,
					a.organization_id as hospital_id,
					a.admission_type_id,
					a.bed_category_id,
					CASE WHEN a.status ilike 'A' then false
                    ELSE TRUE
                    END AS is_deleted,
					(SELECT count(DISTINCT b.bed_id) from adt.m_bed_master as b) as total_beds,
       				(select count(DISTINCT b.bed_id)
			from adt.m_bed_master as b
			where   b.bed_id NOT IN  (SELECT x FROM unnest(array_agg(DISTINCT a.bed_id)) x WHERE x IS NOT NULL UNION SELECT 0)
					AND b.bed_id NOT IN  (SELECT x FROM unnest(array_agg(DISTINCT u.bed_id)) x WHERE x IS NOT NULL UNION SELECT 0)
					) as available_beds,           
					(select count(DISTINCT b.bed_id)
			from adt.m_bed_master as b
			where   b.bed_id  IN  (SELECT x 
									FROM unnest(array_agg(DISTINCT a.bed_id)) x 
										WHERE x IS NOT NULL UNION SELECT 0)) AS occupied_bed,
		count(DISTINCT u.bed_id) as under_maintenance_count	
		FROM (SELECT generate_series('2015-01-01'::date , CURRENT_TIMESTAMP::date, '1day')as date ) dt
		LEFT JOIN (SELECT 	a.unit_id,
					a.organization_id,
					a.admission_type_id,
					a.bed_category_id,
					COUNT(DISTINCT a.bed_id) as occupied_bed,
 					UNNEST(ARRAY_AGG(DISTINCT a.bed_id)) as bed_id,doa  ,a.status
			FROM (SELECT  a.bed_id,
							a.unit_id,
							a.organization_id,
							a.admission_type_id,
							a.bed_category_id,
				a.status,
							generate_series(a.doa, CASE WHEN d.discharge_date IS NULL THEN CURRENT_TIMESTAMP::DATE ELSE d.discharge_date END, '1day') as doa
					FROM  adt.t_admission_details a
					LEFT JOIN adt.t_discharge d ON a.admission_id=d.admission_id )a
					GROUP BY 	a.doa,
								a.unit_id,
						   		a.organization_id,
								a.admission_type_id,
								a.status,
					a.bed_category_id)a ON dt.date = a.doa
					LEFT JOIN (SELECT generate_series(created_date,actual_date,'1day' ) as dt, bed_id FROM adt.t_under_maintenance) u ON u.dt=dt.date
					WHERE  a.doa IN (SELECT ad.doa 
                                 FROM "adt".t_admission_details ad
                                                	WHERE(ad.updated_date::DATE>='2018-12-1' OR ad.created_date::DATE>='2018-12-1')
                                                		  AND ad.status = 'A')
                    		                        
					GROUP BY  	dt.date,	
								a.admission_type_id,
								a.bed_category_id,
								a.unit_id,
								a.organization_id,a.status;
                                
END;

$$;


