CREATE FUNCTION procedure_old.get_bed_reservation(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, patient_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, is_doa_flexible character, count integer, date date)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		ad.unit_id,
		ad.organization_id,
