	group by
		ad.unit_id,
		ad.organization_id,
		ad.patient_id,
		ad.doctor_speciality_id,
		ad.treating_doctor_id,
		ad.admission_type_id,
		ad.is_flexiable_date,
		adm.bed_category_id,
		adm.doa;
end;

$$;


