CREATE FUNCTION procedure_old.get_bi_patient_category_wise_billing_report(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bill_date_time date, bill_number character varying, visit_type_id integer, patient_id integer, patient_category_id integer, sum double precision, status "char")
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	 SELECT pr.unit_id ,
						pr.organization_id,
						b.bill_date_time::date ,
						b.bill_number,
						b.visit_type_id,
 						b.patient_id,
