CREATE FUNCTION procedure_old.get_bi_pending_vendor_return(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, return_date date, vendor_id integer, ret_gp_no character varying, generic_id integer, product_category_id integer, brand_id integer, return_qty integer, reject_reason_id integer, value_cop double precision, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
 
RETURN QUERY SELECT 	rgd.unit_id,
						rgd.organization_id as hospital_id,
						rgd.added_date:: date as return_date  ,
						rg.vendor_id, 
						MAX(rg.ret_gp_no) :: character varying as ret_gp_no,
						i.generic_id,
						i.product_category_id,
						i.id brand_id,
						sum(rgd.return_qty):: integer as return_qty,
						rgd.reject_reason_id,
						sum(rgd.return_qty * b.cop) value_cop,
						rgd.is_deleted
		from inventory.t_returnable_gatepass_detail rgd
		JOIN inventory.t_returnable_gatepass rg on rg.id = rgd.returnable_gatepass_id
		JOIN inventory.t_batch b on b.id = rgd.batch_id  
		JOIN public.m_item i on i.id = b.item_id
		WHERE rgd.added_date::date IN (SELECT rgd.added_date::date
                                 FROM  inventory.t_returnable_gatepass_detail rgd
                                                	WHERE(rgd.updated_date::DATE>=p_date OR rgd.added_date::DATE>=p_date)
                                                		  AND rgd.is_deleted = false)
                    		                        AND b.is_deleted = false
		GROUP BY 	rg.vendor_id,
					i.generic_id,
					i.product_category_id,
					i.id,
					rgd.reject_reason_id,
					rgd.unit_id,
					rgd.organization_id,
					rgd.is_deleted,
					rgd.added_date::date;
					
					END;
					$$;


