CREATE FUNCTION procedure_old.get_billable_consumption(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, added_date date, nursing_station_id integer, patient_id integer, bed_id integer, user_id integer, product_category_id integer, generic_id integer, batch_no character varying, consumable_quantity integer, mrp double precision, amount double precision, is_deleted boolean, is_billable boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY (SELECT 	bc.unit_id,
						bc.organization_id,
						bc.added_date ::date,
						nsm.nursing_station_id, 
						bc.patient_id ,
						bm.bed_id,
						bc.added_by user_id,
						i.product_category_id,
						i.generic_id,
						MAX(b.batch_no):: character varying as batch_no ,
						sum(bcd.consumable_quantity):: integer as consumable_quantity,
						sum(b.rate) mrp,
						sum(bcd.consumable_quantity * b.rate) amount,
						bc.is_deleted,
                        'TRUE':: boolean as is_billable 
		FROM pharmacy.t_billable_consumption bc 
		JOIN pharmacy.t_billable_consumption_detail bcd on bcd.billable_consumption_id = bc.id
		LEFT JOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = bc.ward_id
    	LEFT JOIN adt.m_bed_master bm on bm.bed_id = bc.bed_id
		JOIN inventory.t_batch b on b.id = bcd.batch_id
		JOIN public.m_item i on i.id = b.item_id
         
		 WHERE bc.added_date ::date IN (SELECT bc.added_date ::date
                                 FROM  pharmacy.t_billable_consumption bc 
                                                	WHERE(bc.updated_date::DATE>='2017-10-17' OR bc.added_date::DATE>='2017-10-17')
                                                		  AND bc.is_deleted = false)
                    		                        AND bc.is_deleted = false
		GROUP BY 	nsm.nursing_station_id, 
					bc.patient_id ,
					bc.added_by,
					i.product_category_id,
					i.generic_id,
					bm.bed_id,
					bc.added_date ::date,
					bc.unit_id,
					bc.is_deleted,
					bc.organization_id)
                    
		UNION 
        
 (       			SELECT 	nbc.unit_id,
						nbc.organization_id,
						nbc.added_date ::date,
						nsm.nursing_station_id, 
						NULL,
						NULL,
						nbc.added_by user_id,
						i.product_category_id,
						i.generic_id,
						MAX(b.batch_no):: character varying as batch_no ,
						sum(nbcd.consumed_qty):: integer as consumable_quantity,
						sum(b.rate) mrp,
						sum(nbcd.consumed_qty * b.rate) amount,
						nbc.is_deleted,
                        'FALSE':: boolean as is_billable 
       				FROM inventory.t_non_billable_consumption nbc 
                    JOIN inventory.t_non_billable_consumption_detail nbcd on nbc.id = nbcd.non_billable_consumption_id
              		LEFT JOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = nbc.ward_id
    				--LEFT JOIN adt.m_bed_master bm on bm.bed_id = nbc.bed_id
					JOIN inventory.t_batch b on b.id = nbcd.batch_id
					JOIN public.m_item i on i.id = b.item_id 
                    WHERE nbc.added_date ::date IN (SELECT bc.added_date ::date
                                 FROM  inventory.t_non_billable_consumption bc 
                                                	WHERE(bc.updated_date::DATE>='2017-10-17' OR bc.added_date::DATE>='2017-10-17')
                                                		  AND bc.is_deleted = false)
                    		                        AND nbc.is_deleted = false
		GROUP BY 	nsm.nursing_station_id, 
					
					nbc.added_by,
					i.product_category_id,
					i.generic_id,
					
					nbc.added_date ::date,
					nbc.unit_id,
					nbc.is_deleted,
					nbc.organization_id
);					
						END;
						$$;


