--
-- TOC entry 3796 (class 1255 OID 2969199)
-- Name: get_consignment_store_stock_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_consignment_store_stock_report(p_date date) RETURNS TABLE(item_id integer, vendor_id integer, grn_date date, grn_number character varying, quantity integer, cop double precision, value_cop double precision, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY Select b.item_id, 
					grn.vendor_id,
					grn.added_date :: date as  grn_date,
					MAX(grn.grn_number):: character varying as grn_number,
					sum(ss.available_qty):: integer as quantity,
					sum(b.cop) as cop,
					sum((b.quantity*b.cop)) as value_cop, 
					b.unit_id ,
					b.organization_id as hospital_id ,
					b.is_deleted
				from inventory.t_batch b
				JOIN inventory.t_store_stock ss on ss.batch_id = b.id
				JOIN procurement.t_good_receipt_note_detail grnd on grnd.batch_id = b.id
				JOIN procurement.t_good_receipt_note grn  ON grn.id = grnd.grn_id
				WHERE grn.added_date::date IN (SELECT grn.added_date::date
                                 FROM procurement.t_good_receipt_note grn 
                                                	WHERE(grn.updated_date::DATE>=p_date OR grn.added_date::DATE>=p_date)
                                                		  AND grn.is_deleted = false)
                    		                        AND b.is_deleted = false
				
				GROUP BY
						b.item_id,
						grn.vendor_id,
						grn_date, 
						b.unit_id ,
						b.organization_id ,
						b.is_deleted
				ORDER BY 
						grn_date;
				END;

$$;


--
-- TOC entry 3781 (class 1255 OID 2969200)
-- Name: get_crash_cart_utilization_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
