CREATE FUNCTION procedure_old.get_crash_cart_utilization_report(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, crash_cart_date date, nursing_station_id integer, user_id integer, patient_id integer, bed_id integer, generic_id integer, brand_id integer, batch_no character varying, expiry_date date, approved_quantity integer, mrp double precision, amount double precision, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 	SELECT 	ccr.unit_id,
						ccr.organization_id as hospital_id ,
						ccr.added_date :: date  as crash_cart_date   ,
						nsm.nursing_station_id, 
						ccr.added_by  user_id,
						ccr.patient_id, 
						ccr.bed_id, 
						i.generic_id ,
						ccd.item_id  brand_id,
