						b.expiry_date::date ,
						MAX(ccd.approved_quantity) :: integer as approved_quantity,
						sum(b.rate) mrp,
						sum((ccd.approved_quantity*b.rate)) as amount,
						ccr.is_deleted
			FROM pharmacy.t_crash_cart_request ccr 
			JOIN pharmacy.t_crash_cart_request_detail ccd on ccd.crash_cart_id = ccr.id
			JOIN pharmacy.t_crash_cart_batch_mapper ccb on ccb.crash_cart_detail_id = ccd.id
			JOIN inventory.t_batch b on b.id = ccb.batch_id
			JOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = ccr.ward_id 
			JOIN public.m_item i on i.id = ccd.item_id
			WHERE  ccr.added_date IN (SELECT  ccr.added_date
                                FROM  pharmacy.t_crash_cart_request ccr 
                                                	WHERE(ccr.updated_date::DATE>=p_date OR ccr.added_date::DATE>=p_date)
                                                		  AND ccr.is_deleted = False ) AND b.expiry_date IN 
									(SELECT  b.expiry_date 
                                FROM  inventory.t_batch b  
                                                	WHERE(b.updated_date::DATE>=p_date OR b.added_date::DATE>=p_date)
                                                		  AND b.is_deleted = False )					
                    		                        AND b.is_deleted = False  AND ccr.is_deleted = False
			GROUP BY 	nsm.nursing_station_id, 
						ccr.added_by,
						ccr.patient_id, 
						ccr.bed_id, 
						i.generic_id ,
						ccd.item_id,
						b.expiry_date::date ,
						ccr.added_date,
						ccr.unit_id,
						ccr.is_deleted,
						ccr.organization_id;
END;

$$;


--
-- TOC entry 3797 (class 1255 OID 2969201)
-- Name: get_death_statistics(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_death_statistics(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, discharge_date date, death_count integer, doctor_id integer, speciality_id integer, admission_type_id integer, is_medico_legal character, duration_of_stay bigint, is_high_risk character, diagnosis_id integer, status character, is_notifiable character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	select  
				d.unit_id,
				d.organization_id,
				d.discharge_date :: DATE ,
				count(d.discharge_id) :: integer  death_count ,
				d.doctor_id,
				a.speciality_id,
				ad.admission_type_id,
				ad.is_medico_legal ,
				extract(epoch from(d.discharge_date - ad.doa )):: bigint/3600   duration_of_stay,
				ad.is_high_risk ,
				ca.diagnosis_id ,
				a.status,
				dm.is_notifiable 
		FROM "adt".t_discharge d  
		JOIN "adt".t_admission a on d.admission_id = a.admission_id 
		JOIN "adt".t_admission_details ad on d.admission_id = ad.admission_id 
		JOIN patient.t_patient_registration pr on pr.patient_id = a.patient_id
		JOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_id
		JOIN emr.m_diagnosis_master dm on dm.diagnosis_id = ca.diagnosis_id 
		where d.is_death = 'Y' AND d.visit_type_id <> 4
		AND a.patient_id NOT IN (select nbd.patient_id from "patient".t_new_born_details nbd where is_still_birth = 'Y')
		AND d.discharge_date IN (SELECT d.discharge_date 
                                 FROM "adt".t_discharge d  
                                                	WHERE(d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date)
                                                		  AND d.status = 'A')
                    		                        AND d.status = 'A'
		GROUP BY  d.unit_id,
				d.discharge_date :: date 
				,d.organization_id,
				ad.admission_type_id,
				d.doctor_id,
				a.speciality_id ,ad.is_medico_legal,
				ad.is_high_risk ,
				ca.diagnosis_id ,
				a.status,
				dm.is_notifiable ,
				duration_of_stay;
				
				END;
				$$;


--
-- TOC entry 3798 (class 1255 OID 2969202)
-- Name: get_discharge_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_discharge_analysis(p_date date) RETURNS TABLE(organization_id integer, unit_id integer, discharge_date date, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, discharge_type_id integer, payment_entitlement_id integer, age integer, gender_id integer, is_mlc boolean, is_vip boolean, is_high_risk boolean, status boolean, count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY
SELECT  
					admission.organization_id,
                    admission.unit_id,
                    discharge.discharge_date:: date,
					admissionDetails.admission_type_id, 
					admission.visit_type_id, 
					admission.speciality_id,
					admission.doctor_id,
					discharge.discharge_type_id,
					admissionPatient.payment_entitlement_id,
					extract(year from age(patientRegistration.dob)):: integer as age,
					patientRegistration.gender_id,
					false AS is_mlc,
					CASE WHEN patientRegistration.is_vip = 'N' THEN false
					ELSE True 
                    END AS vip,
					false AS high_risk,
                    CASE WHEN discharge.status ilike 'A' then FALSE
                    ELSE TRUE 
                    END AS is_status,
					count(discharge.admission_id)
			FROM adt.t_admission  admission
			INNER JOIN adt.t_admission_details admissionDetails ON admissionDetails.admission_id = admission.admission_id
			INNER JOIN adt.m_admission_type_master admissionType ON admissionDetails.admission_type_id = admissionType.admission_type_id
			INNER JOIN public.m_visit_type_master visitType ON visitType.visit_type_id = admission.visit_type_id
			INNER JOIN doctor.m_speciality_master specialityMaster ON specialityMaster.speciality_id = admission.speciality_id
			LEFT JOIN adt.t_admission_note admissionNote ON admissionNote.admission_id = admission.admission_id
			LEFT JOIN adt.t_admission_patient_mapping admissionPatient ON admissionPatient.admission_note_id = admissionNote.admission_note_id
			INNER JOIN patient.t_patient_registration patientRegistration ON patientRegistration.patient_id = admission.patient_id
            INNER JOIN adt.t_discharge discharge on discharge.admission_id = admission.admission_id
			WHERE discharge.created_date IN 
				(SELECT  discharge.created_date FROM adt.t_discharge discharge
					WHERE (discharge.updated_date::DATE>=p_date OR discharge.created_date::DATE>=p_date)
					AND discharge.status = 'A') AND 	discharge.status = 'A'
			GROUP BY 
            admission.organization_id,
            admission.unit_id,
            discharge.discharge_date:: date,
			admission.admission_id,
			admissionDetails.admission_type_id, 
			admission.visit_type_id,
			admission.speciality_id,
			admission.doctor_id,
			discharge.discharge_type_id,
			admissionPatient.payment_entitlement_id,
			age,
			patientRegistration.gender_id,
			is_mlc,
			vip,
			high_risk,
            is_status
			order by discharge.discharge_date:: date;

END;
$$;


--
-- TOC entry 3799 (class 1255 OID 2969203)
-- Name: get_discount(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_discount(p_date date) RETURNS TABLE(date date, sale_type_id integer, bill_no character varying, user_id integer, reason_id integer, amount double precision, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT  (s.added_date):: date  as discount_date ,
					s.sale_type_id, 
					MAX(s.bill_no):: character varying  as bill_no , 
					s.added_by  as user_id,
					d.id  as reason_id, 
					sum(s.total_discount_amount) as amount,
					s.unit_id, 
					s.organization_id as hospital_id ,
					s.is_deleted
			from pharmacy.t_sale s
			JOIN  public.m_discount_category d on d.id = s.discount_category_id
			WHERE  s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>='2017-10-17 ' OR s.added_date::DATE>='2017-10-17 ')
                                                		  AND s.is_deleted = false)
                    		                        AND s.is_deleted = false
			group by 	s.added_date :: DATE  ,
						s.sale_type_id,
						s.added_by ,
						d.id,
						s.unit_id,
						s.organization_id,
						s.is_deleted
				order by  s.added_date :: DATE ;
END;

$$;


--
-- TOC entry 3800 (class 1255 OID 2969204)
-- Name: get_doctor_wise_age_wise_disease_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_doctor_wise_age_wise_disease_report(p_date date) RETURNS TABLE(doa date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, age_group_id integer, no_of_patient integer)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	ad.doa :: DATE,
						a.unit_id,
						a.organization_id as hospital_id,
						a.speciality_id,
						a.doctor_id,
						ca.diagnosis_id,
						EXTRACT(year from age(pr.dob)):: INTEGER as age_group_id,
						COUNT(a.patient_id) :: INTEGER as no_of_patient
				FROM  adt.t_admission a
				JOIN adt.t_admission_details ad ON ad.admission_id = a.admission_id
				JOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_id
				JOIN patient.t_patient_registration pr on  pr.patient_id = a.patient_id
				WHERE  ad.doa IN (SELECT ad.doa 
                                 FROM "adt".t_admission_details ad
                                                	WHERE(ad.updated_date::DATE>=p_date OR ad.created_date::DATE>=p_date)
                                                		  AND ad.status = 'A')AND ad.status = 'A'
				GROUP BY 	ad.doa,
							a.unit_id,
							a.organization_id,
							a.speciality_id,
							a.doctor_id,
							ca.diagnosis_id,
							age_group_id;
							
						END;
						$$;


--
-- TOC entry 3801 (class 1255 OID 2969205)
-- Name: get_drug_administration_delays(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_drug_administration_delays(p_date date) RETURNS TABLE(hospital_id integer, unit_id integer, delay_date timestamp without time zone, nursing_station_id integer, patient_id integer, gender_id integer, item_id integer, reason_id integer, user_id integer, time_gap time without time zone, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
RETURN QUERY SELECT  prescription.organization_id as hospital_id, 
                     prescription.unit_id,
                     prescription.added_date as delay_date,
                     admissionDetail.ward_id as nursing_station_id,
                     prescription.patient_id,
                     patient.gender_id,
                     prescriptionDetail.item_id, 
                     drugAdministrationDetail.reason_id, 
                     drugAdministrationDetail.added_by as user_id,
                     (frequencyDetail.administration_time - drugAdministrationDetail.administration_time):: time as time_gap ,
                     prescription.is_deleted
             FROM pharmacy.t_prescription  prescription
INNER JOIN pharmacy.t_prescription_detail prescriptionDetail ON prescription.id = prescriptionDetail.prescription_id
INNER JOIN pharmacy.t_prescription_frequency_detail prescriptionFrequency ON prescriptionDetail.id = prescriptionFrequency.prescription_detail_id 
INNER JOIN pharmacy.t_drug_administration drugAdministration ON drugAdministration.prescription_id = prescription.id
INNER JOIN pharmacy.t_drug_administration_detail drugAdministrationDetail ON drugAdministrationDetail.prescription_detail_id = prescriptionDetail.id
INNER JOIN adt.t_admission admission ON admission.admission_id = prescription.admission_id 
INNER JOIN adt.t_admission_details admissionDetail ON admission.admission_id = admissionDetail.admission_id
INNER JOIN patient.t_patient_registration patient ON patient.patient_id = prescription.patient_id 
INNER JOIN public.m_frequency frequency ON frequency.id = prescriptionFrequency.frequency_id
INNER JOIN public.m_frequency_detail frequencyDetail ON frequency.id = frequencyDetail.frequency_id

WHERE prescription.added_date::date IN (SELECT prescription.added_date::date
                                 FROM pharmacy.t_prescription grn 
                                                	WHERE(prescription.updated_date::DATE>= p_date OR prescription.added_date::DATE>= p_date)
                                                		  AND prescription.is_deleted = false)
                    		                        AND prescription.is_deleted = false
				
GROUP BY 
prescription.organization_id,
prescription.unit_id,
prescription.added_date,
admissionDetail.ward_id, 
prescription.patient_id,
patient.gender_id,
prescriptionDetail.item_id,
drugAdministrationDetail.reason_id,
drugAdministrationDetail.added_by,
(frequencyDetail.administration_time - drugAdministrationDetail.administration_time),
prescription.is_deleted;
      
END;

$$;


--
-- TOC entry 3803 (class 1255 OID 2969206)
-- Name: get_drug_consumption_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_drug_consumption_report(p_date date) RETURNS TABLE(drug_date date, visit_type_id integer, patient_id integer, doctor_id integer, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, unit_id integer, hospital_id integer, qty integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
RETURN QUERY	SELECT 	d.added_date :: date  as drug_date  ,  
						d.visit_type_id,
						d.patient_id,
						p.doctor_id,
						i.product_category_id,
						i.generic_id,
						i.id  brand_id,
						MAX(b.batch_no):: character varying,
						b.unit_id,
						b.organization_id as hospital_id ,
						COUNT(d.id):: integer  qty,
						d.is_deleted
				FROM pharmacy.t_drug_administration d
				JOIN pharmacy.t_drug_administration_detail da on da.drug_administration_id = d.id
				JOIN pharmacy.t_prescription_detail pd on pd.id = da.prescription_detail_id
				JOIN pharmacy.t_prescription p on p.id = pd.prescription_id
				JOIN public.m_item i on i.id = pd.item_id
				JOIN inventory.t_batch b on b.item_id = i.id
				WHERE d.added_date::date IN (SELECT d.added_date::date
                                 FROM pharmacy.t_drug_administration d
                                                	WHERE(d.updated_date::DATE>=p_date OR d.added_date::DATE>=p_date)
                                                		  AND d.is_deleted = false)
                    		                        AND d.is_deleted = false
				GROUP BY 	d.visit_type_id,
							d.patient_id,
							p.doctor_id,
							i.product_category_id,
							i.generic_id,
							i.id  ,
							b.unit_id,
							b.organization_id,
							d.added_date::date,
							d.is_deleted;
							END;
							
$$;


