--
-- TOC entry 3805 (class 1255 OID 2969208)
-- Name: get_er_72hrs_with_same_complaint(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_er_72hrs_with_same_complaint(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		a.unit_id,
		a.organization_id,
		a.patient_id,
		extract(year
	from
		age(pr.dob))::integer as patient_age,
		cad.diagnosis_id,
		true
	from
		adt.t_admission a
	join adt.t_admission_details ad
			using(admission_id)
	join adt.t_complaint_admission cad
			using(admission_id)
	join patient.t_patient_registration pr
			using (patient_id)
	where
		((a.updated_date::date >= p_date ::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
		and a.visit_type_id in (
			select visit_type_id
		from
			m_visit_type_master
		where
			visit_type_code = 'ER')
		and exists (
			select 1
		from
			adt.t_admission pa
		join adt.t_complaint_admission pcad
				using (admission_id)
		join adt.t_admission_details padm
				using (admission_id)
		join adt.t_discharge d
				using (admission_id)
		where
			pa.patient_id = a.patient_id
			and a.visit_type_id in (
				select visit_type_id
			from
				m_visit_type_master
			where
				visit_type_code = 'ER')
			and pcad.icpc_system_id = cad.icpc_system_id
			and padm.is_discharge = 'D'
			and padm.doa >= (ad.doa - ('72 hours')::interval)
			and ad.admission_id != padm.admission_id)
	group by
		a.patient_id,
		a.unit_id,
		a.organization_id,
		patient_age,
		cad.diagnosis_id
union select
		a.unit_id,
		a.organization_id,
		a.patient_id,
		extract(year
	from
		age(pr.dob))::integer as patient_age,
		cad.diagnosis_id,
		false
	from
		adt.t_admission a
	join adt.t_admission_details ad
			using(admission_id)
	join adt.t_complaint_admission cad
			using(admission_id)
	join patient.t_patient_registration pr
			using (patient_id)
	where
		((a.updated_date::date >= p_date ::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
		and a.visit_type_id in (
			select visit_type_id
		from
			m_visit_type_master
		where
			visit_type_code = 'ER')
	group by
		a.patient_id,
		a.unit_id,
		a.organization_id,
		patient_age,
		cad.diagnosis_id;
end;

$$;


--
-- TOC entry 3806 (class 1255 OID 2969209)
-- Name: get_expiry_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_expiry_report(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, product_category_id integer, store_id integer, generic_id integer, brand_id integer, expiry_date date, vendor_id integer, po_number character varying, grn_number character varying, grn_date date, uom_unit_id integer, quantity integer, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, scrapped boolean, batch_no character varying, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT 	b.unit_id,
						b.organization_id as hospital_id,
						i.product_category_id,
						po.store_id,
						i.generic_id,
						b.item_id brand_id,
						b.expiry_date,
						b.vendor_id,
						MAX(po.po_number):: character varying as po_number ,
						MAX(grn.grn_number) :: character varying as grn_number,
						grn.added_date::date grn_date,
						b.uom_unit_id,
						MAX(b.quantity):: integer as quantity ,
						sum(b.cop) cop,
						sum(b.rate) mrp,
						sum((b.quantity*b.cop)) as value_cop, 
						sum((b.quantity*b.rate)) as value_mrp,
						CASE WHEN srd.batch_id = b.id then True
						Else False
						END AS scrapped,
						MAX(b.batch_no):: character varying as batch_no,
						b.is_deleted
			FROM inventory.t_batch b
			JOIN public.m_item i on i.id = b.item_id
			LEFT JOIN procurement.t_purchase_order_detail pod on pod.item_id = i.id
			LEFT JOIN procurement.t_purchase_order po on po.id = pod.purchase_order_id
			LEFT JOIN procurement.t_good_receipt_note_detail grnd on grnd.batch_id = b.id
			LEFT JOIN procurement.t_good_receipt_note grn on grn.id = grnd.grn_id
			LEFT JOIN inventory.t_scrap_request_detail srd on srd.batch_id = b.id
			LEFT JOIN inventory.t_returnable_gatepass_detail rgd on rgd.batch_id = b.id
			LEFT JOIN inventory.t_returnable_gatepass rg on rg.id = rgd.returnable_gatepass_id 
			WHERE    b.expiry_date IN (SELECT  b.expiry_date
                                FROM   inventory.t_batch b
                                                	WHERE(b.updated_date::DATE>='2018-09-15 05:27:06.351' OR b.added_date::DATE>='2018-09-15 05:27:06.351')
                                                		  AND b.is_deleted = False)
                    		                        AND b  .is_deleted = False 
			GROUP BY 	i.product_category_id,
						po.store_id,
						i.generic_id,
						b.item_id,
						b.expiry_date,
						b.vendor_id,
						grn.added_date,
						b.uom_unit_id,
						scrapped,
						b.unit_id,
						b.is_deleted,
						b.organization_id;
					
		END;
		

$$;


--
-- TOC entry 3807 (class 1255 OID 2969210)
-- Name: get_hr_medi_stock(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_hr_medi_stock(p_date date) RETURNS TABLE(store_id integer, generic_id integer, brand_id integer, quantity integer, batch_no character varying, expiry_date date, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
 
RETURN QUERY	select  ss.store_id,
						im.generic_id,
						im.id as brand_id,
						sum(ss.available_qty):: integer as quantity,
						bm.batch_no,
						bm.expiry_date:: date,
						sum(bm.cop) as cop,
						sum(bm.rate ) as mrp,
						sum((bm.quantity*bm.cop)) as value_cop, 
						sum((bm.quantity*bm.rate)) as value_mrp,
						bm.unit_id, 
						bm.organization_id as hospital_id ,
						ss.is_deleted 
				from  inventory.t_batch bm 
	
	inner join  inventory.t_store_stock ss on ss.batch_id = bm.id
	inner join public.m_item im on bm.item_id = im.id 
	WHERE  im.is_high_risk_product = true AND  bm.expiry_date IN (SELECT bm.expiry_date
                                 FROM  inventory.t_batch bm
                                                	WHERE(bm.updated_date::DATE>='2017-10-17' OR bm.added_date::DATE>='2017-10-17')
                                                		  AND bm.is_deleted = false)
                    		                        AND bm.is_deleted = false
	group by  	ss.store_id,
				im.generic_id,
				im.id ,
				bm.batch_no,
				bm.expiry_date,
				bm.unit_id,
				ss.is_deleted,
				bm.organization_id;
END;
$$;


--
-- TOC entry 3809 (class 1255 OID 2969211)
-- Name: get_hr_medi_utili(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_hr_medi_utili(p_date date) RETURNS TABLE(nursing_station_id integer, date_consumption date, generic_id integer, brand_id integer, patient_id integer, doctor_id integer, batch_code character varying, quantity integer, staff_id integer, unit_id integer, organisation_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY select	nsm.nursing_station_id,
					s.added_date  :: date as date_consumption,
					im.generic_id,
					im.id as brand_id,
					s.patient_id,
					p.doctor_id,
					MAX(bm.batch_no):: character varying  as batch_no,
					sum(sd.quantity) :: integer as quantity,
					bm.added_by as user_id ,
					bm.unit_id,
					bm.organization_id,
					bm.is_deleted
        from inventory.t_batch bm 
		join pharmacy.t_sale_detail sd on sd.batch_id = bm.id
		join pharmacy.t_sale s on sd.sale_id = s.id
		join pharmacy.t_prescription p on p.id = s.prescription_id
		join adt.t_admission a on p.visit_type_id = a.visit_type_id 
		join adt.t_admission_details ad on a.admission_id = ad.admission_id
		join adt.t_nursing_station_ward_mapper nsm on ad.ward_id = nsm.ward_id
		join public.m_item im on bm.item_id = im.id 
		WHERE  im.is_high_risk_product = true AND  bm.expiry_date IN (SELECT bm.expiry_date
                                 FROM  inventory.t_batch bm
                                                	WHERE(bm.updated_date::DATE>=p_date OR bm.added_date::DATE>=p_date)
                                                		  AND bm.is_deleted = false)
                    		                        AND bm.is_deleted = false
		group by nsm.nursing_station_id,
				s.added_date,
				im.generic_id,
				brand_id,
				s.patient_id,
				p.doctor_id,
				user_id ,
				bm.unit_id,
				bm.organization_id,
				bm.is_deleted;
				END;

$$;


--
-- TOC entry 3810 (class 1255 OID 2969212)
-- Name: get_icu_48hrs(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_icu_48hrs(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)
    LANGUAGE plpgsql
    AS $$ 
begin
	return QUERY select  a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,true  
from adt.t_admission a 
join adt.t_admission_details ad using(admission_id)
join adt.t_transfer_request tr using (admission_id)
join adt.t_complaint_admission cad using (admission_id)
where tr.transfer_type_id = 3
and ((tr.updated_date::date >= p_date ::date and tr.updated_date::date < current_date)
		or (tr.created_date::date >= p_date::date and tr.created_date::date < current_date))
and exists (select 1 from adt.t_admission pa 
            join adt.t_admission_details prad using(admission_id)
			join adt.t_transfer_request ptr using (admission_id)
			join adt.t_transfer t using(transfer_request_id)
            where pa.patient_id = a.patient_id
            and t.from_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')
            and t.from_date >= (tr.created_date - ('48 hours')::interval)
            and ad.admission_id = prad.admission_id)
group by a.patient_id, 
		 a.unit_id,
		 a.organization_id,
	     a.speciality_id,
	     cad.diagnosis_id
union
	--total discharge from icu            
	select a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,false 
	from adt.t_admission a 
	join adt.t_admission_details ad using(admission_id)
	join adt.t_transfer_request tr using (admission_id)
	join adt.t_complaint_admission cad using (admission_id) 
	where ad.is_discharge = 'D'
	and tr.from_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')
	and ((tr.updated_date::date >= p_date ::date and tr.updated_date::date < current_date)
		or (tr.created_date::date >= p_date::date and tr.created_date::date < current_date))
    group by a.patient_id, 
		 a.unit_id,
		 a.organization_id,
	     a.speciality_id,
	     cad.diagnosis_id
union
	--total transfers to icu
	select a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,false 
	from adt.t_admission a 
	join adt.t_admission_details ad using(admission_id)
	join adt.t_transfer_request tr using (admission_id)
	join adt.t_complaint_admission cad using (admission_id)
	where tr.to_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')
	and tr.transfer_type_id = 3
	and ((tr.updated_date::date >= p_date ::date and tr.updated_date::date < current_date)
		or (tr.created_date::date >= p_date::date and tr.created_date::date < current_date))
     group by a.patient_id, 
		 a.unit_id,
		 a.organization_id,
	     a.speciality_id,
	     cad.diagnosis_id;
end;
$$;


--
-- TOC entry 3811 (class 1255 OID 2969213)
-- Name: get_inpatient_charges(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_inpatient_charges(p_date date) RETURNS TABLE(unit_id integer, organziation_id integer, service_rendered_date date, servcie_group_id integer, doctor_id integer, speciality_id integer, patient_id integer, service_master_id integer, sum double precision, status character)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY	SELECT  a.unit_id,
						a.organization_id,
						od.ord_render_datetime::date as service_rendered_date,
						sm.speciality_id  as service_group_id ,
						a.doctor_id ,
						a.speciality_id,
						om.patient_id,
						sm.service_master_id,
						sum(od.net_amount):: double precision,
						od.status
				FROM  public.t_order_details od
				JOIN service.m_service_master  sm on od.service_id = sm.service_master_id
				JOIN public.t_order_master om on od.order_id = om.order_id
				JOIN adt.t_admission a on om.admission_id = a.admission_id
				WHERE om.visit_type_id >1 AND 
				od.service_rendered = 1 AND (om.admission_id NOT IN (SELECT bm.admission_id
				from billing.m_billing_master bm WHERE bm.admission_id is NOT NULL))
				AND od.ord_render_datetime::date IN (SELECT od.ord_render_datetime::date
                                 FROM  public.t_order_details od
                                                	WHERE(od.updated_date::DATE>=p_date OR od.created_date::DATE>=p_date)
                                                		  AND od.status = 'A') AND od.status = 'A'
				GROUP BY service_group_id ,
						a.doctor_id ,
						a.speciality_id,
						om.patient_id,
						sm.service_master_id,
						service_rendered_date,
		 				a.unit_id,
						od.status,
						a.organization_id;
		END;
		$$;


