--

CREATE FUNCTION procedure_old.get_master_user(p_date date) RETURNS TABLE(user_id integer, unit_id integer, hopsital_id integer, user_name character varying, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
RETURN QUERY  
	SELECT  um.user_id,
			um.unit_id,
			um.organization_id as hopsital_id, 
			um.user_name,
			um.status
	FROM public.m_user_master um
	WHERE (um.updated_date::date >= p_date and um.updated_date::date < current_date) 
