--
-- TOC entry 3829 (class 1255 OID 2969233)
-- Name: get_masters_bi_admission(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_masters_bi_admission(p_date date) RETURNS TABLE(admission_id integer, organization_id integer, unit_id integer, patient_id integer, admission_number character varying, visit_type_id integer, doctor_id integer, speciality_id integer, admission_details_id integer, admission_type_id integer, ward_id integer, floor_id integer, bed_id integer, bed_category_id integer, is_discharge character, is_high_risk character, is_medico_legal character, doa timestamp without time zone, pdd timestamp without time zone, future_discharge_date timestamp without time zone, status character, updated_date timestamp without time zone, created_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 

        SELECT 	a.admission_id, 
				a.organization_id,
				a.unit_id, 
				a.patient_id,
		        a.admission_number,
				a.visit_type_id, 
        		
				a.doctor_id,
				a.speciality_id,
				ad.admission_details_id,
				ad.admission_type_id, 
				ad.ward_id,
				ad.floor_id, 
				ad.bed_id,
				ad.bed_category_id,
				ad.is_discharge, 
				ad.is_high_risk, 
				ad.is_medico_legal,
				ad.doa, 
				ad.pdd, 
				ad.future_discharge_date,
				a.status,
				a.updated_date,
				a.created_date
		FROM adt.t_admission a
		JOIN  adt.t_admission_details ad on a.admission_id = ad.admission_id
		WHERE  a.created_date IN (SELECT  a.created_date
                                FROM adt.t_admission a
                                                	WHERE(a.updated_date::DATE>=p_date OR a.created_date::DATE>=p_date)
                                                		  AND a.status = 'A')
                    		                        AND a.status = 'A'
		ORDER BY 	a.admission_id;

END;

$$;


