--
-- TOC entry 3857 (class 1255 OID 2969261)
-- Name: get_morgue_utilization(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_morgue_utilization(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, morgue_number character varying, patient_id integer, kin_name character varying, phone_no character varying, occupied_date_time timestamp without time zone, expected_release_date_time timestamp without time zone, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	mr.unit_id,
						mr.organization_id,
						bed_number as morgue_number,
						mr.patient_id ,
						kd.kin_name,
						kd.phone_no,
						mr.created_date as occupied_date_time ,
						make_timestamp(EXTRACT(year from mr.expected_release_date):: integer  ,
									EXTRACT(month from mr.expected_release_date) :: integer  ,
									EXTRACT(day from mr.expected_release_date) :: integer ,
									EXTRACT(hour from mr.expected_release_time) :: integer,
									EXTRACT(minute from mr.expected_release_time) :: integer ,
									EXTRACT(second from mr.expected_release_time)) as expected_release_date_time,
									mr.status
				FROM  adt.t_mortuary_request mr 
				JOIN adt.m_bed_master bm on bm.bed_id = mr.mortuary_bed_id
				JOIN adt.t_admission a on a.admission_id = mr.admission_id
				JOIN patient.t_patient_registration pr on pr.patient_id = mr.patient_id
				JOIN public.m_kin_details kd on kd.kin_id = mr.admission_kin_id
				WHERE  mr.created_date  IN (SELECT mr.created_date FROM adt.t_mortuary_request mr 
            							WHERE  (mr.updated_date::DATE>=p_date OR mr.created_date::DATE>=p_date)
												AND mr.status = 'A')
										AND mr.status = 'A'
				GROUP BY 	bm.bed_number,
							mr.patient_id ,
							kd.kin_name,
							kd.phone_no,
							mr.created_date ,
							mr.unit_id,
							mr.organization_id,
							mr.status,
							expected_release_date_time;
							
		END;
		$$;


--
-- TOC entry 3858 (class 1255 OID 2969262)
-- Name: get_mortality_register(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_mortality_register(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, is_death character, reason_id integer, date timestamp without time zone, status character)
    LANGUAGE plpgsql
    AS $$ 
 Begin
 Return 	query	 
       		SELECT at.unit_id,at.organization_id,at.patient_id,ad.doctor_id,sdm.speciality_id,aca.diagnosis_id,ad.is_death,ad.reason_id,ad.discharge_date,ad.status
			FROM adt.t_admission at
			JOIN adt.t_discharge ad on at.admission_id=ad.admission_id and at.organization_id=ad.organization_id
			JOIN adt.t_complaint_admission aca on aca.admission_id=at.admission_id and aca.organization_id=at.organization_id
			JOIN doctor.t_doctor_speciality_mapper sdm on sdm.doctor_id=ad.doctor_id
			WHERE  ad.discharge_date::date >= p_date::date and ad.discharge_date::date < current_date
			GROUP BY at.unit_id,at.organization_id,at.patient_id,ad.doctor_id,sdm.speciality_id,aca.diagnosis_id,ad.is_death,ad.reason_id,ad.discharge_date,ad.status
			ORDER BY ad.discharge_date	;
			
end;
$$;


--
-- TOC entry 3859 (class 1255 OID 2969263)
-- Name: get_mortuary_utilization(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_mortuary_utilization(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, occupied_on_date date, expected_release_date date, morgue_number character varying, patient_id integer, kin_id integer, status character)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		ad.unit_id,
		ad.organization_id,
		ad.expected_arrival_date::date,
		ad.expected_release_date::date,
		ad.toe_band_id,
		kd.death_registration_id,
		kd.kin_id,
		ad.status
	from
		adt.t_mortuary_request ad
		inner join patient.t_death_registration kd on
        ad.d_patient_id=kd.death_registration_id
       -- inner join adt.t_mortuary_request mr on
       -- ad.admission_id=mr.admission_id
	where
		((ad.updated_date::date >= p_date
		and ad.updated_date::date < current_date)
		or (ad.created_date::date >= p_date
		and ad.created_date::date < current_date))
	group by
		ad.unit_id,
		ad.organization_id,
		ad.expected_arrival_date,
		ad.expected_release_date,
		ad.toe_band_id,
		kd.death_registration_id,
		kd.kin_id,
		ad.status;
end;

$$;


