CREATE FUNCTION procedure_old.get_no_show_cases(p_date date) RETURNS TABLE(appointment_date timestamp without time zone, organization_id integer, unit_id integer, speciality_id integer, doctor_id integer, patient_id integer, status boolean, count integer)
    LANGUAGE plpgsql
    AS $$

BEGIN
RETURN QUERY 
		select opd.created_date, opd.organization_id, opd.unit_id,  sm.speciality_id, sm.doctor_id, opd.patient_id, 'false':: boolean, count(opd.patient_id):: Int
		from opd.m_appointment_master opd
		JOIN opd.m_slot_master sm ON sm.slot_id = opd.slot_id and sm.status ='A'
		where opd.appointment_status_id = 7
        AND opd.created_date IN (SELECT opd.created_date
                                 FROM opd.m_appointment_master opd
                                                	WHERE(opd.updated_date::DATE>=p_date OR opd.created_date::DATE>=p_date)
                                                		  AND opd.status = 'A')
		group by 
        opd.created_date, opd.organization_id, opd.unit_id,  sm.speciality_id, sm.doctor_id, opd.patient_id ;

END;

$$;


--
-- TOC entry 3861 (class 1255 OID 2969265)
-- Name: get_non_billable_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_non_billable_report(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, added_date date, ward_id integer, user_id integer, product_category_id integer, generic_id integer, batch_no character varying, cost double precision, amount double precision, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	nbc.unit_id,
				nbc.organization_id as hospital_id ,
				nbc.added_date:: date, 
				nbc.ward_id ,
				nbc.added_by  user_id,
				i.product_category_id ,
				i.generic_id,
				MAX(b.batch_no):: character varying as batch_no,
				SUM(b.rate) as  cost,
				SUM(nbcd.accepted_qty * b.rate) as amount,
				nbc.is_deleted 
		FROM inventory.t_non_billable_consumption nbc
		JOIN inventory.t_non_billable_consumption_detail nbcd  on nbcd.non_billable_consumption_id = nbc.id
		JOIN inventory.t_batch b on b.id = nbcd.batch_id
		JOIN public.m_item i on i.id = b.item_id
		WHERE nbc.added_date IN (SELECT nbc.added_date
                                 FROM  inventory.t_non_billable_consumption nbc
                                                	WHERE(nbc.updated_date::DATE>=p_date OR nbc.added_date::DATE>=p_date)
                                                		  AND nbc.is_deleted = false)
                    		                        AND nbc.is_deleted = false
		
		GROUP BY 	nbc.added_date:: date, 
					nbc.ward_id ,
					nbc.added_by,
					i.product_category_id ,
					i.generic_id,
					nbc.unit_id,
					nbc.is_deleted,
					nbc.organization_id;
				END;
				
$$;


--
-- TOC entry 3862 (class 1255 OID 2969266)
-- Name: get_notifiable_disease(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_notifiable_disease(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, appointment_date date, no_of_disease_diagnosed integer, diagnosis_id integer, patient_id integer, status boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	em.unit_id,
							em.organization_id as hospital_id,
							opd.created_date :: DATE as  appointment_date,
							COUNT(pd.diagnosis_id) :: INTEGER as no_of_disease_diagnosed ,
							pd.diagnosis_id,
							em.patient_id,
							'false':: boolean
				from opd.t_encounter_master em
                JOIN opd.m_appointment_master opd on em.appointment_id = opd.appointment_id
				JOIN patient.t_patient_diagnosis_appo_mapper pd on pd.encounter_id = em.encounter_id 
                JOIN patient.diagnosis_master dm on dm.diagnosis_id = pd.diagnosis_id
				WHERE em.encounter_date IN (SELECT  em.encounter_date FROM opd.t_encounter_master em
											WHERE (em.updated_date::DATE>=p_date OR em.created_date::DATE>=p_date)
                                             AND em.status = 'A') AND 	em.status = 'A'
				GROUP BY 	opd.created_date :: DATE,
							pd.diagnosis_id,
							em.patient_id,
							em.unit_id,
							em.organization_id;
							

						
						
END ;  

						
$$;


