--
-- TOC entry 3867 (class 1255 OID 2969271)
-- Name: get_overbooked_appointments(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_overbooked_appointments(p_date date) RETURNS TABLE(dept_id integer, doctor_id integer, patient_id integer, appointment_type_id integer, unit_id integer, hospital_id integer, encounter_date date, overbooked_status character varying, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	em.dept_id, 
						em.doctor_id,
						em.patient_id,
						am.appointment_type_id,
						em.unit_id ,
						em.organization_id as hospital_id,
						em.encounter_date :: DATE,
						CASE WHEN (COUNT(am.slot_id) > 1)  THEN 'overbooked'
						ELSE 'not_overbooked' :: CHARACTER VARYING
						END as overbooked_status,
						em.status
				FROM opd.t_encounter_master em
				JOIN opd.m_appointment_master am ON am.appointment_id = em.appointment_id
				WHERE  em.encounter_date IN (SELECT em.encounter_date
                                 FROM opd.t_encounter_master em
                                                	WHERE(em.updated_date::DATE>=p_date OR em.created_date::DATE>=p_date)
                                                		  AND em.status = 'A') AND em.status = 'A'
				GROUP BY 
						em.dept_id, 
						em.doctor_id,
						em.patient_id,
						am.appointment_type_id,
						em.status,
						em.unit_id ,
						em.organization_id,
						em.encounter_date :: DATE;
						END;
						$$;


