CREATE FUNCTION procedure_old.get_patient_billing_for_admitted_patient(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, nursing_station_id integer, patient_id integer, bed_number character varying, service_group integer, service_standard_name character varying, status character, sum double precision)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY  SELECT 	a.unit_id,
						a.organization_id,
						n.nursing_station_id ,
 						a.patient_id ,
						bm.bed_number,
						sm.speciality_id as service_group,
						sm.service_standard_name,
						sm.status,
		 				sum(b.net_amount)
						
			FROM billing.m_billing_master b
			JOIN billing.t_billing_details bd on b.billing_master_id = bd.billing_master_id  
			JOIN adt.t_admission a on a.admission_id =  b.admission_id
			JOIN service.m_service_master sm on sm.service_master_id = bd.service_id
			LEFT JOIN adt.t_admission_details ad on ad.admission_id =  a.admission_id
			LEFT JOIN adt.m_bed_master bm on bm.bed_id = ad.bed_id
			LEFT JOIN adt.t_nursing_station_ward_mapper n on ad.ward_id = n.ward_id
			 WHERE b.bill_date_time::date  IN (SELECT b.bill_date_time::date
                                 FROM  billing.m_billing_master b
                                                	WHERE(b.updated_date::DATE>=p_date OR b.created_date::DATE>=p_date)
                                                		  AND b.status = 'A')AND b.status = 'A'
			GROUP BY n.nursing_station_id ,
 					a.patient_id ,
					bm.bed_number,
					sm.speciality_id ,
					sm.service_standard_name,
					sm.status,
					a.unit_id,
					a.organization_id;
	
END;

$$;


--
-- TOC entry 3869 (class 1255 OID 2969273)
-- Name: get_patient_category_wise_billing_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_category_wise_billing_report(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, bill_date_time date, bill_number character varying, visit_type_id integer, patient_id integer, patient_type_id integer, sum double precision, status "char")
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT 	pr.unit_id ,
						pr.organization_id,
						b.bill_date_time::date ,
						b.bill_number,
						b.visit_type_id,
 						b.patient_id,
						pcm.patient_category_id,
  						sum(b.net_amount),
						b.status
 		FROM billing.m_billing_master b
 		JOIN patient.t_patient_registration pr on b.patient_id = pr.patient_id
 		JOIN public.m_patient_category_master pcm on pcm.patient_category_id = pr.patient_category_id
		WHERE  	b.bill_date_time::date  IN (SELECT 	b.bill_date_time::date
                                 FROM billing.m_billing_master b
                                                	WHERE(b.updated_date::DATE>=p_date OR b.created_date::DATE>=p_date)
                                                		  AND b.status = 'A')
                    		                        AND b.status = 'A'
 		GROUP BY 	b.bill_date_time::date ,
 					b.bill_number,
					b.visit_type_id,
 					b.patient_id,
					b.status,
 				pcm.patient_category_id,
					pr.unit_id ,
					pr.organization_id;
					END;
					$$;


--
