--
-- TOC entry 3871 (class 1255 OID 2969275)
-- Name: get_patient_returns_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_returns_report(p_date date) RETURNS TABLE(return_date date, sale_type_id integer, bill_no character varying, bill_date date, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, return_qty integer, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, reason text, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT r.added_date :: date as return_date,
					s.sale_type_id,
					MAX(s.bill_no) :: character varying as bill_no,
					s.added_date :: date as bill_date,
					g.product_category_id,
					im.generic_id,
					im.id as brand_id,
					MAX(b.batch_no) :: character varying as  batch_no ,
					sum(rd.return_qty)::integer as return_qty ,
					sum(b.cop) as cop,
					sum(b.rate ) as mrp,
					sum((b.quantity*b.cop)) as value_cop, 
					sum((b.quantity*b.rate)) as value_mrp,
					MAX(rd.remark)::text as reason,
					r.unit_id,
					r.organization_id as hospital_id,
					s.is_deleted
					FROM pharmacy.t_sale s 
			
			
			JOIN pharmacy.t_sale_detail sd on sd.sale_id = s.id
			JOIN inventory.t_batch b on  sd.batch_id = b.id
			JOIN pharmacy.t_return  r on  r.sale_id = s.id 
			JOIN pharmacy.t_return_detail rd on rd.return_id = r.id
			JOIN public.m_item im on b.item_id = im.id
			JOIN public.m_generic g on g.id = im.generic_id
			WHERE r.added_date IN (SELECT r.added_date
                                 FROM  pharmacy.t_return  r
                                                	WHERE(r.updated_date::DATE>=p_date OR r.added_date::DATE>=p_date)
                                                		  AND r.is_deleted = false)
                    		                        AND r.is_deleted = false
			GROUP BY return_date,
					s.sale_type_id,
					bill_date,
					g.product_category_id,
					im.generic_id,
					brand_id,
					r.unit_id,
					r.organization_id,
					s.is_deleted;
					END;

$$;


--
-- TOC entry 3872 (class 1255 OID 2969276)
-- Name: get_patient_sales(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_sales(p_date date) RETURNS TABLE(date date, store_id integer, generic_id integer, product_category_id integer, quantity integer, bill_no character varying, batch_code character varying, visit_type_id integer, mrp double precision, amount double precision, unit_id integer, organisation_id integer, is_deleted boolean, total_sale integer, brand_id integer, patient_id integer)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT s.added_date ::date as date ,
					s.store_id,
					i.generic_id,
					g.product_category_id,
					SUM(sd.quantity):: integer as quantity,
					s.bill_no:: character varying as bill_no ,
					b.batch_no:: character varying as batch_no,
					s.visit_type_id,
					SUM(sd.rate) as mrp,
					SUM(sd.net_amount) as amount,
					sd.unit_id,
					sd.organization_id,
					s.is_deleted ,
					COUNT(DISTINCT s.id) ::integer as total_sale,
                    i.id as brandId,
                    s.patient_id
			FROM pharmacy.t_sale s
			JOIN pharmacy.t_sale_detail sd on sd.sale_id = s.id
			JOIN inventory.t_batch b on  sd.batch_id = b.id
			JOIN public.m_item i on i.id = b.item_id
			JOIN public.m_generic g on g.id = i.generic_id
			WHERE s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE >= '2017-10-17' OR s.added_date::DATE >= '2018-10-17')
                                                		  AND s.is_deleted = false)
                    		                        AND s.is_deleted = false
			group by
				s.added_date :: date,
				s.store_id,
				i.id,
                s.patient_id,
				s.is_deleted ,
				s.visit_type_id,
				i.generic_id,
				g.product_category_id,
				sd.unit_id,
				sd.organization_id,
                s.bill_no,
				b.batch_no;
					
					
					END;

$$;


--
-- TOC entry 3874 (class 1255 OID 2969277)
-- Name: get_patient_statistics(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_statistics(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, registration_date date, city_id integer, state_id integer, country_id integer, gender_id integer, patient_category_id integer, patient_id integer, age integer, patient_statistics integer, status character)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
		pd.unit_id,
		pd.organization_id,
		pr.created_date :: date registration_date ,
		pd.city_id,
		pd.state_id,
		pd.country_id,
		pr.gender_id ,
		pr.patient_category_id,
		pr.patient_id,
		extract (year
	from
		age(pr.dob)):: integer as age,
		count(distinct coalesce( pr.patient_id, 0)) :: integer as patient_statistics,
		pr.status
	from
		patient.t_patient_registration pr
	join patient.t_patient_details pd on
		pd.patient_id = pr.patient_id
	where
		((pr.updated_date::date >= p_date
		and pr.updated_date::date < current_date)
		or (pr.created_date::date >= p_date
		and pr.created_date::date < current_date))
		and pr.registration_type_id = 1
	group by
		pr.created_date,
		pd.unit_id,
		pd.organization_id,
		pd.city_id,
		pd.state_id,
		pd.country_id,
		pr.patient_id,
		pr.patient_category_id,
		pr.gender_id,
		pr.status ,
		age;
end;

$$;


--
-- TOC entry 3875 (class 1255 OID 2969278)
-- Name: get_patient_transfer_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_transfer_analysis(p_date date) RETURNS TABLE(from_date date, unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, transfer integer, bedcategorychange integer, count integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT  	t.from_date :: date,
						a.unit_id,
						a.organization_id,
						a.doctor_id,
						a.speciality_id, 
						CASE  
						WHEN f_ward.is_icu = 'N' AND t_ward.is_icu = 'N' THEN 1
						WHEN f_ward.is_icu = 'Y' AND t_ward.is_icu = 'N' THEN 3
						WHEN f_ward.is_icu = 'N' AND t_ward.is_icu = 'Y' THEN 2
						END AS Transfer,
						CASE 
						WHEN frombed.hierarchy_id > tobed.hierarchy_id THEN 1
		          		WHEN  frombed.hierarchy_id < tobed.hierarchy_id THEN 2
						WHEN frombed.hierarchy_id = tobed.hierarchy_id THEN  3
						END as BedCategoryChange,
						COUNT(DISTINCT a.patient_id):: integer,
						case when t.status ='A' then false
						else true 
						end as is_deleted
        from "adt".t_transfer t
        JOIN "adt".t_admission a ON t.admission_id = a.admission_id 
 		join "adt".t_admission_details ad ON t.admission_id = ad.admission_id 
 		JOIN "adt".m_ward_master f_ward ON t.from_ward_id = f_ward.ward_id
 		JOIN "adt".m_ward_master t_ward ON t.to_ward_id = t_ward.ward_id
 		JOIN (select bcm.hierarchy_id, t.from_bed_category_id, t.admission_id from adt.t_transfer t 
 		JOIN adt.m_bed_category_master bcm ON t.from_bed_category_id = bcm.bed_category_id) frombed ON  a.admission_id = frombed.admission_id  
 		JOIN(select bcm.hierarchy_id, t.to_bed_category_id, t.admission_id from adt.t_transfer t 
 		JOIN adt.m_bed_category_master bcm ON t.to_bed_category_id = bcm.bed_category_id) tobed ON tobed.admission_id = a.admission_id  	
        WHERE ad.doa IN (SELECT ad.doa FROM "adt".t_admission_details 
        WHERE (t.updated_date :: DATE >= '2018-12-01' OR t.created_date :: DATE >= '2018-12-01 ' AND t.status = 'A')) 
		
				
				GROUP BY
				t.from_date :: date,
				a.unit_id,
				a.organization_id,
				a.doctor_id,
				a.speciality_id,
				t.from_ward_id, 
				t.to_ward_id,
				Transfer,
 				BedCategoryChange,
				is_deleted;
END;

$$;


--
-- TOC entry 3876 (class 1255 OID 2969279)
-- Name: get_patient_wise_transaction_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_patient_wise_transaction_report(p_date date) RETURNS TABLE(org_unit_id integer, org_id integer, ord_render_datetime date, service_standard_code character varying, service_standard_name character varying, service_group_id integer, ord_doc_id integer, visit_type_id integer, patient_id integer, sum double precision, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT  od.org_unit_id,
						od.org_id,
						od.ord_render_datetime::date,	
			        	sm.service_standard_code,
        				sm.service_standard_name,
						sm.speciality_id as service_group_id,
	    				od.ord_doc_id,
						om.visit_type_id,
						om.patient_id,
						sum(od.net_amount):: double precision,
						sm.status
			FROM   service.m_service_master sm
			JOIN public.t_order_details od on od.service_id = sm.service_master_id
			JOIN public.t_order_master om on om.order_id = od.order_id
			WHERE  od.ord_render_datetime::date	 IN (SELECT od.ord_render_datetime::date
                                FROM   public.t_order_details od
                                                	WHERE(od.updated_date::DATE>=p_date OR od.created_date::DATE>=p_date)
                                                		  AND od.status = 'A')
                    		                        AND od.status = 'A'
			GROUP BY   	od.org_unit_id,
						od.org_id,
						od.ord_render_datetime::date,		
						sm.service_standard_code,
        				sm.service_standard_name,
						sm.speciality_id,
	    				od.ord_doc_id,
						om.visit_type_id,
						sm.status,
						om.patient_id;
		END;
		$$;


--
-- TOC entry 3877 (class 1255 OID 2969280)
-- Name: get_pending_prescription_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_pending_prescription_report(p_date date) RETURNS TABLE(destination_store integer, nursing_station_id integer, patient_id integer, bed_id integer, priority_id integer, doctor_id integer, prescription_date date, product_category_id integer, generic_id integer, qty_supplied bigint, qty_prescribed bigint, pending_qty bigint, agening text, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 		select 	pd.store_id as destination_store,
							nsm.nursing_station_id,
							psm.patient_id ,
							ad.bed_id,
							pm.priority_id,
							psm.doctor_id,
							pm.prescription_date :: date,
							g.product_category_id,
							i.generic_id,
							sum(psd.quantity) as qty_supplied ,
							sum(pd.order_qty )  as qty_prescribed,
							sum(pd.pending_qty)  as pending_qty,
							(now()::date - date(pm.prescription_date)) ||' '|| 'days' :: character varying as agening,
							pd.unit_id,
							pd.organization_id as hospital_id ,
							pm.is_deleted
				from pharmacy.t_sale psm 
				JOIN pharmacy.t_sale_detail psd on psd.sale_id = psm.id
				JOIN pharmacy.t_prescription_detail pd on pd.id = psd.prescription_detail_id
				JOIN pharmacy.t_prescription pm on pm.id = pd.prescription_id
				JOIN public.m_item i on pd.item_id = i.id
				JOIN public.m_generic g on g.id = i.generic_id
				JOIN adt.t_admission a on pm.visit_type_id = a.visit_type_id 
				JOIN adt.t_admission_details ad on a.admission_id = ad.admission_id
				JOIN adt.t_nursing_station_ward_mapper nsm on ad.ward_id = nsm.ward_id
				WHERE pm.prescription_date IN (SELECT pm.prescription_date
                                from pharmacy.t_prescription pm
                                                	WHERE(pm.updated_date::DATE>=p_date OR pm.added_date::DATE>=p_date)
                                                		  AND pm.is_deleted = false)
                    		                        AND pm.is_deleted =  false
				group by pd.store_id,
						nsm.nursing_station_id,
						psm.patient_id ,
						ad.bed_id,
						pm.priority_id,
						psm.doctor_id,
						pd.item_id,
						pm.prescription_date,
						g.product_category_id,
						i.generic_id,
						pd.unit_id,
						pm.is_deleted,
						pd.organization_id;
						END;

$$;


--
-- TOC entry 3878 (class 1255 OID 2969281)
-- Name: get_pending_store_indent_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_pending_store_indent_report(p_date date) RETURNS TABLE(indenting_store integer, destination_store integer, indent_date date, indent_no character varying, priority_id integer, brand_id integer, product_category_id integer, generic_id integer, indent_quantity integer, qty_supplied integer, pending_quantity integer, agening character varying, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

	DECLARE

	BEGIN
 
	RETURN QUERY 
				select 	sim.from_store_id as indenting_store,
						sim.to_store_id as destination_store,
						sim.added_date :: date as indent_date,
						sim.indent_no,
						sim.priority_id,
						sid.item_id as brand_id,
						g.product_category_id,
						im.generic_id,
						sum(sid.indent_quantity) :: integer as indent_quantity,
						sum(sid.authorized_quantity):: integer as qty_supplied,
						sum(sid.pending_quantity) :: integer as pending_quantity,
						CAST((now()::date - date(sid.added_date)) ||' '|| 'days' as character varying)  as agening,
						sim.unit_id,
						sim.organization_id as hospital_id ,
						sim.is_deleted
	from inventory.t_store_indent sim
	JOIN inventory.t_store_indent_detail sid on sim.id = sid.store_indent_id
	JOIN public.m_item im on sid.item_id = im.id
	JOIN public.m_generic g on g.id = im.generic_id
	WHERE sim.added_date IN (SELECT sim.added_date
                                from inventory.t_store_indent sim
                                                	WHERE(sim.updated_date::DATE>=p_date OR sim.added_date::DATE>=p_date)
                                                		  AND sim.is_deleted = false)
                    		                        AND sim.is_deleted = false
GROUP BY 	
			g.product_category_id,
			im.generic_id,
			sim.from_store_id,
			sim.to_store_id,
			sim.added_date,
			sim.indent_no,
			sim.priority_id,
			brand_id,
			sim.is_deleted,
			sid.added_date :: date ,
			sim.unit_id,
			sim.organization_id;
END;

$$;


--
-- TOC entry 3879 (class 1255 OID 2969282)
-- Name: get_product_category__stock(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_product_category__stock(p_date date) RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, category character varying, generic_id integer, stock_count integer, is_deleted boolean, total_count integer)
    LANGUAGE plpgsql
    AS $$ declare
begin
	 Select ss.added_date::date as stock_date,
					ss.unit_id,
					ss.organization_id as hospital_id,
					ss.store_id,
					g.product_category_id,
					p.category,
					i.generic_id,
					SUM(  ss.available_qty):: integer as stock_count,
					ss.is_deleted,
					count(ss.id) as total_count 
			from inventory.t_store_stock ss 
	join inventory.t_batch b on b.id = ss.batch_idc
	join public.m_item i on i.id = b.item_id
	join public.m_generic g on g.id = i.generic_id 
	join public.m_product_category p on p.id = g.product_category_id
		WHERE  ss. added_date IN (SELECT ss.added_date
                                 FROM inventory.t_store_stock ss
                                                	WHERE(ss.updated_date::DATE>=p_date OR ss.added_date::DATE>=p_date)
                                                		  AND ss.is_deleted = False)
                    		                        AND ss.is_deleted = false
    	GROUP BY 
		ss.unit_id,
		ss.organization_id,
		ss.store_id,
		g.product_category_id,
		p.category,
		i.generic_id,
		ss.is_deleted,
		cast(ss.added_date as date)
	order by cast(ss.added_date as date) asc;
	
end;

$$;


--
-- TOC entry 3880 (class 1255 OID 2969283)
-- Name: get_product_category_sales(); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_product_category_sales() RETURNS TABLE(id integer, category character varying, type character varying, sale_type_id integer, unit_id integer, hospital_id integer, sales_count integer, sales_date date, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ DECLARE
BEGIN
 		 select  p.id,
			p.category,
			st."type" ,
			s.sale_type_id,
			s.unit_id,
			s.organization_id as hospital_id,
			COUNT(DISTINCT sd.quantity):: integer as sales_count,
			s.added_date :: date as sales_date,
			s.is_deleted
	from public.m_product_category p
  join public.m_generic g  on p.id= g.product_category_id
  join public.m_item i on i.generic_id = g.id
  join inventory.t_batch b on  b.item_id = i.id
  join pharmacy.t_sale_detail sd on sd.batch_id = b.id 
  join pharmacy.t_sale s on s.id = sd.sale_id 
  join pharmacy.m_sale_type st on st.id = s.sale_type_id
  WHERE s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>='2019-01-01' OR s.added_date::DATE>='2019-07-12')
                                                		  AND s.is_deleted = FALSE)
                    		                        AND s.is_deleted = FALSE
  group by p.id,
  			p.category ,
  			(cast( s.added_date as date)),
  			st."type",
  			s.sale_type_id,
  			s.unit_id,
  			s.organization_id,
  			s.is_deleted 
  order by p.id asc; 

END;

$$;


