  join pharmacy.t_sale s on s.id = sd.sale_id 
  join pharmacy.m_sale_type st on st.id = s.sale_type_id
  WHERE s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>=p_date OR s.added_date::DATE>=p_date)
                                                		  AND s.is_deleted = FALSE)
                    		                        AND s.is_deleted = FALSE
  group by p.id ,
  			p.category ,
  			(cast( s.added_date as date)),
  			st."type",
  			s.sale_type_id,
  			s.unit_id,
  			s.organization_id,
  			s.is_deleted 
  order by p.id asc; 

END;

$$;


--
-- TOC entry 3882 (class 1255 OID 2969285)
-- Name: get_product_category_wise_sales(); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_product_category_wise_sales() RETURNS TABLE(id integer, category character, type character, sale_type_id integer, net_amount integer, added_date date)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY select
	    p.id, 
	    category,
	    st."type",
	    s.sale_type_id,
	    sum(s.net_amount ),
	    (cast( s.added_date as date))
	from 
		 public.m_product_category p
				join public.m_generic g  on p.id= g.product_category_id
			 	join public.m_item i on i.generic_id = g.id
			  	join inventory.t_batch b on  b.item_id = i.id
			  	join pharmacy.t_sale_detail sd on sd.batch_id = b.id 
			  	join pharmacy.t_sale s on s.id = sd.sale_id 
			 	join pharmacy.m_sale_type st on st.id = s.sale_type_id
	where
		 sd.added_date between '2019-01-01' and '2019-07-14'		 	
	group by
		 p.id ,
		 p.category ,
		 (cast( s.added_date as date)),
		 st."type",
		 s.sale_type_id;
end;

$$;


--
-- TOC entry 3883 (class 1255 OID 2969286)
-- Name: get_product_category_wise_sales(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_product_category_wise_sales(p_date date) RETURNS TABLE(sales_date date, unit_id integer, hospital_id integer, sale_type_id integer, product_category_id integer, sales_count integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY Select	 	s.added_date :: date as sales_date,
						s.unit_id,
						s.organization_id as hospital_id,
						s.sale_type_id ,
						g.product_category_id,
						COUNT(DISTINCT sd.quantity):: integer as sales_count,
						s.is_deleted
		
		from pharmacy.t_sale s
		JOIN pharmacy.t_sale_detail sd on s.id = sd.sale_id 
		JOIN inventory.t_batch b on b.id = sd.batch_id
		JOIN public.m_item i on i.id = b.item_id
		JOIN public.m_generic g on g.id = i.generic_id
		WHERE  s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>=p_date OR s.added_date::DATE>=p_date)
                                                		  AND s.is_deleted = FALSE)
                    		                        AND s.is_deleted = FALSE
		GROUP BY 
		s.added_date,
		s.sale_type_id ,
		g.product_category_id,
		s.unit_id,
		s.is_deleted,
		s.organization_id;

END;

$$;


--
-- TOC entry 3884 (class 1255 OID 2969287)
-- Name: get_product_category_wise_stock(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_product_category_wise_stock(p_date date) RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, stock_count integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY Select  ss.added_date::date as stock_date,
					ss.unit_id,
					ss.organization_id as hospital_id,
					ss.store_id,
					g.product_category_id,					
					SUM(  ss.available_qty):: integer as stock_count,
					ss.is_deleted
		FROM inventory.t_store_stock ss 
		JOIN inventory.t_batch b on b.id = ss.batch_id
		JOIN public.m_item i on i.id = b.item_id
		JOIN public.m_generic g on g.id = i.generic_id		
		WHERE  ss. added_date IN (SELECT ss.added_date
                                 FROM inventory.t_store_stock ss
                                                	WHERE(ss.updated_date::DATE>=p_date OR ss.added_date::DATE>=p_date)
                                                		  AND ss.is_deleted = False)
                    		                        AND ss.is_deleted = False
		GROUP BY 
		ss.unit_id,
		ss.organization_id,
		ss.store_id,
		g.product_category_id,
		ss.is_deleted,
		ss.added_date:: date
	   
					
	 ORDER BY 	ss.added_date:: date, 
	 			unit_id,
				ss.organization_id,
				ss.store_id, 
				g.product_category_id;
					
					END;

$$;


--
-- TOC entry 3885 (class 1255 OID 2969288)
-- Name: get_profit_margin_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_profit_margin_report(p_date date) RETURNS TABLE(product_category_id integer, generic_id integer, unit_id integer, organization_id integer, brand_id integer, batch_no character varying, vendor_id integer, grn_number character varying, grn_date date, cop double precision, mrp double precision, profit_margin double precision, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	i.product_category_id,
						i.generic_id, 
						b.unit_id ,
						b.organization_id ,
						i.id as brand_id, 
						MAX(b.batch_no):: character varying as batch_no,
						grc.vendor_id,
						MAX(grc.grn_number):: character varying grn_number,
						grc.added_date:: date as grn_date ,
						MAX(b.cop) as cop,
						max(b.rate)  as mrp,
		 				Round((((sum(b.rate) - SUM(b.cop))/SUM(b.cop))*100)::numeric ,2):: double precision as profit_margin,
						b.is_deleted
				FROM inventory.t_batch  b
				JOIN public.m_item i  on i.id = b.item_id 
				LEFT join procurement.t_good_receipt_note_detail grd on grd.item_id = i.id
				LEFT JOIN procurement.t_good_receipt_note grc on grc.id = grd.grn_id
				JOIN pharmacy.t_sale_detail sd on sd.batch_id = b.id
				JOIN pharmacy.t_sale s on s.id = sd.sale_id 
				WHERE grc.added_date::date IN (SELECT grc.added_date::date
                                 FROM  procurement.t_good_receipt_note grc
                                                	WHERE(grc.updated_date::DATE>=p_date OR grc.added_date::DATE>=p_date)
                                                		  AND grc.is_deleted = false)
                    		                        AND grc.is_deleted = false
				GROUP BY  	i.product_category_id,
							i.generic_id,
							brand_id,
							grc.vendor_id,
							grc.added_date,
							b.unit_id,
							b.organization_id ,
							b.is_deleted
				ORDER BY grc.added_date;
				END;
$$;


--
-- TOC entry 3886 (class 1255 OID 2969289)
-- Name: get_records_without_icd(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_records_without_icd(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, first_name character varying, last_name character varying, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, data_summary_released text, diagnosis_code character varying)
    LANGUAGE plpgsql
    AS $$
	BEGIN
	RETURN QUERY
		select distinct
		a.unit_id,
		a.organization_id,
		p.patient_id,
		p.first_name,
		p.last_name,
		wm.ward_name,
		bm.bed_number,
		a.created_date admission_date,
		d.discharge_date discharge_date,
		CASE
      		WHEN tr.discharge_summary_note is null THEN
         		'NO'
      		ELSE
        		'YES'
		end
		as data_summary_released,
		dm.code diagnosis_code 
		from patient.t_patient_registration p 	
		INNER JOIN patient.t_patient_diagnosis_appo_mapper pd on p.patient_id=pd.patient_id
		INNER JOIN emr.m_diagnosis_master dm on pd.diagnosis_id=dm.diagnosis_id
		INNER JOIN adt.t_admission a on p.patient_id=a.patient_id
		INNER JOIN adt.t_admission_details ad on a.admission_id=ad.admission_id
		LEFT JOIN adt.m_ward_master wm ON ad.ward_id = wm.ward_id
		LEFT JOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_id
		INNER JOIN adt.t_discharge d on ad.admission_id=d.admission_id
		INNER JOIN adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id
		where (a.created_date ::Date >= p_date or a.updated_date:: Date>=p_date ) 
		and dm.code isnull  -- comment this line or set as not null to see records, because there are no records with code null.
        and p.status='A';
		END;
$$;


--
-- TOC entry 3887 (class 1255 OID 2969290)
-- Name: get_recordswithout_discharge_summary(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_recordswithout_discharge_summary(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, first_name character varying, last_name character varying, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, discharge_summary_released text)
    LANGUAGE plpgsql
    AS $$ declare
begin
	return QUERY
select
a.unit_id,
a.organization_id,
p.patient_id, 
p.first_name,
p.last_name,
wm.ward_name,
bm.bed_number,
a.created_date,
d.discharge_date,
CASE
      WHEN tr.discharge_summary_note is null THEN
         'NO'
      ELSE
         'YES'
end
from patient.t_patient_registration p 
join adt.t_admission a on p.patient_id=a.patient_id
join adt.t_admission_details ad on a.admission_id=ad.admission_id
join adt.m_ward_master wm ON ad.ward_id = wm.ward_id
join adt.m_bed_master bm ON ad.bed_id = bm.bed_id
join adt.t_discharge d on ad.admission_id=d.admission_id
join adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id and tr.discharge_summary_note isnull
where (d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date )
and a.status='A' and d.discharge_type_id in (1,2,3,4)

union

select
a.unit_id,
a.organization_id,
p.patient_id,
p.first_name,
p.last_name,
wm.ward_name,
bm.bed_number,
a.created_date,
d.discharge_date,
CASE
      WHEN tr.discharge_summary_note is null THEN
         'NO'
      ELSE
         'YES'
end
from patient.t_patient_registration p 
join adt.t_admission a on p.patient_id=a.patient_id
join adt.t_admission_details ad on a.admission_id=ad.admission_id
join adt.m_ward_master wm ON ad.ward_id = wm.ward_id
join adt.m_bed_master bm ON ad.bed_id = bm.bed_id
join adt.t_discharge d on ad.admission_id=d.admission_id
join adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id and tr.discharge_summary_note isnull
where (d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date )
and d.discharge_status_id=5;

end;

$$;


--
-- TOC entry 3888 (class 1255 OID 2969291)
-- Name: get_registration_visit_typewise(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_registration_visit_typewise(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, admission_date date, visit_type_id integer, status character)
    LANGUAGE plpgsql
    AS $$ 
begin
	return QUERY select	
	    a.unit_id ::integer,
		a.organization_id ::integer,
		ad.admission_id ::integer,
       	a.patient_id ::integer,
       	a.doctor_id ::integer,
       	a.speciality_id ::integer,
       	ca.diagnosis_id :: integer,
       	ad.doa::date as admission_date,
       	a.visit_type_id :: integer,
		a.status as status
from adt.t_admission a
join adt.t_admission_details ad ON (a.admission_id = ad.admission_id)
join adt.t_complaint_admission ca ON (a.admission_id = ad.admission_id)
where	((a.updated_date::date >= p_date ::date and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date and a.created_date::date < current_date))
group by a.unit_id,
	     a.organization_id,
	     ad.admission_id,
	     a.patient_id,
	     a.doctor_id,
	     a.speciality_id,
	     ca.diagnosis_id,
	   	 ad.doa,
	   	 a.visit_type_id,
		 a.status;
end;
$$;


--
-- TOC entry 3889 (class 1255 OID 2969292)
-- Name: get_revenue_for_day(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_revenue_for_day(p_date date) RETURNS TABLE(unit_id integer, organziation_id integer, bill_date_time date, service_group_id integer, visit_type_id integer, bill_amt double precision, rendered_not_billed_amt double precision, status "char")
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY	SELECT 	b.unit_id,
						b.organization_id,
						b.bill_date_time::date,	
						b.service_group_id, 
						b.visit_type_id,
						sum(b.bill_amt) AS bill_amt,
						SUM(a.net_amount):: double precision AS rendered_not_billed_amt,
						b.status
				FROM (SELECT	bm.bill_date_time::date AS bill_date_time,	
								sm.speciality_id  as service_group_id, 
								bm.visit_type_id,
								sum(bm.net_amount) AS bill_amt,
								bd.unit_id,
								bd.organization_id,
								bm.status
						FROM billing.m_billing_master bm  
						JOIN billing.t_billing_details bd on bd.billing_master_id = bm.billing_master_id
						JOIN service.m_service_master sm on sm.service_master_id = bd.service_id
						GROUP BY 	bm.bill_date_time::date,	
									sm.speciality_id ,
									bm.visit_type_id,
									bd.unit_id,
									bm.status,
									bd.organization_id
					) b
				LEFT JOIN (SELECT od.net_amount, od.order_date, sm.speciality_id,om.encounter_id,om.admission_id
				FROM public.t_order_details od
				JOIN public.t_order_master om on om.order_id = od.order_id
				JOIN service.m_service_master sm on sm.service_master_id = od.service_id
				WHERE od.service_rendered = 1 AND (( om.encounter_id NOT IN (SELECT bm.encounter_id from billing.m_billing_master bm WHERE bm.encounter_id is NOT NULL)) 
				OR(om.admission_id NOT IN (SELECT bm.admission_id from billing.m_billing_master bm  WHERE bm.admission_id is NOT NULL)))) a
				ON a.order_date::date = b.bill_date_time::date AND 
					a.speciality_id = b.service_group_id
			   WHERE  b.bill_date_time::date IN (SELECT bm.bill_date_time::date
                                 FROM  billing.m_billing_master bm  
                                                	WHERE(bm.updated_date::DATE>=p_date OR bm.created_date::DATE>=p_date)
                                                		  AND bm.status = 'A') AND b.status = 'A'
					
			
				GROUP BY	b.bill_date_time::date,	
							b.service_group_id ,
							b.visit_type_id,
							b.unit_id,
						    b.organization_id,
							b.status
				ORDER BY 	b.bill_date_time::date,	
							b.service_group_id ,
							b.visit_type_id,
							b.unit_id,
						    b.organization_id;
	END;
	
	$$;


--
-- TOC entry 3890 (class 1255 OID 2969293)
-- Name: get_salesbill(bigint); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_salesbill(sales_id bigint) RETURNS TABLE(id bigint, bill_no character varying, added_date timestamp without time zone, total_amount double precision, discount double precision, net_amount double precision, tax_amount double precision, quantity integer, rate double precision, total_amount_details double precision, tax_percentage double precision, tax_amount_detail double precision, discount_amount double precision, net_amount_detail double precision)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY Select pharmacy.t_sale.id,pharmacy.t_sale.bill_no,pharmacy.t_sale.added_date,pharmacy.t_sale.total_amount,pharmacy.t_sale.discount,
		pharmacy.t_sale.net_amount,pharmacy.t_sale.tax_amount,pharmacy.t_sale_detail.quantity,pharmacy.t_sale_detail.rate,
		pharmacy.t_sale_detail.total_amount as total_amount_Details,pharmacy.t_sale_detail.tax_percentage,pharmacy.t_sale_detail.tax_amount as tax_amount_Detail ,pharmacy.t_sale_detail.discount_amount,
		pharmacy.t_sale_detail.net_amount as net_amount_Detail
		from pharmacy.t_sale inner join pharmacy.t_sale_detail 
		on pharmacy.t_sale.id = pharmacy.t_sale_detail.sale_id where pharmacy.t_sale.id=sales_id and pharmacy.t_sale.is_active=true ;
																	
         
END;

$$;


--
-- TOC entry 3891 (class 1255 OID 2969294)
-- Name: get_scrap_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_scrap_report(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, scrap_date date, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, cop double precision, amount double precision, scrap_reason_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY	SELECT 	b.unit_id,
						b.organization_id,
						sr.added_date:: date as scrap_date,	
						i.product_category_id, 
						i.generic_id,
						i.id brand_id,
						MAX(b.batch_no):: character varying  as batch_no , 
						sum(b.cop) cop,
						sum((b.quantity*b.cop)) amount, 
						sr.scrap_reason_id,
					 	b.is_deleted 
 			FROM inventory.t_batch b
			 JOIN inventory.t_scrap_request_detail sr on sr.batch_id = b.id
			 JOIN public.m_item i on i.id = b.item_id
			WHERE sr.added_date:: date IN (SELECT sr.added_date:: date
                                 FROM  inventory.t_scrap_request_detail sr
                                                	WHERE(sr.updated_date::DATE>=p_date OR sr.added_date::DATE>=p_date)
                                                		  AND sr.is_deleted = false)
                    		                        AND sr.is_deleted = false  AND sr.status_id = 6
			GROUP BY 	sr.added_date,	 
						i.product_category_id, 
						i.generic_id,
						brand_id, 
						sr.scrap_reason_id,
						b.unit_id,
						b.is_deleted ,
						b.organization_id;
						
						END;
						$$;


