--

CREATE FUNCTION procedure_old.get_services_ordered_by_consultant(p_date date) RETURNS TABLE(order_date date, speciality_id integer, department_id integer, visit_type_id integer, ord_doctor_id integer, service_order_count integer, amount double precision, org_id integer, org_unit_id integer, status character)
    LANGUAGE plpgsql
    AS $$

