					GROUP BY od.order_date :: date,
							sm.speciality_id, 
							sm.sub_speciality_id,
							om.visit_type_id ,
							om.ord_doctor_id,
							od.org_id, 
							sm.status,
							od.org_unit_id;

END;

$$;


--
-- TOC entry 3894 (class 1255 OID 2969297)
