--

CREATE FUNCTION procedure_old.get_services_rendered_to_patient(p_date date) RETURNS TABLE(ord_render_datetime date, org_unit_id integer, hospital_id integer, speciality_id integer, patient_id integer, visit_type_id integer, org_doctor_id integer, service_master_id integer, services_rendered integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT od.ord_render_datetime ::date ,
					om.org_unit_id,
					sm.organization_id as hospital_id,
					sm.speciality_id  as  service_category_id,  
					om.patient_id,
					om.visit_type_id,
					om.ord_doctor_id,
					sm.service_master_id,
					count(DISTINCT sm.service_master_id) :: integer as services_rendered,
					od.status
			from public.t_order_details od 
			JOIN public.t_order_master om on od.order_id = om.order_id
			JOIN  service.m_service_master sm on sm.service_master_id = od.service_id
			WHERE  od.ord_render_datetime IN (SELECT od.ord_render_datetime
                                 FROM public.t_order_details od
                                                	WHERE(sm.updated_date::DATE>=p_date OR sm.created_date::DATE>=p_date)
                                                		  AND sm.status = 'A')
                    		                        AND sm.status = 'A'
			group by 
					od.ord_render_datetime :: date,
					om.org_unit_id,
					sm.organization_id,
					sm.speciality_id,
					om.patient_id,
					om.visit_type_id,
					sm.service_master_id,
					od.status,
					om.ord_doctor_id;

END;

$$;


--
-- TOC entry 3895 (class 1255 OID 2969298)
-- Name: get_still_birth(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_still_birth(p_date date) RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, no_of_still_birth integer, mother_admission_id integer, mother_patient_id integer, child_patient_id integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
 RETURN QUERY   SELECT  d.discharge_date :: date, 
						pr.unit_id, 
						pr.organization_id,
						count(nbd.new_born_id) :: integer  no_of_still_birth ,
						nbd.mother_admission_id ,
						nbd.mother_id as mother_patient_id,
						nbd.patient_id as child_patient_id,
						d.status 
 				FROM adt.t_discharge d 
				JOIN adt.t_admission a ON a.admission_id = d.admission_id
	    		JOIN "patient".t_patient_registration pr ON pr.patient_id = a.patient_id
				JOIN patient.t_new_born_details nbd on nbd.patient_id = pr.patient_id
				WHERE nbd.is_still_birth = 'Y' AND d.discharge_date IN (SELECT d.discharge_date FROM adt.t_discharge d 
       			 WHERE (d.updated_date :: DATE >= p_date OR d.created_date :: DATE >= p_date  AND d.status = 'A')
					AND d.status = 'A')
				GROUP BY
	   	      			d.discharge_date :: date , 
	   					pr.unit_id,
	   					pr.organization_id,
						nbd.mother_admission_id ,
						child_patient_id,
						mother_patient_id,
						d.status; 
	   			
 
END;

$$;


--
-- TOC entry 3896 (class 1255 OID 2969299)
-- Name: get_stock_adjustment_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_stock_adjustment_report(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, product_category_id integer, item_id integer, generic_id integer, batch_number character varying, expiry_date date, cost_of_product double precision, mrp double precision, quantity_uploaded bigint, value_of_cost_of_product double precision, value_of_mrp double precision, system_stock bigint, system_stock_of_cop double precision, system_stock_of_mrp double precision, difference_in_quantity bigint, difference_of_cop double precision, difference_of_mrp double precision, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 		select 	
							 b.unit_id,
                             b.organization_id as hospital_id,
                             g.product_category_id,
                             im.id as item_id,
							 im.generic_id,
                             b.batch_no,
							 b.expiry_date,
							 sum(b.cop) as cop,
                             sum(b.rate) as mrp,
                             sum(usd.qty) as quantity_uploaded,
                             sum((b.cop) * (usd.qty)) as value_of_cost_of_product,
                             sum((b.rate) * (usd.qty)) as value_of_mrp,
                             sum(b.current_quantity) as system_stock,
                             sum((b.cop) * (b.current_quantity)) as system_stock_of_cop,
                             sum((b.rate) * (b.current_quantity)) as system_stock_of_mrp,
                             sum( (b.current_quantity) - (usd.qty) ) as difference_in_quantity,
                             sum(((b.current_quantity) - (usd.qty)) * (b.cop)) as difference_of_cop,
                             sum(((b.current_quantity) - (usd.qty)) * (b.rate)) as difference_of_mrp,
							 b.is_deleted
                            
				
                from inventory.t_batch b 
                JOIN inventory.t_upload_stock_detail usd on usd.batch_id = b.id
                JOIN public.m_item im on im.id = b.item_id 
				JOIN public.m_generic g on g.id = im.generic_id
                
                WHERE b.added_date IN (SELECT b.added_date
                                from inventory.t_batch b
                                                	WHERE(b.updated_date::DATE>=p_date OR b.added_date::DATE>=p_date)
                                                		  AND b.is_deleted = false)
                    		                        AND b.is_deleted = false
				
				   group by  b.unit_id,
                             b.organization_id,
                             g.product_category_id,
                             im.id,
							 im.generic_id,
                             b.batch_no,
							 b.expiry_date,
                             b.is_deleted;
						END;

$$;


--
-- TOC entry 3897 (class 1255 OID 2969300)
-- Name: get_stock_ledger_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_stock_ledger_report(p_date date) RETURNS TABLE(hospital_id integer, unit_id integer, store_id integer, generic_id integer, brand_id integer, product_category_id integer, batch_number character varying, expiry_date date, opening_balance bigint, quantity_received bigint, stock_in_transit bigint, sales bigint, quantity_returned bigint, sales_return bigint, stock bigint, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
      DECLARE
                                                             
      BEGIN
                                                             
      RETURN QUERY  SELECT
                              ss.organization_id as hospital_id,
                              ss.unit_id  ,
                              ss.store_id,
                              i.generic_id,
                              i.id as brand_id,                              
					          g.product_category_id, 
                              b.batch_no,
                              b.expiry_date, 
                              COALESCE(SUM(ss.available_qty),0) as opening_balance,   
                              COALESCE(SUM(grnd.grn_approved_quantity),0) as quantity_received,
                              COALESCE(SUM(ss.t_qty),0) as stock_in_transit,
                              COALESCE(SUM(sd.quantity),0) as sales,
                              COALESCE(SUM(rgd.return_qty),0) as quantity_returned,
                              COALESCE(SUM(rd.return_qty),0) as sales_returns,                            
                              (COALESCE(SUM(ss.available_qty),0) + COALESCE(SUM(grnd.grn_approved_quantity),0) + COALESCE(SUM(rd.return_qty),0) + 
                               COALESCE(SUM(ss.t_qty),0) - COALESCE(SUM(sd.quantity),0) - COALESCE(SUM(rgd.return_qty),0)) stock_available,
                               ss.is_deleted                         
                               FROM  inventory.t_store_stock ss
                                JOIN inventory.t_batch b on b.id = ss.batch_id   
                                JOIN public.m_item i on i.id = b.item_id
			                    JOIN public.m_generic g on g.id = i.generic_id                             
                                LEFT JOIN procurement.t_good_receipt_note_detail grnd on grnd.item_id = i.id  
                                left JOIN inventory.t_returnable_gatepass_detail rgd on rgd.grn_detail_id = grnd.id                           
                                JOIN pharmacy.t_sale_detail sd on sd.batch_id = b.id                            
                                JOIN pharmacy.t_return_detail rd on rd.sale_detail_id = sd.id  
                      WHERE ss.added_date IN (SELECT ss.added_date
                                 FROM inventory.t_store_stock ss
                                                	WHERE(ss.updated_date::DATE >= p_date OR ss.added_date::DATE >= p_date)
                                                		  AND ss.is_deleted = false)
                    		                              AND ss.is_deleted = false 
                      group by 
                              ss.organization_id,
                              ss.unit_id  ,
                              ss.store_id,
                              i.generic_id,
                              i.id,                              
					          g.product_category_id, 
                              b.batch_no,
                              b.expiry_date,
                              ss.is_deleted ;                                 
      
                              END;  
                           $$;


--
-- TOC entry 3898 (class 1255 OID 2969301)
-- Name: get_stock_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_stock_report(p_date date) RETURNS TABLE(store_id integer, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, expiry_date date, uom_id integer, quantity integer, poc double precision, mrp double precision, value_poc double precision, value_mrp double precision, unit_id integer, hospital_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

	DECLARE

	BEGIN
 
	RETURN QUERY select ss.store_id,
						g.product_category_id,
						im.generic_id,
						im.id as brand_id,
						MAX(b.batch_no) :: character varying as batch_no ,
						b.expiry_date,
						um.id  as uom_id ,
						sum(ss.available_qty):: integer as quantity,
						sum(b.cop) as poc,
						sum(b.rate) as mrp,
						sum((b.quantity*b.cop)) as value_poc, 
						sum((b.quantity*b.rate)) as value_mrp,
						b.unit_id, 
						b.organization_id as hospital_id,
						b.is_deleted
				FROM  inventory.t_batch b
				JOIN inventory.t_store_stock ss on b.id = ss.batch_id
				JOIN public.m_item im on b.item_id = im.id
				JOIN public.m_uom_unit um on b.uom_unit_id  =  um.id
				JOIN public.m_generic g on g.id = im.generic_id
				
		GROUP BY 	ss.store_id,
					g.product_category_id ,
					im.generic_id,
					brand_id,
					um.id ,
					b.expiry_date,
					b.unit_id, 
					b.organization_id,
					b.is_deleted;
					END;

	$$;


--
-- TOC entry 3899 (class 1255 OID 2969302)
-- Name: get_stock_transit_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_stock_transit_report(p_date date) RETURNS TABLE(issuing_store integer, receiving_store integer, indent_no character varying, indent_date date, issue_no character varying, issue_date date, brand_id integer, generic_id integer, batch_number character varying, uom_unit_id integer, quantity integer, cop double precision, value_cop double precision, unit_id integer, organisation_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
RETURN QUERY

				select 	 sim.from_store_id  issuing_store, 
						sim.to_store_id  receiving_store, 
						MAX(sim.indent_no):: character varying   indent_no,
						sim.added_date :: date  indent_date,
						MAX(mim.issue_no) :: character varying  issue_no ,
						mim.added_date :: date as issue_date ,
					    i.id  brand_id,
						i.generic_id,
						MAX(bm.batch_no):: character varying  batch_number, 
						bm.uom_unit_id ,
						SUM(ss.t_qty):: integer as quantity ,
						SUM(bm.cop) as cop,
						SUM(ss.t_qty*bm.cop) as value_cop,
						bm.unit_id ,
						bm.organization_id,
						mim.is_deleted
				FROm inventory.t_material_issue mim
				LEFT JOIN inventory.t_material_issue_detail mid on mid.material_issue_id = mim.id
				LEFT JOIN inventory.t_material_issue_batch_mapper mibm ON mibm.material_issue_detail_id = mid.id
				LEFT JOIN inventory.t_store_indent sim on sim.id = mim.store_indent_id
				join inventory.t_batch bm on bm.id = mibm.batch_id
				JOIN public.m_item i on i.id = bm.item_id
				JOIN inventory.t_store_stock ss on ss.batch_id = bm.id
				WHERE mim.added_date IN (SELECT mim.added_date 
                                 FROM inventory.t_material_issue mim
                                                	WHERE(mim.updated_date::DATE>=p_date OR mim.added_date::DATE>=p_date)
                                                		  AND mim.is_deleted = false) AND 
								sim.added_date IN 	(SELECT sim.added_date
                                 FROM inventory.t_store_indent sim
                                                	WHERE(sim.updated_date::DATE>=p_date OR sim.added_date::DATE>=p_date)
                                                		  AND sim.is_deleted = false)					
                    		                        AND sim.is_deleted = false AND mim.is_deleted = false
				group by    sim.from_store_id, 
							sim.to_store_id , 
							bm.uom_unit_id ,
							issue_date ,
				 			indent_date,
							i.generic_id,
							brand_id,
							mim.is_deleted,
							bm.unit_id ,
							bm.organization_id;
							
							END;
							$$;


--
-- TOC entry 3900 (class 1255 OID 2969303)
-- Name: get_tariff_master(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_tariff_master(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, service_group_id integer, service_standard_name character varying, patient_type integer, visit_type_id integer, billing_bed_category_id integer, valid_from timestamp without time zone, valid_to timestamp without time zone, tariff double precision, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY SELECT tm.unit_id,
					tm.organization_id,
					sm.speciality_id as service_group_id,
        			sm.service_standard_name,
	    			usm.patient_type_id,
					usm.visit_type_id,
					usm.billing_bed_category_id,
					tm.valid_from,
					tm.valid_to,
					usm.rate as tariff,
					usm.status
			FROM  service.m_unit_service_tariff_master usm 
			JOIN service.m_tariff_master tm on tm.tariff_id = usm.tariff_id
			JOIN service.m_service_master sm on sm.service_master_id = usm.service_id 
			JOIN "public".m_patient_category_master pcm on pcm.patient_category_id = usm.patient_type_id
			WHERE  usm.effective_date IN (SELECT  usm.effective_date
                                 FROM   service.m_unit_service_tariff_master usm 
                                                	WHERE(usm.updated_date::DATE>=p_date OR usm.created_date::DATE>=p_date)
                                                		  AND usm.status = 'A')
                    		                        AND usm.status = 'A'
			GROUP BY 	tm.unit_id,
						tm.organization_id,
						service_group_id,
        				sm.service_standard_name,
	    				patient_type,
						usm.visit_type_id,
						usm.patient_type_id,
						usm.billing_bed_category_id,
						tm.valid_from,
						tm.valid_to,
						usm.status,
						usm.rate ;
					
					END;
					$$;


--
-- TOC entry 3901 (class 1255 OID 2969304)
-- Name: get_timeliness_of_appointment(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_timeliness_of_appointment(p_date date) RETURNS TABLE(appointment_date date, avg_time_gap bigint, speciality_id integer, doctor_id integer, status character, unit_id integer, hospital_id integer)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY  SELECT	sm.appointment_date  :: date,
						coalesce(AVG((EXTRACT ( EPOCH from (ed.consultation_start_time)):: bigint)- 
						(EXTRACT( EPOCH from (am.created_date )):: bigint)):: BIGINT ,0)  as avg_time_gap ,
						sm.speciality_id,
						sm.doctor_id,
						sm.status,
						sm.unit_id,
						sm.organization_id as hospital_id
			From opd.m_slot_master sm
			JOIN opd.m_appointment_master am on sm.slot_id = am.slot_id
			JOIN opd.t_encounter_master em on em.appointment_id = am.appointment_id	
			JOIN opd.t_encounter_details ed on ed.encounter_id = em.encounter_id
		   WHERE -- sm.appointment_date  IN (SELECT sm.appointment_date FROM opd.m_slot_master sm WHERE(sm.updated_date::DATE>='2017-11-10' OR sm.created_date::DATE>='2017-11-10') AND sm.status = 'A') AND sm.status = 'A'
			(sm.updated_date::DATE>=p_date OR sm.created_date::DATE>=p_date) 
			AND sm.status = 'A'
		   GROUP BY  	sm.appointment_date :: date,
						sm.speciality_id,
						sm.doctor_id,
						sm.status,
						sm.unit_id,
						sm.organization_id;
						END;
						$$;


--
-- TOC entry 3902 (class 1255 OID 2969305)
-- Name: get_transaction_code_wise_report(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_transaction_code_wise_report(p_date date) RETURNS TABLE(bill_date_time date, service_group_id integer, service_standard_code character varying, service_standard_name character varying, visit_type_id integer, doctor_id integer, speciality_id integer, patient_id integer, sum double precision, status "char", unit_id integer, hospital_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY Select  bm.bill_date_time::date,	
			sm.speciality_id  as service_group_id, 
			sm.service_standard_code, 
			sm.service_standard_name,
			bm.visit_type_id, 
			em.doctor_id,
			d.speciality_id,
			bm.patient_id,
			sum(bm.net_amount),
			bm.status,
			bm.unit_id,
			bm.organisation_id as hospital_id
	from billing.m_billing_master bm  
	JOIN billing.t_billing_details bd on bm.billing_master_id = bd.billing_master_id
	JOIN service.m_service_master  sm  on sm.service_master_id = bd.service_id
	LEFT JOIN opd.t_encounter_master em on bm.encounter_id = em.encounter_id AND bm.visit_type_id = 1 
	LEFT JOIN doctor.t_doctor_speciality_mapper d on d.doctor_id = em.doctor_id
 	WHERE bm.visit_type_id is NOT NULL AND  bm.bill_date_time::date IN (SELECT bm.bill_date_time::date
                        from billing.m_billing_master bm  
                               WHERE  (bm.updated_date::DATE>=p_date OR bm.created_date::DATE>=p_date)
                                                                        AND bm.status = 'A') AND bm.status = 'A'
	GROUP BY	sm.speciality_id,
				sm.service_standard_code,
				sm.service_standard_name,
				bm.visit_type_id,
				em.doctor_id,
				d.speciality_id,
				bm.patient_id,
				bm.bill_date_time::date,
				bm.status,
				bm.unit_id,
				bm.organisation_id
	ORDER BY 	bm.bill_date_time::date;
END;
$$;


--
-- TOC entry 3903 (class 1255 OID 2969306)
-- Name: get_user_get_top10_issues(); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_user_get_top10_issues() RETURNS TABLE(issue_id integer, user_id integer, user_name character varying, user_count integer, quantity integer, unit_id integer, hospital_id integer, build_date date, store_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
          begin
	 select   iss.id,
     					iss.added_by as user_id, 
                       u.user_name,
	                   count(u.user_name):: integer User_count,
	                   s.organization_id as hospital_id,
	                   s.unit_id,
					   s.store_id ,
					   sum( sd.quantity ) as quantity,
					sl.added_date:: date as build_date
		from public.m_user_master u 
		            join pharmacy.t_issue iss on iss.added_by = u.user_id
		            join public.m_store s on s.store_id = iss.store_id
		            join pharmacy.t_sale sl on sl.store_id = s.store_id
		            join pharmacy.t_sale_detail sd on sd.sale_id = sl.id
		            WHERE  sl.added_date IN (SELECT sl.added_date
                                 FROM pharmacy.t_sale sl
                                                	WHERE(sl.updated_date::DATE>='2019-01-01' OR sl.added_date::DATE>='2019-07-12')
                                                		  AND sl.is_deleted = FALSE)
                    		                       AND sl.is_deleted = FALSE
		              GROUP BY  
		            iss.id,
			        s.organization_id,
			        u.user_name,
			        s.unit_id,
			        iss.added_by,
			        s.store_id,
			        date(sl.added_date),
			        quantity
		ORDER BY quantity desc limit 10 ;
					END;

$$;


