--

CREATE FUNCTION procedure_old.get_user_getby_issues() RETURNS TABLE(issue_id integer, user_name character varying, unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	  Select iss.id :: integer as issue_id,
	                   s.added_by as user_id, 
	                   count(u.user_name):: integer User_count,
	                   sd.quantity,
	                   s.organization_id as hospital_id,
	                   s.unit_id,
					   s.store_id ,
					s.added_date:: date as build_date
			from pharmacy.t_issue iss 
		        join public.m_user_master u on u.user_id = iss.added_by
		        join public.m_store s on s.store_id = iss.store_id
		        join pharmacy.t_sale sl on sl.store_id = s.store_id
		        join pharmacy.t_sale_detail sd on sd.sale_id = sl.id
			WHERE  sl.added_date IN (SELECT sl.added_date
                                 FROM pharmacy.t_sale sl
                                                	WHERE(sl.updated_date::DATE>='2019-01-01' OR sl.added_date::DATE>='2019-07-12')
                                                		  AND sl.is_deleted = FALSE)
                    		                        AND sl.is_deleted = FALSE
			GROUP BY 
			        issue_id,
			        iss.organization_id,
			        iss.unit_id,
			        iss.added_by,
			        s.store_id,
			        date(sl.added_date),
			        sd.quantity
					
			order by iss.id asc;
					END;

$$;


