--
-- TOC entry 3906 (class 1255 OID 2969309)
-- Name: get_user_wise_issues(); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_user_wise_issues() RETURNS TABLE(unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	  Select s.unit_id,
					s.organization_id as hospital_id,
					s.added_date:: date as build_date,
					s.added_by as user_id, 
					s.store_id ,
					COUNT(DISTINCT s.id) :: integer as no_of_bills,
					s.is_deleted 
			from pharmacy.t_sale s
			WHERE  s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>='2019-01-01' OR s.added_date::DATE>='2019-07-12')
                                                		  AND s.is_deleted = FALSE)
                    		                        AND s.is_deleted = FALSE
			GROUP BY 
					s.added_date,
 					user_id, 
					s.store_id ,
					s.unit_id,
					s.is_deleted ,
					s.organization_id
			ORDER BY CAST(s.added_date AS DATE),
					user_id, 
					s.store_id,
					s.unit_id,
					s.organization_id;
					END;

$$;


--
-- TOC entry 3907 (class 1255 OID 2969310)
-- Name: get_user_wise_issues(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_user_wise_issues(p_date date) RETURNS TABLE(unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$ declare
begin
	  Select s.unit_id,
					s.organization_id as hospital_id,
					s.added_date:: date as build_date,
					s.added_by as user_id, 
					s.store_id ,
					COUNT(DISTINCT s.id) :: integer as no_of_bills,
					s.is_deleted 
			from pharmacy.t_sale s
			WHERE  s.added_date IN (SELECT s.added_date
                                 FROM pharmacy.t_sale s
                                                	WHERE(s.updated_date::DATE>=p_date OR s.added_date::DATE>=p_date)
                                                		  AND s.is_deleted = FALSE)
                    		                        AND s.is_deleted = FALSE
			GROUP BY 
					s.added_date,
 					user_id, 
					s.store_id ,
					s.unit_id,
					s.is_deleted ,
					s.organization_id
			ORDER BY CAST(s.added_date AS DATE),
					user_id, 
					s.store_id,
					s.unit_id,
					s.organization_id;
					END;

$$;


--
-- TOC entry 3873 (class 1255 OID 2969311)
-- Name: get_visit_analysis(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.get_visit_analysis(p_date date) RETURNS TABLE(visist_date date, doctor_id integer, speciality_id integer, unit_id integer, organization_id integer, visit_type_id integer, no_of_patient_visited integer, status character)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN
 
RETURN QUERY 	SELECT 		visit_date ,
							a.doctor_id,
							a.speciality_id,
							a.unit_id,
							a.organization_id,
							a.visit_type_id,
							COUNT(a.no_of_patient_visited) :: integer as no_of_patient_visited,
							a.status
				FROM
				(SELECT 	em.encounter_date :: date as  visit_date,
							em.doctor_id, 
							em.dept_id as speciality_id,
							em.unit_id,
							1 as visit_type_id,
							em.organization_id,
							COUNT(COALESCE(em.patient_id,0)):: integer AS no_of_patient_visited,
							em.status 
			FROM opd.t_encounter_master em
				WHERE em.encounter_date IN (SELECT em.encounter_date
                            FROM opd.t_encounter_master em
                            WHERE  (em.updated_date::DATE>=p_date OR em.created_date::DATE>=p_date)
                                             AND em.status = 'A')														
			
     		GROUP BY		em.encounter_date :: date  ,
							em.doctor_id, 
							em.dept_id,
							em.unit_id,
  							em.organization_id,
 							em.status
 							 

 			UNION ALL
			SELECT 			ad.doa :: date as visit_date,
							am.doctor_id, 
							am.speciality_id,
							am.unit_id,
							am.organization_id,
							am.visit_type_id, 
							COUNT(COALESCE(am.patient_id,0))::integer AS no_of_patient_visited,
							 am.status 
 			FROM "adt".t_admission am
 			inner join adt.t_admission_details ad on am.admission_id = ad.admission_id
						WHERE am.visit_type_id != 1 AND NOT NULL AND ad.doa IN (SELECT a.doa 
                                    FROM "adt".t_admission_details a
                                   			 WHERE  (a.updated_date::DATE>=p_date OR a.created_date::DATE>=p_date )
                                             			AND a.status = 'A')
                 				
			GROUP BY 
 						am.doctor_id,
 						am.speciality_id,
 						am.unit_id,
 						am.visit_type_id,
						am.organization_id,
						ad.doa :: date ,
						am.status
 						)a
			GROUP BY 
						visit_date  ,
						a.doctor_id,
						a.speciality_id,
						a.unit_id,
						a.status,
						a.organization_id,
						a.visit_type_id;


END;

$$;


