CREATE FUNCTION procedure_old.mis_get_visit_type_admission(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, admission_date date, diagnosis_id integer, advance_amount_paid double precision, doctor_id integer, patient_id integer, bed_id integer, planned_discharge_date date, payment_entitlement_id integer, visit_type_id integer, speciality_id integer, is_deleted boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		d.unit_id,
		d.organization_id,
		ad.doa::date,
		cad.diagnosis_id,
		dm.deposit_amount,
		d.doctor_id,
		a.patient_id,
		ad.bed_id,
		ad.pdd::date,
		apm.payment_entitlement_id,
		a.visit_type_id,
		a.speciality_id,
