	join adt.t_complaint_admission cad
			using(admission_id)
	join billing.m_deposit_master dm
			using (admission_id)
	join adt.t_discharge d
			using (admission_id)
	join adt.t_admission_details ad
			using (admission_id)
	join adt.t_admission_patient_mapping apm on
		(a.patient_id = apm.admission_patient_id)
	where
		((d.updated_date::date >= p_date ::date
		and d.updated_date::date < current_date)
		or (d.created_date::date >= p_date::date
		and d.created_date::date < current_date));
end;

