--
-- TOC entry 3911 (class 1255 OID 2969315)
-- Name: per_med_rec_not_having_dis_summary(); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.per_med_rec_not_having_dis_summary() RETURNS TABLE(unit_id integer, organization_id integer, no_of_discharges integer, no_of_dis_without_summ integer)
    LANGUAGE plpgsql
    AS $$
	begin
		return QUERY 
			with tab1 as 
				(select count(*)nodwodsum,dis.organization_id,dis.unit_id
				from t_discharge dis inner join t_admission ad using (admission_id)
				where ad.status = 'A'
				and dis.admission_id not in (select admission_id from m_discharge_summary)
				and dis.discharge_type_id in (select discharge_type_id 
											  from m_reason_for_discharge_master 
											  where discharge_type_code in('Normal','DAMA','Death','LAMA'))
				group by dis.organization_id,dis.unit_id),
			tab2 as
				(select count(*) nod,organization_id,unit_id 
				from t_discharge
				where discharge_type_id in (select discharge_type_id 
							from m_reason_for_discharge_master 
							where discharge_type_code in('Normal','DAMA','Death','LAMA'))
				group by organization_id,unit_id)
		select tab1.nodwodsum, tab2.nod, tab1.organization_id,tab1.unit_id
		from tab1, tab2
		where tab1.organization_id =tab2.organization_id
		and tab1.unit_id = tab2.unit_id;
	end;
$$;


--
-- TOC entry 3912 (class 1255 OID 2969316)
-- Name: qi_get_avg_length_stay(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.qi_get_avg_length_stay(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, inpatient_days integer, total_discharge integer)
    LANGUAGE plpgsql
    AS $$ declare
begin
return QUERY
select s.unit_id , s.organization_id,s.patient_id, s.speciality_id , s.doctor_id, s.diagnosis_id,
SUM(CASE WHEN diff<=12 THEN 0.5 
								ELSE  (diff/24) + (CASE WHEN diff%24 = 0 THEN 0 ELSE 1 END ) 
						END)  :: integer as inpatient_days,
COUNT(distinct s.discharge_id):: INTEGER as total_discharge	
from(
SELECT 	a.unit_id ,	a.organization_id,p.patient_id, a.speciality_id , d.doctor_id, ca.diagnosis_id ,d.discharge_id,
		extract(epoch from d.discharge_date - ad.doa)::integer/3600 as diff
FROM adt.t_discharge d
JOIN adt.t_admission a on d.admission_id = a.admission_id AND a.visit_type_id IN (2)
JOIN adt.t_admission_details ad on d.admission_id = ad.admission_id 
JOIN adt.t_complaint_admission ca on ad.admission_id = ca.admission_id
join patient.t_patient_registration p using (patient_id)
where -- d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date 
		 a.status = 'A'
GROUP BY 	a.unit_id ,
            p.patient_id,
			a.organization_id,
			a.speciality_id ,
			d.discharge_date,
			d.doctor_id,
			ca.diagnosis_id,
			ad.doa,
			d.discharge_id
)s 
group by s.unit_id , s.organization_id,s.patient_id, s.speciality_id , s.doctor_id, s.diagnosis_id,s.discharge_id;

end;

$$;


--
-- TOC entry 3913 (class 1255 OID 2969317)
-- Name: qi_get_bed_occupancy(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.qi_get_bed_occupancy(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, inpatient_days integer, bed_category_id integer, available_beds integer)
    LANGUAGE plpgsql
    AS $$ declare
begin
return QUERY

select s.unit_id,
s.organization_id,
s.patient_id,
s.patient_age,
SUM(CASE WHEN diff<=12 THEN 0.5 
		 ELSE  (diff/24) + (CASE WHEN diff%24 = 0 THEN 0 ELSE 1 END ) 
	END)  :: integer as inpatient_days,
b.bed_category_id,b.available_beds
from(
SELECT 	a.unit_id ,	a.organization_id,p.patient_id,a.admission_id,
        extract(year
	    from
		age(p.dob))::integer as patient_age,
		extract(epoch from d.discharge_date - ad.doa)::integer/3600 as diff
FROM adt.t_discharge d
JOIN adt.t_admission a on d.admission_id = a.admission_id AND a.visit_type_id IN (2)
JOIN adt.t_admission_details ad on d.admission_id = ad.admission_id 
join patient.t_patient_registration p using (patient_id)
where d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date 
	  and a.status = 'A'
GROUP BY 	a.unit_id ,
            p.patient_id,
			a.organization_id,
			ad.doa,
			a.admission_id,
			d.discharge_date
)s 
join
(
SELECT 	bm.bed_category_id,bed_status_id,a.admission_id,
        count(distinct bm.bed_id)	available_beds	
from adt.t_admission a 
JOIN adt.t_admission_details ad on a.admission_id = ad.admission_id 
join adt.m_bed_master bm on ad.bed_id=bm.bed_id  and (bed_status_id=6 or bed_status_id=3)
where d.updated_date::DATE>=p_date OR d.created_date::DATE>=p_date 
	  and a.status = 'A'
GROUP BY 	bm.bed_category_id,
			bed_status_id,a.admission_id
)b
on s.admission_id=b.admission_id
group by s.unit_id , s.organization_id,s.patient_age,s.patient_id,b.bed_category_id,b.available_beds;

end;

$$;


--
-- TOC entry 3914 (class 1255 OID 2969318)
-- Name: qi_get_er_72hrs_with_same_complaint(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.qi_get_er_72hrs_with_same_complaint(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)
    LANGUAGE plpgsql
    AS $$
begin
	return QUERY select
		a.unit_id,
		a.organization_id,
		a.patient_id,
		extract(year
	from
		age(pr.dob))::integer as patient_age,
		cad.diagnosis_id,
		true
	from
		adt.t_admission a
	join adt.t_admission_details ad
			using(admission_id)
	join adt.t_complaint_admission cad
			using(admission_id)
	join patient.t_patient_registration pr
			using (patient_id)
	where
		((a.updated_date::date >= p_date ::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
		and a.visit_type_id in (
			select visit_type_id
		from
			m_visit_type_master
		where
			visit_type_code = 'ER')
		and exists (
			select 1
		from
			adt.t_admission pa
		join adt.t_complaint_admission pcad
				using (admission_id)
		join adt.t_admission_details padm
				using (admission_id)
		join adt.t_discharge d
				using (admission_id)
		where
			pa.patient_id = a.patient_id
			and a.visit_type_id in (
				select visit_type_id
			from
				m_visit_type_master
			where
				visit_type_code = 'ER')
			and pcad.icpc_system_id = cad.icpc_system_id
			and padm.is_discharge = 'D'
			and padm.doa >= (ad.doa - ('72 hours')::interval)
			and ad.admission_id != padm.admission_id)
	group by
		a.patient_id,
		a.unit_id,
		a.organization_id,
		patient_age,
		cad.diagnosis_id
union select
		a.unit_id,
		a.organization_id,
		a.patient_id,
		extract(year
	from
		age(pr.dob))::integer as patient_age,
		cad.diagnosis_id,
		false
	from
		adt.t_admission a
	join adt.t_admission_details ad
			using(admission_id)
	join adt.t_complaint_admission cad
			using(admission_id)
	join patient.t_patient_registration pr
			using (patient_id)
	where
		((a.updated_date::date >= p_date ::date
		and a.updated_date::date < current_date)
		or (a.created_date::date >= p_date::date
		and a.created_date::date < current_date))
		and a.visit_type_id in (
			select visit_type_id
		from
			m_visit_type_master
		where
			visit_type_code = 'ER')
	group by
		a.patient_id,
		a.unit_id,
		a.organization_id,
		patient_age,
		cad.diagnosis_id;
end;

$$;


--
-- TOC entry 3915 (class 1255 OID 2969319)
-- Name: qi_get_mortality_rate(date); Type: FUNCTION; Schema: procedure_old; Owner: -
--

CREATE FUNCTION procedure_old.qi_get_mortality_rate(p_date date) RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, gender_id integer, is_dead boolean, diagnosis_id integer)
    LANGUAGE plpgsql
    AS $$ 
begin
	return QUERY select 	
		pr.unit_id, 
		pr.organization_id, 
		pr.patient_id,
