declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
declare nextVoucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin 
	----------- Create view ---------------------------
create or replace temporary view 
  opbill
AS
	(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode,  pReceiptDtls.amount  as rcptamount, 
	billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, 
	pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, 
	pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, 
	pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
	billMst.organisation_id as orgid, billMst.unit_id as unitid,
	pReceiptDtls.date_of_transaction  as transdate, billMst.bill_date_time  as billdate,
	pReceiptDtls.trans_transaction_date as transferdate
	from billing.t_payment_reciept_details pReceiptDtls
	inner join public.m_payment_mode_master  pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_id
	inner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id 
	inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_id
	left join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id
	where  billMst.visit_type_id = 1);

------- Insert cash start ---------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales', opbill.mode,  opbill.transdate,   sum(opbill.rcptamount), 0 , 
opbill.unitId, opbill.orgId , 'OP',usedatarange
from opbill
where  opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate  between  starttime and endtime
group by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)
select voucherno, 'Sales', 
opbill.mode,  opbill.transdate,   opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,
coalesce(opbill.chequedate,opbill.transferdate),  'OP', opbill.bankname, 
coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno),usedatarange
from opbill
where  opbill.transdate= opbill.billdate and opbill.modeid <> 1 and opbill.transdate between  starttime and endtime;
------- Insert others start---------------

---------------------- Company amount --------------------------------
with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger,  sum(billDtls.credit_payable) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join public.t_company_master comp on comp.company_id = billDtls.payee_id 
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1 and billDtls.payee_id <> 1
group by  billDtls.payee_id,comp.company_desc, billDtls.created_date, billMst.organisation_id, billMst.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, 
comp.orgId,'OP',usedatarange 
from comp;

------------------------------Package consumption ---------------------------------
with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , 
bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date  as createdDate
from billing.t_billing_details dtls 
inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = dtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_id
where dtls.created_date between  starttime and endtime  and  bill.visit_type_id = 1 and ordt.is_package_service = 'Y'
group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date, bill.organisation_id, bill.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, 
pack.orgId, 'OP',usedatarange 
from pack;
--------------------------------------------------
-------------------- Insert deposit consumption --------------------------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount,
unit_id, hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales', 'Patient Advance', pdc.created_date, 
sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP',usedatarange
from billing.t_payment_deposite_consumption_details pdc
inner join billing.t_payment_deposite_consumption pd
on pd.dep_consumption_id = pdc.dep_consumption_id
inner join billing.m_billing_master bill
on bill.billing_master_id = pd.bill_id
where pdc.created_date between  starttime and endtime and bill.visit_type_id = 1
group by  pdc.organization_id, pdc.unit_id,pdc.created_date;

-------------------xxx-------------------------------------
------- Insert outstanding start---------------
with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, 
bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time as billDate
from billing.m_billing_master bill
where bill.bill_date_time between  starttime and endtime and bill.visit_type_id = 1
group by bill.organisation_id, bill.unit_id, bill.bill_date_time),
cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitId
from billing.t_billing_details billdt 
inner join  billing.m_billing_master bill
on bill.billing_master_id = billdt.billing_master_id
where bill.bill_date_time between  starttime and endtime and bill.visit_type_id = 1
group by billdt.organization_id, billdt.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, 
credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales','Patient Credit', outst.billDate, 
outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP',usedatarange 
from outst , cred
where (outst.outstanding - cred.creditpayable) > 0;

------- Insert outstanding end---------------

-------------------- Discount --------------------------
with gen as (select   sum(billDtls.discount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by billDtls.created_date, billMst.organisation_id, billMst.unit_id 
having  sum(billDtls.discount) > 0)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,
hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 
0, gen.unitId, gen.orgId,'OP',usedatarange from gen;
------------------------------------------------
------------ Ledger start -------------------------
with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger,  
sum(billDtls.gross_amount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by genLedMSt.general_ledger_id, billDtls.created_date, billMst.organisation_id, billMst.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, 
hospital_id,tran_type,findatavaluerange)
select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, 
gen.orgId,'OP',usedatarange from gen;
	------------ Ledger end -------------------------
	
-------------------- Tax ---------------------------
with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.m_tax tax on tax.id = billDtls.tax_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by billDtls.tax_id, tax."name", billDtls.created_date, billMst.organisation_id, billMst.unit_id
having sum(billDtls.tax_amount) > 0)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id, tran_type,findatavaluerange)
select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0,
gen.amount, gen.unitId, gen.orgId, 'OP',usedatarange from gen;
