declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin 
	
	-- insert cash mode advance refund amount
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, 
	hospital_id, tran_type,findatavaluerange)
	select voucherno, 'Payment', 'Patient Advance', prm.created_date, sum(prm.amount_refunded), 0 , 
	 prm.unit_id, prm.orgnisation_id, 'IP',usedatarange
	from billing.t_payment_refund_master prm 
	where prm.is_cn_or_deposit = 0 and prm.created_date between  starttime and endtime
	group by prm.orgnisation_id, prm.unit_id,prm.created_date;
	--- xxx
	
	--- create view for payment details
	create or replace temporary view refundpaydtls
	 as 
	select prd.payment_refund_details_id as id, prd.payment_mode_id as modeid, pmod.payment_mode_desc as mode, prd.amount as amount,
	prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd.date as chequedate,
	prd.orgnisation_id as orgid, prd.unit_id as unitid, prd.created_date as date, bank.bank_name as bankname
	from billing.t_payment_refund_details prd
	inner join public.m_payment_mode_master pmod on pmod.payment_mode_id = prd.payment_mode_id
	inner join billing.t_payment_refund_master prm on prm.payment_refund_id = prd.payment_refund_id
	left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
	where prm.is_cn_or_deposit = 0;
	--xxx
	
	--- insert cash mode transactions
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
	unit_id, hospital_id, tran_type,findatavaluerange)
	select voucherno, 'Payment', rpd.mode,  rpd.date,   0, sum(rpd.amount) , rpd.unitid, 
	rpd.orgid , 'IP',usedatarange
	from refundpaydtls rpd
	where rpd.date between  starttime and endtime and rpd.modeid = 1
	group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;
	---xxx
	
	--- insert other mode transactions
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
	unit_id, hospital_id,unique_number,
	instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)
	select voucherno, 'Payment', rpd.mode,  rpd.date,   0, rpd.amount , rpd.unitid, rpd.orgid, rpd.id,
	coalesce(rpd.chequedate,rpd.date), 'IP', rpd.bankname,
	coalesce(rpd.chequenumber, rpd.cardnumber),usedatarange
	from refundpaydtls rpd
	where rpd.date  between  starttime and endtime and rpd.modeid != 1;
end;

------------------------------End enddate---------------------------------------------------------
	





