--
-- TOC entry 3975 (class 1255 OID 2969327)
-- Name: appointment_log_procedure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appointment_log_procedure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	IF NEW.appointment_status_id=1 AND NEW.appointment_type_id=1 AND NEW.is_appointment_from_my_life='N' then
        INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)
      VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
    END IF;
   IF NEW.appointment_type_id=1 and NEW.is_direct_encounter='Y' and NEW.appointment_status_id=8 then
        INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)
      VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',1,new.organization_id);
    END IF;
   IF (NEW.appointment_status_id=3 OR NEW.appointment_status_id=2 ) AND (NEW.appointment_type_id=1 AND NEW.is_appointment_from_my_life!='R')  then
        INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)
      VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
    END IF;
   IF (NEW.appointment_status_id=5 AND NEW.appointment_type_id=1)  then
        INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)
      VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
    END IF;
   	IF NEW.appointment_type_id=1 AND NEW.appointment_status_id=6 then
   	  INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)
      VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
       INSERT INTO public.t_schedule_logs
        (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)
      VALUES('AppointmentDetails', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',new.organization_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- TOC entry 3999 (class 1255 OID 2969328)
-- Name: billconsultantdoctorname(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billconsultantdoctorname(id integer, visitid integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE passed varchar(100);

BEGIN 
	if  VisitId = 2 then
	select DocMaster.first_name || ' ' || DocMaster.last_name as DoctorName into passed  from billing.m_billing_master BM
	inner join adt.t_admission AD on BM.admission_id = AD.admission_id
	inner join doctor.m_doctor_master DocMaster on AD.doctor_id = DocMaster.doctor_id
	where  BM.visit_type_id=VisitId and AD.Admission_id=Id;
	elseif VisitId = 1 then
	select DocMaster.first_name || ' ' || DocMaster.last_name as DoctorName into passed from billing.m_billing_master BM
	inner join opd.t_encounter_master EM on BM.encounter_id = EM.encounter_id
	inner join doctor.m_doctor_master DocMaster on EM.doctor_id = DocMaster.doctor_id
	where  BM.visit_type_id=VisitId  and EM.encounter_id=Id;
	end if;

        RETURN passed;
END;
$$;


--
-- TOC entry 4065 (class 1255 OID 4691122)
-- Name: bulkservicesave(json, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.bulkservicesave(servicearray json, INOUT failedrecret character varying)
    LANGUAGE plpgsql
    AS $$
--failedRecRet varchar
declare
  serviceArray json := serviceArray;failedrecordjson json[];isServiceMappedToUnit boolean:=false;patCatCount integer;
  obj json;obj1 json;obj2 json;visitMap json;flag boolean;availServId Integer:=null;failedRec varchar:='';
  tariffDataJson json;tariffWithBillBedWiseRate json;patCatJson json;billBedVisitMapper json;allPatCat json;serviceTariffId integer:=null;
 
  orgId integer:=null;unitId integer:=null;deptId integer:=null;subDeptId integer:=null;ledgerId integer:=null;serviceId integer:=null;
  validFrm timestamp:=null;validTo timestamp:=null;isExist BOOLEAN;
  orgName varchar;unitName varchar;deptName varchar;subDeptName varchar;ledgerName varchar;
  serviceCode varchar;serviceName varchar;serviceBasePrice decimal;validFrom  varchar;validTill varchar;visitTypeId integer;failedReason varchar:='';
 
  --unit service tariff master
  tariffName varchar;paymentEntitlement varchar;tariffId integer:=null;paymentEntitlementId integer :=null;patCatId integer :=null;billBedCatId integer:=null;

  ---service flags
  isOutsource bpchar:='N';isPackage bpchar:='N';
  isRateEditable bpchar :='N';minRateEditable decimal :=0;maxRateEditable decimal :=0;isTaxApplicable bpchar :='N';
  isRefDoctorShare bpchar :='N';isDiscount bpchar :='N';discountValue decimal=0;
  isAllowMultipleQuantity bpchar :='N';isProcedure bpchar :='N';isPanel bpchar :='N';
  isDiscountApplicable bpchar :='N';isDoctorRequired bpchar :='N';
  isBedSide bpchar :='N';isPOC bpchar :='N';isPeriodicity bpchar :='N';isAutorender bpchar :='N';isAppointable bpchar :='N';gender integer:=0;
  isPacReq bpchar :='N';refSharePer decimal :=0;isReviewApplicable bpchar :='N';reviewTime integer:=0;billOfMaterial bpchar :='N';docRefPer decimal:=0;
  createdBy integer;createdDate timestamp :=now();status bpchar :='A';updatedBy integer;updatedDate timestamp :=now();
  
begin
  FOR obj IN SELECT * FROM json_array_elements(serviceArray)
  loop
   -- RAISE NOTICE 'output from space %', obj->>'type';
     --orgName:=obj->>'orgName';unitName:=obj->>'unitName';
     createdBy:=cast(obj->>'createdBy' as integer);updatedBy:=cast(obj->>'createdBy' as integer); orgId:=cast(obj->>'organizationId' as integer); unitId:=cast(obj->>'unitId' as integer);
     deptName:=obj->>'departmentName';subDeptName:=obj->>'subDepartmentName';ledgerName:=obj->>'ledgerName';
     serviceCode:=obj->>'serviceCode';serviceBasePrice:=obj->>'basePrice';serviceName:=obj->>'serviceName';
     paymentEntitlement:=1; validFrm=now();validTo=now();

     flag:=false;failedReason:='';isServiceMappedToUnit=false;
	 with getLedgerIdByName as (select general_ledger_id from public.m_general_ledger_master glm
     where glm.organisation_id =orgId and lower(glm.general_ledger_name) = lower(ledgerName))
     select general_ledger_id into ledgerId from getLedgerIdByName;
    
     if ledgerId is null then
	 failedReason:='ledger not exist';
	 with ledgerSave as(insert into public.m_general_ledger_master(general_ledger_code,general_ledger_name,status,created_by,created_date,updated_by,updated_date,unit_id,organisation_id)
	 values(ledgerName,ledgerName,status,createdBy,createdDate,updatedBy,updatedDate,unitId,orgId)returning general_ledger_id)
	 select general_ledger_id into ledgerId from ledgerSave;
	-- return;
	 --continue;
	 end if;
	
     with getDeptIdByName as (select speciality_id from doctor.m_speciality_master sm
     where sm.organization_id=orgId and  lower(sm.speciality_name) = lower(deptName))
     select speciality_id into deptId from getDeptIdByName;
   
     if deptId is null then
     --if dept not exist then save it
    -- with departmentSave as (insert into doctor.m_speciality_master(speciality_name,speciality_code,is_surgical_code,created_by,created_date,status,general_ledger_id,updated_by,updated_date,organization_id,
     --is_clinical_speciality,is_rendering_speciality,dept_wise_appointment,is_kiosk_dept,is_nursing_assessment_required,allowed_overbooking_slots)
    -- values(deptName,deptName,'N',createdBy,createdDate,status,ledgerId,updatedBy,updatedDate,orgId,
    -- 'N','N','N','N','N',0)returning speciality_id)
     --select speciality_id into deptId from departmentSave;
	 failedReason:=concat(failedReason,'Department not exist,');
	 flag:=true;
	-- return;
	 --continue;
	 end if;
	
     with getSubDeptIdByName as (select sub_speciality_id from doctor.m_sub_speciality_master subsm
     where subsm.organization_id=orgId and lower(subsm.sub_speciality_name) = lower(subDeptName) and subsm.speciality_id=deptId)
     select sub_speciality_id into subDeptId from getSubDeptIdByName;
    
     if subDeptId is null then
     failedReason:=concat(failedReason,'Sub Department not exist,');
	-- with subDepartmentSave as (insert into doctor.m_sub_speciality_master (sub_speciality_code,sub_speciality_name,created_by,created_date,status,speciality_id,
   --  updated_by,updated_date,organization_id,is_modality,general_ledger_id) 
    -- values(subDeptName,subDeptName,createdBy,createdDate,status,deptId,updatedBy,updatedDate,orgId,'N',ledgerId) returning sub_speciality_id)
    -- select sub_speciality_id into subDeptId from subDepartmentSave;
	-- return;
	 --continue;
	 flag:=true;
	 end if;
	
	--------Check service exist and return service id if exist
	--availServId :=checkServiceExistAgainstOrg(deptName,serviceName,subDeptName,orgId);
	if (deptId is not null) and (subDeptId is not null) then
	with getServIdIfExist as(SELECT sm.service_master_id as id
    from service.m_service_master sm
    inner join doctor.m_speciality_master msm on msm.speciality_id=sm.speciality_id 
    inner join doctor.m_sub_speciality_master mssm on mssm.sub_speciality_id =sm.sub_speciality_id 
    WHERE lower(sm.service_standard_name) = lower(serviceName) and sm.organization_id =orgid and sm.status ='A'
    and msm.speciality_id = deptId and  mssm.sub_speciality_id=subDeptId )
	
    select id into availServId from getServIdIfExist;
    end if;
  
    if availServId is not null then
    isServiceMappedToUnit=exists(select unitServMap.service_id from service.t_unit_service_mapper unitServMap where unitServMap.service_id=availServId 
    and unitServMap.unit_id=unitId);
    --flag=true;
    --failedReason:=concat(failedReason,' service already exist');
    end if;
   
   ----service master  start 
   if flag=false then
   ----- service master save  
   if(availServId is null) then
   with servicesave as (insert into service.m_service_master (organization_id,service_standard_code,service_standard_name,is_available_for_package,is_outsource_service,
   is_ot_procedure,is_order_set,is_rate_editable,min_rate_editable,max_rate_editable,is_discount_applicable,is_allow_multiple_quantity,
   is_doctor_required,is_tax_applicable,is_autorendered,created_by,created_date,status,updated_by,updated_date,speciality_id,sub_speciality_id,
   is_required_schedule,is_on_bed,valid_from,valid_till,general_ledger_id)
   values(orgId,serviceCode,serviceName,'I','I','I','I','I',0,0,'I','I','I','I','I',createdBy,createdDate,status,updatedBy,updatedDate,deptId,subDeptId,'N','N',validFrm,validTo,ledgerId) returning service_master_id)

   select service_master_id into serviceId from servicesave;
   end if;

    ---- service unit mapping 
    if isServiceMappedToUnit=false then
    insert into service.t_unit_service_mapper(service_id,unit_id,orgnisation_id,status,created_by,created_date,updated_by,updated_date) 
    values(serviceId,unitId,orgId,status,createdBy,createdDate,updatedBy,updatedDate);
   
    ------------unit service master detail
    insert into service.t_unit_service_master_details(service_master_id ,is_outsource,is_package ,is_rate_editable,rate_editble_min_value ,rate_editable_max_value,
	is_tax_applicable ,is_ref_doctor_share,is_discount,unit_id,organization_id ,status ,created_by ,created_date ,updated_by ,updated_date ,
	discount_value ,is_panel,is_allow_multiple_quantity ,is_procedure,is_doc_req ,is_bed_side ,is_poc ,is_periodicity ,is_auto_render ,
	is_appointable,gender,is_pacs_req,ref_share_per,is_review_applicable,review_time,bill_of_material,doc_ref_per) 
	values(serviceId,isOutsource,isPackage,isRateEditable,minRateEditable,maxRateEditable,isTaxApplicable,isRefDoctorShare,isDiscount,unitId,orgId,
	status,createdBy,createdDate,updatedBy,updatedDate,discountValue,isPanel,isAllowMultipleQuantity,isProcedure,isDoctorRequired,isBedSide,
    isPOC,isPeriodicity,isAutorender,isAppointable,gender,isPacReq,refSharePer,isReviewApplicable,reviewTime,billOfMaterial,docRefPer);
    
   -------service base price
   insert into service.m_service_base_price_master (service_master_id,visit_type_id,base_price,from_date,to_date ,
   status,unit_id,organisation_id,created_by,created_date,updated_by,updated_date)values(serviceId,1,
   serviceBasePrice,validFrm,validTo,status,unitId,orgId,createdBy,createdDate,updatedBy,updatedDate);
  
   end if;
  
   end if;--service master  end 
  

   --service tariff master start
  with  getAllPatCategories as(
	SELECT array_to_json(array_agg(row_to_json(data))) 
	from(select
	mpcm.patient_category_id as patcatid
from
	m_patient_category_master mpcm
where
	mpcm.organization_id = orgId
	and mpcm.status = 'A') data)
	select * into allPatCat from getAllPatCategories;

  --with getPaymentEntitleIdByName as (select payment_entitlement_id from m_payment_entitlement_master mpem  where lower(mpem.payment_entitlement_desc)=lower(paymentEntitlement) and mpem.organization_id=orgId  and mpem.status='A')
  --select payment_entitlement_id into paymentEntitlementId from getPaymentEntitleIdByName;
 --Billbedcategorywise rate iteration
 	
  --patcategory wise iteration start
  patCatCount=1;
  FOR patCatJson IN SELECT * FROM json_array_elements(allPatCat)
  loop
    
  FOR tariffDataJson IN SELECT * FROM json_array_elements((obj->>'tariffData')::json)
  loop
  
  FOR tariffWithBillBedWiseRate IN SELECT * FROM json_array_elements((tariffDataJson->>'tariffWithBillBedCatWiseRate')::json)
  loop
   --get tarriff id
   
  
  if (tariffDataJson->>'tariffName')='' and patCatCount=1 then
      flag=true;
      failedReason:=concat(failedReason,'Tariff name can not be blank,');
  else
   with getTariffIdByName as (select tariff_id from service.m_tariff_master mtm where lower(mtm.tariff_desc)=lower(tariffDataJson->>'tariffName') and mtm.organization_id=orgId )
   select tariff_id into tariffId from getTariffIdByName;
   if tariffId is null then
      flag=true;
      failedReason:=concat(failedReason,(tariffDataJson->>'tariffName'),' not exist,');
   end if;
  end if;
 
---------------------Billing bed category check---------------
 if (tariffWithBillBedWiseRate->>'billingBedCategory')='' and patCatCount=1 then
      flag=true;
      failedReason:=concat(failedReason,'Billing bed category name can not be blank,');
  else
  with getBillBedCatByName as (select billing_bed_category_id from adt.m_billing_bed_category_master bbcm 
  where lower(bbcm.billing_bed_desc) =lower(tariffWithBillBedWiseRate->>'billingBedCategory') and bbcm.organization_id =orgId)
  select billing_bed_category_id into billBedCatId from getBillBedCatByName;

   if billBedCatId is null and patCatCount=1 then
      flag=true;
      failedReason:=concat(failedReason,(tariffWithBillBedWiseRate->>'billingBedCategory'),' not exist,');
     else
     --get all visit type mapped with billing bed category
	with  visitMapper as(
	SELECT array_to_json(array_agg(row_to_json(data))) 
	from(select
		bbvtm.visit_type_id as id
	from    adt.t_billing_bed_visit_type_mapper bbvtm 
	where
	bbvtm.billing_bed_category_id =billBedCatId
	and bbvtm.status = 'A'
	and bbvtm.organization_id =orgId
	and bbvtm.unit_id =unitId) data)
	select * into visitMap from visitMapper;
 
     if visitMap is null and patCatCount=1 then
      flag=true;
      failedReason:=concat(failedReason,'Visit type not mapped with billing bed category,');
	 --failedRe:='bill bed category not map to visit type';
	 end if;
   end if;
   
  end if;
	
	if(tariffWithBillBedWiseRate->>'rate') = '' and patCatCount=1 then
	  flag=true;
      failedReason:=concat(failedReason,'Rate can not be blank',' for ',(tariffDataJson->>'tariffName'),' ',(tariffWithBillBedWiseRate->>'billingBedCategory'),',');
	end if;
	
    
  if (serviceId is not null) and (tariffId is not null) and (billBedCatId is not null) and (visitMap is not null) 
	  and (allPatCat is not null) and (tariffWithBillBedWiseRate->>'rate' <> '') then
	  FOR billBedVisitMapper IN SELECT * FROM json_array_elements(visitMap)
	  loop
	 
		   with checkUnitServiceTariffDefined as (select ustm.unit_service_tariff_id as id from service.m_unit_service_tariff_master ustm
		   where ustm.service_id =serviceId and ustm.tariff_id =tariffId and ustm.billing_bed_category_id =billBedCatId 
		   and ustm.patient_type_id =cast(patCatJson->>'patcatid' as integer) and ustm.visit_type_id =cast(billBedVisitMapper->>'id' as integer) 
		   and ustm.status='A')
	       select id into serviceTariffId from checkUnitServiceTariffDefined;
		   
		  --if serviceTariffId is null then
		  INSERT INTO service.m_unit_service_tariff_master
		  (organization_id, unit_id, service_id, tariff_id, payment_entitlement_id, visit_type_id, patient_type_id, billing_bed_category_id,rate,stat_per,effective_date)
		  VALUES(orgId, unitId, serviceId, tariffId, 1, cast(billBedVisitMapper->>'id' as integer), cast(patCatJson->>'patcatid' as integer), billBedCatId, 
		  cast( tariffWithBillBedWiseRate->>'rate' as numeric(10,2)), 0, now());
		  --end if;
		 
	  end loop ; --end of visit type list json
   end if;
   
  end loop ;--end of tariffwithbillbedwiseratearray
  end loop ;--end of tariff array
  patCatCount=2;
  end loop;--end of patcatarray
  	
  if flag=true then
      if(failedReason!='') then
	  failedReason=substring(failedReason,0,length(failedReason));
	  end if;
	  failedRec:=obj::varchar;
	  failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedReason,'"}');
	  failedRecordJson := array_append(failedRecordJson,failedRec::json);
   continue;
  end if;
 end loop;--end of service array
 
	failedRecRet :=failedRecordJson::varchar;
	failedRecRet:=substring(failedRecRet,2,(length(failedRecRet)-2));
	failedRecRet:=concat('{"failedRecordJson":[','',failedRecRet,'',']}');
    failedRecRet= replace(replace(failedRecRet, '"{', '{'),'}"','}');
    failedRecRet= replace(failedRecRet,'\','');
 EXCEPTION 
 when OTHERS then 
	failedRecRet='failed to insert records';
 COMMIT;

END;
$$;


--
-- TOC entry 4045 (class 1255 OID 4243098)
-- Name: casepapercount(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.casepapercount(encdate date, doctorid integer, unitid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare casecount integer;

begin 
	
	select coalesce(count(encounter_id),0) into casecount from opd.t_encounter_master em 
          where em.doctor_id = doctorid  and  
          em.encounter_date::date = encdate and em.unit_id = unitid ;

return casecount;
end;
$$;


--
-- TOC entry 4047 (class 1255 OID 4243097)
-- Name: casepapercount(timestamp without time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.casepapercount(encdate timestamp without time zone, doctorid integer, unitid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare casecount integer;

begin 
	
	select coalesce(count(encounter_id),0) into casecount from opd.t_encounter_master em 
          where em.doctor_id = doctorid  and  
          em.encounter_date::date = encdate and em.unit_id = unitid ;

return casecount;
end;
$$;


--
-- TOC entry 4000 (class 1255 OID 2969329)
-- Name: ceo_dashboard(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ceo_dashboard(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

begin

--truncate m_bill_stats
truncate m_bill_stats;


-- bill stat
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, payment_mode_id, payment_mode, amount) 
select prd.orgnization_id,prd.unit_id,bm.visit_type_id,vtm.visit_type_code,prd.payment_mode_id,pm.payment_mode_code, sum (prd.amount) 
from billing.t_payment_reciept_details prd 
inner join billing.t_payment_reciept_master prm on prm.payment_reciept_id=prd.payment_receipt_master_id
inner join billing.m_billing_master bm on bm.billing_master_id= prm.billing_master_id
inner join public.m_visit_type_master vtm on bm.visit_type_id= vtm.visit_type_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id= prd.payment_mode_id
where prd.date_of_transaction::date=dateoftrans and prd.status = 'A'
group by bm.visit_type_id, prd.payment_mode_id,prd.payment_mode_id,prd.orgnization_id,prd.unit_id,
 vtm.visit_type_code, pm.payment_mode_code;
-- bill stat


-- bed counts
INSERT INTO public.m_bill_stats
(organization_id, unit_id, bed_category_id,bed_category,occupied_count,houskeeping_count,bed_vacant_count) 
select
	bedcategor0_.organization_id,
	bedcategor0_.unit_id,
	bedcategor0_.bed_category_id ,
	bedcategor0_.bed_category_desc,
	(
		select count(bedmaster1_.bed_id)
	from
		adt.m_bed_master bedmaster1_
	inner join adt.t_bed_log_status listbedlog2_ on
		bedmaster1_.bed_id = listbedlog2_.bed_id
	where
		listbedlog2_.bed_status_id = 3
		and bedmaster1_.bed_category_id = bedcategor0_.bed_category_id
		and listbedlog2_.status = 'A'
		and listbedlog2_.updated_date::date=dateoftrans) ,
	(
		select count(bedmaster3_.bed_id)
	from
		adt.m_bed_master bedmaster3_
	inner join adt.t_bed_log_status listbedlog4_ on
		bedmaster3_.bed_id = listbedlog4_.bed_id
	where
		listbedlog4_.bed_status_id = 2
		and bedmaster3_.bed_category_id = bedcategor0_.bed_category_id
		and listbedlog4_.status = 'A'
		and listbedlog4_.updated_date::date=dateoftrans) ,
	(
		select count(bedmaster5_.bed_id)
	from
		adt.m_bed_master bedmaster5_
	inner join adt.t_bed_log_status listbedlog6_ on
		bedmaster5_.bed_id = listbedlog6_.bed_id
	where
		listbedlog6_.bed_status_id = 5
		and bedmaster5_.bed_category_id = bedcategor0_.bed_category_id
		and listbedlog6_.status = 'A'
		and listbedlog6_.updated_date::date=dateoftrans)
	
from
	adt.m_bed_category_master bedcategor0_
where
	 bedcategor0_.status = 'A'
order by
	bedcategor0_.bed_category_id;

-- bed counts


-- procedure count
INSERT INTO public.m_bill_stats
(organization_id, unit_id, procedure_count) 

select
	org_id,org_unit_id, count(order_details_id)
	
from
	t_order_details
where
	service_id in (
		select service_master_id
	from
		service.t_unit_service_master_details
	where
		is_procedure = 'Y')
	and service_rendered = 1
	and service_is_billed = 1
	and status = 'A'
	and ord_render_datetime::date= dateoftrans
group by
	org_unit_id,
	org_id;

--EHC Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id, ehc_count) 

select
	organization_id,
	unit_id,
	count(encounter_id)
	
	
from
	opd.t_encounter_master
where
	encounter_type_id = 3
	and encounter_date::date = dateoftrans
group by
	unit_id,
	organization_id;

--Diagnostics Count
--Lab Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, lab_count) 

select
	od.org_id,
	od.org_unit_id,
	om.visit_type_id,
	vtm.visit_type_code,
	count(od.order_details_id)
	
from
	t_order_details od
inner join t_order_master om on
	om.order_id = od.order_id
inner join service.m_service_master ser on
	ser.service_master_id = od.service_id
inner join public.m_visit_type_master vtm on 
om.visit_type_id= vtm.visit_type_id
where
	od.service_rendered = 1
	and od.status = 'A'
	and od.ord_render_datetime::date= dateoftrans
	and ser.speciality_id in (
		select lab_speciality_id
	from
		t_lab_configuration
	where
		unit_id = od.org_unit_id
		and status = 'A')
group by
	om.visit_type_id,
	vtm.visit_type_code,
	od.org_unit_id,
	od.org_id;

--Radiology Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, radiology_count) 
select
	od.org_id,
	od.org_unit_id,
	om.visit_type_id,
	vtm.visit_type_code,
	count(od.order_details_id)
	
from
	t_order_details od
inner join t_order_master om on
	om.order_id = od.order_id
inner join service.m_service_master ser on
	ser.service_master_id = od.service_id
inner join public.m_visit_type_master vtm on
	om.visit_type_id= vtm.visit_type_id
where
	od.service_rendered = 1
	and od.status = 'A'
	and od.ord_render_datetime::date= dateoftrans
	and ser.speciality_id in(
		select radiology_speciality_id
	from
		t_unit_application_billing_configuration where unit_id= od.org_unit_id
		and status = 'A')
group by
	om.visit_type_id,
	vtm.visit_type_code,
	od.org_unit_id,
	od.org_id;

--Admission Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, admission_count)
select
    organization_id,
	unit_id,
	visit_type_id,
	visit_type_code,
	count(unit_id) 
from
	public.getadmittedpatientlist
where
	--unit_id = 1
	 admission_date::date = dateoftrans
group by
	visit_type_id, visit_type_code, organization_id, unit_id
union 
select organization_id,
	unit_id,
	1 as visit_type_id,
	'OP' as visit_type_code,
		count(unit_id) 
	  from opd.t_encounter_master
	  where 
	 encounter_date::date = dateoftrans
	group by
	visit_type_id, visit_type_code, organization_id, unit_id;	


--Discharge Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, discharge_count) 
select
	organization_id,
	unit_id,
	visit_type_id,
	visit_type_code,
	count(unit_id)
from
	public.getdischargedetails
where
	discharge_Date::date = dateoftrans
group by
	visit_type_id, visit_type_code, organization_id, unit_id;

--Death Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, death_count) 

select 
dch.organization_id,
dch.unit_id,
dch.visit_type_id,
vtm.visit_type_code,
count(unit_id)
from
	adt.t_discharge dch
	inner join public.m_visit_type_master vtm on vtm.visit_type_id=dch.visit_type_id
where
	dch.discharge_type_id = 2
	--and dch.status = 'A'
	and dch.discharge_status_id = 5
	and dch.created_date::date= dateoftrans
group by dch.organization_id,
dch.unit_id,vtm.visit_type_code,dch.visit_type_id;

--total out patients visit count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,user_defined_visit_type_id, totat_pat_count) 

select 
	organization_id,
	unit_id,
	user_defined_visit_type_id ,
	count(unit_id)
from 
	public.getopdconsultatationdoctorwise 
where 
	bill_date_time::date=dateoftrans
group by  
	user_defined_visit_type_id,organization_id,unit_id;

-----discount
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, discount_count) 

select
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code,
	sum(bm.discount_amount)
from 
	billing.m_billing_master bm
inner join public.m_visit_type_master vtm on bm.visit_type_id=vtm.visit_type_id

where
	bm.bill_date_time::date=dateoftrans
	and bm.bill_cancelled = 'N'
group by
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code;
-----discount

----credit notes
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, credit_note_count) 

select
	
	crd.organisation_id ,
	crd.unit_id ,
	bill.visit_type_id,
	vtm.visit_type_code,
	sum(crd.cr_net_amount)
from
	billing.m_credit_note_master crd
inner join billing.m_billing_master bill on
	bill.billing_master_id = crd.bill_id
inner join public.m_visit_type_master vtm on
	bill.visit_type_id = vtm.visit_type_id
where
	bill.bill_date_time :: date= dateoftrans
group by
	bill.visit_type_id,
	vtm.visit_type_code,
	crd.organisation_id,
	crd.unit_id;
----credi notes


----refund	
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, refund_count) 
select
	
	prd.orgnisation_id,
	prd.unit_id,
	billmst.visit_type_id,
	vtm.visit_type_code,
	sum(prd.amount) as amount
from
	billing.t_payment_refund_master prm
inner join billing.t_payment_refund_details prd on
	prd.payment_refund_id = prm.payment_refund_id
inner join billing.m_credit_note_master cnm on
	cnm.credit_note_id = prm.credit_note_id
inner join billing.m_billing_master billmst on
	billmst.billing_master_id = cnm.bill_id 
inner join public.m_visit_type_master vtm on
	billmst.visit_type_id = vtm.visit_type_id 
where
	prm.date_of_refund::date =dateoftrans
group by
	billmst.visit_type_id,
	vtm.visit_type_code,
	prd.orgnisation_id,
	prd.unit_id;
----refund

------insurance
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, company_type_id, company_type, insurance_count) 
select
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code,
	com.company_type_id,
	'Insurance',
	sum(bpd.bill_amount)
	
from
	billing.t_bill_payee_details bpd
inner join billing.m_billing_master bm on
	bpd.bill_id = bm.billing_master_id
inner join t_company_master com on
	com.company_id = bpd.payee_id
inner join m_company_type_master ctm on
	com.company_type_id = ctm.company_type_id
inner join public.m_visit_type_master vtm on
	bm.visit_type_id = vtm.visit_type_id
where
	com.company_type_id = 2
	and bm.bill_date_time::date= dateoftrans
	and bm.bill_cancelled = 'N'
group by
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code,
	com.company_type_id,
	ctm.company_type_code;
------insurance


-----company
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, company_type_id, company_type, corporate_company_count) 

select
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code,
	com.company_type_id,
	'Company',
	sum(bpd.bill_amount)
from
	billing.t_bill_payee_details bpd
inner join billing.m_billing_master bm on
	bpd.bill_id = bm.billing_master_id
inner join t_company_master com on
	com.company_id = bpd.payee_id
inner join m_company_type_master ctm on
	com.company_type_id = ctm.company_type_id
inner join public.m_visit_type_master vtm on
	bm.visit_type_id = vtm.visit_type_id
where
	com.company_type_id = 3
	and bm.bill_date_time::date= dateoftrans
	and bm.bill_cancelled = 'N'
group by
	bm.organisation_id,
	bm.unit_id,
	bm.visit_type_id,
	vtm.visit_type_code,
	com.company_type_id,
	ctm.company_type_code;
-----company
	
return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


--
-- TOC entry 4001 (class 1255 OID 2969331)
-- Name: ceo_dashboard_123(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ceo_dashboard_123(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

begin
--declare dateoftrans1 date;

--truncate m_bill_stats
truncate m_bill_stats;


-- bill stat
create or replace temporary view 
billstat as
select sum (prd.amount) as amount ,bm.visit_type_id as visit_type_id, vtm.visit_type_code as visit_type, pm.payment_mode_code as payment_mode,
prd.payment_mode_id as payment_mode_id ,prd.orgnization_id as orgnization_id,prd.unit_id as unit_id
from billing.t_payment_reciept_details prd 
inner join billing.t_payment_reciept_master prm on prm.payment_reciept_id=prd.payment_receipt_master_id
inner join billing.m_billing_master bm on bm.billing_master_id= prm.billing_master_id
inner join public.m_visit_type_master vtm on bm.visit_type_id= vtm.visit_type_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id= prd.payment_mode_id
where cast(date_of_transaction as date) = cast(dateoftrans as date) group by bm.visit_type_id, prd.payment_mode_id,prd.payment_mode_id,prd.orgnization_id,prd.unit_id,
 vtm.visit_type_code, pm.payment_mode_code;
	/*
INSERT INTO public.m_bill_stats
(organization_id, unit_id, visit_type_id, visit_type, payment_mode_id, payment_mode, amount) 
select bs.orgnization_id, bs.unit_id, bs.visit_type_id, bs.visit_type, bs.payment_mode_id, bs.payment_mode, bs.amount from billstat bs ;

-- bill stat


-- bed counts

INSERT INTO public.m_bill_stats
(organization_id, unit_id, bed_category_id,bed_category,occupied_count,houskeeping_count,bed_vacant_count) 
select
	bedcategor0_.organization_id,
	bedcategor0_.unit_id,
	bedcategor0_.bed_category_id ,
	bedcategor0_.bed_category_desc,
	(
		select count(bedmaster1_.bed_id)
	from
		adt.m_bed_master bedmaster1_
	inner join adt.t_bed_log_status listbedlog2_ on
		bedmaster1_.bed_id = listbedlog2_.bed_id
	where
		listbedlog2_.bed_status_id = 3
		and bedmaster1_.bed_category_id = bedcategor0_.bed_category_id
		--and bedmaster1_.organization_id =1
		--and bedmaster1_.unit_id =1
		and listbedlog2_.status = 'A'
		and cast(listbedlog2_.updated_date as date)=dateoftrans) ,
	(
		select count(bedmaster3_.bed_id)
	from
		adt.m_bed_master bedmaster3_
	inner join adt.t_bed_log_status listbedlog4_ on
		bedmaster3_.bed_id = listbedlog4_.bed_id
	where
		listbedlog4_.bed_status_id = 2
		and bedmaster3_.bed_category_id = bedcategor0_.bed_category_id
		--and bedmaster3_.organization_id =1
		--and bedmaster3_.unit_id =1
		and listbedlog4_.status = 'A'
		and cast(listbedlog4_.updated_date as date)=dateoftrans) ,
	(
		select count(bedmaster5_.bed_id)
	from
		adt.m_bed_master bedmaster5_
	inner join adt.t_bed_log_status listbedlog6_ on
		bedmaster5_.bed_id = listbedlog6_.bed_id
	where
		listbedlog6_.bed_status_id = 5
		and bedmaster5_.bed_category_id = bedcategor0_.bed_category_id
		--and bedmaster5_.organization_id =1
		--and bedmaster5_.unit_id =1
		and listbedlog6_.status = 'A'
		and cast(listbedlog6_.updated_date as date)=dateoftrans)
	
from
	adt.m_bed_category_master bedcategor0_
where
	--bedcategor0_.organization_id =1
	--and bedcategor0_.unit_id =1
	 bedcategor0_.status = 'A'
order by
	bedcategor0_.bed_category_id;

-- bed counts


-- procedure count
INSERT INTO public.m_bill_stats
(organization_id, unit_id, procedure_count) 

select
	org_id,org_unit_id, count(order_details_id)
	
from
	t_order_details
where
	service_id in (
		select service_master_id
	from
		service.t_unit_service_master_details
	where
		is_procedure = 'Y')
	and service_rendered = 1
	and service_is_billed = 1
	and cast(ord_render_datetime as date)= dateoftrans
group by
	org_unit_id,
	org_id;

--EHC Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id, ehc_count) 

select
	organization_id,
	unit_id,
	count(encounter_id)
	
	
from
	opd.t_encounter_master
where
	encounter_type_id = 3
	and cast(encounter_date as date) = dateoftrans
group by
	unit_id,
	organization_id;

--Diagnostics Count
--Lab Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, lab_count) 

select
	od.org_id,
	od.org_unit_id,
	om.visit_type_id,
	vtm.visit_type_code,
	count(od.order_details_id)
	
from
	t_order_details od
inner join t_order_master om on
	om.order_id = od.order_id
inner join service.m_service_master ser on
	ser.service_master_id = od.service_id
inner join public.m_visit_type_master vtm on 
om.visit_type_id= vtm.visit_type_id
where
	od.service_rendered = 1
	and cast(od.ord_render_datetime as date)= dateoftrans
	and ser.speciality_id in (
		select lab_speciality_id
	from
		t_lab_configuration
	where
		unit_id = od.org_unit_id
		and status = 'A')
group by
	om.visit_type_id,
	vtm.visit_type_code,
	od.org_unit_id,
	od.org_id;

--Radiology Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, radiology_count) 
select
	od.org_id,
	od.org_unit_id,
	om.visit_type_id,
	vtm.visit_type_code,
	count(od.order_details_id)
	
from
	t_order_details od
inner join t_order_master om on
	om.order_id = od.order_id
inner join service.m_service_master ser on
	ser.service_master_id = od.service_id
inner join public.m_visit_type_master vtm on
	om.visit_type_id= vtm.visit_type_id
where
	od.service_rendered = 1
	and cast(od.ord_render_datetime as date)= dateoftrans
	and ser.speciality_id in(
		select radiology_speciality_id
	from
		t_unit_application_billing_configuration where unit_id= od.org_unit_id
		and status = 'A')
group by
	om.visit_type_id,
	vtm.visit_type_code,
	od.org_unit_id,
	od.org_id;

--Admission Count
INSERT INTO public.m_bill_stats
(organization_id, unit_id,visit_type_id, visit_type, admission_count)
select
    organization_id,
	unit_id,
	visit_type_id,
	visit_type_code,
	count(*)
from
	public.getadmittedpatientlist
