CREATE FUNCTION public.checkserviceexist(servname character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT *
    from service.m_service_master
    WHERE lower(service_standard_name) = lower(servName) );
END
$$;


--
-- TOC entry 4050 (class 1255 OID 4343363)
-- Name: checkserviceexistcall(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkserviceexistcall(servname character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE 
servId integer :=null;
BEGIN
  with serviceChk as (
    SELECT service_master_id 
    from service.m_service_master
    WHERE lower(service_standard_name) = lower(servName) )
   select service_master_id into servId from serviceChk;
  if servId is not null then
  return true;
  else 
  return false;
  end if;
END
$$;


