--
-- TOC entry 4007 (class 1255 OID 2969333)
-- Name: collection_sms(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collection_sms(todays_date text, unit integer) RETURNS TABLE(self_adm_count bigint, credit_adm_count bigint, self_dis_count bigint, credit_dis_count bigint, new_visit_count bigint, follow_up_visit_count bigint, deth_count bigint, total_amt numeric, refund_amt numeric, deposit_amt numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE 

BEGIN
	RETURN QUERY 	
	select 
		(select count(adm.admission_id) 
		from opd.t_patient_sponsor_details psd 
		inner join adt.t_admission adm on adm.admission_id = psd.admission_id
		where psd.admission_id is not null 
		and psd.unit_id=unit
		and psd.priority_id = 1 
		and psd.payee_id =1 
		and to_char (adm.created_date,'yyyy-mm-dd')=todays_date
		and adm.status='A')as self_adm_count,
		
		(select count(adm.admission_id) 
		from opd.t_patient_sponsor_details psd 
		inner join adt.t_admission adm on adm.admission_id = psd.admission_id
		where psd.admission_id is not null 
		and psd.priority_id = 1 
		and psd.unit_id=unit
		and psd.payee_id !=1 
		and to_char (adm.created_date,'yyyy-mm-dd') =todays_date
		and adm.status='A') as credit_adm_count,
		
		
		(select count(adm.admission_id) 
		from opd.t_patient_sponsor_details psd 
		inner join adt.t_admission adm on adm.admission_id = psd.admission_id
		inner join adt.t_discharge dis on dis.admission_id = adm.admission_id
		where psd.admission_id is not null 
		and psd.priority_id = 1 
		and psd.payee_id =1 
		and psd.unit_id=unit
		and to_char (adm.created_date,'yyyy-mm-dd') =todays_date
		and adm.status='A'
		and dis.discharge_status_id = 5)as self_dis_count,
		
		(select count(adm.admission_id) 
		from opd.t_patient_sponsor_details psd 
		inner join adt.t_admission adm on adm.admission_id = psd.admission_id
		inner join adt.t_discharge dis on dis.admission_id = adm.admission_id
		where psd.admission_id is not null 
		and psd.priority_id = 1 
		and psd.payee_id !=1 
		and psd.unit_id=unit
		and to_char (adm.created_date,'yyyy-mm-dd') =todays_date
		and adm.status='A'
		and dis.discharge_status_id = 5)as creditDisCount,
		
		(select count(encounter_id)  from opd.t_encounter_master where user_defined_visit_type_id = 1 and unit_id=unit and to_char(created_date,'yyyy-mm-dd') = todays_date )as newVisitCount,
		
		(select count(encounter_id) from opd.t_encounter_master where user_defined_visit_type_id != 1 and unit_id=unit and to_char(created_date,'yyyy-mm-dd') = todays_date )  as followUpVisitCount,
		
		(select count(admission_id)  from adt.t_discharge where discharge_type_id=2 and unit_id=unit and status='A' and discharge_status_id=5 and to_char(created_date,'yyyy-mm-dd') = todays_date)as dethCount,
		
		 (SELECT coalesce(cast(sum(prm.amount) as numeric(10,2)),0)
		   	 FROM billing.t_payment_reciept_master prm where to_char(prm.date_of_reciept,'yyyy-mm-dd')='2019-04-12' and prm.unit_id=unit	) as total_amt , 
     
     	(select coalesce(cast(sum(prm.amount_refunded) as numeric(10,2)),0) from billing.t_payment_refund_master prm WHERE to_char(prm.created_date,'yyyy-mm-dd')=todays_date and prm.unit_id=unit) as refund_amt,
     	
     	(select coalesce(cast(sum(dp.deposit_amount) as numeric(10,2)),0) from billing.m_deposit_master dp WHERE to_char(dp.created_date,'yyyy-mm-dd')=todays_date and dp.unit_id=unit ) as deposit_amt
     	;
		
END;
$$;


--
-- TOC entry 4010 (class 1255 OID 2969334)
-- Name: createbarcodecode128(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.createbarcodecode128(barcode character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

  declare site_value integer;
   v_data_to_encode VARCHAR;
   check_digit_char VARCHAR;
   check_digit INT8;
   start_character VARCHAR(0203); 
   stop_character varchar(0206);
   current_value bigint;       
   encoded_string VARCHAR(1000);
   weight_total int8;
   mrLen BIGINT;
begin	
     site_value = 1;
     v_data_to_encode = Barcode;

-- Calcuation variables

  start_character = '0203';
  stop_character = '0206';
  weight_total = ASCII(start_character) - 100;
  mrLen := length(v_data_to_encode);
	case when site_value <= mrLen then		
			current_value = CAST(ASCII(SUBSTRING (v_data_to_encode, site_value, 1)) AS BIGINT);		        
			 if current_value < 135 THEN				
					 current_value = (current_value - 32);							
			ELSEif current_value >= 135  THEN				
					 current_value = (current_value - 100);				
			end if;			  
			 current_value = current_value * site_value;
			 weight_total = weight_total + current_value;
  			 site_value = site_value+1;		
		end case;

		check_digit = (weight_total % 103);
  BEGIN
  	if check_digit < 95 and check_digit > 0 THEN
    	 check_digit_char = cast((check_digit + 32) as varchar);
  ELSEif	check_digit >= 95 THEN
	   	 check_digit_char = cast((check_digit + 100) as varchar);
  elseif check_digit = 0 THEN
		 check_digit_char = cast((194) as varchar);
  	end if; 
   encoded_string = replace(v_data_to_encode,' ',cast((194) as varchar));
	 return CONCAT (start_character,encoded_string,check_digit_char,stop_character);
  end;   
 end;
 
$$;


