  opbill
AS
	(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode,  pReceiptDtls.amount  as rcptamount, 
	billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, 
	pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, 
	pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, 
	pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
	billMst.organisation_id as orgid, billMst.unit_id as unitid,
	pReceiptDtls.date_of_transaction  as transdate, billMst.bill_date_time  as billdate,
	pReceiptDtls.trans_transaction_date as transferdate
	from billing.t_payment_reciept_details pReceiptDtls
	inner join public.m_payment_mode_master  pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_id
	inner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id 
	inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_id
	left join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id
	where  billMst.visit_type_id = 1);

------- Insert cash start ---------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type)
select voucherno, 'Sales', opbill.mode,  opbill.transdate,   sum(opbill.rcptamount), 0 , 
opbill.unitId, opbill.orgId , 'OP'
from opbill
where  opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate  between  starttime and endtime
group by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Sales', 
opbill.mode,  opbill.transdate,   opbill.rcptamount, 0 , opbill.unitId, 
opbill.orgId, opbill.paymentreceiptdetailId,
coalesce(opbill.chequedate,opbill.transferdate),  'OP', opbill.bankname, 
coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)
from opbill
where  opbill.transdate= opbill.billdate and opbill.modeid <> 1 and opbill.transdate between  starttime and endtime;
------- Insert others start---------------

---------------------- Company amount --------------------------------
with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger,  sum(billDtls.credit_payable) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join public.t_company_master comp on comp.company_id = billDtls.payee_id 
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1 and billDtls.payee_id <> 1
group by  billDtls.payee_id,comp.company_desc, billDtls.created_date, billMst.organisation_id, billMst.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type)
select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, 
comp.orgId,'OP'
from comp;

------------------------------Package consumption ---------------------------------
with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , 
bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date  as createdDate
from billing.t_billing_details dtls 
inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = dtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_id
where dtls.created_date between  starttime and endtime  and  bill.visit_type_id = 1 and ordt.is_package_service = 'Y'
group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date, bill.organisation_id, bill.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,tran_type)
select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, 
pack.orgId, 'OP' 
from pack;
--------------------------------------------------
-------------------- Insert deposit consumption --------------------------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount,
unit_id, hospital_id,tran_type)
select voucherno, 'Sales', 'Patient Advance', pdc.created_date, 
sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP'
from billing.t_payment_deposite_consumption_details pdc
inner join billing.t_payment_deposite_consumption pd
on pd.dep_consumption_id = pdc.dep_consumption_id
inner join billing.m_billing_master bill
on bill.billing_master_id = pd.bill_id
where pdc.created_date between  starttime and endtime and bill.visit_type_id = 1
group by  pdc.organization_id, pdc.unit_id,pdc.created_date;

-------------------xxx-------------------------------------
------- Insert outstanding start---------------
with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, 
bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time as billDate
from billing.m_billing_master bill
where bill.bill_date_time between  starttime and endtime and bill.visit_type_id = 1
group by bill.organisation_id, bill.unit_id, bill.bill_date_time),
cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitId
from billing.t_billing_details billdt 
inner join  billing.m_billing_master bill
on bill.billing_master_id = billdt.billing_master_id
where bill.bill_date_time between  starttime and endtime and bill.visit_type_id = 1
group by billdt.organization_id, billdt.unit_id)
insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, 
voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales','Patient Credit', outst.billDate, 
outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP'
from outst , cred where (outst.outstanding - cred.creditpayable) > 0;

------- Insert outstanding end---------------

-------------------- Discount --------------------------
with gen as (select   sum(billDtls.discount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by billDtls.created_date, billMst.organisation_id, billMst.unit_id 
having  sum(billDtls.discount) > 0)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,
hospital_id,tran_type)
select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 
0, gen.unitId, gen.orgId,'OP' from gen;
------------------------------------------------
------------ Ledger start -------------------------
with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger,  
sum(billDtls.gross_amount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by genLedMSt.general_ledger_id, billDtls.created_date, billMst.organisation_id, billMst.unit_id)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, 
hospital_id,tran_type)
select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, 
gen.orgId,'OP' from gen;
	------------ Ledger end -------------------------
	
-------------------- Tax ---------------------------
with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,
billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.m_tax tax on tax.id = billDtls.tax_id
where billDtls.created_date between  starttime and endtime and billMst.visit_type_id = 1
group by billDtls.tax_id, tax."name", billDtls.created_date, billMst.organisation_id, billMst.unit_id
having sum(billDtls.tax_amount) > 0)
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id, tran_type)
select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0,
gen.amount, gen.unitId, gen.orgId, 'OP' from gen;
--------------------------------------------------
	
----------------------Previous date settlement start cash-----------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id, tran_type)
select nextVoucherno, 'Sales', opbill.mode,  opbill.transdate,  
sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId, 'OP'
from opbill
where  opbill.transdate != opbill.billdate and opbill.modeid = 1 and opbill.transdate between  starttime and endtime--cash
group by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;
----------------------------
----------------------Previous date settlement start others-----------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select nextVoucherno, 'Sales', 
opbill.mode,  opbill.transdate,   opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, 
opbill.paymentreceiptdetailId,
coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, 
coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)
from opbill
where  opbill.transdate != opbill.billdate and opbill.modeid <> 1 and opbill.transdate between  starttime and endtime;
--------------------------------
------------------------------Credit insert start--------------------------
insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
	unit_id, hospital_id, tran_type)
 	select nextVoucherno, 'Sales', 'Patient Credit',  opbill.transdate,
 	0, sum(opbill.rcptamount), opbill.unitid, opbill.orgid, 'OP'
	from opbill 
	where opbill.transdate between  starttime and endtime and opbill.transdate != opbill.billdate
	group by opbill.transdate, opbill.unitid, opbill.orgid; 

end;

-----------------------------------end postopfadata-----------------------------







-------------------------startdate postadvancerefund------------------------------------------------------

declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin 
	
	-- insert cash mode advance refund amount
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, 
	hospital_id, tran_type)
	select voucherno, 'Payment', 'Patient Advance', prm.created_date, sum(prm.amount_refunded), 0 , 
	 prm.unit_id, prm.orgnisation_id, 'IP'
	from billing.t_payment_refund_master prm 
	where prm.is_cn_or_deposit = 0 and prm.created_date between  starttime and endtime
	group by prm.orgnisation_id, prm.unit_id,prm.created_date;
	--- xxx
	
	--- create view for payment details
	create or replace temporary view refundpaydtls
	 as 
	select prd.payment_refund_details_id as id, prd.payment_mode_id as modeid, pmod.payment_mode_desc as mode, prd.amount as amount,
	prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd.date as chequedate,
	prd.orgnisation_id as orgid, prd.unit_id as unitid, prd.created_date as date, bank.bank_name as bankname
	from billing.t_payment_refund_details prd
	inner join public.m_payment_mode_master pmod on pmod.payment_mode_id = prd.payment_mode_id
	inner join billing.t_payment_refund_master prm on prm.payment_refund_id = prd.payment_refund_id
	left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
	where prm.is_cn_or_deposit = 0;
	--xxx
	
	--- insert cash mode transactions
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
	unit_id, hospital_id, tran_type)
	select voucherno, 'Payment', rpd.mode,  rpd.date,   0, sum(rpd.amount) , rpd.unitid, 
	rpd.orgid , 'IP'
	from refundpaydtls rpd
	where rpd.date between  starttime and endtime and rpd.modeid = 1
	group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;
	---xxx
	
	--- insert other mode transactions
	insert into public.t_finaccial_tally_interface 
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
	unit_id, hospital_id,unique_number,
	instrument_date,tran_type,bank_name,instrument_number)
	select voucherno, 'Payment', rpd.mode,  rpd.date,   0, rpd.amount , rpd.unitid, rpd.orgid, rpd.id,
	coalesce(rpd.chequedate,rpd.date), 'IP', rpd.bankname,
	coalesce(rpd.chequenumber, rpd.cardnumber)
	from refundpaydtls rpd
	where rpd.date  between  starttime and endtime and rpd.modeid != 1;
end;

------------------------------End enddate---------------------------------------------------------
	





----------------------start creditnotes--------------------

declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');

begin

create or replace temporary view
creditnotes as 
select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, 
refd.date_of_refund as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid 
from  billing.m_credit_note_master crd
inner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_id
inner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_id
inner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_id
inner join service.m_service_master srv on srv.service_master_id = bdt.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_id
inner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_id
inner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id 
where crd.cr_deu_amount = 0 and billmst.visit_type_id = 1
group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund, crd.cr_net_amount;

-------------- Insert credit notes into tally interface start-----------------------------	
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,
hospital_id, tran_type)
select voucherno, 'Payment', crd.ledger, 
crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP'
from creditnotes crd 
where crd.refunddate between  starttime and endtime
group by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;
-------------- Insert credit notes into tally interface end-----------------------------

---------------------- refund details view --------------------------------------
create or replace temporary view
creditnoterefunds as 
select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,
prm.date_of_refund as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,
prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,
bank.bank_name as bankname
from billing.t_payment_refund_master prm
inner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_id
inner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id 
inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_id
left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
where billmst.visit_type_id = 1;
-----------------------------xxx-----------------------------------

---------------------- insert cash mode transactions ------------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, 
unit_id, hospital_id, tran_type)
select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, 
sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'
from creditnoterefunds rfd
where rfd.refunfdate between  starttime and endtime and rfd.modeid = 1
group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;
-------------------------xxx------------------------------------------------

----------------------- insert other mode transactions ----------------------
insert into public.t_finaccial_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, 
credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from creditnoterefunds rfd
where rfd.refunfdate between  starttime and endtime and rfd.modeid != 1
group by  rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;

end;
insert into public.t_synctimestamp(startDate,Enddate) values(starttime,endtime);
----------------------end postcreditnotes-------------------------------------
return true;

EXCEPTION 
 when OTHERS then 
  GET STACKED DIAGNOSTICS err_context = PG_EXCEPTION_CONTEXT;
        RAISE INFO 'Error Name:%',SQLERRM;
        RAISE INFO 'Error State:%', SQLSTATE;
        RAISE INFO 'Error Context:%', err_context;
	return false;
COMMIT;
end;

$$;


--
-- TOC entry 4066 (class 1255 OID 4691124)
-- Name: fixedassetitemssaveproc(json, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.fixedassetitemssaveproc(itemarray json, INOUT failedrecres character varying)
    LANGUAGE plpgsql
    AS $$

declare
  obj json;obj1 json;obj2 json;failedRecordJson json[];failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;
  
  isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=2;
  isItemCodeExist boolean;isProductCodeExist boolean;isItemNameExist boolean;
 
  orgName varchar;unitName varchar;assetCategory varchar;productCategory varchar;formulationType varchar;
  itemCode varchar;productCode varchar;itemName varchar;genericName  varchar;strength double precision;strengthUnitName varchar;
  pharmClass varchar;manufacture varchar;purchaseTax varchar;saleTax  varchar;HSNCode varchar;storageUnit varchar;
  errorRemark varchar:=null;
 
 orgId integer:=null;unitId integer:=null;itemId integer:=null;createdBy integer:=null;updatedBy integer:=null;
 assetCatId integer:=null;prodCatId integer:=null;manufactureId integer:=null;
 purchasetaxId integer:=null;saleTaxId integer:=null;strengthUnitId integer:=null;storageUnitId integer:=null;
 
 isCSSD boolean=false;isModality boolean=false;isChargeableEquipment boolean=false;isAccessories boolean=false;isSpares boolean=false;
 isDialyser boolean=false;
begin
	
  	
  FOR obj IN SELECT * FROM json_array_elements(itemArray)
  loop
     flag:=false;failedRecordReason='';
     orgId:=obj->>'organizationId';unitId:=obj->>'unitId';createdBy:=cast(obj->>'createdBy' as integer);updatedBy:=cast(obj->>'createdBy' as integer);
     assetCategory:=obj->>'assetCategory';productCategory:=obj->>'productCategory';
     itemCode:=obj->>'itemCode';productCode:=obj->>'productCode';itemName:=obj->>'assetName';
     manufacture:=obj->>'manufacture';

    isCSSD =(case when (lower(obj->>'isCSSD')='yes') then true else false end);
    isModality =(case when (lower(obj->>'isModality')='yes') then true else false end);
    isChargeableEquipment =(case when (lower('sChargeableEquipment')='yes') then true else false end);
    isAccessories =(case when (lower(obj->>'isAccessories')='yes') then true else false end);
    isSpares =(case when (lower(obj->>'isSpares')='yes') then true else false end);
    isDialyser =(case when (lower(obj->>'isDialyser')='yes') then true else false end);
   
   
	--avaiItemId :=checkItemExistAgainstOrg(itemName,itemCode,productCode,orgId);

    ---Check for unique item
	if itemCode='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item Code can not be blank,');
    elseif itemCode!='' and length(itemCode)<=10 then
       isItemCodeExist=exists(select item.id from public.m_item item where lower(item.code)=lower(itemCode)
       and item.organization_id=orgId --and item.unit_id=unitId 
       and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isItemCodeExist then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item Code already exist,');
	    end if;
    elseif length(itemCode)>10 then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item Code can not be greater than 10 characters,');
    end if;
   
   ---Product code check
   if productCode='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product Code can not be blank,');
   elseif productCode!='' and length(productCode)<=50 then
      isProductCodeExist=exists(select item.id from public.m_item item where lower(item.product_code)=lower(productCode)
         and item.organization_id=orgId --and item.unit_id=unitId 
         and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isProductCodeExist then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product Code already exist,');
	    end if;
    elseif length(productCode)>50 then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product Code can not be greater than 50 characters,');
    end if;
   
   ----Item Name check
      ---Product code check
   if itemName='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Asset Name can not be blank,');
   elseif itemName!='' and length(itemName)<=500 then
    isItemNameExist=exists(select item.id from public.m_item item where lower(item.name)=lower(itemName)
    and item.organization_id=orgId --and item.unit_id=unitId 
    and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isItemNameExist then
