  values (orgId,unitId,((select count(mm.id) from public.m_manufacturer mm where  mm.organization_id=orgId)+1),manufacture,'',true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into manufactureId from manufacturesave;
  end if;
 
  end if;  
 
 

 ---Insert call for item master
 if flag=false then 
with itemmasterSave as (insert into public.m_item (organization_id,unit_id,manufacturer_id,code,
name,product_code,hsn_code,is_reusable,is_vaccin,is_otc,is_combination,is_batch_required,is_high_risk_product,
is_psychotropic,is_kit,is_infusion,is_narcotic,is_active,updated_by,updated_date,added_by,added_date,is_deleted,
is_consignment,is_consumable,is_hospital_formulary,product_category_id,is_cssd,is_modality,
is_chargeable_equpiment,is_sterilize,is_implant,is_ot,is_critical,is_accessories,is_spares,is_injection,is_dialyser,reusable_percentage)
values(orgId,unitId,manufactureId,itemCode,itemName,productCode,HSNCode,false,false,false,false,
false,false,false,false,false,false,true,updatedBy,now(),createdBy,now(),false,false,false,false,
prodCatId,isCSSD,isModality,isChargeableEquipment,false,false,false,false,isAccessories,isSpares,false,isDialyser,'[]')returning id)

select id into itemId from itemmasterSave;


end if;

  if flag=true then
