CREATE PROCEDURE public.fixedassetopeningbalance(itemarray json, INOUT failedrecres character varying)
    LANGUAGE plpgsql
    AS $$

declare
  obj json;obj1 json;obj2 json;taxDetailJson json;itemUomMapper json;failedRecordJson json[];storeItemMapperId integer:=null;
  
  isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;
  
  orgId integer:=null;unitId integer:=null;createdBy integer:=null;updatedBy integer:=null;
  storeName varchar;storeId integer;assetName varchar;itemId integer;vendorName varchar;serialNo varchar;expiryDate timestamp;
  quantity integer;manufactureYear integer;serviceProvider varchar;warrantyFrom date;warrantyTo date;
  pmsFrequency varchar;workingCondition varchar;specifications varchar;
  orgIdFlag integer:=null;storeIdFlag integer:=null;openingBalanceId integer;openingBalanceDetailId integer;
  opbNo varchar:= concat('OPB-',nextval('inventory.t_opening_balance_id_seq'));screenId integer:=3;
  insertflag integer:=1;vendorId integer:=null;manufactureId integer:=null;freqId integer:=null;workingCondId integer:=null;
begin
	
  FOR obj IN SELECT * FROM json_array_elements(itemArray)
  loop
  orgId:=obj->>'organizationId';unitId:=obj->>'unitId';createdBy:=cast(obj->>'createdBy' as integer);updatedBy:=cast(obj->>'createdBy' as integer);
  storeName:=obj->>'storeName';itemId:=obj->>'itemId'; assetName:=obj->>'assetName';serialNo:=obj->>'serialNo';
  manufactureYear:=cast(obj->>'manufactureYear' as integer);vendorName:=obj->>'vendor';serviceProvider:=obj->>'serviceProvider';
  warrantyFrom=cast(obj->>'warrantyFrom' as date);warrantyTo=cast(obj->>'warrantyTo' as date);
  pmsFrequency:=obj->>'pmsFrequency';workingCondition:=obj->>'workingCondition';specifications:=obj->>'specifications'; 
  quantity:=cast(obj->>'quantity' as integer); 
 
  flag=false;failedRecordReason='';
 
 ----Item name is exist and blank check
if assetName='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Asset name can not be blank,');
else
  with getItemIdByName as (select mi.id as id from public.m_item mi where lower(mi.name)=lower(assetName) and mi.organization_id =orgId)
  select id into itemId from getItemIdByName;
  if itemId is null then 
  failedRecordReason=concat(failedRecordReason,'Asset name not exist,');
  flag=true;
  end if;
 
end if;
 

-------store name is exist and blank check
 if storeName='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Store name can not be blank,');
 else
  with getStoreIdByName as (SELECT s.store_id as id FROM public.m_store s
  WHERE lower(s.store_name)=lower(storeName) and s.organization_id=orgId)
  select id into storeId from getStoreIdByName;
 
  if storeId is null then 
  failedRecordReason=concat(failedRecordReason,'Store name not exist,');
  flag=true;
  end if;
 end if;

  --check is item map to store
  if storeId is not null and itemId is not null then 
  with itemStoreMapping as(select msim.id from public.m_store_item_mapper msim 
  where msim.item_id=itemId and msim.store_id=storeId and msim.organization_id=orgId limit 1)
   select mm.id into storeItemMapperId from itemStoreMapping mm;
  if storeItemMapperId is null then
  insert into public.m_store_item_mapper(organization_id,unit_id,store_id,item_id,max_qty,min_qty,
		is_active,updated_by,updated_date,added_by,added_date,is_deleted) values(orgId,unitId,storeId,itemId,9999,1,
		true,updatedBy,now(),createdBy,now(),false);
  end if;
  end if;
  
 ----------Check vendor exist or not
 if vendorName='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Vendor name can not be blank,');
 else
  with getVendorIdByName as(select mv.id as id from public.m_vendor mv where lower(mv.name)=lower(vendorName) 
  and mv.organization_id =orgId and mv.unit_id =unitId and mv.is_active=true and mv.is_deleted=false limit 1)
  select id into vendorId from getVendorIdByName;
 
  if vendorId is null then 
  failedRecordReason=concat(failedRecordReason,'Vendor name not exist,');
  flag=true;
  end if;
 end if;
 
----------Check service Provider 
if serviceProvider='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Service provider can not be blank,');
 else
  with getManufactureIdByName as(
  select mv.id as manufId from public.m_vendor mv where mv.is_service_provider =true
  and lower(mv.name)=lower(serviceProvider) and mv.organization_id =orgId
  and mv.unit_id =unitId and mv.is_active =true and mv.is_deleted =false limit 1)
  
  select manufId into manufactureId from getManufactureIdByName;
  if manufactureId is null then 
  failedRecordReason=concat(failedRecordReason,'Service provider not exist,');
  flag=true;
  end if;
 end if;
 
---------------Check frequency exist or not
 if pmsFrequency='' then 
   flag=true;
   failedRecordReason=concat(failedRecordReason,'PMS frequency can not be blank,');
 else
  with getFrequencyIdByName as( select mf.id as id from inventory.m_pms_frequency mf where lower(mf.description)=lower(pmsFrequency)
   and mf.organization_id =orgId and mf.unit_id =unitId and mf.is_active =true 
   and mf.is_deleted =false)
   select id into freqId from getFrequencyIdByName;
	
  if freqId is null then 
  failedRecordReason=concat(failedRecordReason,'PMS frequency not exist,');
  flag=true;
  end if;
 end if;

---------------------Check working condition exist or not
 if workingCondition='' then 
  flag=true;
   failedRecordReason=concat(failedRecordReason,'Working condition can not be blank,');
 else
   with getworkingCondIdByName as(select mwc.id as id from inventory.m_working_condition mwc where lower(description)=lower(workingCondition) 
      and mwc.is_active =true and mwc.is_deleted=false)
    select id into workingCondId from getworkingCondIdByName;
   
   if workingCondId is null then 
  failedRecordReason=concat(failedRecordReason,'Working condition is not available,');
  flag=true;
  end if;
 end if;
 
  --if orgIdFlag <> orgId or storeIdFlag <> storeId then 
  if flag=false then
  if insertflag=1 then
  with openingBalanceSave as (insert into inventory.t_opening_balance (organization_id,unit_id,store_id,status_id,opb_no,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values(orgId,unitId,storeId,1,opbNo,true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into openingBalanceId from openingBalanceSave;
  orgIdFlag:=orgId;
  storeIdFlag:=storeId;
  insertflag=2;
  end if;

  with openingBalanceDetailSave as(insert into inventory.t_opening_balance_detail (organization_id,unit_id,opening_balance_id,item_id,status_id,
  quantity,is_active,updated_by,updated_date,added_by,added_date,is_deleted,serial_number,vendor_id,service_provider_id,warranty_from,
  warranty_to,pms_frequency_id,year_of_manufacture,working_condition_id,remark)
  values(orgId,unitId,openingBalanceId,itemId,1,quantity,true,updatedBy,now(),createdBy,now(),false,serialNo,vendorId,manufactureId,
  warrantyFrom,warrantyTo,freqId,manufactureYear,workingCondId,specifications) returning id)
  select id into openingBalanceDetailId from openingBalanceDetailSave;
 
 end if;

  if flag=true then
	  
	  if(failedRecordReason!='') then
	  failedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
	  end if;
	  failedRec:=obj::varchar;
	  failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedRecordReason,'"}');
	  failedRecordJson := array_append(failedRecordJson,failedRec::json);
  end if;
 
  end loop;
 
 
  failedRecRes :=failedRecordJson::varchar;
  failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
  failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
  failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
  failedRecRes= replace(failedRecRes,'\','');
 EXCEPTION 
 when OTHERS then 
