CREATE FUNCTION public.fun_crash_cart_after_insert_doc_dept() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	
	IF NEW.admission_id is not null  then
	UPDATE pharmacy.t_crash_cart_request
		SET  doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id),
		doc_spl_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id)
		WHERE id=new.id;
    END IF;
   IF NEW.encounter_id is not null  then
	UPDATE pharmacy.t_crash_cart_request
		SET  doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id),
		doc_spl_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)
		WHERE id=new.id;
    END IF;
    RETURN NEW;
END;
$$;


