                                                                        AND v.is_deleted = FALSE;
																		
				END;
				$$;


--
-- TOC entry 4002 (class 1255 OID 2969342)
-- Name: get_mortality_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mortality_rate() RETURNS real
    LANGUAGE plpgsql
    AS $$ 
	declare 
		v_ration real;
	begin
		select  
		((select count(*) as no_of_deaths  from adt.t_discharge where discharge_type_id = 3)::real /
		 (select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3)::real *100)
	 into v_ration;
	return v_ration;
	end;
$$;


--
-- TOC entry 4003 (class 1255 OID 2969343)
-- Name: get_mortality_rate(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mortality_rate(param_date date) RETURNS TABLE(no_of_deaths integer)
    LANGUAGE plpgsql
    AS $$ 
	declare 
		v_no_of_deaths integer;
		v_no_of_discharge integer;
		v_mortality_rate real;
	begin
		
		select  
		(select count(*) as no_of_deaths  from adt.t_discharge where discharge_type_id = 3)::real /
		 ((select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3) *100)
	 as ration;
	end;
$$;


--
-- TOC entry 3997 (class 1255 OID 2969344)
-- Name: get_mortality_rate(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mortality_rate(fromdate date, todate date) RETURNS real
    LANGUAGE plpgsql
    AS $$ 
	declare 
		v_ration real;
	begin
		select  
		((select count(*) as no_of_deaths  from adt.t_discharge where discharge_type_id = 3 and discharge_date between fromDate and toDate)::real /
		 (select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3 and discharge_date between fromDate and toDate)::real *100)
	 into v_ration;
	return v_ration;
	end;
$$;


--
-- TOC entry 3919 (class 1255 OID 2969345)
-- Name: get_records_without_icd(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_records_without_icd(p_date date) RETURNS TABLE(patient_id integer, first_name text, last_name text, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, data_summary_released text, diagnosis_code character varying)
    LANGUAGE plpgsql
    AS $$
	BEGIN
	RETURN QUERY
		select distinct 
		p.patient_id,
		p.first_name,
		p.last_name,
		wm.ward_name,
		bm.bed_number,
		a.created_date as "Admission Date",
		d.discharge_date as "Discharge Date",
		CASE
      		WHEN tr.discharge_summary_note is null THEN
         		'NO'
      		ELSE
        		'YES'
		end
		as "Discharge Summary Released",
		dm.code as "Diagnosis Code"
		from patient.t_patient_registration p 	
		INNER JOIN patient.t_patient_diagnosis_appo_mapper pd on p.patient_id=pd.patient_id
		INNER JOIN emr.m_diagnosis_master dm on pd.diagnosis_id=dm.diagnosis_id
		INNER JOIN adt.t_admission a on p.patient_id=a.patient_id
		INNER JOIN adt.t_admission_details ad on a.admission_id=ad.admission_id
		LEFT JOIN adt.m_ward_master wm ON ad.ward_id = wm.ward_id
		LEFT JOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_id
		INNER JOIN adt.t_discharge d on a.admission_id=d.admission_id
		INNER JOIN adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id   -- 1.Comment this line to see records as there are no common admission ids.
		where (a.created_date ::Date >= p_date or a.updated_date:: Date>=p_date ) 
		and dm.code is null  -- 2. Also, comment this line or set as not null, because there are no records with code null.
                and p.status='A';
		END;
$$;


--
-- TOC entry 4059 (class 1255 OID 4663847)
-- Name: getnurrationname(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.getnurrationname(_billid integer) RETURNS TABLE(narration text)
    LANGUAGE sql
    AS $$

select
	concat(pat.first_name, ' ', pat.last_name, ' | ', billMst.bill_number, ' | ', (select array_to_string(array(select reciept_number from billing.t_payment_reciept_master tprm where tprm.billing_master_id = billMst.billing_master_id), ', '))) as Narration
from
	billing.m_billing_master billMst
inner join patient.t_patient_registration pat on
	pat.patient_id = billMst.patient_id
where
	billMst.billing_master_id = _billid;

$$;


--
-- TOC entry 4062 (class 1255 OID 4665507)
-- Name: getpayeeid(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.getpayeeid(billid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare payeeidnew text;
begin
	    SELECT coalesce(cm.company_id,0) into payeeidnew
           FROM billing.t_bill_payee_details bpd
             JOIN t_company_master cm ON bpd.payee_id = cm.company_id
          WHERE bpd.bill_id = billid AND (bpd.payee_id <> ALL (ARRAY[119, 1]))
         LIMIT 1 ;      

return payeeidnew;
end;
$$;


