CREATE FUNCTION public.getpayeename(billid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare payeename text;
begin
	SELECT cm.company_desc into payeename
           FROM billing.t_bill_payee_details bpd
             JOIN t_company_master cm ON bpd.payee_id = cm.company_id
          WHERE bpd.bill_id = billid AND (bpd.payee_id <> ALL (ARRAY[119, 1]))  LIMIT 1 ;        

return payeename;
end;
$$;


