--
-- TOC entry 4068 (class 1255 OID 4691128)
-- Name: itemopeningbalanceproc(json, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.itemopeningbalanceproc(itemarray json, INOUT failedrecres character varying)
    LANGUAGE plpgsql
    AS $$

declare
  obj json;obj1 json;obj2 json;taxDetailJson json;itemUomMapper json;failedRecordJson json[];storeItemMapperId integer:=null;
  
  isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;
  
  orgId integer:=null;unitId integer:=null;createdBy integer:=null;updatedBy integer:=null;
  storeName varchar;storeId integer;itemId integer;itemUOM varchar;batchNo varchar;expiryDate timestamp:=null;
  quantity integer;copPrice double precision;mrpPrice double precision;mrpUom varchar;taxPer double precision;markupPer double precision;
  taxId  integer;taxAmount double precision;
  orgIdFlag integer:=null;storeIdFlag integer:=null;openingBalanceId integer;openingBalanceDetailId integer;itemUomTypeId integer;
  itemUomUnitId integer;mrpUomTypeId integer;
  opbNo varchar:= concat('OPB-',nextval('inventory.t_opening_balance_id_seq'));totalAmount double precision;screenId integer:=3;
  lcopAmount double precision;insertflag integer:=1;itemUomType varchar;itemName varchar;
begin
	
  FOR obj IN SELECT * FROM json_array_elements(itemArray)
  loop
  orgId:=cast(obj->>'organizationId' as integer);unitId:=cast(obj->>'unitId'as integer);createdBy:=cast(obj->>'createdBy' as integer);updatedBy:=cast(obj->>'createdBy' as integer);
  storeName:=obj->>'storeName';itemId:=obj->>'itemId'; batchNo:=obj->>'batchNo';
  --quantity:=cast(obj->>'quantity' as integer); --copPrice:=cast(obj->>'COP' as double precision);mrpPrice:=cast(obj->>'MRP' as double precision);
  mrpUom:=obj->>'mrpUom';--taxPer:=cast(obj->>'taxPer' as double precision);markupPer:=cast(obj->>'markupPer' as double precision);
  itemName:=obj->>'itemName';
 --taxAmount:=cast(obj->>'taxAmount' as double precision);
  itemUomType:=obj->>'itemUomType';itemUOM:=obj->>'uomUnit';
 
 
 
  flag=false;
  failedRecordReason:='';
 
 if batchNo='' then
 batchNo='NA';
 end if;

 if (obj->>'expiryDate')='' then
 expiryDate=null;
 else
 expiryDate:=TO_TIMESTAMP(obj->>'expiryDate', 'YYYY-MM-DD');
 end if;

-- if (batchNo='' or lower(batchNo)=lower('NA')) then 
-- expiryDate:=null;
-- else
-- expiryDate:=TO_TIMESTAMP(obj->>'expiryDate', 'YYYY-MM-DD');
-- end if;
 
 
 ----Item name is exist and blank check
if itemName='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Item name can not be blank,');
else
  with getItemIdByName as (select mi.id as id from public.m_item mi where lower(mi.name)=lower(itemName) and mi.organization_id =orgId)
  select id into itemId from getItemIdByName;
  if itemId is null then 
  failedRecordReason=concat(failedRecordReason,'Item name not exist,');
  flag=true;
  else
  with getTaxIdFromItem as (SELECT mt.id as id,mt.tax_percentage as per FROM public.m_item item 
                    inner join public.m_tax mt on mt.id=item.s_tax_id 
                    WHERE item.id=itemId and mt.organization_id=orgId and item.is_active=true and item.is_deleted=false limit 1)
   select id,per into taxId,taxPer from getTaxIdFromItem;
   --select taxper into taxPer from getTaxIdFromItem;
                    
  end if;
 
end if;
 

-------store name is exist and blank check
 if storeName='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Store name can not be blank,');
 else
  with getStoreIdByName as (SELECT s.store_id as id FROM public.m_store s
  WHERE lower(s.store_name)=lower(storeName) and s.organization_id=orgId)
  select id into storeId from getStoreIdByName;
 
  if storeId is null then 
  failedRecordReason=concat(failedRecordReason,'Store name not exist,');
  flag=true;
  end if;
 end if;
  
  --check is item map to store
  if storeId is not null and itemId is not null then 
  with itemStoreMapping as(select msim.id from public.m_store_item_mapper msim 
  where msim.item_id=itemId and msim.store_id=storeId and msim.organization_id=orgId limit 1)
   select mm.id into storeItemMapperId from itemStoreMapping mm;
  if storeItemMapperId is null then
  insert into public.m_store_item_mapper(organization_id,unit_id,store_id,item_id,max_qty,min_qty,
		is_active,updated_by,updated_date,added_by,added_date,is_deleted) values(orgId,unitId,storeId,itemId,9999,1,
		true,updatedBy,now(),createdBy,now(),false);
  end if;
  end if;
  
 if batchNo='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Batch Number can not be blank,');
 end if;

------------------Check quantity
 if (obj->>'quantity')='' then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'Quantity can not be blank,');
 else
   quantity:=NULLIF(regexp_replace(obj->>'quantity', '\D','','g'), '')::integer;
    
   if quantity is null then
    flag=true;
    failedRecordReason=concat(failedRecordReason,'Incorrect Quantity,');
   else
   quantity=cast(replace(obj->>'quantity',',','') as integer);
   end if;
  
 end if;

-------------------Check COP Price
 if (obj->>'cop')='' then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'COP can not be blank,');
 else
   copPrice:=NULLIF(regexp_replace(obj->>'cop', '\D','','g'), '')::integer;
    
   if copPrice is null then
    flag=true;
    failedRecordReason=concat(failedRecordReason,'Incorrect COP,');
   else
   copPrice=cast(replace(obj->>'cop',',','') as double precision);
   end if;
  
 end if;

-------------------Check MRP Price
 if (obj->>'mrp')='' then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'MRP can not be blank,');
 else
   mrpPrice:=NULLIF(regexp_replace(obj->>'mrp', '\D','','g'), '')::integer;
    
   if mrpPrice is null then
    flag=true;
    failedRecordReason=concat(failedRecordReason,'Incorrect MRP,');
   else
   mrpPrice=cast(replace(obj->>'mrp',',','') as double precision);
   end if;
  
 end if;

-------------------Check Markup Percentage
 if (obj->>'markupPer')='' then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'Markup % can not be blank,');
 else
   markupPer:=NULLIF(regexp_replace(obj->>'markupPer', '\D','','g'), '')::integer;
    
   if markupPer is null then
    flag=true;
    failedRecordReason=concat(failedRecordReason,'Incorrect Markup %,');
   else
   markupPer=cast(obj->>'markupPer' as double precision);
   end if;
  
 end if;

 ------Tax percentage check
--  if (obj->>'taxPercentage')='' then
--     flag=true;
--    failedRecordReason=concat(failedRecordReason,'Tax % can not be blank,');
--   else
--    --purchaseTaxPer:=cast(obj->>'purchaseTaxPer' as float8) ;
--    taxPer:=NULLIF(regexp_replace(obj->>'taxPercentage', '\D','','g'), '')::float8;
--    
--   if taxPer is null then
--    flag=true;
--    failedRecordReason=concat(failedRecordReason,'Inccorrect Tax %,');
--   else
--    taxPer=cast(obj->>'taxPercentage' as double precision);
--    with getTaxIdByPer as (SELECT mt.id as id FROM public.m_tax mt 
--    WHERE mt.tax_percentage=taxPer and mt.organization_id=orgId and mt.is_active=true and mt.is_deleted=false limit 1)
--    select id into taxId from getTaxIdByPer;
-- 
--    if taxId is null then
--    flag=true;
--    failedRecordReason=concat(failedRecordReason,'Tax % not exist,',taxPer,orgId);
--    end if;
--   
--   end if;
--   
--   end if;
--   
 -------------MRP Price and COP Price check  
 if  mrpPrice is not null and copPrice is not null then 
 if (mrpPrice < copPrice) then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'MRP price should be equal or greater than COP price,');
 end if;
end if;
 
--------calculation of total amount and tax amount
if quantity is not null and mrpPrice is not null and copPrice is not null and taxId is not null then 
totalAmount:=quantity*copPrice;
taxAmount:=(totalAmount*taxPer)/100;
lcopAmount:=(totalAmount+taxAmount)/quantity;
end if;  

 -------------Check UOM Unit
 if itemUOM='' then
    flag=true;
    failedRecordReason=concat(failedRecordReason,'UOM Unit can not be blank,');
 else  
  with getUOMUnitId as (SELECT  uu.id as id,muom.uom_type_id as typeid FROM public.m_uom_unit uu
  inner join public.m_unit_of_measurement muom on muom.uom_unit_id=uu.id
  WHERE lower(uu.unit)=lower(itemUOM) and uu.is_active =true and uu.is_deleted =false and muom.item_id=itemId order by muom.id desc limit 1)
  select id,typeid into itemUomUnitId,itemUomTypeId from getUOMUnitId;
  --select typeid into itemUomTypeId from getUOMUnitId;
 
  if itemUomUnitId is null then 
  flag=true;
  failedRecordReason=concat(failedRecordReason,'UOM Unit not exist,');
  end if;
 end if;
  ---------------get mrp uom type id by unit---------------
 if mrpUom='' then
  flag=true;
    failedRecordReason=concat(failedRecordReason,'MRP UOM Unit can not be blank,');
 else  
   with getMrpUnitByType as (SELECT  uu.id as id,muom.uom_type_id as typeid FROM public.m_uom_unit uu
  inner join public.m_unit_of_measurement muom on muom.uom_unit_id=uu.id
  WHERE lower(uu.unit)=lower(mrpUom) and uu.is_active =true and uu.is_deleted =false and muom.item_id=itemId order by muom.id desc limit 1)
  select typeid into mrpUomTypeId from getMrpUnitByType;
 if mrpUomTypeId is null then
  flag=true;
  failedRecordReason=concat(failedRecordReason,'MRP UOM Unit not exist,');
 end if;
 end if;

  --if orgIdFlag <> orgId or storeIdFlag <> storeId then 
  if flag=false then
  if insertflag=1 then
  with openingBalanceSave as (insert into inventory.t_opening_balance (organization_id,unit_id,store_id,status_id,opb_no,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values(orgId,unitId,storeId,1,opbNo,true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into openingBalanceId from openingBalanceSave;
  orgIdFlag:=orgId;
  storeIdFlag:=storeId;
  insertflag=2;
  end if;
 
  with openingBalanceDetailSave as(insert into inventory.t_opening_balance_detail (organization_id,unit_id,opening_balance_id,item_id,uom_type_id,uom_unit_id,batch_no,expiry_date,
  quantity,cop,mrp,amount_cop,markup,tax_id,tax_percentage,tax_amount,status_id,is_active,updated_by,updated_date,added_by,added_date,is_deleted,mrp_uom_type_id,lcop)
  values(orgId,unitId,openingBalanceId,itemId,itemUomTypeId,itemUomUnitId,batchNo,expiryDate,quantity,copPrice,mrpPrice,totalAmount,markupPer,
  taxId,taxPer,taxAmount,1,true,updatedBy,now(),createdBy,now(),false,mrpUomTypeId,lcopAmount) returning id)
  select id into openingBalanceDetailId from openingBalanceDetailSave;
 
	with  getTaxDetail as(
	SELECT array_to_json(array_agg(row_to_json(data))) 
	from(select
		mtd.tax_component_id as id,mtd.tax_percentage as taxper
	from   public.m_tax_detail mtd 
	where
	mtd.tax_id =taxId
	and mtd.is_active=true
	and mtd.organization_id =orgId
	) data)
	select * into taxDetailJson from getTaxDetail;

  --save tax component wise
  FOR obj1 IN SELECT * FROM json_array_elements(taxDetailJson)
  loop
  insert into inventory.t_opb_tax_component(opb_detail_id,tax_component_id,percentage,amount,is_active,updated_by,updated_date,added_by,added_date,
  is_deleted,organization_id,unit_id)
  values(openingBalanceDetailId,cast(obj1->>'id' as integer),cast(obj1->>'taxper' as double precision),((totalAmount*(cast(obj1->>'taxper' as double precision)))/100),
  true,updatedBy,now(),createdBy,now(),false,orgId,unitId);
  end loop;
 
  --get all item uom mapper
  with  getItemUomMapper as(
	SELECT array_to_json(array_agg(row_to_json(data))) 
	from(select
		uom.uom_type_id as typeid,uom.uom_unit_id as uomunitid,uom.conversions as conv,
		uom.ip_uom as ipuom,uom.op_uom as opuom,uom.store_uom as storeuom
	from   public.m_unit_of_measurement uom 
	where
	uom.item_id=itemId
	and uom.is_active=true
	and uom.organization_id =orgId
	) data)
  select * into itemUomMapper from getItemUomMapper;

  FOR obj2 IN SELECT * FROM json_array_elements(itemUomMapper)
  loop
  ---insert into opb uom mapper
  insert into inventory.t_opb_uom_mapper (organization_id,unit_id,opb_detail_id,uom_type_id,uom_unit_id,conversions,ip_uom,op_uom,store_uom,
  is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values(orgId,unitId,openingBalanceDetailId,cast(obj2->>'typeid' as integer),cast(obj2->>'uomunitid' as integer),cast(obj2->>'conv' as integer),
  cast(obj2->>'ipuom' as boolean),cast(obj2->>'opuom' as boolean),cast(obj2->>'storeuom' as boolean),true,updatedBy,now(),createdBy,now(),false);
  end loop;
  end if;
 
  if flag=true then
      if(failedRecordReason!='') then
	  failedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
	  end if;
	  failedRec:=obj::varchar;
	  failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedRecordReason,'"}');
	  failedRecordJson := array_append(failedRecordJson,failedRec::json);
  end if;
 
  end loop;
 
 --select substring('{{"a"},{"b"}}',2,length('{{"a"},{"b"}}')-2)
  failedRecRes :=failedRecordJson::varchar;
  failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
  failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
  failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
  failedRecRes= replace(failedRecRes,'\','');
--	 EXCEPTION 
--	 when OTHERS then 
--		failedRecRes='failed to insert records';
--	 COMMIT;
  END;
  $$;


--
-- TOC entry 4069 (class 1255 OID 4691130)
-- Name: nonpharmacyitemssaveproc(json, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.nonpharmacyitemssaveproc(itemarray json, INOUT failedrecres character varying)
    LANGUAGE plpgsql
    AS $$

declare
  obj json;obj1 json;obj2 json;failedrecordjson json[];failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;
  
  isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;
  isItemCodeExist boolean;isProductCodeExist boolean;isItemNameExist boolean;
 
  orgName varchar;unitName varchar;assetCategory varchar;productCategory varchar;formulationType varchar;
  itemCode varchar;productCode varchar;itemName varchar;genericName  varchar;strength double precision;strengthUnitName varchar;
  pharmClass varchar;manufacture varchar;purchaseTax varchar;saleTax  varchar;HSNCode varchar;storageUnit varchar;
  errorRemark varchar:=null;
 --All flags
 itemReusable boolean=false;isVaccine boolean=false;isCombination boolean=false;batchReq boolean=false;highRisk boolean=false;
 psychotropic boolean=false;isKit boolean=false;isInfusion boolean=false;isNarcotic boolean=false;hospitalFormulary boolean=false;
 isConsumable boolean=false;isInjection boolean=false;
 
 purchaseUOMUnit varchar;purchaseUOMQty integer:=null;stockUOMUnit varchar;stockUOMQty  integer:=null;dispenseUOMUnit varchar;dispenseUOMQty integer:=null;
 ipUOM varchar;opUOM varchar;storeUOM varchar;

 orgId integer:=null;unitId integer:=null;itemId integer:=null;createdBy integer:=null;updatedBy integer:=null;
 assetCatId integer:=null;prodCatId integer:=null;genericId integer:=null;pharmacologyClassId integer:=null;manufactureId integer:=null;
 formulationTypeId integer:=null;purchasetaxId integer:=null;saleTaxId integer:=null;strengthUnitId integer:=null;storageUnitId integer:=null;
 
 purchaseUomUnitId integer:=null;stockUomUnitId integer:=null;dispenseUomUnitId integer:=null;ipUomTypeId integer:=null;opUomTypeId integer:=null;
 storeUomTypeId integer:=null;purchaseTaxPer float8;saleTaxPer float8;

begin
	
  	
  FOR obj IN SELECT * FROM json_array_elements(itemArray)
  loop
     flag:=false;failedRecordReason='';
   -- RAISE NOTICE 'output from space %', obj->>'type';
     orgId:=obj->>'organizationId';unitId:=obj->>'unitId';createdBy:=cast(obj->>'createdBy' as integer);updatedBy:=cast(obj->>'createdBy' as integer);
     assetCategory:=obj->>'assetCategory';productCategory:=obj->>'productCategory';formulationType:=obj->>'formulationType';
     itemCode:=obj->>'itemCode';productCode:=obj->>'productCode';itemName:=obj->>'itemName';genericName:=obj->>'genericName';
     strength:=cast(obj->>'strength' as double precision);strengthUnitName:=obj->>'strengthUnitName';pharmClass:=obj->>'pharmacologyClassification';manufacture:=obj->>'manufacture';
    --purchaseTaxPer:=cast(obj->>'purchaseTaxPer' as float8) ;saleTaxPer:=cast(obj->>'saleTaxPer' as float8);
    HSNCode:=obj->>'HSNCode';storageUnit:=obj->>'storageUnit';
     
     purchaseUOMUnit:=obj->>'purchaseUOMUnit';purchaseUOMQty:=obj->>'purchaseToStockConvQty';stockUOMUnit:=obj->>'stockUOMUnit';stockUOMQty:=obj->>'stockToDispenseConvQty';
     dispenseUOMUnit:=obj->>'dispenseUOMUnit';dispenseUOMQty:=obj->>'dispenseUOMQty';ipUOM:=obj->>'ipUOM';opUOM:=obj->>'opUOM';storeUOM:=obj->>'storeUOM';
     --itemName:=concat(obj->>'itemName','',counter);
	
    batchReq =(case when (lower(obj->>'batchRequired')='yes') then true else false end);
    isConsumable =(case when (lower(obj->>'isConsumable')='yes') then true else false end);
   
	--avaiItemId :=checkItemExistAgainstOrg(itemName,itemCode,productCode,orgId);
    ---Check for unique item
	if itemCode='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item Code can not be blank,');
    elseif itemCode!='' and length(itemCode)<=10 then
       isItemCodeExist=exists(select item.id from public.m_item item where lower(item.code)=lower(itemCode)
       and item.organization_id=orgId --and item.unit_id=unitId 
       and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isItemCodeExist then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item code already exist,');
	    end if;
    elseif length(itemCode)>10 then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item code can not be greater than 10 characters,');
    end if;
   
   ---Product code check
   if productCode='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product code can not be blank,');
   elseif productCode!='' and length(productCode)<=50 then
      isProductCodeExist=exists(select item.id from public.m_item item where lower(item.product_code)=lower(productCode)
         and item.organization_id=orgId --and item.unit_id=unitId 
         and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isProductCodeExist then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product code already exist,');
	    end if;
    elseif length(productCode)>50 then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Product code can not be greater than 50 characters,');
    end if;
   
   ----Item Name check
      ---Product code check
   if itemName='' then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item name can not be blank,');
   elseif itemName!='' and length(itemName)<=500 then
    isItemNameExist=exists(select item.id from public.m_item item where lower(item.name)=lower(itemName)
    and item.organization_id=orgId --and item.unit_id=unitId 
    and item.is_active=true and item.is_deleted=false limit 1);
   
	    if isItemNameExist then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item name already exist,');
	    end if;
    elseif length(itemName)>500 then
	    flag=true;
	    failedRecordReason=concat(failedRecordReason,'Item name can not be greater than 500 characters,');
    end if;
  --asset category
   --asset category
  if assetCategory='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Asset category can not be blank,');
  else
  with getAssetCatId as (select mac.id as id from public.m_asset_category mac where lower(mac.category)=lower(assetCategory) 
  and mac.organization_id =orgId  and mac.is_active=true and mac.is_deleted=false and mac.asset_type_id=assetTypeId limit 1)
  
  select id into assetCatId from getAssetCatId;
 
  if assetCatId is null then
  with assetCategorySave as (insert into public.m_asset_category (organization_id,unit_id,asset_type_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values (orgId,unitId,assetTypeId,((select count(mac.id) from public.m_asset_category mac where  mac.organization_id =orgId )+1),
  assetCategory,true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into assetCatId from assetCategorySave; 
  end if;
  end if;
  
	
  --product category
   if productCategory='' then
   flag=true;
   failedRecordReason=concat(failedRecordReason,'Product category can not be blank,');
  else
   with getProdCatId as (select pc.id as id from public.m_product_category pc where lower(pc.category)=lower(productCategory) 
  and pc.asset_category_id =assetCatId  and pc.organization_id=orgId and pc.is_active =true and pc.is_deleted=false limit 1)
  select id into prodCatId from getProdCatId;
  
  if prodCatId is null then
  with productCategorySave as (insert into public.m_product_category (organization_id,unit_id,asset_category_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values(orgId,unitId,assetCatId,((select count(pc.id) from public.m_product_category pc where  pc.organization_id=orgId)+1),productCategory,true,updatedBy,now(),createdBy,now(),false) returning id )
  select id into prodCatId from productCategorySave; 
  end if;
  end if;
 
 	
  --Formulation Type
  with getFormulationTypeId as (select mft.id as id from public.m_formulation_type mft where lower(mft.type)=lower('NA') and mft.organization_id =orgId 
  and mft.is_active =true and mft.is_deleted =false)
  select id into formulationTypeId from getFormulationTypeId;
  
  if formulationTypeId is null then
  with formulationTypeSave as (insert into public.m_formulation_type (organization_id,unit_id,code,type,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
  values(orgId,unitId,((select count(mft.id) from public.m_formulation_type mft where  mft.organization_id =orgId)+1),'NA',true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into formulationTypeId from formulationTypeSave;
  end if;
 
 
   --Generic Name
  with getGenericId as (select mg.id as id from public.m_generic mg where lower(mg.name)=lower('NA') and mg.product_category_id=prodCatId   
  and mg.organization_id=orgId and mg.is_active =true and mg.is_deleted =false)
  select id into genericId from getGenericId;
  
  if genericId is null then
  with genericSave	as (insert into public.m_generic (organization_id,unit_id,product_category_id,code,name,is_active,updated_by,updated_date,added_by,added_date,is_deleted)
      values(orgId,unitId,prodCatId,((select count(mg.id) from public.m_generic mg where  mg.organization_id=orgId)+1),'NA',true,updatedBy,now(),createdBy,now(),false) returning id)
  select id into genericId from genericSave;
  end if;
 
 
  --Strength unit name
  with getStrengthUnitId as (select msu.id as id from public.m_strength_unit msu where lower(msu.unit)=lower(strengthUnitName) and msu.is_active =true and msu.is_deleted =false)
  select id into strengthUnitId from getStrengthUnitId;
 
 
   --pharmacological classification
