--
-- TOC entry 4064 (class 1255 OID 2969346)
-- Name: orderedamountforadmittedpatient(double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orderedamountforadmittedpatient(admid double precision) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE passed double precision;
BEGIN      
		select sum(chargesdetail.net_amount) as OrderedAmount into passed from public.t_order_master Charges 
		inner join public.t_order_details ChargesDetail on charges.order_id = ChargesDetail.order_id
		where  charges.visit_type_id=2 and ChargesDetail.is_drug='N'  and charges.Admission_id=Admid;

        RETURN passed;
END;
$$;


