--
-- TOC entry 4015 (class 1255 OID 2969348)
-- Name: percentage_of_medical_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.percentage_of_medical_records(OUT percentage numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
declare
v_percentage numeric:=0;
begin

	              with not_discharge as  (  select count(1) as ntdis_count 	from adt.t_admission ad
	                                  										 where ad.admission_id not in (select dis.admission_id 
	                                                                 											 from adt.t_discharge dis )
	                                  										 and ad.status='A'                               
	                                                                  )                                                
	               select   
	                        (a.ntdis_count/(select count(1) as disc_count 	from adt.t_admission ad
	                                  										where ad.admission_id  in (select dis.admission_id 
	                                                                  										from adt.t_discharge dis )
	                                   										and ad.status='A' 
	                                   )) *100  into v_percentage
	                from not_discharge a;
	                
	               raise notice 'v_percentage%',v_percentage;
	                percentage:=v_percentage;

end;
$$;


