--
-- TOC entry 3956 (class 1255 OID 4343404)
-- Name: pharmacyservice_id(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pharmacyservice_id(bid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare id integer;
begin	
	select distinct coalesce(bill.service_id,0) into id  from billing.t_billing_details bill   
	WHERE EXISTS (    
    select pharmacy_service_id from t_unit_application_billing_configuration where unit_id=38     
    and  pharmacy_service_id= bill.service_id     
	)  and bill.billing_master_id = bid limit 1	;
return id;
end;
$$;


--
-- TOC entry 4071 (class 1255 OID 4731285)
-- Name: pharmacyservice_idnew(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pharmacyservice_idnew(bid integer, unitid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare id integer;
begin	
	select distinct coalesce(bill.service_id,0) into id  from billing.t_billing_details bill   
	WHERE EXISTS (    
    select pharmacy_service_id from t_unit_application_billing_configuration where unit_id= unitid   
    and  pharmacy_service_id= bill.service_id     
	)  and bill.billing_master_id = bid limit 1	;
return id;
end;
$$;


--
-- TOC entry 3930 (class 1255 OID 2969349)
-- Name: post_advance_refund(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_advance_refund(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucherno_ip integer = nextval('public.tally_voucher_no_seq');
begin 
	
	create or replace temporary view refundvouchers 
	as 
	select 
 	prm.amount_refunded as amount_refunded, 
 	prm.is_cn_or_deposit as is_cn_or_deposit, 
	refcn.balance_amount as balance_amount,
	dep.visit_type_id as visit_type_id,
	dep.deposit_type_id as deposit_type_id,
	refcn.created_date as created_date,
	refcn.organization_id as orgnisation_id,
	refcn.unit_id as unit_id
	from billing.t_refund_cn refcn
	inner join billing.m_deposit_master dep on dep.deposit_master_id=refcn.deposit_id
	inner join billing.t_payment_refund_master prm  on refcn.t_refund_cn_id=prm.t_refund_cn_id ;
	--where to_char(prm.created_date,'yyyy-mm-dd')::date=dateoftrans;
	
	--- create view for payment details
	create or replace temporary view refundpaydtls
	 as 
	select
		prd.payment_refund_details_id as id,
		prd.payment_mode_id as modeid,
		pmod.ledger_name as mode,
		prd.amount as amount,
		prd.card_number as cardnumber,
		prd.cheque_number as chequenumber,
		prd.date::date as chequedate,
		prd.orgnisation_id as orgid,
		prd.unit_id as unitid,
		prd.created_date::date as date,
		bank.bank_name as bankname,
		dep.visit_type_id as visit_type_id,
		dep.deposit_type_id as deposit_type_id 
	from billing.t_refund_cn refcn
	inner join billing.m_deposit_master dep on 
		dep.deposit_master_id=refcn.deposit_id
	inner join billing.t_payment_refund_master prm  on 
		refcn.t_refund_cn_id=prm.t_refund_cn_id
	inner join	billing.t_payment_refund_details prd on 
		prd.payment_refund_id=prm.payment_refund_id
	inner join public.m_payment_mode_master pmod on
		pmod.payment_mode_id = prd.payment_mode_id
	left join billing.m_bank_master bank on
		bank.bank_id = prd.bank_id
	where
		prm.is_cn_or_deposit = 0;
		--and  to_char(prm.created_date,'yyyy-mm-dd')::date=dateoftrans;
	--xxx
	
	-- insert cash mode advance refund amount
	insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
	select voucherno, 'Payment', 'Patient Advance', prm.created_date::date, sum(prm.amount_refunded), 0 , 
	 prm.unit_id, prm.orgnisation_id, 'OP'
	from refundvouchers prm 
	where prm.is_cn_or_deposit = 0 and prm.created_date::date = dateoftrans and ( prm.deposit_type_id = 1 or prm.visit_type_id = 1)
	group by prm.orgnisation_id, prm.unit_id,prm.created_date::date,prm.amount_refunded;
	--- xxx
	
	
	--- insert cash mode transactions
	insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
	select voucherno, 'Payment', rpd.mode,  rpd.date,   0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'OP'
	from refundpaydtls rpd
	where rpd.date = dateoftrans and ( rpd.deposit_type_id = 1 or rpd.visit_type_id = 1)
	group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;
	---xxx
	
	-- 2. IP data

	insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
	select voucherno_ip, 'Payment', 'Patient Advance', prm.created_date::date, sum(prm.amount_refunded), 0 , 
	 prm.unit_id, prm.orgnisation_id, 'IP'
	from refundvouchers prm 
	where prm.is_cn_or_deposit = 0 and prm.created_date::date = dateoftrans and prm.deposit_type_id =2 and prm.visit_type_id = 2
	group by prm.orgnisation_id, prm.unit_id,prm.created_date::date,prm.amount_refunded;


	
	insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
	select voucherno_ip, 'Payment', rpd.mode,  rpd.date,   0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'IP'
	from refundpaydtls rpd
	where rpd.date = dateoftrans and rpd.deposit_type_id =2 and rpd.visit_type_id = 2
	group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;

	-- IP data end


	
 
return true;
EXCEPTION 
 when OTHERS then 
 
	return false;
COMMIT;
end;
$$;


