--
-- TOC entry 3921 (class 1255 OID 2969352)
-- Name: post_credit_notes(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_credit_notes(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucher_ip integer = nextval('public.tally_voucher_no_seq');

begin
-----<---- 1.OP -------------
create or replace temporary view
creditnotes as 
select
	genl.general_ledger_id ledgerid,
	genl.general_ledger_name as ledger,
	crdt.cr_net_amount as amount,
	crd.credit_note_date::date as refunddate,
	crd.organisation_id as orgid,
	crd.unit_id as unitid
from
	billing.m_credit_note_master crd
inner join billing.t_credit_note_detail crdt on
	crdt.credit_note_id = crd.credit_note_id
inner join billing.m_billing_master bill on bill.billing_master_id=crd.bill_id
inner join t_order_details od on od.order_details_id=crdt.order_dtl_id_old
inner join service.m_service_master srv on
	srv.service_master_id = od.service_id
inner join doctor.m_speciality_master spc on
	spc.speciality_id = srv.speciality_id
inner join public.m_general_ledger_master genl on
	genl.general_ledger_id = spc.general_ledger_id
where bill.visit_type_id = 1;

-------------- Insert credit notes into tally interface start-----------------------------	
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Credit Note', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP'
from creditnotes crd 
where crd.refunddate::date = dateoftrans 
group by crd.orgid, crd.unitid,crd.refunddate, crd.ledger;
-------------- Insert credit notes into tally interface end-----------------------------

--------------Insert patient credit--------------
create or replace temporary view
creditnotedueamt as 
select
	sum(crd.cr_deu_amount) as amount,
	crd.credit_note_date::date as credit_note_date,
	crd.organisation_id as orgid,
	crd.unit_id as unitid
from
	billing.m_credit_note_master crd
inner join billing.m_billing_master billmst on
	billmst.billing_master_id = crd.bill_id
where billmst.visit_type_id = 1
group by
	crd.organisation_id,
	crd.unit_id,
	crd.cr_deu_amount,
	crd.credit_note_date;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Credit Note', 'Patient Credit', crd.credit_note_date, 0, sum(amount), crd.unitid, crd.orgid, 'OP'
from creditnotedueamt crd 
where crd.credit_note_date::date = dateoftrans
group by crd.orgid, crd.unitid,crd.credit_note_date,crd.amount
having crd.amount > 0;
--------------Insert patient credit--------------

--------------Discount round off start----------------
with roundoff as (select
	sum(bm.discount_roundoff) as round_off_amount,
	bm.unit_id as unitId,
	bm.organisation_id as orgId,
	bm.created_date::date as transactionDate
from
	billing.m_credit_note_master bm
	inner join billing.m_billing_master bill on bill.billing_master_id=bm.bill_id
where
	bm.created_date::date = dateoftrans
	and bill.visit_type_id = 1
group by
	bm.organisation_id,
	bm.unit_id,
	bm.created_date::date
having
	sum(bm.discount_roundoff) is not null) 
	
		insert
			into
				public.t_tally_interface (voucher_no,
				voucher_type,
				ledger,
				voucher_date,
				debit_amount,
				credit_amount,
				unit_id,
				hospital_id,
				tran_type) select
					voucherno,
					'Credit Note',
					'Discount round-off',
					roundoff.transactionDate,
					case 
					when roundoff.round_off_amount<0 then 
					0
						else 
					cast(roundoff.round_off_amount as numeric(10, 2))  end,
					case 
					when roundoff.round_off_amount>0 then 
					0
						else cast(-roundoff.round_off_amount as numeric(10, 2)) 
					 end ,
					roundoff.unitId,
					roundoff.orgId,
					'OP'
				from
					roundoff
				where roundoff.round_off_amount >0 or roundoff.round_off_amount <0 ;
--------------Discount round off start----------------

---------------------- refund details view --------------------------------------
create or replace temporary view
creditnoterefunds as 
select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,
prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,
prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,cnm.credit_note_date as ceditnotedate,
bank.bank_name as bankname
from billing.t_payment_refund_master prm
inner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_id
inner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id 
inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_id
left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
where billmst.visit_type_id = 1 and prm.is_cn_or_deposit = 1;
-----------------------------xxx-----------------------------------

---------------------- insert cash mode transactions ------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'
from creditnoterefunds rfd
where rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid = 1
group by  rfd.orgid, rfd.unitid,rfd.refunfdate, rfd.mode;
-------------------------xxx------------------------------------------------

----------------------- insert other mode transactions ----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from creditnoterefunds rfd
where rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid != 1
group by  rfd.orgid,rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;
-------------------------xxx---------------------------------

----------------------Previous date settlement start cash-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid = 1 and rfd.refunfdate::date=dateoftrans
group by rfd.orgid,rfd.unitid,rfd.refunfdate, rfd.mode;
----------------------------
----------------------Previous date settlement start others-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid != 1 and rfd.refunfdate::date=dateoftrans
group by rfd.orgid, rfd.unitid,  rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;
--------------------------------
------------------------------Credit insert start--------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Credit Note', 'Patient Credit', rfd.refunfdate,sum(rfd.amount),0, rfd.unitid, rfd.orgid, 'OP'
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.refunfdate::date=dateoftrans
group by rfd.orgid, rfd.unitid,rfd.refunfdate
having sum(rfd.amount) > 0;
------------------------------Credit insert stop--------------------------
--------- 1.OP ---->---------

------<--- 2.IP -------------
create or replace temporary view
creditnotes as 
select
	genl.general_ledger_id ledgerid,
	genl.general_ledger_name as ledger,
	crdt.cr_net_amount as amount,
	crd.credit_note_date::date as refunddate,
	crd.organisation_id as orgid,
	crd.unit_id as unitid
from
	billing.m_credit_note_master crd
inner join billing.t_credit_note_detail crdt on
	crdt.credit_note_id = crd.credit_note_id
inner join billing.m_billing_master bill on bill.billing_master_id=crd.bill_id
inner join t_order_details od on od.order_details_id=crdt.order_dtl_id_old
inner join service.m_service_master srv on
	srv.service_master_id = od.service_id
inner join doctor.m_speciality_master spc on
	spc.speciality_id = srv.speciality_id
inner join public.m_general_ledger_master genl on
	genl.general_ledger_id = spc.general_ledger_id
where bill.visit_type_id = 2;

-------------- Insert credit notes into tally interface start-----------------------------	
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucher_ip, 'Credit Note', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'IP'
from creditnotes crd 
where crd.refunddate::date = dateoftrans 
group by  crd.orgid, crd.unitid,crd.refunddate,crd.ledger;
-------------- Insert credit notes into tally interface end-----------------------------

--------------Insert patient credit--------------
create or replace temporary view
creditnotedueamt as 
select
	sum(crd.cr_deu_amount) as amount,
	crd.credit_note_date::date as credit_note_date,
	crd.organisation_id as orgid,
	crd.unit_id as unitid
from
	billing.m_credit_note_master crd
inner join billing.m_billing_master billmst on
	billmst.billing_master_id = crd.bill_id
where billmst.visit_type_id = 2
group by
	crd.organisation_id,
	crd.unit_id,
	crd.cr_deu_amount,
	crd.credit_note_date;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucher_ip, 'Credit Note', 'Patient Credit', crd.credit_note_date, 0, sum(amount), crd.unitid, crd.orgid, 'IP'
from creditnotedueamt crd 
where crd.credit_note_date::date = dateoftrans
group by crd.orgid, crd.unitid,crd.credit_note_date,crd.amount
having crd.amount > 0;
--------------Insert patient credit--------------

--------------Discount round off start----------------
with roundoff as (select
	sum(bm.discount_roundoff) as round_off_amount,
	bm.unit_id as unitId,
	bm.organisation_id as orgId,
	bm.created_date::date as transactionDate
from
	billing.m_credit_note_master bm
	inner join billing.m_billing_master bill on bill.billing_master_id=bm.bill_id
where
	bm.created_date::date = dateoftrans
	and bill.visit_type_id = 2
group by
	bm.organisation_id,
	bm.unit_id,
	bm.created_date::date
having
	sum(bm.discount_roundoff) is not null) 
	
		insert
			into
				public.t_tally_interface (voucher_no,
				voucher_type,
				ledger,
				voucher_date,
				debit_amount,
				credit_amount,
				unit_id,
				hospital_id,
				tran_type) select
					voucher_ip,
					'Credit Note',
					'Discount round-off',
					roundoff.transactionDate,
					case 
					when roundoff.round_off_amount<0 then 
					0
						else 
					cast(roundoff.round_off_amount as numeric(10, 2))  end,
					case 
					when roundoff.round_off_amount>0 then 
					0
						else cast(-roundoff.round_off_amount as numeric(10, 2)) 
					 end ,
					roundoff.unitId,
					roundoff.orgId,
					'IP'
				from
					roundoff
				where roundoff.round_off_amount >0 or roundoff.round_off_amount <0 ;
--------------Discount round off start----------------

---------------------- refund details view --------------------------------------
create or replace temporary view
creditnoterefunds as 
select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,
prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,
prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,cnm.credit_note_date as ceditnotedate,
bank.bank_name as bankname
from billing.t_payment_refund_master prm
inner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_id
inner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id 
inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_id
left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
where billmst.visit_type_id = 2 and prm.is_cn_or_deposit = 1;
-----------------------------xxx-----------------------------------

---------------------- insert cash mode transactions ------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'
from creditnoterefunds rfd
where rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid = 1
group by rfd.orgid,rfd.unitid,rfd.refunfdate,rfd.mode;
-------------------------xxx------------------------------------------------

----------------------- insert other mode transactions ----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from creditnoterefunds rfd
where rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid != 1
group by  rfd.orgid, rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;
-------------------------xxx---------------------------------

----------------------Previous date settlement start cash-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid = 1 and rfd.refunfdate::date=dateoftrans
group by  rfd.orgid,rfd.unitid,rfd.refunfdate,rfd.mode;
----------------------------
----------------------Previous date settlement start others-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid != 1 and rfd.refunfdate::date=dateoftrans
group by  rfd.orgid, rfd.unitid,  rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;
--------------------------------
------------------------------Credit insert start--------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucher_ip, 'Credit Note', 'Patient Credit', rfd.refunfdate,sum(rfd.amount),0, rfd.unitid, rfd.orgid, 'IP'
from creditnoterefunds rfd
where rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.refunfdate::date=dateoftrans
group by rfd.orgid, rfd.unitid,rfd.refunfdate
having sum(rfd.amount) > 0;
------------------------------Credit insert stop--------------------------

--------- 2.IP ---->---------



return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


