CREATE FUNCTION public.post_deposit_data(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare vouchernoip integer = nextval('public.tally_voucher_no_seq');
begin
----------- Create view --------------------------
create or replace temporary view
 deposit
 as 
 select depdt.payment_mode_id as modeid, pmode.ledger_name as mode, depdt.amount as recamount,
 dep.deposit_date::date as date ,dep.deposit_master_id as depositid, dep.org_id as orgid, dep.unit_id as unitid,
 depdt.card_no as cardnumber, depdt.card_type_id as cardtypeid, depdt.cheque_number as chequenumber, 
 depdt.cheque_date as chequedate, bank.bank_name as bankname, depdt.deposit_details_id as depositdetailsid,
 dep.deposit_type_id as deposittypeid,dep.visit_type_id as visittypeid
 from billing.m_deposit_master dep
 inner join billing.t_payment_deposit_details depdt
 on depdt.deposit_id = dep.deposit_master_id
 inner join public.m_payment_mode_master pmode
 on pmode.payment_mode_id = depdt.payment_mode_id
 left join billing.m_bank_master bank
 on bank.bank_id = depdt.bank_id;
 ------------------xxx--------------------------

-- <-----1. OP

------------------ Insert cash deposits ------------------------------
insert into public.t_tally_interface 
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', dep.mode, dep.date, cast(sum(dep.recamount) as numeric(10,2)), 0, dep.unitid, dep.orgid , 'OP'
from deposit dep
where dep.modeid = 1 and dep.date = dateoftrans and (dep.deposittypeid=1 or dep.visittypeid=1)
