CREATE FUNCTION public.post_doc_share_data(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucherno_ip integer = nextval('public.tally_voucher_no_seq');
begin 
 -------<---- 1. OP ---------------------------
 
 ------------ Group wise doctor share posting start -------------------------
with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join service.m_service_master sm on sm.service_master_id = ds.service_id
inner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_id
where  log.created_date:: date = dateoftrans and ds.visit_type_id=1
group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Journal', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid,'OP' from gen;
 ------------  Group wise doctor share posting  end -------------------------

------- Doctor share start ---------------
with docshare as (select  concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans and ds.visit_type_id=1 
group by  ledger, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Journal', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'OP' from docshare;
------- Doctor share end ---------------


------- Retainship amount start ---------------
with docretainship as (select  sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans and ds.visit_type_id=1
group by   log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Journal', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'OP' from docretainship;
------- Retainship amount end ---------------


 ------- OP ----->-----
 

-------<---- 2. IP ---------------------------
 
 ------------ Group wise doctor share posting start -------------------------
with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join service.m_service_master sm on sm.service_master_id = ds.service_id
inner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_id
where  log.created_date:: date = dateoftrans and ds.visit_type_id=2
group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno_ip, 'Journal', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid,'IP' from gen;
 ------------  Group wise doctor share posting  end -------------------------

------- Doctor share start ---------------
with docshare as (select  concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans and ds.visit_type_id=2 
group by  ledger, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno_ip, 'Journal', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'IP' from docshare;
------- Doctor share end ---------------


------- Retainship amount start ---------------
with docretainship as (select  sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans and ds.visit_type_id=2
group by   log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno_ip, 'Journal', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'IP' from docretainship;
------- Retainship amount end ---------------

 ------- IP ----->-----



return true;
EXCEPTION 
 when OTHERS then 
 return false;
COMMIT;
end;
$$;


--
-- TOC entry 4063 (class 1255 OID 2969356)
-- Name: post_grn_notes(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_grn_notes(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$ begin create or replace
temporary view grn as (
select
	grn.id,
	'Purchase' as voucherType,
	pc.category::character varying(255) as Ledger,
	grn.added_date as transactionDate,
	sum(grnd.net_amount) as debitNote,
	0::double precision as creditNote,
	grn.remark,
	grn.unit_id,
	grn.organization_id,
	grn.invoice_number,
	'Purchase' as tran_type
from
	procurement.t_good_receipt_note_detail grnd
inner join procurement.t_good_receipt_note grn on
	grn.id = grnd.grn_id
inner join public.m_item item on
	item.id = grnd.item_id
left join public.m_generic generic on
	generic.id = item.generic_id
left join public.m_product_category pc on
	(case
		when item.product_category_id is not null then pc.id = item.product_category_id
		else pc.id = generic.product_category_id
	end)
group by
	grn.organization_id,
	grn.unit_id,
	grn.added_date,
	pc.category,
	grn.id,
	grn.remark,
	grn.invoice_number
order by
	grn.id)
union all (
select
distinct(grn.id), 'Purchase' as voucherType, vendor."name"::character varying(255) as Ledger, grn.added_date as transactionDate, 0::double precision as debitNote, grn.net_amount as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Purchase' as tran_type
from
procurement.t_good_receipt_note_detail grnd
inner join procurement.t_good_receipt_note grn on
grn.id = grnd.grn_id
inner join public.m_vendor vendor on
vendor.id = grn.vendor_id
order by
grn.id)
union all (
select
distinct (grn.id), 'Purchase' as voucherType, 'Round off'::character varying(255) as Ledger, grn.added_date as transactionDate, grn.round_off as debitNote, 0::double precision as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Purchase' as tran_type
from
procurement.t_good_receipt_note_detail grnd
inner join procurement.t_good_receipt_note grn on
grn.id = grnd.grn_id
where
grn.round_off > 0
order by
grn.id)
union all (
select
distinct (grn.id), 'Purchase' as voucherType, 'Round off'::character varying(255) as Ledger, grn.added_date as transactionDate, 0::double precision as debitNote, (grn.round_off * -1) as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Purchase' as tran_type
from
procurement.t_good_receipt_note_detail grnd
inner join procurement.t_good_receipt_note grn on
grn.id = grnd.grn_id
where
grn.round_off < 0
order by
grn.id)
order by
id;
-----Create Voucher Number ----
 create or replace
temporary view grn_voucher as
select
	distinct(id) as grnId,
	concat('V000', id) as voucherNo
from
	grn
order by
	grnId;
------insert grn into tally interface start--------
 insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, ref_no_type, ref_number, tran_type)
select
	grnv.voucherno,
	grn.vouchertype,
	grn.Ledger,
	grn.transactionDate,
	grn.debitNote as debitnote,
	grn.creditNote as creditNote,
	grn.unit_id,
	grn.organization_id,
	'New Ref',
	grn.invoice_number,
	tran_type
from
	grn grn
inner join grn_voucher grnv on
	grn.id = grnv.grnId
where
	grn.transactionDate::date = dateoftrans
order by
	grnv.voucherno,
	grn.creditNote;
------------GRN Return --------
 create or replace
temporary view grnreturn as (
select
	returndetail.returnable_gatepass_id as id,
	'Purchase Return' as voucherType,
	pc.category as ledger,
	grnreturn.added_date as transacionDate,
	0::double precision as debitNote,
	sum(returndetail.total_amt) as creditAmount,
	grnreturn.unit_id,
	grnreturn.organization_id
from
	inventory.t_returnable_gatepass_detail returndetail
inner join inventory.t_returnable_gatepass grnreturn on
	grnreturn.id = returndetail.returnable_gatepass_id
inner join inventory.t_batch batch on
	batch.id = returndetail.batch_id
inner join public.m_item item on
	item.id = batch.item_id
left join public.m_generic generic on
	generic.id = item.generic_id
left join public.m_product_category pc on
	(case
		when item.product_category_id is not null then pc.id = item.product_category_id
		else pc.id = generic.product_category_id
	end)
group by
	grnreturn.organization_id,
	grnreturn.unit_id,
	grnreturn.added_date,
	returndetail.returnable_gatepass_id,
	pc.category
order by
	returndetail.returnable_gatepass_id)
union all (
select
distinct(returndetail.returnable_gatepass_id) as id, 'Purchase Return' as voucherType, vendor.name as ledger, grnreturn.added_date as transacionDate,
--sum(grnreturn.total_amt) as debitNote, 
(grnreturn.total_amt) as debitNote, 0::double precision as creditNote, grnreturn.unit_id, grnreturn.organization_id
from
inventory.t_returnable_gatepass_detail returndetail
inner join inventory.t_returnable_gatepass grnreturn on
grnreturn.id = returndetail.returnable_gatepass_id
inner join public.m_vendor vendor on
vendor.id = grnreturn.vendor_id
--group by  returndetail.returnable_gatepass_id, vendor.name , grnreturn.added_date, grnreturn.unit_id, grnreturn.organization_id

order by returndetail.returnable_gatepass_id )
order by
id;
-----Create Voucher Number ----
 create or replace
temporary view grnreturn_voucher as
select
	distinct(id) as grnreturnId,
	concat('V000', id) as voucherNo
from
	grnreturn
order by
	grnreturnId;
------insert grn into tally interface start--------
 insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, ref_no_type, tran_type)
select
	grnv.voucherno,
	grn.vouchertype,
	grn.Ledger,
	grn.transacionDate,
	grn.debitNote as debitnote,
	grn.creditAmount as creditNote,
	grn.unit_id,
	grn.organization_id,
	'GRN Return',
	'GRN Return'
from
	grnreturn grn
inner join grnreturn_voucher grnv on
	grn.id = grnv.grnreturnId
where
	grn.transacionDate::date = dateoftrans
order by
	grnv.voucherno,
	grn.creditAmount;

return true;

exception
when others then return false;
end;

$$;


--
-- TOC entry 4017 (class 1255 OID 2969357)
-- Name: post_sale_notes(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_sale_notes(dateoftrans date) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin
	
-----------Cash Payment---------
	
create or replace temporary view	
sale_cash as 
(select 'Cash Pharmacy' as ledger, date(sale.added_date) as transactionDate, ROUND((sum(pm.amount))::numeric,2 ) as debitNote,
0::numeric as creditNote, sale.unit_id, sale.organization_id
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 1
group by date(sale.added_date), sale.unit_id, sale.organization_id )
union all
(select  'Pharmacy Sales' as ledger, date(sale.added_date) as transactionDate, 0::numeric as debitNote,
ROUND((sum(pm.amount))::numeric,2 ) as creditNote, sale.unit_id, sale.organization_id
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 1
group by date(sale.added_date), sale.unit_id, sale.organization_id)
order by ledger;

create or replace temporary view	
sale_cash_voucher as 
select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_cash.transactionDate
from sale_cash
group by sale_cash.transactionDate;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id)
select scv.voucher, 'Sale' as voucherType, sc.ledger, sc.transactionDate, sc.debitNote, sc.creditNote, '' as voucherNarration
, sc.unit_id, sc.organization_id
from sale_cash sc
join sale_cash_voucher scv on sc.transactionDate = scv.transactionDate
where date(sc.transactionDate) =  dateoftrans
order by sc.transactionDate, scv.transactionDate;
-----------Debit Card Payment---------

create or replace temporary view	
sale_debit as 
(select 'Credited Bank Account' as ledger, date(sale.added_date) as transactionDate, ROUND((sum(pm.amount))::numeric,2 ) as debitNote,
0::numeric as creditNote, sale.unit_id, sale.organization_id, concat('Card No:', pm.card_number,' ','Sale No: ',sale.bill_no) as VouNarration
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id 
where pm.payment_mode_id = 4
group by date(sale.added_date), sale.unit_id, sale.organization_id, VouNarration )
union all
(select  'Pharmacy Sales' as ledger, date(sale.added_date) as transactionDate, 0::numeric as debitNote,
ROUND((sum(pm.amount))::numeric,2 ) as creditNote, sale.unit_id, sale.organization_id, '' as VouNarration
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 4
group by date(sale.added_date), sale.unit_id, sale.organization_id)
order by transactionDate;


create or replace temporary view	
sale_debit_voucher as 
select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_debit.transactionDate
from sale_debit
group by sale_debit.transactionDate;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id, tran_type)
select scv.voucher, 'Sale' as voucherType, sc.ledger, sc.transactionDate, sc.debitNote, sc.creditNote, sc.VouNarration as voucherNarration
, sc.unit_id, sc.organization_id, 'DebitCard' as tran_type
from sale_debit sc
join sale_debit_voucher scv on sc.transactionDate = scv.transactionDate
where date(sc.transactionDate) =  dateoftrans
order by sc.transactionDate, scv.transactionDate;

-----------Credit Card Payment---------

create or replace temporary view	
sale_credit as 
(select 'Credited Bank Account' as ledger, date(sale.added_date) as transactionDate, ROUND((sum(pm.amount))::numeric,2 ) as debitNote,
0::numeric as creditNote, sale.unit_id, sale.organization_id, concat('Card No:', pm.card_number,' ','Sale No: ',sale.bill_no) as VouNarration
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 3
group by pm.sale_id, date(sale.added_date), sale.unit_id, sale.organization_id, VouNarration )
union all
(select  'Pharmacy Sales' as ledger, date(sale.added_date) as transactionDate, 0::numeric as debitNote,
ROUND((sum(pm.amount))::numeric,2 ) as creditNote, sale.unit_id, sale.organization_id, '' as VouNarration
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 3
group by date(sale.added_date), sale.unit_id, sale.organization_id)
order by transactionDate;

create or replace temporary view	
sale_credit_voucher as 
select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_credit.transactionDate
from sale_credit
group by sale_credit.transactionDate;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id, tran_type)
select scv.voucher, 'Sale' as voucherType, sc.ledger, sc.transactionDate, sc.debitNote, sc.creditNote, sc.VouNarration as voucherNarration
, sc.unit_id, sc.organization_id, 'CreditCard' as tran_type
from sale_credit sc
join sale_credit_voucher scv on sc.transactionDate = scv.transactionDate
where date(sc.transactionDate) =  dateoftrans
order by sc.transactionDate, scv.transactionDate;


-----------Cheque Payment---------

create or replace temporary view	
sale_cheque as 
(select 'Credited Bank Account' as ledger, date(sale.added_date) as transactionDate, ROUND((sum(pm.amount))::numeric,2 ) as debitNote,
0::numeric as creditNote, sale.unit_id, sale.organization_id, concat('Cheque No:', pm.check_number,' ','Sale No: ',sale.bill_no) as VouNarration, 
bank.bank_name as bankName
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id 
join billing.m_bank_master bank on bank.bank_id = pm.bank_id
where pm.payment_mode_id = 2
group by pm.sale_id, date(sale.added_date), sale.unit_id, sale.organization_id, VouNarration, bank.bank_name )
union all
(select  'Pharmacy Sales' as ledger, date(sale.added_date) as transactionDate, 0::numeric as debitNote,
ROUND((sum(pm.amount))::numeric,2 ) as creditNote, sale.unit_id, sale.organization_id, '' as VouNarration,'' as bankName
from pharmacy.t_sale sale
join pharmacy.t_sale_payment_mode pm on sale.id = pm.sale_id where pm.payment_mode_id = 2
group by date(sale.added_date), sale.unit_id, sale.organization_id)
order by transactionDate;

create or replace temporary view	
sale_cheque_voucher as 
select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_cheque.transactionDate
from sale_cheque
group by sale_cheque.transactionDate;

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id, tran_type, bank_name)
select scv.voucher, 'Sale' as voucherType, sc.ledger, sc.transactionDate, sc.debitNote, sc.creditNote, sc.VouNarration as voucherNarration
, sc.unit_id, sc.organization_id, 'chequeCard' as tran_type, sc.bankName
from sale_cheque sc
join sale_cheque_voucher scv on sc.transactionDate = scv.transactionDate
where date(sc.transactionDate) =  dateoftrans
order by sc.transactionDate, scv.transactionDate;

return true;
EXCEPTION 
 when OTHERS then 
	return false;

end;
$$;


--
-- TOC entry 4042 (class 1255 OID 2969358)
-- Name: post_visit_fa_data(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_visit_fa_data(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$ begin
----------- Create view ---------------------------
 create or replace
temporary view opbillPatientSpecific as (
select
	pMode.payment_mode_id as modeid,
	pMode.payment_mode_desc as mode,
	pReceiptDtls.amount as rcptamount,
	billMst.outstanding as outstanding,
	billMst.net_amount as billnetamount,
	bank.bank_name as bankname,
	pReceiptDtls.card_number as cardnumber,
	pReceiptDtls.card_type_id as cardtypeid,
	pReceiptDtls.check_number as chequenumber,
	pReceiptDtls.cheque_date::date as chequedate,
	pReceiptDtls.transaction_no as transactionno,
	pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
	billMst.organisation_id as orgid,
	billMst.unit_id as unitid,
	pReceiptDtls.date_of_transaction :: date as transdate,
	billMst.bill_date_time :: date as billdate,
	pReceiptDtls.trans_transaction_date as transferdate,
	pReceiptDtls.available_fund as availableFund,
	pat.patient_id as patientId,
	concat(pat.first_name, ' ', pat.last_name) as patientname,
	pReceiptMst.reciept_number as recieptnumber,
	billMst.bill_number as billnumber,
	billMst.billing_master_id as billId,
	trans.transaction_type_desc as transactionType,
	(case
		when billMst.visit_type_id = 1 then 'OP'
		else 'IP'
	end) as visittype
from
	billing.t_payment_reciept_details pReceiptDtls
inner join public.m_payment_mode_master pMode on
	pMode.payment_mode_id = pReceiptDtls.payment_mode_id
inner join billing.t_payment_reciept_master pReceiptMst on
	pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id
inner join billing.m_billing_master billMst on
	pReceiptMst.billing_master_id = billMst.billing_master_id
inner join patient.t_patient_registration pat on
	pat.patient_id = billMst.patient_id
left join billing.m_bank_master bank on
	bank.bank_id = pReceiptDtls.bank_id
left join billing.m_transaction_type_master trans on
	pReceiptDtls.transaction_type_id = trans.transaction_type_id
where
	pReceiptDtls.status = 'A'
	and pReceiptMst.status = 'A'
	and billMst.status = 'A');
------- Insert cash start ---------------
 insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, tran_type, vou_narration, patient_specific)
select
	concat(opbill.billnumber),
	'Receipt',
	opbill.mode,
	opbill.transdate,
	cast(sum(opbill.rcptamount) as numeric(10, 2)),
	0 ,
	opbill.unitId,
	opbill.orgId ,
	opbill.billId,
	opbill.visittype,
	(
	select
		narration
	from
		public.getnurrationname(opbill.billId)),
	'Y'
from
	opbillPatientSpecific as opbill
where
	opbill.transdate = opbill.billdate
	and opbill.modeid = 1
	and opbill.transdate = dateoftrans
group by
	opbill.orgid,
	opbill.unitid,
	opbill.transdate,
	opbill.billId,
	opbill.billnumber,
	opbill.patientname,
	opbill.paymentreceiptdetailId,
	opbill.modeid,
	opbill.mode,
	opbill.visittype;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
 insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)
select
	opbill.billnumber,
	'Receipt',
	opbill.mode,
	opbill.transdate,
	cast(opbill.rcptamount as numeric(10, 2)),
	0 ,
	opbill.unitId,
	opbill.orgId,
	opbill.billId,
	coalesce(opbill.chequedate, opbill.transferdate),
	opbill.visittype,
	opbill.bankname,
	coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),
	concat((select narration from public.getnurrationname(opbill.billId)), ' | ', opbill.transactionType),
	'Y'
from
	opbillPatientSpecific as opbill
where
	opbill.transdate = opbill.billdate
	and opbill.modeid <> 1
	and opbill.transdate = dateoftrans
group by
	opbill.orgid,
	opbill.unitid,
	opbill.transdate,
	opbill.billId,
	opbill.billnumber,
	opbill.patientname,
	opbill.modeid,
	opbill.mode,
	opbill.rcptamount,
	opbill.paymentreceiptdetailId,
	opbill.chequedate,
	opbill.transferdate,
	opbill.bankname,
	opbill.chequenumber,
	opbill.cardnumber,
	opbill.transactionno,
	opbill.transactionType,
	opbill.visittype;
------- Insert others start---------------
 with roundoff as (
select
	bm.bill_number as billno,
	sum(bm.round_off) as round_off_amount,
	bm.unit_id as unitId,
	bm.organisation_id as orgId,
	bm.created_date::date as transactionDate,
	pat.patient_id as patientid,
	concat(concat(pat.first_name, ' ', pat.last_name) , ' | ', coalesce(bm.bill_number, ''))as patientname,
	bm.billing_master_id as billid,
	(case
		when bm.visit_type_id = 1 then 'OP'
		else 'IP'
	end) as visittype
from
	billing.m_billing_master bm
inner join patient.t_patient_registration pat on
	pat.patient_id = bm.patient_id
where
	bm.created_date::date = dateoftrans
	and bm.visit_type_id = 1
	and bm.bill_cancelled = 'N'
	and bm.status = 'A'
group by
	bm.organisation_id,
	bm.unit_id,
	bm.created_date::date,
	bm.billing_master_id,
	bm.bill_number,
	pat.patient_id
having
	sum(bm.round_off) <> 0)
insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)
select
	roundoff.billno,
	'Receipt',
	'Discount round-off',
	roundoff.transactionDate,
	case
		when roundoff.round_off_amount<0 then cast(-roundoff.round_off_amount as numeric(10, 2))
		else 0
	end,
	case
		when roundoff.round_off_amount>0 then cast(roundoff.round_off_amount as numeric(10, 2))
		else 0
	end ,
	roundoff.unitId,
	roundoff.orgId,
	roundoff.visittype,
	(
	select
		narration
	from
		public.getnurrationname(roundoff.billid)),
	'Y',
	roundoff.billid
from
	roundoff
where
	roundoff.round_off_amount >0
	or roundoff.round_off_amount <0 ;
---------------------- Company amount --------------------------------
 with comp as (
select
	mpr.payee_id as ledgerId,
	comp.company_desc as ledger,
	sum(mpr.payee_amount) as amount,
	billMst.bill_date_time ::date as transactionDate,
	billMst.organisation_id as orgId,
	billMst.unit_id as unitId,
	concat(pat.first_name, ' ', pat.last_name) as patientname,
	billMst.bill_number as billno,
	billMst.billing_master_id as billid,
	(case
		when billMst.visit_type_id = 1 then 'OP'
		else 'IP'
	end) as visittype
from
	billing.t_bill_details_payee_mapper mpr
inner join billing.t_billing_details billDtls on
	mpr.bill_details_id = billDtls.billing_details_id
inner join billing.m_billing_master billMst on
	billMst.billing_master_id = billDtls.billing_master_id
inner join public.t_company_master comp on
	comp.company_id = mpr.payee_id
inner join patient.t_patient_registration pat on
	pat.patient_id = billMst.patient_id
where
	billMst.bill_date_time::date = dateoftrans
	--and billMst.visit_type_id = 1
	and mpr.status = 'A'
	and billMst.bill_cancelled = 'N'
	and mpr.payee_id <> (
	select
		self_payee_id
	from
		t_unit_application_billing_configuration
	where
		unit_id = billMst.unit_id
		and status = 'A')
group by
	billMst.organisation_id,
	billMst.unit_id,
	billMst.bill_date_time::date,
	billMst.billing_master_id,
	billMst.bill_number,
	pat.patient_id,
	mpr.payee_id,
	comp.company_desc )
insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)
select
	comp.billno,
	'Receipt',
	comp.ledger,
	comp.transactionDate,
	cast(comp.amount as numeric(10, 2)),
	0,
	comp.unitId,
	comp.orgId,
	comp.visittype,
	(
	select
		narration
	from
		public.getnurrationname(comp.billid)),
	'Y',
	comp.billid
from
	comp;
------------------------------Package consumption ---------------------------------
 /*with pack as (
select
genLedMst.general_ledger_id,
genLedMst.general_ledger_name as ledger,
sum(dtls.gross_amount) as amount ,
bill.organisation_id as orgId,
bill.unit_id as unitId,
dtls.created_date::date as createdDate,
concat(pat.first_name, ' ', pat.last_name) as patientname,
bill.bill_number as billno,
bill.billing_master_id as billid
from
billing.t_billing_details dtls
inner join billing.m_billing_master bill on
bill.billing_master_id = dtls.billing_master_id
inner join service.m_service_master servMst on
servMst.service_master_id = dtls.service_id
inner join doctor.m_speciality_master spc on
spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on
genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.t_order_details ordt on
ordt.order_details_id = dtls.order_details_id
inner join patient.t_patient_registration pat on
pat.patient_id = bill.patient_id
where
dtls.created_date::date = dateoftrans
and bill.visit_type_id = 1
and ordt.is_package_service = 'Y'
and bill.bill_cancelled = 'N'
group by
bill.organisation_id,
bill.unit_id,
