insert
	into
	public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)
select
	opbill.billnumber,
	'Receipt',
	'Available Fund',
	opbill.transdate,
	0,
	cast(sum(opbill.availableFund) as numeric(10, 2)),
	opbill.unitid,
	opbill.orgid,
	opbill.visittype,
	(
	select
		narration
	from
		public.getnurrationname(opbill.billid)),
	'Y',
	opbill.billid
from
	opbillPatientSpecific as opbill
where
	opbill.transdate = dateoftrans
group by
	opbill.orgid,
	opbill.unitid,
	opbill.transdate,
	opbill.billid,
	opbill.billnumber,
	opbill.patientname,
	opbill.visittype
having
	sum(opbill.availableFund) > 0;

return true;

exception
when others then return false;

commit;
end;

