--
-- TOC entry 4030 (class 1255 OID 4154964)
-- Name: post_visit_fa_data_patientwise(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_visit_fa_data_patientwise(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

begin 

------<----1. OP---------------	
	
----------- Create view ---------------------------
create or replace temporary view 
  opbillPatientSpecific
AS
	(select
		pMode.payment_mode_id as modeid,
		pMode.payment_mode_desc as mode,
		pReceiptDtls.amount as rcptamount,
		billMst.outstanding as outstanding,
		billMst.net_amount as billnetamount,
		bank.bank_name as bankname,
		pReceiptDtls.card_number as cardnumber,
		pReceiptDtls.card_type_id as cardtypeid,
		pReceiptDtls.check_number as chequenumber,
		pReceiptDtls.cheque_date::date as chequedate,
		pReceiptDtls.transaction_no as transactionno,
		pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
		billMst.organisation_id as orgid,
		billMst.unit_id as unitid,
		pReceiptDtls.date_of_transaction :: date as transdate,
		billMst.bill_date_time :: date as billdate,
		pReceiptDtls.trans_transaction_date as transferdate,
		pReceiptDtls.available_fund as availableFund,
		pat.patient_id as patientId,
		concat(pat.first_name,' ',pat.last_name) as patientname,
		pReceiptMst.reciept_number as recieptnumber,
		billMst.bill_number as billnumber,
		billMst.billing_master_id as billId,
		trans.transaction_type_desc as transactionType
	from
		billing.t_payment_reciept_details pReceiptDtls
	inner join public.m_payment_mode_master pMode on
		pMode.payment_mode_id = pReceiptDtls.payment_mode_id
	inner join billing.t_payment_reciept_master pReceiptMst on
		pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id
	inner join billing.m_billing_master billMst on
		pReceiptMst.billing_master_id = billMst.billing_master_id
	inner join patient.t_patient_registration pat on
		pat.patient_id = billMst.patient_id 	
	left join billing.m_bank_master bank on
		bank.bank_id = pReceiptDtls.bank_id
	left join billing.m_transaction_type_master trans on
		pReceiptDtls.transaction_type_id = trans.transaction_type_id 	
	where
		billMst.visit_type_id = 1
		and pReceiptDtls.status = 'A'
		and pReceiptMst.status  = 'A'
		and billMst.status = 'A');

------- Insert cash start ---------------
	insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number, tran_type,vou_narration, patient_specific)
	select
		concat(opbill.billnumber),
		'Receipts',
		opbill.mode,
		opbill.transdate,
		cast(sum(opbill.rcptamount) as numeric(10, 2)),
		0 ,
		opbill.unitId,
		opbill.orgId ,
		opbill.billId,
		'OP',
		(select narration from public.getnurrationname(opbill.billId)),'Y'
	from
		opbillPatientSpecific as opbill
	where
		opbill.transdate = opbill.billdate
		and opbill.modeid = 1
		and opbill.transdate = dateoftrans
		group by opbill.orgid,
		opbill.unitid,
		opbill.transdate,
		opbill.billId,
		opbill.billnumber,
		opbill.patientname,
		opbill.paymentreceiptdetailId,
		opbill.modeid,
		opbill.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
	insert
		into
		public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)
	select
		opbill.billnumber,
		'Receipts',
		opbill.mode,
		opbill.transdate,
		cast(opbill.rcptamount as numeric(10, 2)),
		0 ,
		opbill.unitId,
		opbill.orgId,
		opbill.billId,
		coalesce(opbill.chequedate, opbill.transferdate),
		'OP',
		opbill.bankname,
		coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),
		concat((select narration from public.getnurrationname(opbill.billId)),' | ',opbill.transactionType),'Y'
	from
		opbillPatientSpecific as opbill
	where
		opbill.transdate = opbill.billdate
		and opbill.modeid <> 1
		and opbill.orgid!=10
		and opbill.transdate = dateoftrans
	group by
		opbill.orgid,
		opbill.unitid,
		opbill.transdate,
		opbill.billId,
		opbill.billnumber,
		opbill.patientname,
		opbill.modeid,
		opbill.mode,
		opbill.rcptamount,
		opbill.paymentreceiptdetailId,
		opbill.chequedate,
		opbill.transferdate,
		opbill.bankname,
		opbill.chequenumber, 
		opbill.cardnumber, 
		opbill.transactionno,opbill.transactionType;
------- Insert others start--------------- 

	with roundoff as (
	select
		bm.bill_number as billno,
		sum(bm.round_off) as round_off_amount,
		bm.unit_id as unitId,
		bm.organisation_id as orgId,
		bm.created_date::date as transactionDate,
		pat.patient_id as patientid,
		concat(concat(pat.first_name,' ',pat.last_name) ,' | ', coalesce(bm.bill_number,''))as patientname,
		bm.billing_master_id as billid
	from
		billing.m_billing_master bm
	inner join patient.t_patient_registration pat on
			pat.patient_id = bm.patient_id 	
	where
		bm.created_date::date = dateoftrans
		and bm.visit_type_id = 1
		and bm.bill_cancelled = 'N'
		and bm.status  = 'A'
	group by
		bm.organisation_id,
		bm.unit_id,
		bm.created_date::date,
		bm.billing_master_id,
		bm.bill_number,
		pat.patient_id
	having
		sum(bm.round_off) <>0)
	insert
		into
		public.t_tally_interface (voucher_no,voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type,vou_narration, patient_specific,unique_number)
	select
		roundoff.billno,
		'Receipts',
		'Discount round-off',
		roundoff.transactionDate,
		case
			when roundoff.round_off_amount<0 then cast(-roundoff.round_off_amount as numeric(10, 2))
			else 0
		end,
		case
			when roundoff.round_off_amount>0 then cast(roundoff.round_off_amount as numeric(10, 2))
			else 0
		end ,
		roundoff.unitId,
		roundoff.orgId,
		'OP',
		(select narration from public.getnurrationname(roundoff.billid)),'Y',
		roundoff.billid
	from
		roundoff
	where
		roundoff.round_off_amount >0
		or roundoff.round_off_amount <0 ;

---------------------- Company amount --------------------------------
	with comp as (
	select
		mpr.payee_id as ledgerId,
		comp.company_desc as ledger,
		sum(mpr.payee_amount) as amount,
		billDtls.created_date::date as transactionDate,
		billMst.organisation_id as orgId,
		billMst.unit_id as unitId,
		concat(pat.first_name, ' ', pat.last_name) as patientname,
		billMst.bill_number as billno,
		billMst.billing_master_id as billid
	from
		billing.t_bill_details_payee_mapper mpr
	inner join billing.t_billing_details billDtls on
		mpr.bill_details_id = billDtls.billing_details_id
	inner join billing.m_billing_master billMst on
		billMst.billing_master_id = billDtls.billing_master_id
	inner join public.t_company_master comp on
		comp.company_id = mpr.payee_id
	inner join patient.t_patient_registration pat on
		pat.patient_id = billMst.patient_id
	where
		billDtls.created_date::date = dateoftrans
		and billMst.visit_type_id = 1
		and mpr.status = 'A'
		and billMst.bill_cancelled = 'N'
		and mpr.payee_id <> (
		select
			self_payee_id
		from
			t_unit_application_billing_configuration
		where
			unit_id = billMst.unit_id
			and status = 'A')
	group by
		billMst.organisation_id,
		billMst.unit_id,
		billDtls.created_date::date,
		billMst.billing_master_id, 
		billMst.bill_number,
		pat.patient_id,
		mpr.payee_id,
		comp.company_desc )
	insert
		into
		public.t_tally_interface (voucher_no,voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)
	select
		comp.billno,
		'Receipts',
		comp.ledger,
		comp.transactionDate,
		cast(comp.amount as numeric(10, 2)),
		0,
		comp.unitId,
		comp.orgId,
		'OP',
		(select narration from public.getnurrationname(comp.billid)),'Y',comp.billid
	from
		comp;

