--------------------------------------------------
-------------------- Insert deposit consumption --------------------------------------
	insert
		into
		public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)
	select
		bill.bill_number,
		'Receipts',
		'Patient Advance',
