------- Insert outstanding start---------------
	with outst as (
	select
		coalesce(sum(tbpd.due_amount), 0) as outstanding,
		bill.organisation_id as orgId,
		bill.unit_id as unitId,
		bill.bill_date_time::date as billDate,
		concat(pat.first_name, ' ', pat.last_name) as patientname,
		bill.bill_number as billno,
		bill.billing_master_id as billid
	from
		billing.m_billing_master bill
	inner join billing.t_bill_payee_details tbpd on
		bill.billing_master_id = tbpd.bill_id
	inner join patient.t_patient_registration pat on
		pat.patient_id = bill.patient_id
	where
		bill.bill_date_time::date = dateoftrans
		and	bill.visit_type_id = 1
		and bill.bill_cancelled = 'N'
		and tbpd.payee_id = (
		select
			self_payee_id
		from
			t_unit_application_billing_configuration tuabc
		where
			unit_id = bill.unit_id )
	group by
		bill.organisation_id,
		bill.unit_id,
		bill.bill_date_time::date,
		bill.billing_master_id,
		bill.bill_number,
		pat.patient_id )
	insert
		into
		public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)
	select
		outst.billno,
		'Receipts',
		'Patient Credit',
		outst.billDate,
		cast((outst.outstanding) as numeric(10, 2)),
		0,
		outst.unitId,
		outst.orgId,
		'OP',
		(select narration from public.getnurrationname(outst.billid)),'Y',outst.billid
	from
		outst
	where
		(outst.outstanding) > 0;
	
	
	with outstand as (
	select
		coalesce(tprm.amount- (select available_fund from billing.t_payment_reciept_details tprd where tprd.payment_receipt_master_id = tprm.payment_reciept_id), 0) as outstanding,
		bill.organisation_id as orgId,
		bill.unit_id as unitId,
		bill.bill_date_time::date as billDate,
		concat(pat.first_name, ' ', pat.last_name) as patientname,
		bill.bill_number as billno,
		bill.billing_master_id as billid
	from
		billing.t_payment_reciept_master tprm
	inner join billing.m_billing_master bill on
		bill.billing_master_id = tprm.billing_master_id
	inner join patient.t_patient_registration pat on
		pat.patient_id = bill.patient_id
	where
		bill_date_time::date != tprm.date_of_reciept::date
		and	bill.bill_date_time::date = dateoftrans
		and bill.visit_type_id = 1
		and bill.bill_cancelled = 'N'
	group by
		bill.organisation_id,
		bill.unit_id,
		bill.bill_date_time::date,
		bill.billing_master_id,
		bill.bill_number,
		pat.patient_id,
		tprm.amount,
		tprm.payment_reciept_id )
	insert
		into
		public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)
	select
		outstand.billno,
		'Receipts',
		'Patient Credit ',
		outstand.billDate,
		cast((outstand.outstanding) as numeric(10, 2)),
		0,
		outstand.unitId,
		outstand.orgId,
		'OP',
		(select narration from public.getnurrationname(outstand.billid)),'Y',outstand.billid
	from
		outstand
	where
		(outstand.outstanding) > 0;

------- Insert outstanding end---------------

-------------------- Discount --------------------------
	with gen as (
	select
