--
-- TOC entry 3922 (class 1255 OID 2969361)
-- Name: postbillrefund(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postbillrefund(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare nextvoucherno integer = nextval('public.tally_voucher_no_seq');
begin
create or replace temporary view
billrefundsledger as 
select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, 
refd.date_of_refund::date as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid 
from  billing.m_credit_note_master crd
inner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_id
inner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_id
inner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_id
inner join service.m_service_master srv on srv.service_master_id = bdt.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_id
inner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_id
inner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id 
inner join public.t_company_master cmp on cmp.company_id = bdt.payee_id
where crd.cr_deu_amount = 0 and billmst.visit_type_id != 1
group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund::date, crd.cr_net_amount;

-------------- Insert credit notes into tally interface start-----------------------------	
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Payment', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'IP'
from billrefundsledger crd 
where crd.refunddate = dateoftrans
group by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;
-------------- Insert credit notes into tally interface end-----------------------------

--- create view for payee wise details
create or replace temporary view
payeewisedtls as 
select bdt.payee_id as payeeid, bdt.net_amt as amount, cmp.company_desc as companyname, 
bdt.organization_id as orgid, bdt.unit_id as unitid, bdt.created_date::date as date,
bdt.self_payable as selfpay, bdt.credit_payable as creditpay
from billing.t_billing_details bdt
inner join billing.m_billing_master bm on bm.billing_master_id = bdt.billing_master_id
inner join billing.m_credit_note_master crd on crd.bill_id = bm.billing_master_id
inner join public.t_company_master cmp on cmp.company_id = bdt.payee_id
inner join billing.t_credit_note_detail cnd on cnd.billing_details_id = bdt.billing_details_id
where bm.visit_type_id != 1 and crd.cr_deu_amount = 0;
--- xxx

--- insert payee wise details for self
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Payment', 'IPB', pwd.date, 0, sum(pwd.selfpay), pwd.unitid, pwd.orgid, 'IP'
from payeewisedtls pwd 
where pwd.date = dateoftrans and pwd.payeeid = 1
group by pwd.date, pwd.unitid, pwd.orgid;
--- xxx

--- insert payee wise details for company
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Payment', pwd.companyname, pwd.date, 0, sum(pwd.creditpay), pwd.unitid, pwd.orgid, 'IP'
from payeewisedtls pwd 
where pwd.date = dateoftrans and pwd.payeeid != 1 
group by pwd.companyname, pwd.unitid, pwd.orgid, pwd.date;
--- xxx

---- data for debit 

--- insert payee wise details for self for debit section
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select nextvoucherno, 'Receipt', 'IPB', pwd.date, sum(pwd.selfpay), 0, pwd.unitid, pwd.orgid, 'IP'
from payeewisedtls pwd 
where pwd.date = dateoftrans and pwd.payeeid = 1
group by pwd.date, pwd.unitid, pwd.orgid;
--- xxx

--- insert payee wise details for company for debit section
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select nextvoucherno, 'Receipt', pwd.companyname, pwd.date, sum(pwd.creditpay), 0, pwd.unitid, pwd.orgid, 'IP'
from payeewisedtls pwd 
where pwd.date = dateoftrans and pwd.payeeid != 1
group by pwd.companyname,  pwd.unitid, pwd.orgid, pwd.date;
--- xxx

--- create view for refunds at credit side
create or replace temporary view
payeewiserefunds as 
select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,
prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,
prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,
bank.bank_name as bankname
from billing.t_payment_refund_master prm
inner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_id
inner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id 
inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_id
inner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_id
left join billing.m_bank_master bank on bank.bank_id = prd.bank_id
where billmst.visit_type_id != 1 and cnm.cr_deu_amount = 0;
--- xxx

--- insert cash mode transactions for refunds
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select nextvoucherno, 'Receipt', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'
from payeewiserefunds rfd
where rfd.refunfdate = dateoftrans and rfd.modeid = 1
group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;
-------------------------xxx------------------------------------------------

----------------------- insert other mode transactions for refunds ----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select nextvoucherno, 'Receipt', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,
rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)
from payeewiserefunds rfd
where rfd.refunfdate = dateoftrans and rfd.modeid != 1
group by  rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,
rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;
-------------------------xxx---------------------------------

return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


