--
-- TOC entry 4021 (class 1255 OID 2969364)
-- Name: postdocsharedata(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postdocsharedata(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin 
 ----------- Create view ---------------------------
 
 ------------ Group wise doctor share posting start -------------------------
with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join service.m_service_master sm on sm.service_master_id = ds.service_id
inner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_id
where  log.created_date:: date = dateoftrans 
group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id)
select voucherno, 'General Vouchers', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid from gen;
 ------------  Group wise doctor share posting  end -------------------------

------- Doctor share start ---------------
with docshare as (select  concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans 
group by  ledger, log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'General Vouchers', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'Doctor Share' from docshare;
------- Doctor share end ---------------


------- Retainship amount start ---------------
with docretainship as (select  sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,
log.org_id as orgid, log.org_unit_id as unitid
from billing.t_doc_share_voucher dsv
inner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_id
inner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_id
inner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_no
inner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_id
where  dsv.created_date:: date = dateoftrans 
group by   log.created_date:: date, log.org_id, log.org_unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'General Vouchers', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'Doctor Share' from docretainship;
------- Retainship amount end ---------------


 

return true;
EXCEPTION 
 when OTHERS then 
 return false;
COMMIT;
end;
$$;


--
-- TOC entry 4022 (class 1255 OID 2969365)
-- Name: postipbcompcollectiondata(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postipbcompcollectiondata(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin 

create or replace temporary view 
ipbillcomp as 
select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode,  pReceiptDtls.amount  as rcptamount, 
bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, 
pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, 
pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
crm.organisation_id as orgid, crm.unit_id as unitid,
pReceiptDtls.date_of_transaction :: date as transdate, crm.company_receipt_date :: date as recieptdate,
pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, 
crm.other_deduction as otherdeduction
from billing.t_payment_reciept_details pReceiptDtls
inner join public.m_payment_mode_master  pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_id
inner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id 
inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_id
inner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_id
inner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_receipt_detail_id
inner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_id
left join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id
where bill.visit_type_id != 1 and pReceiptMst.payee_id != 1;

------- Insert cash start ---------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', ipbillself.mode,  ipbillself.transdate,   sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId , 'IP'
from ipbillself
where  ipbillself.transdate = ipbillself.billdate and ipbillself.modeid = 1 and ipbillself.transdate = dateoftrans--cash
group by ipbillself.modeid, ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Receipt', 
ipbillself.mode,  ipbillself.transdate,   ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,
coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, 
coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)
from ipbillself
where  ipbillself.transdate= ipbillself.billdate and ipbillself.modeid <> 1 and ipbillself.transdate = dateoftrans;

------------------- tds ------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'TDS', ipbc.recieptdate, sum(ipbc.tds) , 0,  ipbc.unitid , ipbc.orgid, 'IP'
from ipbillcomp ipbc 
where ipbc.recieptdate::date = dateoftrans
group by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;
--------------------------------------------

------------------- disallowed amount ------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'Disallowed amount', ipbc.recieptdate, sum(ipbc.disallowedamount) , 0,  ipbc.unitid , ipbc.orgid, 'IP'
from ipbillcomp ipbc 
where ipbc.recieptdate::date = dateoftrans
group by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;
--------------------------------------------

------------------- other deductions ------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'Other deductions', ipbc.recieptdate, sum(ipbc.otherdeduction) , 0,  ipbc.unitid , ipbc.orgid, 'IP'
from ipbillcomp ipbc 
where ipbc.recieptdate::date = dateoftrans
group by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;
--------------------------------------------

-------------- insert company wise details ---------------------------
with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date::date as dateoftrans,  sum(crd.net_receipt_amount) as amount,
crd.organisation_id as orgId, crd.unit_id as unitId
from billing.t_company_receipt_detail crd
inner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_id
left join billing.m_billing_master bm on bm.billing_master_id = cid.bill_id
inner join public.t_company_master cm on cm.company_id = cid.bill_payee_id
where crd.created_date::date = dateoftrans  and bm.visit_type_id !=1
group by crd.created_date::date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cr.amount, cr.unitId, cr.orgId, 'IP' 
from company_receipt cr;
---------------------------------------

return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


--
-- TOC entry 3923 (class 1255 OID 2969366)
-- Name: postipbselfcollectiondata(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postipbselfcollectiondata(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin 

create or replace temporary view 
  ipbillself
AS
	(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode,  pReceiptDtls.amount  as rcptamount, 
	billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, 
	pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, 
	pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, 
	pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
	billMst.organisation_id as orgid, billMst.unit_id as unitid,
	pReceiptDtls.date_of_transaction :: date as transdate, billMst.bill_date_time :: date as billdate,
	pReceiptDtls.trans_transaction_date as transferdate
	from billing.t_payment_reciept_details pReceiptDtls
	inner join public.m_payment_mode_master  pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_id
	inner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id 
	inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_id
	left join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id 
	inner join opd.t_patient_sponsor_details spd on spd.admission_id=billMst.admission_id
	where  billMst.visit_type_id = 2 and spd.payment_entitlement_id = 1 );

------- Insert cash start ---------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', ipbillself.mode,  ipbillself.transdate,   sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId, 'IP' 
from ipbillself
where  ipbillself.transdate = ipbillself.billdate and ipbillself.transdate = dateoftrans--cash
group by ipbillself.modeid, ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
/*insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Receipt', 
ipbillself.mode,  ipbillself.transdate,   ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,
coalesce(ipbillself.chequedate,ipbillself.transferdate),  'IP', ipbillself.bankname, 
coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)
from ipbillself
where  ipbillself.transdate= ipbillself.billdate and ipbillself.modeid <> 1 and ipbillself.transdate = dateoftrans;*/



------------------------------Package consumption ---------------------------------
with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , 
bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date::date as createdDate
from billing.t_billing_details dtls 
inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = dtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where dtls.created_date::date = dateoftrans and self_payable = 0 and credit_payable = 0 and bill.visit_type_id = 2
group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date::date, bill.organisation_id, bill.unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'IP' from pack;
--------------------------------------------------
-------------------- Insert deposit consumption --------------------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'Patient Advance', pdc.created_date::date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id, 'IP'
from billing.t_payment_deposite_consumption_details pdc
inner join billing.t_payment_deposite_consumption pd
on pd.dep_consumption_id = pdc.dep_consumption_id
inner join billing.m_billing_master bill
on bill.billing_master_id = pd.bill_id
where pdc.created_date::date = dateoftrans and bill.visit_type_id = 2
group by pdc.dep_consumption_id, pdc.organization_id, pdc.unit_id,pdc.created_date::date;

-------------------- Discount --------------------------
with gen as (select   sum(billDtls.discount) as amount,
billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 2
group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id 
having  sum(billDtls.discount) > 0)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId, 'IP' from gen;



--------------------------- IPBR CREDIT POSTING START -------------------------------------
-- CALCULATED SUM OF CASH RECEIVED, DEPOSITE CONSUMED, DISCOUNNT GIVEN, PACKAGE CONSUMPTION --------------
create or replace temporary view 
  IPBREVERSE
as
	(select sum(ipbillself.rcptamount) as amount, ipbillself.unitId, ipbillself.orgId , ipbillself.transdate as transdate
	from ipbillself
	where  ipbillself.transdate= ipbillself.billdate 
	group by ipbillself.unitId, ipbillself.orgId, ipbillself.transdate)
union
	(select sum(pdc.consumed_amount) as amount, pdc.unit_id, pdc.organization_id, pdc.created_date::date as transdate
	from billing.t_payment_deposite_consumption_details pdc
	inner join billing.t_payment_deposite_consumption pd on pd.dep_consumption_id = pdc.dep_consumption_id
	inner join billing.m_billing_master bill on bill.billing_master_id = pd.bill_id
	where  bill.visit_type_id = 2
	group by pdc.dep_consumption_id, pdc.organization_id, pdc.unit_id,pdc.created_date::date)
union
	(select   sum(billDtls.discount) as amount, billMst.unit_id as unitId, billMst.organisation_id as orgId, billDtls.created_date::date as transdate
	from billing.t_billing_details billDtls
	inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
	inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
	where billMst.visit_type_id = 2
	group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)
union
	(select sum(dtls.gross_amount) as amount , bill.unit_id as unitId, bill.organisation_id as orgId, dtls.created_date::date as transdate
	from billing.t_billing_details dtls 
	inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_id
	where  self_payable = 0 and credit_payable = 0 and bill.visit_type_id = 2
	group by  bill.organisation_id, bill.unit_id, dtls.created_date::date);

insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Receipt', 'IPB', ipbr.transdate, 0, sum(ipbr.amount), ipbr.unitId, ipbr.orgId , 'IP'
from IPBREVERSE ipbr 
where ipbr.transdate = dateoftrans
group by unitid, orgid, ipbr.transdate;

--------------------------- IPBR CREDIT POSTING END -------------------------------------

return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


