	from compipserv cip
	where cip.billdate = dateoftrans
	group by  cip.billdate, cip.unitid, cip.orgid, cip.company ;
 ----------- xxx -------------------------
 
	------ inser ip bill service wise ledger data -------
	insert into public.t_tally_interface
