	select salesvoucherno, 'Sales', cip.generalledger,  cip.billdate,   0, sum(cip.amount) , cip.unitid, cip.orgid , 'IP'
	from compipserv cip
	where cip.billdate = dateoftrans 
	group by  cip.billdate, cip.unitid, cip.orgid, cip.generalledger ;
	--------------xxx-----------------------------
	
return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


