--
-- TOC entry 3924 (class 1255 OID 2969370)
-- Name: postopfadata(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postopfadata(dateoftrans timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare nextVoucherno integer = nextval('public.tally_voucher_no_seq');
begin 
	----------- Create view ---------------------------
create or replace temporary view 
  opbill
AS
	(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode,  pReceiptDtls.amount  as rcptamount, 
	billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, 
	pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, 
	pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, 
	pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,
	billMst.organisation_id as orgid, billMst.unit_id as unitid,
	pReceiptDtls.date_of_transaction :: date as transdate, billMst.bill_date_time :: date as billdate,
	pReceiptDtls.trans_transaction_date as transferdate
	from billing.t_payment_reciept_details pReceiptDtls
	inner join public.m_payment_mode_master  pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_id
	inner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id 
	inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_id
	left join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id
	where  billMst.visit_type_id = 1);

------- Insert cash start ---------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales', opbill.mode,  opbill.transdate,   sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId , 'OP'
from opbill
where  opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate = dateoftrans--cash
group by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;
------- Insert cash end ---------------

------- Insert others start where transaction-date = bill-date---------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select voucherno, 'Sales', 
opbill.mode,  opbill.transdate,   opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,
coalesce(opbill.chequedate,opbill.transferdate),  'OP', opbill.bankname, 
coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)
from opbill
where  opbill.transdate= opbill.billdate and opbill.modeid <> 1 and opbill.transdate = dateoftrans;
------- Insert others start---------------

---------------------- Company amount --------------------------------
with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger,  sum(billDtls.credit_payable) as amount,
billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join public.t_company_master comp on comp.company_id = billDtls.payee_id 
where billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 1 and billDtls.payee_id <> 1
group by  billDtls.payee_id,comp.company_desc, billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, comp.orgId,'OP' from comp;

------------------------------Package consumption ---------------------------------
with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , 
bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date::date as createdDate
from billing.t_billing_details dtls 
inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = dtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_id
where dtls.created_date::date = dateoftrans and  bill.visit_type_id = 1 and ordt.is_package_service = 'Y'
group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date::date, bill.organisation_id, bill.unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'OP' from pack;
--------------------------------------------------
-------------------- Insert deposit consumption --------------------------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales', 'Patient Advance', pdc.created_date::date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP'
from billing.t_payment_deposite_consumption_details pdc
inner join billing.t_payment_deposite_consumption pd
on pd.dep_consumption_id = pdc.dep_consumption_id
inner join billing.m_billing_master bill
on bill.billing_master_id = pd.bill_id
where pdc.created_date::date = dateoftrans and bill.visit_type_id = 1
group by  pdc.organization_id, pdc.unit_id,pdc.created_date::date;

-------------------xxx-------------------------------------
------- Insert outstanding start---------------
with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, 
bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time::date as billDate
from billing.m_billing_master bill
where bill.bill_date_time::date = dateoftrans and bill.visit_type_id = 1
group by bill.organisation_id, bill.unit_id, bill.bill_date_time::date),
cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitId
from billing.t_billing_details billdt 
inner join  billing.m_billing_master bill
on bill.billing_master_id = billdt.billing_master_id
where bill.bill_date_time::date = dateoftrans and bill.visit_type_id = 1
group by billdt.organization_id, billdt.unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales','Patient Credit', outst.billDate, outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP' 
from outst , cred
where (outst.outstanding - cred.creditpayable) > 0;

------- Insert outstanding end---------------

-------------------- Discount --------------------------
with gen as (select   sum(billDtls.discount) as amount,
billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date::date = dateOfTrans and billMst.visit_type_id = 1
group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id 
having  sum(billDtls.discount) > 0)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId,'OP' from gen;
------------------------------------------------
------------ Ledger start -------------------------
with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger,  sum(billDtls.gross_amount) as amount,
billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
where billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 1
group by genLedMSt.general_ledger_id, billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)
select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId,'OP' from gen;
	------------ Ledger end -------------------------
	
-------------------- Tax ---------------------------
with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,
billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitId
from billing.t_billing_details billDtls
inner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_id
inner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_id
inner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_id
inner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_id
inner join public.m_tax tax on tax.id = billDtls.tax_id
where billDtls.created_date::date = dateOfTrans and billMst.visit_type_id = 1
group by billDtls.tax_id, tax."name", billDtls.created_date::date, billMst.organisation_id, billMst.unit_id
having sum(billDtls.tax_amount) > 0)
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId, 'OP' from gen;
--------------------------------------------------
	
----------------------Previous date settlement start cash-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
select nextVoucherno, 'Sales', opbill.mode,  opbill.transdate,   sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId, 'OP' 
from opbill
where  opbill.transdate != opbill.billdate and opbill.modeid = 1 and opbill.transdate = dateoftrans--cash
group by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;
----------------------------
----------------------Previous date settlement start others-----------------------
insert into public.t_tally_interface
(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,
instrument_date,tran_type,bank_name,instrument_number)
select nextVoucherno, 'Sales', 
opbill.mode,  opbill.transdate,   opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,
coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, 
coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)
from opbill
where  opbill.transdate != opbill.billdate and opbill.modeid <> 1 and opbill.transdate = dateoftrans;
--------------------------------
------------------------------Credit insert start--------------------------
insert into public.t_tally_interface
	(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)
 	select nextVoucherno, 'Sales', 'Patient Credit',  opbill.transdate, 0, sum(opbill.rcptamount), opbill.unitid, opbill.orgid, 'OP'
	from opbill 
	where opbill.transdate = dateoftrans and opbill.transdate != opbill.billdate
	group by opbill.transdate, opbill.unitid, opbill.orgid; 

return true;
EXCEPTION 
 when OTHERS then 
	return false;
COMMIT;
end;
$$;


--
-- TOC entry 4025 (class 1255 OID 2969372)
-- Name: reset_balance_amount_proc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_balance_amount_proc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	IF NEW.balance_amount > NEW.authorized_amount  then
      update billing.m_preauth_master set balance_amount = authorized_amount where preauth_id=NEW.preauth_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- TOC entry 3929 (class 1255 OID 4343339)
-- Name: servicemasterproc(character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.servicemasterproc(orgname character varying, unitname character varying, deptname character varying, subdeptname character varying, ledgername character varying, servicecode character varying, servicename character varying, servicebaseprice numeric, validfrom character varying, validtill character varying, INOUT msg character varying)
    LANGUAGE plpgsql
    AS $$
declare
   orgId integer:=null;unitId integer:=null;deptId integer:=null;subDeptId integer:=null;ledgerId integer:=null;serviceId integer:=null;
  validFrm timestamp:=null;validTo timestamp:=null;isExist BOOLEAN;
begin
	--if valid from and validTill param is varchar then conversion will be 
	 validFrm=TO_TIMESTAMP(concat(validFrom,' 00:00:00'), 'YYYY-MM-DD');
	 validTo=TO_TIMESTAMP(concat(validTill,' 00:00:00'), 'YYYY-MM-DD');

	 isExist :=checkServiceExistCall1(serviceName);
	--dbms_output.put_line(isExist);
    msg:=concat('service already exist','',serviceName,cast(isExist as varchar));
    return;
	if isExist=TRUE then
	 msg:='service already exist';
	return;
    end if;
   
	 with getOrgId as (select organization_id from m_organization_master mom where lower(mom.organization_name) = lower(orgName) )
	 select organization_id into orgId from getOrgId;
   
	 if orgId is null then
	 msg:='org not exist';
	 return;
	 end if;
	
	 with getUnitIdByName as (select unit_id from public.m_unit_master um where lower(um.unit_name) = lower(unitName) and um.organization_id=orgId )
	 select unit_id into unitId from getUnitIdByName;
	
     with getDeptIdByName as (select speciality_id from doctor.m_speciality_master sm
     where sm.organization_id=orgId and  lower(sm.speciality_name) = lower(deptName))
     select speciality_id into deptId from getDeptIdByName;
   
     with getSubDeptIdByName as (select sub_speciality_id from doctor.m_sub_speciality_master subsm
     where subsm.organization_id=orgId and lower(subsm.sub_speciality_name) = lower(subDeptName))
     select sub_speciality_id into subDeptId from getSubDeptIdByName;
    
    
     with getLedgerIdByName as (select general_ledger_id from public.m_general_ledger_master glm
     where glm.organisation_id =orgId and lower(glm.general_ledger_name) = lower(ledgerName))
     select general_ledger_id into ledgerId from getLedgerIdByName;
    
   ----- service master save  
   with servicesave as (insert into service.m_service_master (organization_id,service_standard_code,service_standard_name,is_available_for_package,is_outsource_service,
   is_ot_procedure,is_order_set,is_rate_editable,min_rate_editable,max_rate_editable,is_discount_applicable,is_allow_multiple_quantity,
   is_doctor_required,is_tax_applicable,is_autorendered,created_by,created_date,status,updated_by,updated_date,speciality_id,sub_speciality_id,
   is_required_schedule,is_on_bed,valid_from,valid_till,general_ledger_id)
   values(orgId,serviceCode,serviceName,'I','I','I','I','I',0,0,'I','I','I','I','I',1,now(),'A',1,now(),deptId,subDeptId,'N','N',now(),now(),ledgerId) returning service_master_id)

   select service_master_id into serviceId from servicesave;

    ---- service unit mapping 
    insert into service.t_unit_service_mapper(service_id,unit_id,orgnisation_id,status,created_by,created_date,updated_by,updated_date) 
    values(serviceId,unitId,orgId,'A',1,now(),1,now());
   
   ------------unit service master detail
   insert into service.t_unit_service_master_details(service_master_id ,is_outsource,is_package ,is_rate_editable,rate_editble_min_value ,rate_editable_max_value,
	is_tax_applicable ,is_ref_doctor_share,is_discount,unit_id,organization_id ,status ,created_by ,created_date ,updated_by ,updated_date ,
	discount_value ,is_panel,is_allow_multiple_quantity ,is_procedure,is_doc_req ,is_bed_side ,is_poc ,is_periodicity ,is_auto_render ,is_appointable,gender,
	review_time) values(serviceId,'N','I','N',0,0,'N','N','N',unitId,orgId,
	'A',1,now(),1,now(),0,'N','N','N','N','N','N','N','N','N',0,0);
    
   -------service base price
   insert into service.m_service_base_price_master (service_master_id,visit_type_id,base_price,from_date,to_date ,
   status,unit_id,organisation_id,created_by,created_date,updated_by,updated_date)values(serviceId,1,
   serviceBasePrice,validFrm,validTo,'A',unitId,orgId,1,now(),1,now());
  -- 500,now(),now(),'A',unitId,orgId,1,now(),1,now());

    msg:=concat('Inserted Successfully');
end ;
$$;


--
-- TOC entry 4026 (class 1255 OID 2969373)
-- Name: t_generate_prefix_number(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.t_generate_prefix_number(p_store_id integer, p_unit_id integer, p_screen_id integer) RETURNS TABLE(new_running_number character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE p_running_number INTEGER;
		p_current_running_number INTEGER;
		p_reset_id INTEGER;
		p_length INTEGER;
		p_format_id INTEGER;
		p_generated_code VARCHAR;
		p_new_running_number VARCHAR;
		p_prefix_running_id INTEGER;
		p_prefix_id INTEGER;
		p_store_code VARCHAR;
		p_unit_code VARCHAR;
        p_organization_id INTEGER;
BEGIN

SELECT id, prn.running_number, prn.reset_id, prn.length, prn.format_id, prn.generated_code, prn.organization_id
		INTO  p_prefix_id, p_running_number, p_reset_id, p_length, p_format_id, p_generated_code, p_organization_id
FROM  public.m_prefix_configuration AS prn 
WHERE  prn.screen_id = p_screen_id AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id 
LIMIT 1;

IF p_prefix_id IS NOT NULL AND p_prefix_id>0 then

	SELECT id, current_running 
		INTO  p_prefix_running_id, p_current_running_number
    FROM  public.t_prefix_running_number AS prn 
    WHERE (prn.store_id=p_store_id or p_store_id = 0 ) AND prn.screen_id = p_screen_id 
    	AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id 	
    LIMIT 1;
    	
    IF p_prefix_running_id IS NOT NULL AND p_prefix_running_id>0   THEN
    	IF p_current_running_number IS NOT NULL AND  p_current_running_number>0 THEN
    		p_running_number := p_current_running_number + 1 ;
        END IF;
        
        UPDATE  public.t_prefix_running_number
        SET current_running=p_running_number
        WHERE id=p_prefix_running_id;
        
    ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id<1) AND p_running_number>0 THEN 
    	
    	if (p_store_id > 0) then 
    	
			      	INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, 
			                                                   is_active, updated_by, updated_date, added_by, added_date, is_deleted)
					VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
		else
		
			      	INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, 
                                                   is_active, updated_by, updated_date, added_by, added_date, is_deleted)
					VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
		END IF;
        
    ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id<1) THEN
   
    		p_running_number := 1;

		if (p_store_id > 0)  then

			     	INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, 
			                                                    is_active, updated_by, updated_date, added_by, added_date, is_deleted)
			 		VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
		else

					INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, 
                                                    is_active, updated_by, updated_date, added_by, added_date, is_deleted)
					VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
		END IF;
        
    END IF;

   
   SELECT 
m_store.store_code INTO p_store_code
	FROM public.m_store
    WHERE (m_store.store_id = p_store_id or p_store_id = 0 )
     AND m_store.unit_id=p_unit_id;
   
    if p_store_code IS NULL THEN
		select 'AB' INTO p_store_code;
end if;
    
     SELECT m_unit_master.unit_code  INTO p_unit_code
	FROM public.m_unit_master
    WHERE m_unit_master.unit_id=p_unit_id;
    
    SELECT REPLACE (
           REPLACE (
                 REPLACE (
                  REPLACE (
                   REPLACE (
                        REPLACE (
                            REPLACE (
                                REPLACE (
                                     REPLACE (
                                        REPLACE (
                                            REPLACE (
                                                REPLACE (
                                                    REPLACE (
                                                        REPLACE (p_generated_code, '[YY]', to_char(CURRENT_TIMESTAMP, 'YY')), 
                                                        '[YYYY]', to_char(CURRENT_TIMESTAMP, 'YYYY')), 
                                                    '[MM]', to_char(CURRENT_TIMESTAMP, 'MM')),
                                                '[MMM]', to_char(CURRENT_TIMESTAMP, 'FMMON')),
                                            '[MMMM]', to_char(CURRENT_TIMESTAMP, 'FMMONTH')),
                                        '[DD]', to_char(CURRENT_TIMESTAMP, 'DD')),
                                    '[/]', '/'),
                                '[-]', '-'),
                            '[SF]', p_running_number::VARCHAR),
                        '[UC]', p_unit_code),
                    '[SC]', p_store_code),
             '|', ''),
    	'}', ''), 
    	'{', '')
        INTO p_new_running_number;
     
ELSE 

	IF  p_screen_id = 1 THEN
    	p_new_running_number := 'WLS-001';
     ELSIF p_screen_id = 16 THEN
    	p_new_running_number := 'SR-001';
       ELSIF p_screen_id = 30 THEN
    	 p_new_running_number := 'PI-001';
        ELSIF p_screen_id = 32 THEN
    	  p_new_running_number := 'REJ-001';
         ELSIF p_screen_id = 33 THEN
    	   p_new_running_number := 'REJ-001';
           ELSIF p_screen_id = 27 THEN
    	    p_new_running_number := 'PATIND-001';
			 ELSIF p_screen_id = 28 THEN
    	      p_new_running_number := 'BC-001';
			   ELSIF p_screen_id = 64 THEN
    	        p_new_running_number := 'RBC-001';
				  ELSIF p_screen_id = 68 THEN
    	           p_new_running_number := 'CCR-001';
				    ELSIF p_screen_id = 17 THEN
    	             p_new_running_number := 'IR-001';
					  ELSIF p_screen_id = 4 THEN
    	               p_new_running_number := 'PR-001';
						ELSIF p_screen_id = 5 THEN
    	                 p_new_running_number := 'LPR-001';
						  ELSIF p_screen_id = 10 THEN
    	                   p_new_running_number := 'POC-001';
							ELSIF p_screen_id = 12 THEN
    	                     p_new_running_number := 'GRN-001';
							  ELSIF p_screen_id = 37 THEN
    	                       p_new_running_number := 'QE-001';
							    ELSIF p_screen_id = 38 THEN
    	                         p_new_running_number := 'ESTV-001';
								   ELSIF p_screen_id = 92 THEN
    	                             p_new_running_number := 'WOR-001';
									  ELSIF p_screen_id = 97 THEN
    	                               p_new_running_number := 'WOQR-001';
										ELSIF p_screen_id = 98 THEN
    	                                 p_new_running_number := 'WOQSV-001';
										  ELSIF p_screen_id = 92 THEN
    	                                   p_new_running_number := 'WOC-001';
											ELSIF p_screen_id = 73 THEN
    	                                     p_new_running_number := 'LI-001';
											  ELSIF p_screen_id = 74 THEN
    	                                       p_new_running_number := 'LIO-001';
												ELSIF p_screen_id = 75 THEN
    	                                         p_new_running_number := 'LO-001';
												  ELSIF p_screen_id = 79 THEN
    	                                           p_new_running_number := 'LOR-001';
                                                    ELSIF p_screen_id = 54 THEN
    	                                              p_new_running_number := 'PIR-001';
  													   ELSIF p_screen_id = 120 THEN
    	                                                p_new_running_number := 'ConInw-001';
 														 ELSIF p_screen_id = 122 THEN
    	                                                  p_new_running_number := 'ImpInd-001';
                                                           ELSIF p_screen_id = 129 THEN
    	                                                   p_new_running_number := 'ImpRet-001';
    	                                                   ELSIF p_screen_id = 132 THEN
    	                                                   p_new_running_number := 'PR-001';
                                                           ELSIF p_screen_id = 66 THEN
    	                                                   p_new_running_number := 'INW-001';
                                                           ELSIF p_screen_id = 77 THEN
    	                                                   p_new_running_number := 'DR-001';
														ELSIF p_screen_id = 137 THEN
    	                                                   p_new_running_number := 'OPB-001';
    	                                                
    END IF;

END IF;
 RETURN QUERY SELECT p_new_running_number AS new_running_number;
 
END;
$$;


