         ELSIF p_screen_id = 33 THEN
    	   p_new_running_number := 'REJ-001';
           ELSIF p_screen_id = 27 THEN
    	    p_new_running_number := 'PATIND-001';
			 ELSIF p_screen_id = 28 THEN
    	      p_new_running_number := 'BC-001';
			   ELSIF p_screen_id = 64 THEN
    	        p_new_running_number := 'RBC-001';
				  ELSIF p_screen_id = 68 THEN
    	           p_new_running_number := 'CCR-001';
				    ELSIF p_screen_id = 17 THEN
    	             p_new_running_number := 'IR-001';
					  ELSIF p_screen_id = 4 THEN
    	               p_new_running_number := 'PR-001';
						ELSIF p_screen_id = 5 THEN
    	                 p_new_running_number := 'LPR-001';
						  ELSIF p_screen_id = 10 THEN
    	                   p_new_running_number := 'POC-001';
							ELSIF p_screen_id = 12 THEN
    	                     p_new_running_number := 'GRN-001';
							  ELSIF p_screen_id = 37 THEN
    	                       p_new_running_number := 'QE-001';
							    ELSIF p_screen_id = 38 THEN
    	                         p_new_running_number := 'ESTV-001';
								   ELSIF p_screen_id = 92 THEN
    	                             p_new_running_number := 'WOR-001';
									  ELSIF p_screen_id = 97 THEN
    	                               p_new_running_number := 'WOQR-001';
										ELSIF p_screen_id = 98 THEN
    	                                 p_new_running_number := 'WOQSV-001';
										  ELSIF p_screen_id = 92 THEN
    	                                   p_new_running_number := 'WOC-001';
											ELSIF p_screen_id = 73 THEN
    	                                     p_new_running_number := 'LI-001';
											  ELSIF p_screen_id = 74 THEN
    	                                       p_new_running_number := 'LIO-001';
												ELSIF p_screen_id = 75 THEN
    	                                         p_new_running_number := 'LO-001';
												  ELSIF p_screen_id = 79 THEN
    	                                           p_new_running_number := 'LOR-001';
                                                    ELSIF p_screen_id = 54 THEN
    	                                              p_new_running_number := 'PIR-001';
  													   ELSIF p_screen_id = 120 THEN
    	                                                p_new_running_number := 'ConInw-001';
 														 ELSIF p_screen_id = 122 THEN
    	                                                  p_new_running_number := 'ImpInd-001';
                                                           ELSIF p_screen_id = 129 THEN
    	                                                   p_new_running_number := 'ImpRet-001';
    	                                                   ELSIF p_screen_id = 132 THEN
    	                                                   p_new_running_number := 'PR-001';
                                                           ELSIF p_screen_id = 66 THEN
    	                                                   p_new_running_number := 'INW-001';
                                                           ELSIF p_screen_id = 77 THEN
    	                                                   p_new_running_number := 'DR-001';
														ELSIF p_screen_id = 137 THEN
    	                                                   p_new_running_number := 'OPB-001';
    	                                                
    END IF;

END IF;
 RETURN QUERY SELECT p_new_running_number AS new_running_number;
 
END;
$$;


