--
-- TOC entry 4027 (class 1255 OID 2969378)
-- Name: trigger_autoindnet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_autoindnet() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
currentQty int;
minQty int;
maxQty int;
indentId int;
itemId int;
uomType int;
uomUnit int;
indentNumber character varying;
assetType int;
isConsignment boolean;
-- added by minesh for consignmentBatch (if consignment batch then do not to gen auto indent).
batchNo character varying;
lotNo character varying;
consignmentBatchCount int;
inventorystoreid int;
BEGIN
currentQty = 0;
minQty = 0;
consignmentBatchCount = 0;
inventorystoreid=0;
select available_qty into currentQty from inventory.t_store_stock where store_id = old.store_id and batch_id = old.batch_id;
/* select item_id into itemId from inventory.t_batch where id = old.batch_id; */
-- origin commented above and added this by minesh
select item_id, batch_no, lot_no into itemId, batchNo,lotNo   from inventory.t_batch where id = old.batch_id;
select count(*) into consignmentBatchCount from inventory.t_batch as batch where batch.batch_no = batchNo and batch.lot_no = lot_no and is_consignment = true;
select sim.min_qty, sim.max_qty into minQty, maxQty from public.m_store_item_mapper as sim where sim.store_id = old.store_id and sim.item_id = itemId;
select uom_type_id, uom_unit_id into uomType, uomUnit from public.m_unit_of_measurement where item_id = itemId and store_uom = true;
select inventory_store_id into inventorystoreid from  public.m_application_configuration  where organization_id=old.organization_id and unit_id=old.unit_id;
select is_consignment into isConsignment from public.m_item where id = itemId;
select assetCategory.asset_type_id into assetType from public.m_item item
inner join public.m_generic generic on generic.id = item.generic_id
inner join public.m_product_category productCategory on productCategory.id = generic.product_category_id
inner join public.m_asset_category assetCategory on assetCategory.id = productCategory.asset_category_id
where item.id = itemId;
/* if currentQty <= minQty and assetType = 1  then */
-- origin commented above and added this by minesh
if currentQty <= minQty and assetType = 1 and consignmentBatchCount = 0 then
	select * into indentNumber from public.t_generate_prefix_number(old.store_id, old.unit_id, 2);
	/* insert into inventory.t_store_indent (priority_id,  unit_id, organization_id, indent_no, from_store_id, indent_type_id, status_id, approval_status_id, added_by, updated_by, is_consignment)
	values (1, old.unit_id, old.organization_id, indentNumber, old.store_id, 2, 1, 1, 1, 1, isConsignment) returning id into indentId; */
-- origin commented above and added this by minesh for to_store_id is mandatory field.
	insert into inventory.t_store_indent (priority_id,  unit_id, organization_id, indent_no, from_store_id, to_store_id, indent_type_id, status_id, approval_status_id, added_by, updated_by, is_consignment)
	values (1, old.unit_id, old.organization_id, indentNumber, old.store_id,inventorystoreid, 2, 1, 1, 1, 1, isConsignment) returning id into indentId;
/*select * from inventory.t_store_indent_detail*/
	insert into inventory.t_store_indent_detail(unit_id, organization_id, store_indent_id, item_id, uom_type_id, uom_unit_id, status_id,indent_quantity, pending_quantity, updated_by, added_by)
	values (old.unit_id, old.organization_id, indentId, itemId, uomType, uomUnit, 1,maxQty, maxQty, 1, 1);
END IF;
 RETURN NEW;
END;
$$;


