--
-- TOC entry 503 (class 1259 OID 2969588)
-- Name: patientinformation; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.patientinformation AS
 SELECT t_patient_registration.prefix_id,
    t_patient_registration.uhid_number,
    concat(COALESCE(m_prefix_master.prefix_desc, (''::character varying)::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,
    m_gender_master.gender_name,
    t_patient_registration.bar_code,
    age(t_patient_registration.dob) AS age,
    t_patient_registration.mobile_number,
    t_patient_registration.email,
    t_patient_registration.mobile_number AS patientmobile,
    t_patient_registration.email AS patientemail,
    m_patient_registration_type_master.reg_type,
    m_gender_master.gender_name AS patientgender,
    m_patient_category_master.patient_category,
    t_patient_registration.created_date AS regdate,
    t_patient_registration.is_vip,
    t_patient_registration.dob AS patientdob,
    t_patient_registration.identification_number,
    t_patient_registration.identification_expiry_date,
    t_patient_details.address AS patientaddress,
    t_patient_details.zip_code,
    t_patient_details.phone_number,
    t_patient_registration.patient_id,
    m_marital_status_master.marital_status_name,
    t_patient_registration.image,
    m_gender_master.gender_id
   FROM ((((((patient.t_patient_registration
     LEFT JOIN public.m_prefix_master ON ((t_patient_registration.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN public.m_gender_master ON ((t_patient_registration.gender_id = m_gender_master.gender_id)))
     LEFT JOIN public.m_patient_category_master ON ((t_patient_registration.patient_category_id = m_patient_category_master.patient_category_id)))
     LEFT JOIN patient.m_patient_registration_type_master ON ((t_patient_registration.registration_type_id = m_patient_registration_type_master.id)))
     LEFT JOIN patient.t_patient_details ON ((t_patient_registration.patient_id = t_patient_details.patient_id)))
     LEFT JOIN public.m_marital_status_master ON ((t_patient_details.marital_status_id = m_marital_status_master.marital_status_id)));


