   FROM ((((((billing.t_miscellaneous_expense me
     JOIN billing.t_miscellaneous_expense_reciept er ON ((me.expense_id = er.expense_id)))
     JOIN billing.t_miscellaneous_expense_reciept_details erd ON ((er.expense_reciept_id = erd.expense_reciept_id)))
     LEFT JOIN public.m_payment_mode_master paymode ON ((erd.payment_mode_id = paymode.payment_mode_id)))
     LEFT JOIN public.m_general_ledger_master acc ON ((me.account_head = acc.general_ledger_id)))
