     LEFT JOIN public.m_user_master usermaster ON ((me.created_by = usermaster.user_id)))
  WHERE ((me.is_cancelled = 'N'::bpchar) AND (er.reciept_cancelled = 'N'::bpchar) AND (me.status = 'A'::bpchar));


