    t_patient_registration.identification_expiry_date,
    t_patient_details.address AS patientaddress,
    t_patient_details.zip_code,
    t_patient_details.phone_number,
    t_patient_registration.patient_id,
    m_marital_status_master.marital_status_name,
    m_occupation_master.occupation_name,
    m_unit_master.image,
    m_unit_master.unit_name,
    m_unit_master.unit_address,
    m_gender_master.gender_id,
    (abs(date_part('Year'::text, age((to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS ageyear,
    t_patient_registration.image AS patientimage,
    public.createbarcodecode128((t_patient_registration.patient_id)::character varying) AS barcode,
    (abs(date_part('Month'::text, age((to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS agemonth,
    (abs(date_part('Day'::text, age((to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS ageday,
    m_unit_master.unit_id
   FROM ((((((((patient.t_patient_registration
     LEFT JOIN public.m_prefix_master ON ((t_patient_registration.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN public.m_gender_master ON ((t_patient_registration.gender_id = m_gender_master.gender_id)))
     LEFT JOIN public.m_patient_category_master ON ((t_patient_registration.patient_category_id = m_patient_category_master.patient_category_id)))
     LEFT JOIN patient.m_patient_registration_type_master ON ((t_patient_registration.registration_type_id = m_patient_registration_type_master.id)))
