--
-- TOC entry 2755 (class 1259 OID 2980508)
-- Name: opipdbillsummary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.opipdbillsummary AS
 SELECT bm.billing_master_id,
    ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
    vm.visit_type_code,
    vm.visit_type_id,
    pmm.payment_mode_desc,
    prd.amount,
    0 AS consumed_amount,
    0 AS tdsamt,
    (concat(emp.first_name, ' ', emp.last_name))::character varying(100) AS user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    prd.date_of_transaction AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Income'::text AS amttype,
    rm.reciept_number,
    countermaster.counter_id,
    countermaster.counter_desc
   FROM (((((((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bdet ON ((bm.billing_master_id = bdet.billing_master_id)))
     JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
     JOIN billing.t_payment_reciept_master rm ON ((bm.billing_master_id = rm.billing_master_id)))
     JOIN billing.t_payment_reciept_details prd ON ((rm.payment_reciept_id = prd.payment_receipt_master_id)))
     JOIN public.m_payment_mode_master pmm ON ((prd.payment_mode_id = pmm.payment_mode_id)))
     JOIN public.m_user_master um ON ((rm.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((emp.user_id = um.user_id)))
     JOIN public.m_unit_master umm ON ((rm.unit_id = umm.unit_id)))
     JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((rm.counter_id = countermaster.counter_id)))
     LEFT JOIN ( SELECT prm.billing_master_id,
            sum(prm.amount) AS amount
           FROM (billing.t_payment_reciept_master prm
             JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
          GROUP BY prm.billing_master_id) payment ON ((bm.billing_master_id = payment.billing_master_id)))
  WHERE ((COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar) AND (COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar))
UNION
 SELECT bm.billing_master_id,
    ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
    vm.visit_type_code,
    vm.visit_type_id,
    'selfconsumed'::text AS payment_mode_desc,
    0 AS amount,
    dc.consumed_amount,
    0 AS tdsamt,
    (concat(emp.first_name, ' ', emp.last_name))::character varying(100) AS user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    dc.dep_consumption_date AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Income'::text AS amttype,
    dc.deposite_consumption_number AS reciept_number,
    countermaster.counter_id,
    countermaster.counter_desc
   FROM (((((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bdet ON ((bm.billing_master_id = bdet.billing_master_id)))
     JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
     JOIN billing.t_payment_deposite_consumption dc ON ((bm.billing_master_id = dc.bill_id)))
     LEFT JOIN public.m_user_master um ON ((dc.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((emp.user_id = um.user_id)))
     JOIN public.m_unit_master umm ON ((dc.unit_id = umm.unit_id)))
     JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((dc.counter_id = countermaster.counter_id)))
     LEFT JOIN ( SELECT prm.billing_master_id,
            sum(prm.amount) AS amount
           FROM (billing.t_payment_reciept_master prm
             JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
          GROUP BY prm.billing_master_id) payment ON ((bm.billing_master_id = payment.billing_master_id)))
  WHERE (COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar)
UNION
 SELECT DISTINCT 0 AS billing_master_id,
    ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
    vm.visit_type_code,
    vm.visit_type_id,
    pmm.payment_mode_desc,
    companyrecdetail.net_receipt_amount AS amount,
    0 AS consumed_amount,
    0 AS tdsamt,
    (concat(emp.first_name, ' ', emp.last_name))::character varying(100) AS user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    prd.date_of_transaction AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Income'::text AS amttype,
    rm.reciept_number,
    countermaster.counter_id,
    countermaster.counter_desc
   FROM ((((((((((((((((billing.m_company_receipt_master compnayrecmaster
     JOIN billing.t_company_receipt_detail companyrecdetail ON ((compnayrecmaster.company_receipt_id = companyrecdetail.company_receipt_id)))
     JOIN billing.t_payment_reciept_master rm ON ((rm.payment_reciept_id = compnayrecmaster.receipt_id)))
     JOIN billing.t_payment_reciept_details prd ON ((rm.payment_reciept_id = prd.payment_receipt_master_id)))
     JOIN billing.t_company_invoice_details invoice_details ON ((companyrecdetail.company_invoice_detail_id = invoice_details.company_invoice_detail_id)))
     JOIN billing.m_company_invoice_master invoice_master ON ((invoice_details.company_invoice_id = invoice_master.company_invoice_id)))
     JOIN billing.m_billing_master bm ON ((invoice_details.bill_id = bm.billing_master_id)))
     JOIN public.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     JOIN public.t_company_master company ON ((company.company_id = invoice_details.bill_payee_id)))
     LEFT JOIN billing.m_deposit_master deposit_master ON ((bm.billing_master_id = deposit_master.bill_id)))
     LEFT JOIN public.m_payment_entitlement_master entitlement_master ON ((invoice_master.payment_entitlement_id = entitlement_master.payment_entitlement_id)))
     LEFT JOIN public.m_payment_mode_master pmm ON ((prd.payment_mode_id = pmm.payment_mode_id)))
     LEFT JOIN public.m_user_master um ON ((compnayrecmaster.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((emp.user_id = um.user_id)))
     LEFT JOIN public.m_unit_master umm ON ((compnayrecmaster.unit_id = umm.unit_id)))
     JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((rm.counter_id = countermaster.counter_id)))
  WHERE ((COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar) AND (COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar));


