--
-- TOC entry 2757 (class 1259 OID 2980518)
-- Name: allcollectionsummary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.allcollectionsummary AS
 SELECT opdipdcollectionsummary.deposit_master_id,
    opdipdcollectionsummary.deposit,
    opdipdcollectionsummary.visit_type_code,
    opdipdcollectionsummary.visit_type_id,
    opdipdcollectionsummary.user_name,
    opdipdcollectionsummary.user_id,
    opdipdcollectionsummary.unit_id,
    opdipdcollectionsummary.organization_id,
    opdipdcollectionsummary.unit_name,
    opdipdcollectionsummary.patientname,
    opdipdcollectionsummary.patient_id,
    opdipdcollectionsummary.uhid_number,
    opdipdcollectionsummary.depositdate,
    opdipdcollectionsummary.unit_address,
    opdipdcollectionsummary.unit_contact_2,
    opdipdcollectionsummary.unit_contact,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Cash'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS cash,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Cheque'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS cheque,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Card Payment'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS creditcard,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Debit Card'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS debitcard,
    COALESCE(sum(opdipdcollectionsummary.consumed_amount), (0)::double precision) AS patadvused,
    COALESCE((sum(opdipdcollectionsummary.tdsamt))::double precision, (0)::double precision) AS tdsamt,
    opdipdcollectionsummary.amttype,
    opdipdcollectionsummary.reciptno,
    COALESCE(opdipdcollectionsummary.counter_id, 0) AS counter_id,
    opdipdcollectionsummary.counter_desc,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Mpesa'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS mpesa,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Loyalty Card'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS loyaltycard,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'E-Transfer'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS e_transfer,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Available Fund'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS availablefund,
    COALESCE(sum(
        CASE
            WHEN (opdipdcollectionsummary.payment_mode_desc = 'Doctor Credit'::text) THEN opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS doctorcredit
   FROM public.opdipdcollectionsummary
  GROUP BY opdipdcollectionsummary.deposit_master_id, opdipdcollectionsummary.deposit, opdipdcollectionsummary.visit_type_code, opdipdcollectionsummary.user_name, opdipdcollectionsummary.user_id, opdipdcollectionsummary.unit_id, opdipdcollectionsummary.organization_id, opdipdcollectionsummary.unit_name, opdipdcollectionsummary.patientname, opdipdcollectionsummary.patient_id, opdipdcollectionsummary.uhid_number, opdipdcollectionsummary.depositdate, opdipdcollectionsummary.unit_address, opdipdcollectionsummary.unit_contact_2, opdipdcollectionsummary.unit_contact, opdipdcollectionsummary.amttype, opdipdcollectionsummary.reciptno, opdipdcollectionsummary.visit_type_id, opdipdcollectionsummary.counter_id, opdipdcollectionsummary.counter_desc;


