CREATE VIEW public.get_patientcountdetails AS
 WITH cte AS (
         SELECT (((((pt.first_name)::text || ' '::text) || (pt.middle_name)::text) || ' '::text) || (pt.last_name)::text) AS patientname,
            (pt.created_date)::date AS created_date,
            'OP'::text AS type,
            ptinfo.patientmobile,
            ptinfo.patientaddress,
            ptinfo.gender_name,
            um.unit_id,
            um.unit_name,
            ptinfo.gender_id,
            um.organization_id
           FROM (((patient.t_patient_registration pt
             JOIN public.patientinformation ptinfo ON ((pt.patient_id = ptinfo.patient_id)))
             JOIN public.unitinformation um ON ((ptinfo.unit_id = um.unit_id)))
             JOIN patient.t_patient_details pd ON ((pt.patient_id = pd.patient_id)))
          WHERE (pd.status = 'A'::bpchar)
        )
 SELECT cte.created_date,
    cte.type,
    cte.patientname,
    cte.patientmobile,
    cte.patientaddress,
    cte.gender_name,
    cte.unit_id,
    cte.unit_name,
    cte.gender_id,
    cte.organization_id
   FROM cte
  ORDER BY cte.created_date;


