--
-- TOC entry 3573 (class 1259 OID 3934247)
-- Name: bi_groupwiserevenucount; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".bi_groupwiserevenucount AS
 SELECT (bm.bill_date_time)::date AS bill_date_time,
    sp.speciality_id,
    sp.speciality_name,
    ssp.sub_speciality_id,
    ssp.sub_speciality_name,
    sum((bd.gross_amount - bd.discount)) AS net_amt,
    count(bm.patient_id) AS patient_id,
    bm.unit_id,
    bm.bill_cancelled,
    row_number() OVER (ORDER BY ((bm.bill_date_time)::date)) AS serialno,
    um.unit_name,
    um.unit_address,
    bm.organisation_id
   FROM (((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bd ON ((bd.billing_master_id = bm.billing_master_id)))
     JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     JOIN doctor.m_speciality_master sp ON ((sm.speciality_id = sp.speciality_id)))
     JOIN doctor.m_sub_speciality_master ssp ON ((sm.sub_speciality_id = ssp.sub_speciality_id)))
     JOIN public.unitinformation um ON ((bm.unit_id = um.unit_id)))
     JOIN billing.t_payment_reciept_master pr ON ((bm.billing_master_id = pr.billing_master_id)))
     JOIN billing.t_payment_reciept_details rd ON ((pr.payment_reciept_id = rd.payment_receipt_master_id)))
  WHERE ((bm.bill_cancelled = 'N'::bpchar) AND (bm.bill_status_id = 3))
  GROUP BY ((bm.bill_date_time)::date), sp.speciality_id, sp.speciality_name, ssp.sub_speciality_id, ssp.sub_speciality_name, bm.unit_id, bm.bill_cancelled, um.unit_name, um.unit_address, bm.organisation_id;


