--
-- TOC entry 3574 (class 1259 OID 3934252)
-- Name: get_groupwisetotal; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".get_groupwisetotal AS
 SELECT bi_groupwiserevenucount.organisation_id AS organization_id,
    bi_groupwiserevenucount.unit_id,
    bi_groupwiserevenucount.bill_date_time AS trandate,
    sum(bi_groupwiserevenucount.net_amt) AS totalcash,
    0 AS online,
    bi_groupwiserevenucount.sub_speciality_id,
    bi_groupwiserevenucount.sub_speciality_name,
    COALESCE(sum(bi_groupwiserevenucount.net_amt), (0)::double precision) AS netsum,
    bi_groupwiserevenucount.speciality_id,
    bi_groupwiserevenucount.speciality_name
   FROM "Reports".bi_groupwiserevenucount
  WHERE ((bi_groupwiserevenucount.sub_speciality_id IN ( SELECT mssm.sub_speciality_id
           FROM doctor.m_sub_speciality_master mssm
          WHERE (mssm.speciality_id IN ( SELECT tuabc.radiology_speciality_id
                   FROM public.t_unit_application_billing_configuration tuabc)))) OR (bi_groupwiserevenucount.sub_speciality_id IN ( SELECT mssm.sub_speciality_id
           FROM doctor.m_sub_speciality_master mssm
          WHERE (mssm.speciality_id IN ( SELECT tlc.lab_speciality_id
                   FROM public.t_lab_configuration tlc)))))
  GROUP BY bi_groupwiserevenucount.organisation_id, bi_groupwiserevenucount.unit_id, bi_groupwiserevenucount.bill_date_time, bi_groupwiserevenucount.sub_speciality_id, bi_groupwiserevenucount.sub_speciality_name, bi_groupwiserevenucount.speciality_id, bi_groupwiserevenucount.speciality_name;


--
-- TOC entry 3580 (class 1259 OID 3936682)
-- Name: bi_dashboard_revenue_collection_patientcount; Type: MATERIALIZED VIEW; Schema: Reports; Owner: -
--

CREATE MATERIALIZED VIEW "Reports".bi_dashboard_revenue_collection_patientcount AS
 SELECT row_to_json(detaillist.*) AS payment,
    grtotal.detaillist1 AS revenue,
    detaillist2.ptcount AS patientcount,
    detaillist.trandate,
    detaillist.organization_id,
    detaillist.unit_id
   FROM ((( SELECT bi_finaltotalnew.trandate,
            bi_finaltotalnew.organization_id,
            bi_finaltotalnew.unit_id,
            sum(bi_finaltotalnew.totalcash) AS cash,
            sum(bi_finaltotalnew.cheque) AS cheque,
            sum(bi_finaltotalnew.creditcard) AS creditcard,
            sum(bi_finaltotalnew.debitcard) AS debitcard,
            sum(bi_finaltotalnew.online) AS online
           FROM "Reports".bi_finaltotalnew
          GROUP BY bi_finaltotalnew.trandate, bi_finaltotalnew.organization_id, bi_finaltotalnew.unit_id) detaillist
     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,
            detaillist1.trandate,
            detaillist1.organization_id,
            detaillist1.unit_id
           FROM ( SELECT pay.trandate,
                    pay.organization_id,
                    pay.unit_id,
                    sum(pay.lab) AS lab,
                    sum(pay.radiology) AS radiology
                   FROM ( SELECT get_groupwisetotal.trandate,
                            get_groupwisetotal.organization_id,
                            get_groupwisetotal.unit_id,
                                CASE
                                    WHEN ((get_groupwisetotal.speciality_name)::text = 'Pathology'::text) THEN sum(get_groupwisetotal.netsum)
                                    ELSE NULL::double precision
                                END AS lab,
                                CASE
                                    WHEN ((get_groupwisetotal.speciality_name)::text = 'Radiology'::text) THEN sum(get_groupwisetotal.netsum)
                                    ELSE NULL::double precision
                                END AS radiology
                           FROM "Reports".get_groupwisetotal
                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name, get_groupwisetotal.organization_id, get_groupwisetotal.unit_id) pay
                  GROUP BY pay.trandate, pay.organization_id, pay.unit_id) detaillist1) grtotal ON (((grtotal.trandate = detaillist.trandate) AND (grtotal.organization_id = detaillist.organization_id) AND (grtotal.unit_id = detaillist.unit_id))))
     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,
            ptcount.trandate,
            ptcount.organization_id,
            ptcount.unit_id
           FROM ( SELECT ptcounts.created_date AS trandate,
                    ptcounts.organization_id,
                    ptcounts.unit_id,
                    COALESCE(sum(ptcounts.op), (0)::numeric) AS op,
                    COALESCE(sum(ptcounts.ip), (0)::numeric) AS ip,
                    COALESCE(sum(ptcounts.male), (0)::numeric) AS male,
                    COALESCE(sum(ptcounts.female), (0)::numeric) AS female
                   FROM ( SELECT bi_collection_new.created_date,
                                CASE
                                    WHEN (bi_collection_new.type = 'OP'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS op,
                                CASE
                                    WHEN (bi_collection_new.type = 'IP'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS ip,
                                CASE
                                    WHEN ((bi_collection_new.gender_name)::text = 'Male'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS male,
                                CASE
                                    WHEN ((bi_collection_new.gender_name)::text = 'Female'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS female,
                            bi_collection_new.organization_id,
                            bi_collection_new.unit_id,
                            bi_collection_new.ptcount
                           FROM "Reports".bi_collection_new) ptcounts
                  GROUP BY ptcounts.created_date, ptcounts.organization_id, ptcounts.unit_id) ptcount) detaillist2 ON (((detaillist2.trandate = detaillist.trandate) AND (detaillist2.organization_id = detaillist.organization_id) AND (detaillist2.unit_id = detaillist.unit_id))))
  WITH NO DATA;


--
-- TOC entry 3526 (class 1259 OID 3768709)
-- Name: image_groupwiserevenucount; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".image_groupwiserevenucount AS
 SELECT (bm.bill_date_time)::date AS bill_date_time,
    sp.speciality_id,
    sp.speciality_name,
    ssp.sub_speciality_id,
    ssp.sub_speciality_name,
    sum((bd.gross_amount - bd.discount)) AS net_amt,
    count(bm.patient_id) AS patient_id,
    bm.unit_id,
    bm.bill_cancelled,
    row_number() OVER (ORDER BY ((bm.bill_date_time)::date)) AS serialno,
    um.unit_name,
    um.unit_address,
    bm.organisation_id
   FROM (((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bd ON ((bd.billing_master_id = bm.billing_master_id)))
     JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     JOIN doctor.m_speciality_master sp ON ((sm.speciality_id = sp.speciality_id)))
     JOIN doctor.m_sub_speciality_master ssp ON ((sm.sub_speciality_id = ssp.sub_speciality_id)))
     JOIN public.unitinformation um ON ((bm.unit_id = um.unit_id)))
     JOIN billing.t_payment_reciept_master pr ON ((bm.billing_master_id = pr.billing_master_id)))
     JOIN billing.t_payment_reciept_details rd ON ((pr.payment_reciept_id = rd.payment_receipt_master_id)))
  WHERE ((bm.organisation_id = 10) AND (bm.bill_cancelled = 'N'::bpchar) AND (bm.bill_status_id = 3))
  GROUP BY ((bm.bill_date_time)::date), sp.speciality_id, sp.speciality_name, ssp.sub_speciality_id, ssp.sub_speciality_name, bm.unit_id, bm.bill_cancelled, um.unit_name, um.unit_address, bm.organisation_id;


--
-- TOC entry 3553 (class 1259 OID 3792270)
-- Name: bi_group_total; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".bi_group_total AS
 SELECT image_groupwiserevenucount.organisation_id AS organization_id,
    image_groupwiserevenucount.unit_id,
    image_groupwiserevenucount.bill_date_time AS trandate,
    sum(image_groupwiserevenucount.net_amt) AS totalcash,
    0 AS online,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1194) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS sono,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1185) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS x_ray,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1186) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS echo,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1187) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS doppler,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1196) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS ct,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1510) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS ecg,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1197) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS mri,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = ANY (ARRAY[1193, 1184, 1189])) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS path,
    COALESCE(sum(
        CASE
            WHEN (image_groupwiserevenucount.sub_speciality_id = 1195) THEN image_groupwiserevenucount.net_amt
            ELSE NULL::double precision
        END), (0)::double precision) AS consultation,
    image_groupwiserevenucount.unit_name,
    image_groupwiserevenucount.unit_address
   FROM "Reports".image_groupwiserevenucount
  GROUP BY image_groupwiserevenucount.organisation_id, image_groupwiserevenucount.unit_id, image_groupwiserevenucount.bill_date_time, image_groupwiserevenucount.sub_speciality_id, image_groupwiserevenucount.unit_name, image_groupwiserevenucount.unit_address;


