     JOIN public.m_unit_master umm ON ((dm.unit_id = umm.unit_id)))
     JOIN adt.t_admission adm ON ((dm.admission_id = adm.admission_id)))
     JOIN patient.patientinformation pm ON ((adm.patient_id = pm.patient_id)))
