    countermaster.counter_desc,
    transtype.transaction_type_desc
   FROM ((((((((billing.t_payment_deposit_details dd
     JOIN billing.m_deposit_master dm ON ((dm.deposit_master_id = dd.deposit_id)))
     JOIN patient.t_patient_registration pr ON ((pr.patient_id = dm.patient_id)))
     JOIN public.m_payment_mode_master pmm ON ((dd.payment_mode_id = pmm.payment_mode_id)))
     LEFT JOIN public.m_user_master um ON ((dd.created_by = um.user_id)))
     JOIN public.m_unit_master umm ON ((dm.unit_id = umm.unit_id)))
