-- TOC entry 3440 (class 1259 OID 3248938)
-- Name: image_opipdadvancerefund; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.image_opipdadvancerefund AS
 SELECT bm.payment_refund_id AS id,
        CASE
            WHEN (brc.visit_type_id = 1) THEN ((vtm.visit_type_code)::text || 'D Advance Refund'::text)
            WHEN (brc.visit_type_id IS NULL) THEN 'Active Advance Refund'::text
            ELSE ((vtm.visit_type_code)::text || 'D Advance Refund'::text)
        END AS deposit,
    'Active patient'::character varying AS visit_type_code,
    brc.visit_type_id,
    pmm.payment_mode_desc,
    brdet.amount,
    0 AS consumed_amount,
    0 AS tdsamt,
    um.user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    brdet.created_date AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Refund'::text AS amttype,
    bm.payment_refund_voucher_no AS reciptno,
    countermaster.counter_id,
    countermaster.counter_desc
   FROM ((((((((billing.t_payment_refund_details brdet
     LEFT JOIN billing.t_payment_refund_master bm ON ((bm.payment_refund_id = brdet.payment_refund_id)))
     JOIN billing.t_refund_cn brc ON ((brc.t_refund_cn_id = bm.t_refund_cn_id)))
     LEFT JOIN public.m_visit_type_master vtm ON ((vtm.visit_type_id = brc.visit_type_id)))
     JOIN public.m_payment_mode_master pmm ON ((brdet.payment_mode_id = pmm.payment_mode_id)))
     JOIN public.m_unit_master umm ON ((brdet.unit_id = umm.unit_id)))
     LEFT JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_user_master um ON ((brdet.created_by = um.user_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((bm.counter_id = countermaster.counter_id)))
UNION ALL
 SELECT bm.payment_refund_id AS id,
        CASE
            WHEN (billmst.visit_type_id = 1) THEN ((vtm.visit_type_code)::text || 'D Refund bill'::text)
            ELSE ((vtm.visit_type_code)::text || 'D Refund bill'::text)
        END AS deposit,
    vtm.visit_type_code,
    vtm.visit_type_id,
    pmm.payment_mode_desc,
    brdet.amount,
    0 AS consumed_amount,
    0 AS tdsamt,
    um.user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    brdet.created_date AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Refund'::text AS amttype,
    bm.payment_refund_voucher_no AS reciptno,
    countermaster.counter_id,
    countermaster.counter_desc
   FROM (((((((((billing.t_payment_refund_details brdet
     JOIN billing.t_payment_refund_master bm ON ((bm.payment_refund_id = brdet.payment_refund_id)))
     JOIN billing.m_credit_note_master bcnid ON ((bm.credit_note_id = bcnid.credit_note_id)))
     JOIN billing.m_billing_master billmst ON ((billmst.billing_master_id = bcnid.bill_id)))
     JOIN public.m_visit_type_master vtm ON ((vtm.visit_type_id = billmst.visit_type_id)))
     JOIN public.m_payment_mode_master pmm ON ((brdet.payment_mode_id = pmm.payment_mode_id)))
     JOIN public.m_unit_master umm ON ((brdet.unit_id = umm.unit_id)))
     LEFT JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_user_master um ON ((brdet.created_by = um.user_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((bm.counter_id = countermaster.counter_id)))
  ORDER BY 1;


