CREATE VIEW public.image_opipdbillsummary AS
(
         SELECT bm.billing_master_id,
            ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
            vm.visit_type_code,
            vm.visit_type_id,
            pmm.payment_mode_desc,
            prd.amount,
            0 AS consumed_amount,
            0 AS tdsamt,
            um.user_name,
            um.user_id,
            bm.unit_id,
            bm.organisation_id AS organization_id,
            umm.unit_name,
            umm.unit_address,
            umm.unit_contact,
            umm.unit_contact_2,
                CASE
                    WHEN (COALESCE(bm.outstanding, (0)::double precision) <> (0)::double precision) THEN bm.bill_date_time
                    ELSE prd.date_of_transaction
                END AS depositdate,
            pm.patientname,
            pm.patient_id,
            pm.uhid_number,
            'Income'::text AS amttype,
            bm.bill_number AS reciept_number,
            countermaster.counter_id,
            countermaster.counter_desc,
            bm.total_bill_amount,
            bm.discount_amount,
            bm.net_amount,
            bm.outstanding,
            payment.amount AS paidamount,
            transtype.transaction_type_desc,
            bm.bill_date_time,
            m_refferel.referral_name
           FROM (((((((((((((billing.m_billing_master bm
             JOIN billing.t_billing_details bdet ON ((bm.billing_master_id = bdet.billing_master_id)))
             JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
             LEFT JOIN billing.t_payment_reciept_master rm ON ((bm.billing_master_id = rm.billing_master_id)))
             LEFT JOIN billing.t_payment_reciept_details prd ON ((rm.payment_reciept_id = prd.payment_receipt_master_id)))
             LEFT JOIN public.m_payment_mode_master pmm ON ((prd.payment_mode_id = pmm.payment_mode_id)))
             LEFT JOIN public.m_user_master um ON ((rm.created_by = um.user_id)))
             LEFT JOIN public.m_unit_master umm ON ((bm.unit_id = umm.unit_id)))
             JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
             LEFT JOIN public.m_counter_master countermaster ON ((rm.counter_id = countermaster.counter_id)))
             LEFT JOIN billing.m_transaction_type_master transtype ON ((prd.transaction_type_id = transtype.transaction_type_id)))
             LEFT JOIN public.t_referal_details admreff ON ((bm.encounter_id = admreff.encounter_id)))
             LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
             LEFT JOIN ( SELECT prm.billing_master_id,
                    sum(prm.amount) AS amount
                   FROM (billing.t_payment_reciept_master prm
                     JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
                  GROUP BY prm.billing_master_id) payment ON ((bm.billing_master_id = payment.billing_master_id)))
          WHERE ((COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar) AND (COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar))
        UNION ALL
         SELECT bm.billing_master_id,
            ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
            vm.visit_type_code,
            vm.visit_type_id,
            'selfconsumed'::text AS payment_mode_desc,
            0 AS amount,
            dc.consumed_amount,
            0 AS tdsamt,
            um.user_name,
            um.user_id,
            umm.unit_id,
            umm.organization_id,
            umm.unit_name,
            umm.unit_address,
            umm.unit_contact,
            umm.unit_contact_2,
            dc.dep_consumption_date AS depositdate,
            pm.patientname,
            pm.patient_id,
            pm.uhid_number,
            'Income'::text AS amttype,
            dc.deposite_consumption_number AS reciept_number,
            countermaster.counter_id,
            countermaster.counter_desc,
            bm.total_bill_amount,
            bm.discount_amount,
            bm.net_amount,
            bm.outstanding,
            payment.amount AS paidamount,
            ''::text AS transaction_type_desc,
            bm.bill_date_time,
            m_refferel.referral_name
           FROM ((((((((((billing.m_billing_master bm
             JOIN billing.t_billing_details bdet ON ((bm.billing_master_id = bdet.billing_master_id)))
             JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
             JOIN billing.t_payment_deposite_consumption dc ON ((bm.billing_master_id = dc.bill_id)))
             JOIN public.m_user_master um ON ((dc.created_by = um.user_id)))
             JOIN public.m_unit_master umm ON ((dc.unit_id = umm.unit_id)))
             JOIN patient.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
             LEFT JOIN public.m_counter_master countermaster ON ((dc.counter_id = countermaster.counter_id)))
             LEFT JOIN public.t_referal_details admreff ON ((bm.encounter_id = admreff.encounter_id)))
             LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
             LEFT JOIN ( SELECT prm.billing_master_id,
                    sum(prm.amount) AS amount
                   FROM (billing.t_payment_reciept_master prm
                     JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
                  GROUP BY prm.billing_master_id) payment ON ((bm.billing_master_id = payment.billing_master_id)))
          WHERE (COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar)
) UNION
 SELECT DISTINCT 0 AS billing_master_id,
    ((vm.visit_type_code)::text || 'D Bill'::text) AS deposit,
    vm.visit_type_code,
    vm.visit_type_id,
    pmm.payment_mode_desc,
