    bm.bill_date_time,
    m_refferel.referral_name
   FROM (((((((((((((((((((billing.m_company_receipt_master compnayrecmaster
     JOIN billing.t_company_receipt_detail companyrecdetail ON ((compnayrecmaster.company_receipt_id = companyrecdetail.company_receipt_id)))
     JOIN billing.t_payment_reciept_master rm ON ((rm.payment_reciept_id = compnayrecmaster.receipt_id)))
