    (image_allcollectionsummary_all.cash + image_allcollectionsummary_all.e_transfer) AS netcash,
    image_allcollectionsummary_all.outstanding
   FROM public.image_allcollectionsummary_all
  WHERE ((image_allcollectionsummary_all.organization_id = 10) AND (image_allcollectionsummary_all.deposit = ANY (ARRAY['OPD Bill'::text, 'Mis.Income'::text])))
