--
-- TOC entry 3556 (class 1259 OID 3792336)
-- Name: bi_finaltotal; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".bi_finaltotal AS
 SELECT bi_image_collection.organization_id,
    bi_image_collection.unit_id,
    bi_image_collection.depositdate AS trandate,
    sum(bi_image_collection.cash) AS totalcash,
    sum(bi_image_collection.e_transfer) AS online,
    grtran.sono,
    grtran.x_ray,
    grtran.echo,
    grtran.doppler,
    grtran.ct,
    grtran.ecg,
    grtran.mri,
    grtran.path,
    grtran.consultation
   FROM ("Reports".bi_image_collection
     JOIN ( SELECT bi_group_total.organization_id,
            bi_group_total.unit_id,
            bi_group_total.trandate,
            sum(bi_group_total.totalcash) AS totalcash,
            sum(bi_group_total.online) AS online,
            sum(bi_group_total.sono) AS sono,
            sum(bi_group_total.x_ray) AS x_ray,
            sum(bi_group_total.echo) AS echo,
            sum(bi_group_total.doppler) AS doppler,
            sum(bi_group_total.ct) AS ct,
            sum(bi_group_total.ecg) AS ecg,
            sum(bi_group_total.mri) AS mri,
            sum(bi_group_total.path) AS path,
            sum(bi_group_total.consultation) AS consultation
           FROM "Reports".bi_group_total
          GROUP BY bi_group_total.organization_id, bi_group_total.unit_id, bi_group_total.trandate) grtran ON (((bi_image_collection.unit_id = grtran.unit_id) AND (bi_image_collection.depositdate = grtran.trandate))))
  GROUP BY bi_image_collection.organization_id, bi_image_collection.unit_id, bi_image_collection.depositdate, grtran.sono, grtran.x_ray, grtran.echo, grtran.doppler, grtran.ct, grtran.ecg, grtran.mri, grtran.path, grtran.consultation;


