-- Name: nabh_nursing; Type: VIEW; Schema: Reports; Owner: -
--

CREATE VIEW "Reports".nabh_nursing AS
 SELECT DISTINCT t_patient_registration.prefix_id,
    t_patient_registration.uhid_number,
    ((((((m_prefix_master.prefix_desc || ' '::text) || (t_patient_registration.first_name)::text) || ' '::text) || (t_patient_registration.middle_name)::text) || ' '::text) || (t_patient_registration.last_name)::text) AS patientname,
    m_gender_master.gender_name,
    age(t_patient_registration.dob) AS age,
    t_patient_registration.mobile_number,
    t_patient_registration.patient_id,
    t_admission.admission_id,
    um.unit_address_2,
    um.unit_address,
    um.unit_name,
    (abs(date_part('Year'::text, age(t_patient_registration.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageyear,
    (abs(date_part('month'::text, age(t_patient_registration.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS agemonth,
    (abs(date_part('Day'::text, age(t_patient_registration.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageday,
    (((('Dr.'::text || ' '::text) || (dm.first_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    (((('Dr.'::text || ' '::text) || (dmt.first_name)::text) || ' '::text) || (dmt.last_name)::text) AS doctornametreating,
    t_admission.admission_number,
    t_admission.created_date,
    m_bed_master.bed_desc,
    (((('Dr.'::text || ' '::text) || (refdoctor.first_name)::text) || ' '::text) || (refdoctor.last_name)::text) AS refdoctor,
    wm.ward_name
   FROM ((((((((((((patient.t_patient_registration
     LEFT JOIN public.m_prefix_master ON ((t_patient_registration.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN public.m_gender_master ON ((t_patient_registration.gender_id = m_gender_master.gender_id)))
     JOIN adt.t_admission ON ((t_patient_registration.patient_id = t_admission.patient_id)))
     LEFT JOIN public.patientinformation patinfo ON ((t_patient_registration.patient_id = patinfo.patient_id)))
     JOIN public.m_unit_master um ON ((um.unit_id = t_admission.unit_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((t_admission.admitting_doctor_id = dm.doctor_id)))
     LEFT JOIN doctor.m_doctor_master dmt ON ((t_admission.doctor_id = dmt.doctor_id)))
     JOIN adt.t_admission_details ON ((t_admission.admission_id = t_admission_details.admission_id)))
     LEFT JOIN adt.m_bed_master ON ((t_admission_details.bed_id = m_bed_master.bed_id)))
     LEFT JOIN opd.t_consult_doctor cd ON ((t_admission.admission_id = cd.admission_id)))
     LEFT JOIN doctor.m_doctor_master refdoctor ON ((cd.ref_to_doctor_id = refdoctor.doctor_id)))
     LEFT JOIN adt.m_ward_master wm ON ((t_admission_details.ward_id = wm.ward_id)))
  WHERE (t_admission_details.admission_details_id = ( SELECT t_admission_details_1.admission_details_id
           FROM adt.t_admission_details t_admission_details_1
          WHERE (t_admission_details_1.admission_id = t_admission.admission_id)
          ORDER BY t_admission_details_1.admission_details_id DESC
         LIMIT 1));


--
-- TOC entry 3577 (class 1259 OID 3934273)
-- Name: paymentsnew; Type: MATERIALIZED VIEW; Schema: Reports; Owner: -
--

CREATE MATERIALIZED VIEW "Reports".paymentsnew AS
 SELECT row_to_json(detaillist.*) AS payment,
    grtotal.detaillist1 AS revenue,
    detaillist2.ptcount AS patientcount,
    detaillist.trandate
   FROM ((( SELECT bi_finaltotalnew.trandate,
            sum(bi_finaltotalnew.totalcash) AS cash,
            sum(bi_finaltotalnew.cheque) AS cheque,
            sum(bi_finaltotalnew.creditcard) AS creditcard,
            sum(bi_finaltotalnew.debitcard) AS debitcard,
            sum(bi_finaltotalnew.online) AS online
           FROM "Reports".bi_finaltotalnew
          GROUP BY bi_finaltotalnew.trandate) detaillist
     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,
            detaillist1.trandate
           FROM ( SELECT pay.trandate,
                    sum(pay.lab) AS lab,
                    sum(pay.radiology) AS radilogy
                   FROM ( SELECT get_groupwisetotal.trandate,
                                CASE
                                    WHEN ((get_groupwisetotal.speciality_name)::text = 'LAB'::text) THEN sum(get_groupwisetotal.netsum)
                                    ELSE NULL::double precision
                                END AS lab,
                                CASE
                                    WHEN ((get_groupwisetotal.speciality_name)::text = 'RADIOLOGY'::text) THEN sum(get_groupwisetotal.netsum)
                                    ELSE NULL::double precision
                                END AS radiology
                           FROM "Reports".get_groupwisetotal
                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name) pay
                  GROUP BY pay.trandate) detaillist1) grtotal ON ((grtotal.trandate = detaillist.trandate)))
     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,
            ptcount.trandate
           FROM ( SELECT ptcounts.created_date AS trandate,
                    COALESCE(sum(ptcounts.op), (0)::numeric) AS op,
                    COALESCE(sum(ptcounts.ip), (0)::numeric) AS ip,
                    COALESCE(sum(ptcounts.male), (0)::numeric) AS male,
                    COALESCE(sum(ptcounts.female), (0)::numeric) AS female
                   FROM ( SELECT bi_collection_new.created_date,
                                CASE
                                    WHEN (bi_collection_new.type = 'OP'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS op,
                                CASE
                                    WHEN (bi_collection_new.type = 'IP'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS ip,
                                CASE
                                    WHEN ((bi_collection_new.gender_name)::text = 'Male'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS male,
                                CASE
                                    WHEN ((bi_collection_new.gender_name)::text = 'Female'::text) THEN bi_collection_new.ptcount
                                    ELSE NULL::bigint
                                END AS female,
                            bi_collection_new.organization_id,
                            bi_collection_new.unit_id,
                            bi_collection_new.ptcount
                           FROM "Reports".bi_collection_new) ptcounts
                  GROUP BY ptcounts.created_date) ptcount) detaillist2 ON ((detaillist2.trandate = detaillist.trandate)))
  WITH NO DATA;


