     LEFT JOIN adt.m_ward_master ON ((t_admission_details.ward_id = m_ward_master.ward_id)))
     LEFT JOIN adt.m_room_master ON ((t_admission_details.room_id = m_room_master.room_id)))
     LEFT JOIN adt.m_bed_master ON ((t_admission_details.bed_id = m_bed_master.bed_id)))
     LEFT JOIN adt.m_bed_category_master ON ((t_admission_details.bed_category_id = m_bed_category_master.bed_category_id)))
     LEFT JOIN adt.m_billing_bed_category_master ON ((t_admission_details.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_id)))
     LEFT JOIN adt.m_meal_preference_master ON ((t_admission_details.meal_pref_id = m_meal_preference_master.meal_preference_id)))
     LEFT JOIN adt.m_floor_master ON ((t_admission_details.floor_id = m_floor_master.floor_id)))
     LEFT JOIN public.m_user_master umc ON ((t_admission_details.cancel_by = umc.user_id)))
     LEFT JOIN public.m_employee_master ON ((umc.user_id = m_employee_master.user_id)))
     LEFT JOIN public.m_prefix_master ON ((m_employee_master.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN doctor.m_speciality_master ON ((t_admission.speciality_id = m_speciality_master.speciality_id)))
     LEFT JOIN public.m_kin_details kd ON ((kd.patient_id = t_admission.patient_id)))
     LEFT JOIN public.m_relation_master rm ON ((kd.relation_id = rm.relation_id)))
     LEFT JOIN opd.t_patient_sponsor_details ON ((t_admission.admission_id = t_patient_sponsor_details.admission_id)))
     LEFT JOIN public.t_company_master ON ((t_patient_sponsor_details.payee_id = t_company_master.company_id)))
     LEFT JOIN adt.t_medico_legal mlc ON ((t_admission.admission_id = mlc.admission_id)))
     LEFT JOIN public.m_relation_master relation ON ((mlc.mlc_relation_id = relation.relation_id)))
     LEFT JOIN public.t_referal_details admreff ON ((t_admission.admission_id = admreff.admission_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
  WHERE ((t_patient_sponsor_details.status = 'A'::bpchar) AND (t_admission_details.admission_details_id = ( SELECT t_admission_details_1.admission_details_id
           FROM adt.t_admission_details t_admission_details_1
          WHERE (t_admission_details_1.admission_id = t_admission.admission_id)
          ORDER BY t_admission_details_1.admission_details_id DESC
         LIMIT 1)))
  ORDER BY t_admission.admission_id, t_admission_details.doa;


