--
-- TOC entry 607 (class 1259 OID 2970231)
-- Name: get_patient_transfer_details; Type: VIEW; Schema: adt; Owner: -
--

CREATE VIEW adt.get_patient_transfer_details AS
 SELECT pr.uhid_number,
    (((((pr.first_name)::text || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS p_name,
    bcm1.bed_category_desc AS from_bed_category,
    COALESCE(bcm2.bed_category_desc, '--'::text) AS to_bed_category,
    tsm.transfer_status_desc,
    COALESCE(bbcm1.billing_bed_desc, '--'::character varying) AS from_billing_bed_category,
    COALESCE(bbcm2.billing_bed_desc, '--'::character varying) AS to_billing_bed_category,
    COALESCE(wm1.ward_name, '--'::character varying) AS from_ward,
    COALESCE(wm2.ward_name, '--'::character varying) AS to_ward,
    COALESCE(rm1.room_desc, '--'::text) AS from_room,
    COALESCE(rm2.room_desc, '--'::text) AS to_room,
    COALESCE(bm1.bed_number, '--'::character varying) AS from_bed,
    COALESCE(bm2.bed_number, '--'::character varying) AS to_bed,
    t.created_date,
    t.updated_date,
    u.unit_name,
    u.unit_address,
    u.unit_contact,
    wm1.ward_id AS fromward_id,
    wm2.ward_id AS toward_id,
    tsm.transfer_status_id,
    u.unit_id,
    u.image
   FROM ((((((((((((((adt.t_transfer t
     JOIN adt.t_admission a ON ((t.admission_id = a.admission_id)))
     JOIN patient.t_patient_registration pr ON ((a.patient_id = pr.patient_id)))
     LEFT JOIN adt.m_bed_category_master bcm1 ON ((t.from_bed_category_id = bcm1.bed_category_id)))
     LEFT JOIN adt.m_bed_category_master bcm2 ON ((t.to_bed_category_id = bcm2.bed_category_id)))
     LEFT JOIN adt.m_billing_bed_category_master bbcm1 ON ((t.from_billing_bed_category_id = bbcm1.billing_bed_category_id)))
     LEFT JOIN adt.m_billing_bed_category_master bbcm2 ON ((t.from_billing_bed_category_id = bbcm2.billing_bed_category_id)))
     LEFT JOIN adt.m_ward_master wm1 ON ((t.from_ward_id = wm1.ward_id)))
     LEFT JOIN adt.m_ward_master wm2 ON ((t.to_ward_id = wm2.ward_id)))
     LEFT JOIN adt.m_room_master rm1 ON ((t.from_room_id = rm1.room_id)))
     LEFT JOIN adt.m_room_master rm2 ON ((t.to_room_id = rm2.room_id)))
     LEFT JOIN adt.m_bed_master bm1 ON ((t.from_bed_id = bm1.bed_id)))
     LEFT JOIN adt.m_bed_master bm2 ON ((t.to_bed_id = bm2.bed_id)))
     JOIN public.unitinformation u ON ((t.unit_id = u.unit_id)))
     JOIN adt.m_transfer_status_master tsm ON ((t.transfer_status_id = tsm.transfer_status_id)))
  ORDER BY t.transfer_id;


