--
-- TOC entry 3613 (class 1259 OID 3987857)
-- Name: get_asset_opbalance; Type: VIEW; Schema: assets; Owner: -
--

CREATE VIEW assets.get_asset_opbalance AS
 SELECT ob.id,
    ob.opb_no,
    ob.added_date,
    ob.unit_id,
    m_store.store_name,
    mstatus.status,
    concat(em.first_name, ' ', em.last_name) AS empaddedby,
    concat(emapp.first_name, ' ', emapp.last_name) AS empapprovby,
    ob.approved_date,
    m_item.name AS itemname,
    obd.quantity,
    obd.serial_number,
    obd.remark,
    obd.warranty_from,
    obd.warranty_to,
    frequency.description,
    obd.year_of_manufacture,
    vendor.name AS vendor,
    unit.unit_name,
    unit.unit_address
   FROM (((((((((((inventory.t_opening_balance ob
     JOIN inventory.t_opening_balance_detail obd ON ((ob.id = obd.opening_balance_id)))
     JOIN public.m_store ON ((ob.store_id = m_store.store_id)))
     LEFT JOIN public.m_status mstatus ON ((ob.status_id = mstatus.id)))
     LEFT JOIN public.m_user_master usermaster ON ((ob.added_by = usermaster.user_id)))
     LEFT JOIN public.m_employee_master em ON ((usermaster.user_id = em.user_id)))
     LEFT JOIN public.m_user_master usermasterapprov ON ((ob.approved_by = usermasterapprov.user_id)))
     LEFT JOIN public.m_employee_master emapp ON ((usermaster.user_id = emapp.user_id)))
     JOIN public.m_item ON ((obd.item_id = m_item.id)))
     LEFT JOIN inventory.m_pms_frequency frequency ON ((obd.pms_frequency_id = frequency.id)))
     LEFT JOIN public.m_vendor vendor ON ((obd.vendor_id = vendor.id)))
     JOIN public.unitinformation unit ON ((ob.unit_id = unit.unit_id)));


