    unitservic5_.discount_value,
    doctormaster.admission_id,
    doctormaster.doctor_id,
    doctormaster.doctorname,
    doctormaster.docgender,
    doctormaster.doctor_category_description,
    doctormaster.docspeciality,
    doctormaster.docage,
    doctormaster.docdob,
    doctormaster.country_calling_code,
    doctormaster.docmobile,
    doctormaster.docemail,
    doctormaster.doctor_image,
    doctormaster.docreg,
    doctormaster.slot_time_span,
    doctormaster.doctor_episod_time_span,
    doctormaster.speciality_id,
    unitinformation.unit_id,
    unitinformation.unit_name,
