   FROM (((((((((public.t_order_details orderdetails
     LEFT JOIN public.t_order_master ordermaster ON ((orderdetails.order_id = ordermaster.order_id)))
     LEFT JOIN adt.t_admission adm ON ((adm.admission_id = ordermaster.admission_id)))
     LEFT JOIN patient.patientinformation patreg ON ((patreg.patient_id = adm.patient_id)))
     LEFT JOIN public.m_prefix_master prefix ON ((patreg.prefix_id = prefix.prefix_id)))
     LEFT JOIN service.m_service_master servicemaster ON ((orderdetails.service_id = servicemaster.service_master_id)))
     LEFT JOIN service.t_unit_service_master_details unitservic5_ ON ((servicemaster.service_master_id = unitservic5_.service_master_id)))
     LEFT JOIN doctor.doctorinformationipd doctormaster ON ((adm.admission_id = doctormaster.admission_id)))
