    m_billing_master.bill_date_time,
    m_billing_master.net_amount,
    m_billing_master.discount_amount,
    m_billing_master.is_credit_bill,
    m_billing_master.organisation_id,
    m_billing_master.created_date,
    m_billing_master.created_by,
    m_billing_master.updated_date,
    m_billing_master.concession_amount,
    m_billing_master.gst,
    m_billing_master.total_bill_amount,
    m_billing_master.outstanding,
    m_billing_master.round_off,
    m_billing_master.status,
    m_billing_master.updated_by,
    m_billing_master.bill_status_id,
    m_billing_master.admission_id,
    m_billing_master.cr_amount,
    m_billing_master.settlement_date,
    m_billing_master.bill_cancelled,
    m_billing_master.bill_cancel_reason_id,
    m_billing_master.bill_cancel_datetime,
    m_billing_master.bill_cancel_by,
    m_billing_master.bill_cancel_remark,
    m_billing_master.is_interim_or_final_bill,
    m_billing_master.is_doctor_referral_posted,
    m_billing_master.is_invoice_creation,
