    m_billing_master.is_addendum_bill,
    m_billing_master.old_bill_id,
    m_payment_mode_master.payment_mode_desc,
    t_patient_registration.uhid_number,
    concat(COALESCE(m_prefix_master.prefix_desc, (''::character varying)::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,
    m_organization_master.organization_name,
    unitinformation.unit_id,
