    unitinformation.unit_contact,
    unitinformation.unit_contact_2,
    unitinformation.unit_contact_3,
    unitinformation.unit_country_code,
    unitinformation.registration_number,
    unitinformation.unit_website,
    unitinformation.currency_name,
    unitinformation.sub_currency,
    t_payment_reciept_details.payment_mode_id,
    t_payment_reciept_details.amount AS paymentamount,
    m_bank_master.bank_name,
    t_payment_reciept_details.check_number,
    t_payment_reciept_details.cheque_date,
    t_payment_reciept_details.card_holder_name,
    t_payment_reciept_details.date_of_transaction,
    t_payment_reciept_details.card_number,
    t_payment_reciept_details.expiry_date,
    ((((pm.prefix_desc || ' '::text) || (m_employee_master.first_name)::text) || ' '::text) || (m_employee_master.last_name)::text) AS username,
    m_visit_type_master.visit_type_name,
    t_payment_reciept_details.transaction_no,
    unitinformation.image
   FROM (((((((((((((billing.t_payment_reciept_master
     LEFT JOIN billing.t_payment_reciept_details ON ((t_payment_reciept_master.payment_reciept_id = t_payment_reciept_details.payment_receipt_master_id)))
     LEFT JOIN billing.m_billing_master ON ((t_payment_reciept_master.billing_master_id = m_billing_master.billing_master_id)))
     LEFT JOIN public.m_payment_mode_master ON ((t_payment_reciept_details.payment_mode_id = m_payment_mode_master.payment_mode_id)))
     LEFT JOIN patient.t_patient_registration ON ((m_billing_master.patient_id = t_patient_registration.patient_id)))
     LEFT JOIN public.m_prefix_master ON ((t_patient_registration.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN public.m_gender_master ON ((t_patient_registration.gender_id = m_gender_master.gender_id)))
     LEFT JOIN public.m_organization_master ON ((m_billing_master.organisation_id = m_organization_master.organization_id)))
     LEFT JOIN public.unitinformation ON ((m_billing_master.unit_id = unitinformation.unit_id)))
     LEFT JOIN billing.m_bank_master ON ((t_payment_reciept_details.bank_id = m_bank_master.bank_id)))
     LEFT JOIN public.m_user_master ON ((t_payment_reciept_master.created_by = m_user_master.user_id)))
     LEFT JOIN public.m_employee_master ON ((m_user_master.user_id = m_employee_master.user_id)))
     LEFT JOIN public.m_prefix_master pm ON ((m_employee_master.prefix_id = pm.prefix_id)))
     LEFT JOIN public.m_visit_type_master ON ((m_billing_master.visit_type_id = m_visit_type_master.visit_type_id)));


