    t_payment_refund_master.date_of_refund,
    t_payment_refund_master.is_cn_or_deposit,
    t_payment_refund_master.t_refund_cn_id,
    t_payment_refund_master.amount_refunded,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_email_id,
    unitinformation.unit_logo,
    unitinformation.post_code,
    unitinformation.unit_contact,
    unitinformation.unit_contact_2,
    unitinformation.unit_contact_3,
    unitinformation.unit_country_code,
    unitinformation.registration_number,
    unitinformation.unit_website,
    unitinformation.currency_name,
    unitinformation.sub_currency,
    ((((epm.prefix_desc || ' '::text) || (m_employee_master.first_name)::text) || ' '::text) || (m_employee_master.last_name)::text) AS username,
    m_payment_mode_master.payment_mode_desc,
    m_bank_master.bank_name,
    t_payment_refund_details.card_number,
    t_payment_refund_details.cheque_number,
    t_payment_refund_details.date AS chequedate,
    t_patient_registration.uhid_number,
    concat(COALESCE(m_prefix_master.prefix_desc, (''::character varying)::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,
    m_credit_note_master.credit_note_no AS againstcreditnoteno,
    t_payment_refund_details.payment_mode_id,
    ''::text AS service_standard_name,
    0 AS rate,
    0 AS tax_amount,
    0 AS tax_per,
    0 AS quantity,
    0 AS concession,
    t_payment_refund_details.amount AS gross_amount,
    0 AS servicenetamt,
    unitinformation.image
   FROM (((((((((((((billing.t_payment_refund_master
     JOIN billing.t_payment_refund_details ON ((t_payment_refund_master.payment_refund_id = t_payment_refund_details.payment_refund_id)))
     JOIN billing.m_credit_note_master ON ((t_payment_refund_master.credit_note_id = m_credit_note_master.credit_note_id)))
     JOIN billing.t_credit_note_detail ON ((m_credit_note_master.credit_note_id = t_credit_note_detail.credit_note_id)))
     JOIN public.t_order_details ON ((t_credit_note_detail.order_detail_id = t_order_details.order_details_id)))
     JOIN service.m_service_master ON ((t_order_details.service_id = m_service_master.service_master_id)))
     LEFT JOIN patient.t_patient_registration ON ((t_payment_refund_master.patient_id = t_patient_registration.patient_id)))
     LEFT JOIN public.m_prefix_master ON ((t_patient_registration.prefix_id = m_prefix_master.prefix_id)))
     LEFT JOIN public.m_user_master ON ((t_payment_refund_master.created_by = m_user_master.user_id)))
     LEFT JOIN public.m_employee_master ON ((m_user_master.user_id = m_employee_master.user_id)))
     LEFT JOIN public.m_prefix_master epm ON ((m_employee_master.prefix_id = epm.prefix_id)))
     LEFT JOIN public.unitinformation ON ((t_payment_refund_master.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.m_payment_mode_master ON ((t_payment_refund_details.payment_mode_id = m_payment_mode_master.payment_mode_id)))
     LEFT JOIN billing.m_bank_master ON ((t_payment_refund_details.bank_id = m_bank_master.bank_id)))
  WHERE (t_payment_refund_master.is_cn_or_deposit = 1)
UNION
 SELECT DISTINCT t_payment_refund_master.payment_refund_id,
    t_payment_refund_master.payment_refund_voucher_no,
    t_payment_refund_master.date_of_refund,
    t_payment_refund_master.is_cn_or_deposit,
