    ((((epm.prefix_desc || ' '::text) || (m_employee_master.first_name)::text) || ' '::text) || (m_employee_master.last_name)::text) AS username,
    m_payment_mode_master.payment_mode_desc,
    m_bank_master.bank_name,
    t_payment_refund_details1.card_number,
    t_payment_refund_details1.cheque_number,
    t_payment_refund_details1.date AS chequedate,
    t_patient_registration.uhid_number,
    concat(COALESCE(m_prefix_master.prefix_desc, (''::character varying)::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,
    m_deposit_master.deposit_no AS againstcreditnoteno,
    t_payment_refund_details1.payment_mode_id,
    ''::text AS service_standard_name,
    0 AS rate,
    0 AS tax_amount,
    0 AS tax_per,
    0 AS quantity,
    0 AS concession,
    t_payment_refund_details1.amount AS gross_amount,
    0 AS servicenetamt,
    unitinformation.image
   FROM ((((((((((((billing.t_payment_refund_master
     JOIN ( SELECT t_payment_refund_details.payment_refund_id,
            t_payment_refund_details.payment_mode_id,
            t_payment_refund_details.bank_id,
            t_payment_refund_details.card_number,
            t_payment_refund_details.cheque_number,
            t_payment_refund_details.date,
            sum(t_payment_refund_details.amount) AS amount
           FROM billing.t_payment_refund_details
          GROUP BY t_payment_refund_details.payment_refund_id, t_payment_refund_details.payment_mode_id, t_payment_refund_details.bank_id, t_payment_refund_details.card_number, t_payment_refund_details.cheque_number, t_payment_refund_details.date) t_payment_refund_details1 ON ((t_payment_refund_master.payment_refund_id = t_payment_refund_details1.payment_refund_id)))
