--
-- TOC entry 3476 (class 1259 OID 3695097)
-- Name: doctorshare; Type: VIEW; Schema: doctor; Owner: -
--

CREATE VIEW doctor.doctorshare AS
 SELECT doctormaster.first_name,
    doctormaster.last_name,
    speciality.speciality_name,
    billmaster.bill_number,
    billmaster.bill_date_time,
    servicemaster.service_standard_name,
    share.bill_dtl_id,
    share.ord_dtl_id,
    share.admission_id AS visit_id,
    share.visit_type_id,
    share.service_id,
    share.unit_rate,
    share.total_amount,
    share.discount,
    share.due_share_amt,
    share.share_per,
    share.doc_share,
    share.processed_share_amt,
    share.hosp_share,
    share.processed_share_date,
    share.doc_id,
    share.doc_spec_id,
    share.doctor_share_id
   FROM (((((billing.t_doctor_share share
     JOIN doctor.m_doctor_master doctormaster ON ((share.doc_id = doctormaster.doctor_id)))
     JOIN doctor.m_speciality_master speciality ON ((share.doc_spec_id = speciality.speciality_id)))
     JOIN service.m_service_master servicemaster ON ((share.service_id = servicemaster.service_master_id)))
     JOIN billing.t_billing_details billdetails ON ((share.bill_dtl_id = billdetails.billing_details_id)))
     JOIN billing.m_billing_master billmaster ON ((billdetails.billing_master_id = billmaster.billing_master_id)))
  WHERE ((share.doc_share <> (0)::double precision) AND (share.visit_type_id = 1))
UNION
 SELECT doctormaster.first_name,
    doctormaster.last_name,
    speciality.speciality_name,
    billmaster.bill_number,
    billmaster.bill_date_time,
    servicemaster.service_standard_name,
    share.bill_dtl_id,
    share.ord_dtl_id,
    share.admission_id AS visit_id,
    share.visit_type_id,
    share.service_id,
    share.unit_rate,
    share.total_amount,
    share.discount,
    share.due_share_amt,
    share.share_per,
    share.doc_share,
    share.processed_share_amt,
    share.hosp_share,
    share.processed_share_date,
    share.doc_id,
    share.doc_spec_id,
    share.doctor_share_id
   FROM (((((billing.t_doctor_share share
     JOIN doctor.m_doctor_master doctormaster ON ((share.doc_id = doctormaster.doctor_id)))
     JOIN doctor.m_speciality_master speciality ON ((share.doc_spec_id = speciality.speciality_id)))
     JOIN service.m_service_master servicemaster ON ((share.service_id = servicemaster.service_master_id)))
     JOIN billing.t_billing_details billdetails ON ((share.bill_dtl_id = billdetails.billing_details_id)))
     JOIN billing.m_billing_master billmaster ON ((billdetails.billing_master_id = billmaster.billing_master_id)))
  WHERE ((share.doc_share <> (0)::double precision) AND (share.visit_type_id = 2));


--
-- TOC entry 3477 (class 1259 OID 3695102)
-- Name: doctorsharedetails; Type: VIEW; Schema: doctor; Owner: -
--

CREATE VIEW doctor.doctorsharedetails AS
 SELECT doctormaster.first_name,
    doctormaster.last_name,
    speciality.speciality_name,
    billmaster.bill_number,
    billmaster.bill_date_time,
    servicemaster.service_standard_name,
    share.bill_dtl_id,
    share.ord_dtl_id,
    share.admission_id AS visit_id,
    share.visit_type_id,
    share.service_id,
    share.unit_rate,
    share.total_amount,
    share.discount,
    share.due_share_amt,
    share.share_per,
    share.doc_share,
    share.processed_share_amt,
    share.hosp_share,
    share.processed_share_date,
    share.doc_id,
    share.doc_spec_id,
    share.doctor_share_id,
    speciality.speciality_id,
    unit.unit_name,
    unit.unit_address,
    unit.unit_id,
    unit.image
   FROM ((((((billing.t_doctor_share share
     JOIN doctor.m_doctor_master doctormaster ON ((share.doc_id = doctormaster.doctor_id)))
     JOIN doctor.m_speciality_master speciality ON ((share.doc_spec_id = speciality.speciality_id)))
     JOIN service.m_service_master servicemaster ON ((share.service_id = servicemaster.service_master_id)))
     JOIN billing.t_billing_details billdetails ON ((share.bill_dtl_id = billdetails.billing_details_id)))
     JOIN billing.m_billing_master billmaster ON ((billdetails.billing_master_id = billmaster.billing_master_id)))
     LEFT JOIN public.unitinformation unit ON ((share.org_unit_id = unit.unit_id)))
  WHERE (share.doc_share <> (0)::double precision);


