CREATE VIEW doctor.ipddoctorinformation AS
 SELECT m_doctor_master.doctor_id,
    (((('Dr. '::text || ' '::text) || (m_doctor_master.first_name)::text) || ' '::text) || (m_doctor_master.last_name)::text) AS doctorname,
    m_gender_master.gender_name,
    m_doctor_category.doctor_category_description,
    m_speciality_master.speciality_name,
    age(m_doctor_master.dob) AS docage,
    m_doctor_master.dob,
    m_doctor_master.country_calling_code,
    m_doctor_master.mobile_number,
    m_doctor_master.email,
    m_doctor_master.doctor_image,
    m_doctor_master.registration_number AS docreg
   FROM ((((adt.t_admission
     LEFT JOIN doctor.m_doctor_master ON ((t_admission.doctor_id = m_doctor_master.doctor_id)))
     LEFT JOIN doctor.m_speciality_master ON ((t_admission.speciality_id = m_speciality_master.speciality_id)))
     LEFT JOIN public.m_gender_master ON ((m_doctor_master.gender_id = m_gender_master.gender_id)))
     LEFT JOIN public.m_doctor_category ON ((m_doctor_master.doc_category_id = m_doctor_category.doctor_category_id)));


