--
-- TOC entry 3708 (class 1259 OID 4596538)
-- Name: get_machine_data; Type: VIEW; Schema: lab; Owner: -
--

CREATE VIEW lab.get_machine_data AS
 SELECT DISTINCT testmaster.test_desc,
    mmp.machine_parameter_desc AS machineparname,
        CASE
            WHEN (om.admission_id IS NULL) THEN em.encounter_number
            WHEN (om.admission_id IS NOT NULL) THEN adm.admission_number
            ELSE NULL::character varying
        END AS opipdno,
    om.order_date AS date,
    samplemaster.sample_id AS sample_no,
    prefix.prefix_desc AS prefix,
    reg.last_name,
    reg.first_name,
    reg.middle_name,
    (abs(date_part('Year'::text, age((to_char(reg.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS ageyear,
    (abs(date_part('Month'::text, age((to_char(reg.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS agemonth,
    (abs(date_part('Day'::text, age((to_char(reg.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS ageday,
    pim.gender_name AS sex,
    mmm.machine_desc,
    om.admission_id,
    om.encounter_id,
    samplemaster.lab_sample_id,
    mmm.machine_id,
    um.unit_id,
    um.organization_id,
    pim.patient_id,
    (reg.dob)::date AS dob,
    mmp.code AS machineparacode
   FROM ((((((((((((((public.t_order_master om
     JOIN lab.t_lab_sample_master samplemaster ON ((om.order_id = samplemaster.order_id)))
     JOIN lab.t_lab_sample_dtls sampledetail ON ((samplemaster.lab_sample_id = sampledetail.lab_sample_id)))
     JOIN lab.m_test_master testmaster ON ((sampledetail.test_id = testmaster.test_id)))
     JOIN lab.t_test_parameter_mppr testparmapper ON (((sampledetail.test_id = testparmapper.test_id) AND (testparmapper.org_id = om.org_id) AND (testparmapper.org_unit_id = om.org_unit_id))))
     JOIN lab.m_parameter_master parammaster ON ((testparmapper.parameter_id = parammaster.parameter_id)))
     JOIN lab.t_machine_parameter_mppr machinepara ON (((testparmapper.parameter_id = machinepara.parameter_id) AND (machinepara.organisation_id = om.org_id) AND (machinepara.unit_id = om.org_unit_id))))
     JOIN lab.m_machine_parameter mmp ON ((machinepara.machin_parameter_id = mmp.machin_parameter_id)))
     JOIN lab.m_machine_master mmm ON ((mmp.machine_id = mmm.machine_id)))
     LEFT JOIN adt.t_admission adm ON ((om.admission_id = adm.admission_id)))
     LEFT JOIN opd.t_encounter_master em ON ((om.encounter_id = em.encounter_id)))
     JOIN public.patientinformation pim ON ((om.patient_id = pim.patient_id)))
     JOIN patient.t_patient_registration reg ON ((pim.patient_id = reg.patient_id)))
     JOIN public.m_prefix_master prefix ON ((reg.prefix_id = prefix.prefix_id)))
     JOIN public.unitinformation um ON ((um.unit_id = om.org_unit_id)))
  WHERE ((machinepara.status = 'A'::bpchar) AND (testparmapper.test_para_status = 'A'::bpchar));


