--
-- TOC entry 1835 (class 1259 OID 2976158)
-- Name: get_turnaroundtime; Type: VIEW; Schema: lab; Owner: -
--

CREATE VIEW lab.get_turnaroundtime AS
 SELECT sample_dtls.test_id,
    testmaster.test_desc,
    ((date_part('day'::text, (sample_dtls.sample_accept_datetime - sample_dtls.sample_collection_datetime)) * (24)::double precision) + date_part('hour'::text, (sample_dtls.sample_accept_datetime - sample_dtls.sample_collection_datetime))) AS collection_to_accept,
    ((date_part('day'::text, (test_result.result_enter_datetime - sample_dtls.sample_accept_datetime)) * (24)::double precision) + date_part('hour'::text, (test_result.result_enter_datetime - sample_dtls.sample_accept_datetime))) AS accept_to_resultentry,
    ((date_part('day'::text, (test_result.result_authorised_datetime - test_result.result_enter_datetime)) * (24)::double precision) + date_part('hour'::text, (test_result.result_authorised_datetime - test_result.result_enter_datetime))) AS resultentry_to_release,
    (sample_dtls.sample_collection_datetime)::date AS sample_collection_datetime,
    sample_dtls.org_unit_id,
    um.unit_name,
    um.unit_address,
    um.unit_id,
    um.image
   FROM (((lab.t_lab_sample_dtls sample_dtls
     JOIN lab.t_lab_test_result test_result ON ((test_result.lab_sample_dtls_id = sample_dtls.lab_sample_dtls_id)))
     JOIN lab.m_test_master testmaster ON ((sample_dtls.test_id = testmaster.test_id)))
     LEFT JOIN public.unitinformation um ON ((sample_dtls.org_unit_id = um.unit_id)));


