-- Name: investigationslip; Type: VIEW; Schema: lab; Owner: -
--

CREATE VIEW lab.investigationslip AS
 SELECT DISTINCT t_order_master.order_id,
    t_order_master.order_date,
    t_order_master.order_no,
    t_order_details.order_details_id,
    t_order_details.order_qty,
    m_service_master.service_standard_name,
    patientinformation.prefix_id,
    patientinformation.uhid_number,
    patientinformation.patientname,
    patientinformation.gender_name,
    patientinformation.bar_code,
    patientinformation.age,
    patientinformation.mobile_number,
    patientinformation.email,
    patientinformation.patientmobile,
    patientinformation.patientemail,
    patientinformation.reg_type,
    patientinformation.patientgender,
    patientinformation.patient_category,
    patientinformation.regdate,
    patientinformation.is_vip,
    patientinformation.patientdob,
    patientinformation.identification_number,
    patientinformation.identification_expiry_date,
    patientinformation.patientaddress,
    patientinformation.zip_code,
    patientinformation.phone_number,
    patientinformation.patient_id,
    patientinformation.marital_status_name,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_email_id,
    unitinformation.unit_logo,
    unitinformation.post_code,
    unitinformation.unit_contact,
    unitinformation.unit_contact_2,
    unitinformation.unit_contact_3,
    unitinformation.unit_country_code,
    unitinformation.registration_number,
    unitinformation.unit_website,
    unitinformation.currency_name,
    unitinformation.sub_currency,
    COALESCE(t_order_details.ord_cancelled, ('N'::character varying)::bpchar) AS ord_cancelled,
    doctormaster.doctor_id,
    doctormaster.doctorname,
    doctormaster.docgender,
    doctormaster.doctor_category_description,
    doctormaster.docspeciality,
    doctormaster.docage,
    doctormaster.docdob,
    doctormaster.country_calling_code,
    doctormaster.docmobile,
    doctormaster.docemail,
    doctormaster.doctor_image,
    doctormaster.docreg,
    doctormaster.slot_time_span,
    doctormaster.doctor_episod_time_span,
    doctormaster.encounter_id,
    doctormaster.speciality_id,
    m_speciality_master.speciality_name AS groupname,
    t_order_master.created_by,
    t_order_details.created_by AS dtlscreated_by,
    m_service_master.speciality_id AS groupid
   FROM (((((((public.t_order_master
     JOIN public.t_order_details ON (((t_order_master.order_id = t_order_details.order_id) AND (t_order_master.visit_type_id = 1))))
     LEFT JOIN opd.t_encounter_master ON ((t_order_master.encounter_id = t_encounter_master.encounter_id)))
     LEFT JOIN patient.patientinformation ON ((t_encounter_master.patient_id = patientinformation.patient_id)))
     LEFT JOIN service.m_service_master ON ((t_order_details.service_id = m_service_master.service_master_id)))
     LEFT JOIN public.unitinformation ON ((t_order_master.org_unit_id = unitinformation.unit_id)))
     LEFT JOIN doctor.doctorinformation doctormaster ON ((t_encounter_master.encounter_id = doctormaster.encounter_id)))
     LEFT JOIN doctor.m_speciality_master ON ((m_service_master.speciality_id = m_speciality_master.speciality_id)))
  ORDER BY t_order_details.order_details_id;


