        CASE
            WHEN (COALESCE(dm.user_id, 0) = 0) THEN (((m_employee_master.first_name)::text || ' '::text) || (m_employee_master.last_name)::text)
            ELSE ((('Dr.'::text || ''::text) || ((dm.first_name)::text || ' '::text)) || (dm.last_name)::text)
