     LEFT JOIN doctor.m_doctor_master dm ON ((t_vital.created_by = dm.user_id)))
     LEFT JOIN public.m_user_master um ON ((t_vital.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master ON ((um.user_id = m_employee_master.user_id)))
  WHERE (((t_vital.value)::text <> ''::text) AND (t_vital.is_entered_in_error = 'N'::bpchar) AND (t_vital.is_post_facto = 'N'::bpchar));


