-- TOC entry 3480 (class 1259 OID 3695117)
-- Name: get_ot_register_completed; Type: VIEW; Schema: otims; Owner: -
--

CREATE VIEW otims.get_ot_register_completed AS
 SELECT DISTINCT reqmst.pro_req_id,
    pim.uhid_number,
    pim.patientname,
    reqmst.visit_type_id,
    visittype.visit_type_name,
    um.user_name AS username,
    reqmst.primary_procedure_id,
    servicemaster.service_standard_name AS procedurename,
    typemaster.procedure_type_desc,
    anes_type.anesthesia_type_desc,
    tabletype.table_desc,
    time_sheet.procedure_start_time,
    time_sheet.procedure_end_time,
    reqmst.ot_bill_completion_date_time,
    typemaster.procedure_type_id,
    unit.unit_name,
    unit.unit_address,
    ordermaster.amount,
    rolemaster.role_name,
    (((('Dr.'::text || ''::text) || (docmaster.first_name)::text) || ' '::text) || (docmaster.last_name)::text) AS doctor,
    (staff.created_date)::date AS staffcompletiondate,
    unit.unit_id,
    unit.image
   FROM ((((((((((((((((otims.t_procedure_req_mst reqmst
     JOIN public.patientinformation pim ON ((reqmst.patient_id = pim.patient_id)))
     JOIN public.m_visit_type_master visittype ON ((reqmst.visit_type_id = visittype.visit_type_id)))
     LEFT JOIN public.m_user_master um ON ((reqmst.request_by = um.user_id)))
     LEFT JOIN otims.t_procedure_order_master ordermaster ON ((reqmst.pro_req_id = ordermaster.pro_req_id)))
     LEFT JOIN otims.t_procedure_order_service orderservice ON (((reqmst.pro_req_id = orderservice.procedure_request_id) AND (reqmst.primary_procedure_id = orderservice.service_id))))
     LEFT JOIN service.m_service_master servicemaster ON ((reqmst.primary_procedure_id = servicemaster.service_master_id)))
     LEFT JOIN otims.t_procedure_configuration proc_config ON ((servicemaster.service_master_id = proc_config.service_id)))
     LEFT JOIN otims.m_procedure_type_master typemaster ON ((proc_config.procedure_type_id = typemaster.procedure_type_id)))
     LEFT JOIN otims.m_anesthesia_type_master anes_type ON ((proc_config.anesthesia_type_id = anes_type.anesthesia_type_id)))
     LEFT JOIN otims.m_operation_table_type tabletype ON ((proc_config.operation_theatre_type_id = tabletype.operation_table_type_id)))
     LEFT JOIN otims.t_ot_completion_time_sheet time_sheet ON ((reqmst.pro_req_id = time_sheet.pro_req_id)))
     LEFT JOIN public.unitinformation unit ON ((reqmst.unit_id = unit.unit_id)))
     JOIN otims.t_ot_completion_staff staff ON ((reqmst.pro_req_id = staff.proc_req_id)))
     LEFT JOIN doctor.m_doctor_master docmaster ON ((staff.doctor_id = docmaster.doctor_id)))
     LEFT JOIN otims.t_procedure_staff_schedule staff_schedule ON ((reqmst.pro_req_id = staff_schedule.pro_req_id)))
     LEFT JOIN public.m_role_master rolemaster ON ((staff_schedule.role_id = rolemaster.role_id)))
  WHERE (ordermaster.is_primary_secondary = 'Y'::"char");


