--
-- TOC entry 3481 (class 1259 OID 3695122)
-- Name: get_ot_reservation; Type: VIEW; Schema: otims; Owner: -
--

CREATE VIEW otims.get_ot_reservation AS
 SELECT DISTINCT otr.ot_reservation_id,
    otr.ot_reservation_no,
    pim.patient_id,
    pim.patientname,
    theatre.theatre_name,
    ottable.table_name,
    staffschedule.created_date,
    staffschedule.f_time,
    visittype.visit_type_name,
    servicemaster.service_standard_name,
    om.is_primary_secondary,
    fordoctor.user_id,
    fordoctor.doctor,
    um.unit_name,
    um.unit_address,
    um.unit_id,
    um.image
   FROM (((((((((((otims.t_ot_reservation otr
     JOIN public.patientinformation pim ON ((otr.patient_id = pim.patient_id)))
     JOIN otims.t_procedure_ot_schedule staffschedule ON ((otr.schedule_id = staffschedule.procedure_schedule_id)))
     JOIN otims.m_operation_theatre theatre ON ((staffschedule.theatre_id = theatre.operation_theatre_id)))
     JOIN otims.m_operation_table ottable ON ((staffschedule.table_id = ottable.operation_table_id)))
     JOIN otims.t_procedure_req_mst reqmaster ON ((otr.pro_req_id = reqmaster.pro_req_id)))
     JOIN public.m_visit_type_master visittype ON ((reqmaster.visit_type_id = visittype.visit_type_id)))
     JOIN otims.t_procedure_order_master om ON ((om.pro_req_id = otr.pro_req_id)))
     JOIN service.m_service_master servicemaster ON ((om.service_id = servicemaster.service_master_id)))
     JOIN otims.t_procedure_order_staff orderstaff ON ((orderstaff.procedure_order_id = om.procedure_order_id)))
     LEFT JOIN public.unitinformation um ON ((otr.unit_id = um.unit_id)))
     JOIN ( SELECT DISTINCT doctorsched.pro_req_id,
            doctorsched.user_id,
            (((('Dr.'::text || ''::text) || (docmaster.first_name)::text) || ' '::text) || (docmaster.last_name)::text) AS doctor
           FROM (otims.t_procedure_staff_schedule doctorsched
             LEFT JOIN doctor.m_doctor_master docmaster ON ((doctorsched.user_id = docmaster.user_id)))
          WHERE (doctorsched.role_id = 3)) fordoctor ON ((otr.pro_req_id = fordoctor.pro_req_id)));


