--
-- TOC entry 3518 (class 1259 OID 3695309)
-- Name: get_otprocedure_details; Type: VIEW; Schema: otims; Owner: -
--

CREATE VIEW otims.get_otprocedure_details AS
 SELECT DISTINCT pr.uhid_number AS uhidnumber,
    concat(COALESCE(prefix_mst.prefix_code), ' ', COALESCE(pr.first_name), ' ', COALESCE(pr.last_name)) AS "patientName",
    pr.patient_id AS patientid,
    to_char(adtdtls.doa, 'dd/MM/yyyy'::text) AS doa,
    to_char(adtdtls.pdd, 'dd/MM/yyyy'::text) AS pdd,
    to_char(pr.dob, 'DD/MM/YYYY'::text) AS birthdate,
    prm.admission_id AS admissionid,
    prm.encounter_id AS encounterid,
    prm.pro_req_id AS proreqid,
    bm.bed_number AS bednumber,
    ward.ward_name AS wardname,
    prm.visit_type_id AS visittypeid,
    to_char((prm.prefered_time)::interval, 'hh24:mi:ss'::text) AS prefertime,
    gender.gender_code AS gendercode,
    concat(date_part('year'::text, age(CURRENT_TIMESTAMP, (pr.dob)::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, (pr.dob)::timestamp with time zone)), 'M ') AS age,
    to_char(prm.prefered_date_time, 'DD-MM-YYYY'::text) AS scheduledate,
    prm.procedure_status_id AS proceduerstatusid,
    prost.status AS procedurestatusname,
    prm.emergency,
    otdetails.total_hrs AS totalduration,
    servicemaster.service_standard_name AS procedurename,
    staff.doctor,
    staff.service_standard_name AS servicename,
    ordermaster.is_primary_secondary,
    proctype.procedure_type_desc,
    servicemaster1.service_standard_name AS servicedetail,
    proctype.procedure_type_id,
    prm.visit_type_id,
    prm.primary_procedure_id,
    anesthesia.anesthesia_type_name,
    tbl.table_name,
    otdetails.ot_sheet_no,
    unitmaster.unit_name,
    unitmaster.unit_address,
    staff.role_id,
    prm.unit_id,
    staff.doctor_id,
    staff.speciality_name,
    staff.speciality_id,
    prm.ot_bill_completion_date_time,
    prm.created_date,
    unitmaster.image
   FROM ((((((((((((((((((((otims.t_procedure_req_mst prm
     JOIN otims.m_procedure_order_status prost ON ((prm.procedure_status_id = prost.id)))
     JOIN otims.t_ot_completion_details otdetails ON ((otdetails.pro_req_id = prm.pro_req_id)))
     LEFT JOIN otims.m_operation_table tbl ON ((otdetails.ot_table_id = tbl.operation_table_id)))
     JOIN patient.t_patient_registration pr ON ((prm.patient_id = pr.patient_id)))
     JOIN public.m_prefix_master prefix_mst ON ((pr.prefix_id = prefix_mst.prefix_id)))
     LEFT JOIN adt.t_admission admission ON ((prm.admission_id = admission.admission_id)))
     LEFT JOIN adt.t_admission_details adtdtls ON (((admission.admission_id = adtdtls.admission_id) AND (adtdtls.status = 'A'::bpchar))))
     LEFT JOIN adt.m_bed_master bm ON ((adtdtls.bed_id = bm.bed_id)))
     LEFT JOIN adt.m_ward_master ward ON ((bm.ward_id = ward.ward_id)))
     LEFT JOIN opd.t_encounter_master encounter ON ((prm.encounter_id = encounter.encounter_id)))
     JOIN public.m_gender_master gender ON ((pr.gender_id = gender.gender_id)))
     LEFT JOIN public.unitinformation unitmaster ON ((prm.unit_id = unitmaster.unit_id)))
     LEFT JOIN otims.t_procedure_order_master ordermaster ON ((prm.pro_req_id = ordermaster.pro_req_id)))
     LEFT JOIN otims.t_procedure_order_service orderservice ON ((prm.pro_req_id = orderservice.procedure_request_id)))
     LEFT JOIN service.m_service_master servicemaster ON ((ordermaster.service_id = servicemaster.service_master_id)))
     LEFT JOIN service.m_service_master servicemaster1 ON ((orderservice.service_id = servicemaster1.service_master_id)))
     LEFT JOIN otims.t_procedure_configuration proc_config ON ((servicemaster.service_master_id = proc_config.service_id)))
     LEFT JOIN otims.m_procedure_type_master proctype ON ((proc_config.procedure_type_id = proctype.procedure_type_id)))
     LEFT JOIN otims.m_anesthesia_type_master anesthesia ON ((proc_config.anesthesia_type_id = anesthesia.anesthesia_type_id)))
     LEFT JOIN ( SELECT staff_1.proc_req_id,
            rolemaster.role_name,
            (((('Dr.'::text || ''::text) || (docmaster.first_name)::text) || ' '::text) || (docmaster.last_name)::text) AS doctor,
            servicemaster_1.service_standard_name,
            rolemaster.role_id,
            docmaster.doctor_id,
            sm.speciality_name,
            sm.speciality_id
           FROM (((((otims.t_ot_completion_staff staff_1
             JOIN doctor.m_doctor_master docmaster ON ((staff_1.doctor_id = docmaster.doctor_id)))
             JOIN otims.t_procedure_staff_schedule staff_schedule ON ((staff_1.proc_req_id = staff_schedule.pro_req_id)))
             LEFT JOIN public.m_role_master rolemaster ON ((staff_schedule.role_id = rolemaster.role_id)))
             LEFT JOIN service.m_service_master servicemaster_1 ON ((staff_1.service_id = servicemaster_1.service_master_id)))
             LEFT JOIN doctor.m_speciality_master sm ON ((servicemaster_1.speciality_id = sm.speciality_id)))) staff ON ((prm.pro_req_id = staff.proc_req_id)))
  WHERE ((prm.procedure_status_id = ANY (ARRAY[2, 3, 4])) AND (prm.emergency = true) AND (ordermaster.status = 'A'::bpchar))
UNION
 SELECT DISTINCT pr.uhid_number AS uhidnumber,
    concat(COALESCE(prefix_mst.prefix_code), ' ', COALESCE(pr.first_name), ' ', COALESCE(pr.last_name)) AS "patientName",
    pr.patient_id AS patientid,
    to_char(adtdtls.doa, 'dd/MM/yyyy'::text) AS doa,
    to_char(adtdtls.pdd, 'dd/MM/yyyy'::text) AS pdd,
    to_char(pr.dob, 'DD/MM/YYYY'::text) AS birthdate,
    prm.admission_id AS admissionid,
    prm.encounter_id AS encounterid,
    prm.pro_req_id AS proreqid,
    bm.bed_number AS bednumber,
    ward.ward_name AS wardname,
    prm.visit_type_id AS visittypeid,
    to_char((prm.prefered_time)::interval, 'hh24:mi:ss'::text) AS prefertime,
    gender.gender_code AS gendercode,
    concat(date_part('year'::text, age(CURRENT_TIMESTAMP, (pr.dob)::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, (pr.dob)::timestamp with time zone)), 'M ') AS age,
    to_char(prm.prefered_date_time, 'DD-MM-YYYY'::text) AS scheduledate,
    prm.procedure_status_id AS proceduerstatusid,
    prost.status AS procedurestatusname,
    prm.emergency,
    0 AS totalduration,
    servicemaster.service_standard_name AS procedurename,
    staff.doctor,
    staff.service_standard_name AS servicename,
    ordermaster.is_primary_secondary,
    proctype.procedure_type_desc,
    servicemaster1.service_standard_name AS servicedetail,
    proctype.procedure_type_id,
    prm.visit_type_id,
    prm.primary_procedure_id,
    anesthesia.anesthesia_type_name,
    tbl.table_name,
    ''::text AS ot_sheet_no,
    unitmaster.unit_name,
    unitmaster.unit_address,
    staff.role_id,
    prm.unit_id,
    staff.doctor_id,
    staff.speciality_name,
    staff.speciality_id,
    prm.ot_bill_completion_date_time,
    prm.created_date,
    unitmaster.image
   FROM ((((((((((((((((((((((((otims.t_procedure_req_mst prm
     JOIN otims.t_procedure_schedule schedule ON ((prm.pro_req_id = schedule.pro_req_id)))
     JOIN otims.m_procedure_order_status prost ON ((prm.procedure_status_id = prost.id)))
     JOIN otims.t_procedure_configuration proconfig ON ((prm.primary_procedure_id = proconfig.service_id)))
     JOIN otims.t_procedure_ot_schedule otdetails ON ((schedule.procedure_schedule_id = otdetails.procedure_schedule_id)))
     JOIN otims.m_operation_theatre ot ON ((otdetails.theatre_id = ot.operation_theatre_id)))
     JOIN otims.m_operation_table tbl ON ((otdetails.table_id = tbl.operation_table_id)))
     LEFT JOIN doctor.m_doctor_master doc ON ((doc.user_id = prm.created_by)))
     JOIN patient.t_patient_registration pr ON ((prm.patient_id = pr.patient_id)))
     JOIN public.m_prefix_master prefix_mst ON ((pr.prefix_id = prefix_mst.prefix_id)))
     LEFT JOIN adt.t_admission admission ON ((prm.admission_id = admission.admission_id)))
     LEFT JOIN adt.t_admission_details adtdtls ON (((admission.admission_id = adtdtls.admission_id) AND (adtdtls.status = 'A'::bpchar))))
     LEFT JOIN adt.m_bed_master bm ON ((adtdtls.bed_id = bm.bed_id)))
     LEFT JOIN adt.m_ward_master ward ON ((bm.ward_id = ward.ward_id)))
     LEFT JOIN opd.t_encounter_master encounter ON ((prm.encounter_id = encounter.encounter_id)))
     JOIN public.m_gender_master gender ON ((pr.gender_id = gender.gender_id)))
     LEFT JOIN public.unitinformation unitmaster ON ((prm.unit_id = unitmaster.unit_id)))
     LEFT JOIN otims.t_procedure_order_master ordermaster ON ((prm.pro_req_id = ordermaster.pro_req_id)))
     LEFT JOIN otims.t_procedure_order_service orderservice ON ((prm.pro_req_id = orderservice.procedure_request_id)))
     LEFT JOIN service.m_service_master servicemaster ON ((ordermaster.service_id = servicemaster.service_master_id)))
     LEFT JOIN service.m_service_master servicemaster1 ON ((orderservice.service_id = servicemaster1.service_master_id)))
     LEFT JOIN otims.t_procedure_configuration proc_config ON ((servicemaster.service_master_id = proc_config.service_id)))
     LEFT JOIN otims.m_procedure_type_master proctype ON ((proc_config.procedure_type_id = proctype.procedure_type_id)))
     LEFT JOIN otims.m_anesthesia_type_master anesthesia ON ((proc_config.anesthesia_type_id = anesthesia.anesthesia_type_id)))
     LEFT JOIN ( SELECT staff_1.proc_req_id,
            rolemaster.role_name,
            (((('Dr.'::text || ''::text) || (docmaster.first_name)::text) || ' '::text) || (docmaster.last_name)::text) AS doctor,
            servicemaster_1.service_standard_name,
            rolemaster.role_id,
            docmaster.doctor_id,
            sm.speciality_name,
            sm.speciality_id
           FROM (((((otims.t_ot_completion_staff staff_1
             JOIN doctor.m_doctor_master docmaster ON ((staff_1.doctor_id = docmaster.doctor_id)))
             JOIN otims.t_procedure_staff_schedule staff_schedule ON ((staff_1.proc_req_id = staff_schedule.pro_req_id)))
             LEFT JOIN public.m_role_master rolemaster ON ((staff_schedule.role_id = rolemaster.role_id)))
             LEFT JOIN service.m_service_master servicemaster_1 ON ((staff_1.service_id = servicemaster_1.service_master_id)))
             LEFT JOIN doctor.m_speciality_master sm ON ((servicemaster_1.speciality_id = sm.speciality_id)))) staff ON ((prm.pro_req_id = staff.proc_req_id)))
  WHERE ((prm.procedure_status_id = ANY (ARRAY[2, 3, 4])) AND (schedule.status = 'A'::bpchar) AND (otdetails.status = 'A'::bpchar) AND (ordermaster.status = 'A'::bpchar) AND (prm.emergency = false))
  ORDER BY 1, 24 DESC;


