--
-- TOC entry 3483 (class 1259 OID 3695132)
-- Name: groupwise_receipt_report; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.groupwise_receipt_report AS
 SELECT DISTINCT bd.service_id,
    sm.service_standard_name,
    bd.rate,
    bd.quantity,
    bd.concession,
    bd.gross_amount,
    bd.co_pay_percentage,
    bd.unit_id,
    bd.created_by,
    bd.created_date,
    bd.discount,
    bd.tax_amount,
    bd.net_amt,
    bd.self_payable,
    em.encounter_number,
    em.encounter_date,
    sm.speciality_id,
    dsm.speciality_name,
    ssm.sub_speciality_id,
    ssm.sub_speciality_name,
    ad.admission_id,
    bm.patient_id,
    ((((pm.prefix_desc || ' '::text) || (pr.first_name)::text) || (pr.middle_name)::text) || (pr.last_name)::text) AS patient_name,
    bm.visit_type_id,
    vtm.visit_type_name,
    bd.billing_details_id,
    um.user_id,
    ((((upm.prefix_desc || ' '::text) || (emp.first_name)::text) || ' '::text) || (emp.last_name)::text) AS user_name,
    ui.unit_name,
    ui.unit_address,
    bm.bill_number,
    prm.reciept_number,
    prm.date_of_reciept,
    prm.amount
   FROM ((((((((((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bd ON ((bm.billing_master_id = bd.billing_master_id)))
     LEFT JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     LEFT JOIN opd.t_encounter_master em ON ((bm.encounter_id = em.encounter_id)))
     LEFT JOIN doctor.m_speciality_master dsm ON ((sm.speciality_id = dsm.speciality_id)))
     LEFT JOIN doctor.m_sub_speciality_master ssm ON ((sm.sub_speciality_id = ssm.sub_speciality_id)))
     LEFT JOIN adt.t_admission ad ON ((bm.admission_id = ad.admission_id)))
     LEFT JOIN patient.t_patient_registration pr ON ((bm.patient_id = pr.patient_id)))
     LEFT JOIN public.m_prefix_master pm ON ((pr.prefix_id = pm.prefix_id)))
     LEFT JOIN public.m_visit_type_master vtm ON ((bm.visit_type_id = vtm.visit_type_id)))
     LEFT JOIN public.m_user_master um ON ((bd.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
     LEFT JOIN public.m_prefix_master upm ON ((emp.prefix_id = upm.prefix_id)))
     LEFT JOIN public.unitinformation ui ON ((bd.unit_id = ui.unit_id)))
     LEFT JOIN billing.t_payment_reciept_master prm ON ((bm.billing_master_id = prm.billing_master_id)))
  WHERE (bm.bill_status_id = 3)
  ORDER BY bm.bill_number;


