-- Name: mis_issue_to_department_list_report; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.mis_issue_to_department_list_report AS
 SELECT DISTINCT indentmaster.id AS indentid,
    (indentmaster.added_date)::date AS added_date,
    indentmaster.indent_no,
    storefrom.store_name AS fromstore,
    storeto.store_name AS tostore,
    indenttype.type,
    m_status.status,
    prioritymaster.priority_desc,
    storefrom.store_id AS fromstoreid,
    storeto.store_id AS tostoreid,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_email_id,
    prioritymaster.priority_id,
    indenttype.id AS typeid,
    m_status.id AS status_id
   FROM (((((((inventory.t_store_indent indentmaster
     JOIN inventory.t_store_indent_detail indentdetails ON ((indentmaster.id = indentdetails.store_indent_id)))
     LEFT JOIN public.m_store storefrom ON ((indentmaster.from_store_id = storefrom.store_id)))
     LEFT JOIN public.m_store storeto ON ((indentmaster.to_store_id = storeto.store_id)))
     LEFT JOIN inventory.m_indent_type indenttype ON ((indentmaster.indent_type_id = indenttype.id)))
     LEFT JOIN public.m_status ON ((indentmaster.status_id = m_status.id)))
     LEFT JOIN adt.m_priority_master prioritymaster ON ((indentmaster.priority_id = prioritymaster.priority_id)))
     LEFT JOIN public.unitinformation ON ((indentmaster.unit_id = unitinformation.unit_id)))
  ORDER BY indentmaster.id;


--
-- TOC entry 3484 (class 1259 OID 3695137)
-- Name: mis_patient_charge_detail_report; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.mis_patient_charge_detail_report AS
 SELECT DISTINCT bm.billing_master_id,
    bm.encounter_id,
    bm.visit_type_id,
    bm.patient_id,
    bm.bill_number,
    bm.bill_date_time,
    bm.net_amount,
    bm.discount_amount,
        CASE
            WHEN (bm.is_credit_bill = 'Y'::"char") THEN 'Credit'::text
            ELSE 'Self'::text
        END AS credit_paid,
    bm.unit_id,
    bm.concession_amount,
    bm.gst,
    bm.total_bill_amount,
    bm.outstanding,
    bm.round_off,
    bm.bill_status_id,
    bm.admission_id,
    bm.cr_amount,
    bm.total_self_payable,
    bm.total_credit_payable,
    bm.disallowed_amount,
    bd.service_id,
    sm.service_standard_name,
    bd.rate,
    bd.quantity,
    bd.concession,
    bd.gross_amount,
    bd.discount,
    bd.tax_per,
    bd.tax_amount,
    bd.net_amt,
    bd.self_payable,
    bd.credit_payable,
    ((((((pm.prefix_desc || ' '::text) || (pr.first_name)::text) || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS patient_name,
    vtm.visit_type_name,
    em.encounter_number,
    em.encounter_date,
    adm.admission_number,
    adm.admitting_doctor_id,
    adm.created_date,
    (((('Dr. '::text || ' '::text) || (dm.first_name)::text) || ' '::text) || (dm.last_name)::text) AS opd_doctor,
    (((('Dr.'::text || ' '::text) || (addm.first_name)::text) || ' '::text) || (addm.last_name)::text) AS admitting_doctor,
        CASE
            WHEN (bm.bill_status_id = 1) THEN 'Pending'::text
            WHEN (bm.bill_status_id = 2) THEN 'On Hold'::text
            ELSE 'Settle'::text
        END AS bill_status,
    ((((upm.prefix_desc || ' '::text) || (emp.first_name)::text) || ' '::text) || (emp.last_name)::text) AS user_name,
    um.user_id,
    bd.billing_details_id,
    u.unit_name,
    u.unit_address
   FROM (((((((((((((billing.m_billing_master bm
     LEFT JOIN billing.t_billing_details bd ON ((bm.billing_master_id = bd.billing_master_id)))
     LEFT JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     LEFT JOIN public.m_visit_type_master vtm ON ((bm.visit_type_id = vtm.visit_type_id)))
     LEFT JOIN patient.t_patient_registration pr ON ((bm.patient_id = pr.patient_id)))
     LEFT JOIN public.m_prefix_master pm ON ((pr.prefix_id = pm.prefix_id)))
     LEFT JOIN opd.t_encounter_master em ON ((bm.encounter_id = em.encounter_id)))
     LEFT JOIN adt.t_admission adm ON ((bm.admission_id = adm.admission_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((em.doctor_id = dm.doctor_id)))
     LEFT JOIN doctor.m_doctor_master addm ON ((adm.admitting_doctor_id = addm.doctor_id)))
     LEFT JOIN public.unitinformation u ON ((bm.unit_id = u.unit_id)))
     LEFT JOIN public.m_user_master um ON ((bd.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
     LEFT JOIN public.m_prefix_master upm ON ((emp.prefix_id = upm.prefix_id)));


