--
-- TOC entry 2309 (class 1259 OID 2978241)
-- Name: mis_pending_purchase_order_report; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.mis_pending_purchase_order_report AS
 SELECT DISTINCT po.id AS poid,
    po.unit_id,
    u.unit_name,
    u.unit_address,
    po.vendor_id,
    ve.name AS vendor_name,
    s.store_id,
    s.store_name,
    po.po_number,
    po.total_amount,
    dt.type AS discount_type,
    po.discount,
    po.total_discount,
    po.total_tax_amount,
    po.total_other_amount,
    po.net_amount,
    po.round_off_amount,
    st.status,
    po.remark,
    po.status_id,
    po.grn_id,
    ((((pm.prefix_desc || ' '::text) || (emp.first_name)::text) || ' '::text) || (emp.last_name)::text) AS user_name,
    po.added_date,
    po.added_by,
    um.user_id
   FROM ((((((((procurement.t_purchase_order po
     LEFT JOIN public.unitinformation u ON ((po.unit_id = u.unit_id)))
     LEFT JOIN public.m_vendor ve ON ((po.vendor_id = ve.id)))
     LEFT JOIN public.m_store s ON ((po.store_id = s.store_id)))
     LEFT JOIN public.m_discount_type dt ON ((po.discount_type_id = dt.id)))
     LEFT JOIN public.m_status st ON ((po.status_id = st.id)))
     LEFT JOIN public.m_user_master um ON ((po.added_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
     LEFT JOIN public.m_prefix_master pm ON ((emp.prefix_id = pm.prefix_id)))
  WHERE (po.status_id = 2)
  ORDER BY po.id;


--
-- TOC entry 2310 (class 1259 OID 2978246)
-- Name: mis_ward_wise_monthly_income_report; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.mis_ward_wise_monthly_income_report AS
 SELECT DISTINCT prm.amount,
    prm.date_of_reciept,
    prm.reciept_number,
    bm.bill_number,
    bm.bill_date_time,
    bm.net_amount,
    adm.admission_id,
    adm.admission_number,
    admd.ward_id,
    wm.ward_name,
    um.user_id,
    ((((pm.prefix_desc || ' '::text) || (emp.first_name)::text) || ' '::text) || (emp.last_name)::text) AS user_name,
    pmm.payment_mode_id,
    pmm.payment_mode_desc,
    prm.unit_id,
    u.unit_name,
    u.unit_address,
    adm.patient_id,
    ((((((ppm.prefix_desc || ' '::text) || (pr.first_name)::text) || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS patient_name
   FROM (((((((((((((billing.m_billing_master bm
     LEFT JOIN billing.t_billing_details bd ON ((bm.billing_master_id = bd.billing_master_id)))
     LEFT JOIN billing.t_payment_reciept_master prm ON ((bm.billing_master_id = prm.billing_master_id)))
     LEFT JOIN adt.t_admission adm ON ((bm.admission_id = adm.admission_id)))
     LEFT JOIN adt.t_admission_details admd ON ((adm.admission_id = admd.admission_id)))
     LEFT JOIN adt.m_ward_master wm ON ((admd.ward_id = wm.ward_id)))
     LEFT JOIN public.unitinformation u ON ((prm.unit_id = u.unit_id)))
     LEFT JOIN public.m_user_master um ON ((prm.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
     LEFT JOIN public.m_prefix_master pm ON ((emp.prefix_id = pm.prefix_id)))
     LEFT JOIN billing.t_payment_reciept_details prd ON ((prm.payment_reciept_id = prd.payment_receipt_master_id)))
     LEFT JOIN public.m_payment_mode_master pmm ON ((prd.payment_mode_id = pmm.payment_mode_id)))
     LEFT JOIN patient.t_patient_registration pr ON ((adm.patient_id = pr.patient_id)))
     LEFT JOIN public.m_prefix_master ppm ON ((pr.prefix_id = ppm.prefix_id)))
  WHERE ((bm.bill_status_id = 3) AND (bm.visit_type_id = 2))
  ORDER BY prm.reciept_number;


