-- TOC entry 3485 (class 1259 OID 3695142)
-- Name: opdcaspaper; Type: VIEW; Schema: patient; Owner: -
--

CREATE VIEW patient.opdcaspaper AS
 SELECT billmst.billing_master_id,
    pntmst.uhid_number,
    pntmst.first_name,
    pntmst.middle_name,
    pntmst.last_name,
    pntmst.email,
    billdtls.gross_amount AS amount,
    (billdtls.created_date)::date AS transactiondate,
    billmst.organisation_id AS orgid,
    billmst.unit_id AS unitid,
    servmst.service_standard_name,
    encmst.encounter_date
   FROM ((((((billing.t_billing_details billdtls
     JOIN billing.m_billing_master billmst ON ((billmst.billing_master_id = billdtls.billing_master_id)))
     JOIN service.m_service_master servmst ON ((servmst.service_master_id = billdtls.service_id)))
     JOIN doctor.m_speciality_master spc ON ((spc.speciality_id = servmst.speciality_id)))
     JOIN public.m_general_ledger_master genledmst ON ((genledmst.general_ledger_id = spc.general_ledger_id)))
     JOIN opd.t_encounter_master encmst ON ((billmst.encounter_id = encmst.encounter_id)))
     JOIN patient.t_patient_registration pntmst ON ((pntmst.patient_id = encmst.patient_id)))
  WHERE (billmst.visit_type_id = 1);


