--
-- TOC entry 2390 (class 1259 OID 2978773)
-- Name: get_inpatientissue; Type: VIEW; Schema: pharmacy; Owner: -
--

CREATE VIEW pharmacy.get_inpatientissue AS
 SELECT DISTINCT pim.uhid_number,
    pim.patientname,
    visitmaster.visit_type_name,
    issue.added_date,
    prescription.prescription_date,
    (((('Dr.'::text || ' '::text) || (doctormaster.first_name)::text) || ' '::text) || (doctormaster.last_name)::text) AS doctorname,
    ward.ward_name,
    bed.bed_decs,
    um.unit_id,
    um.unit_name,
    um.unit_address,
    um.image
   FROM ((((((((((((pharmacy.t_issue issue
     JOIN pharmacy.t_issue_detail issuedetails ON ((issue.id = issuedetails.issue_id)))
     JOIN pharmacy.t_sale sales ON ((issue.sale_id = sales.id)))
     JOIN pharmacy.t_sale_detail salesdetails ON ((sales.id = salesdetails.sale_id)))
     JOIN public.patientinformation pim ON ((sales.patient_id = pim.patient_id)))
     JOIN public.m_visit_type_master visitmaster ON ((issue.visit_type_id = visitmaster.visit_type_id)))
     JOIN adt.t_admission admission ON ((issue.admission_id = admission.admission_id)))
     LEFT JOIN adt.t_admission_details admdetails ON ((admission.admission_id = admdetails.admission_id)))
     LEFT JOIN pharmacy.t_prescription prescription ON ((issue.prescription_id = prescription.id)))
     LEFT JOIN doctor.m_doctor_master doctormaster ON ((issue.doctor_id = doctormaster.doctor_id)))
     LEFT JOIN adt.m_ward_master ward ON ((admdetails.ward_id = ward.ward_id)))
     LEFT JOIN adt.m_bed_master bed ON ((admdetails.bed_id = bed.bed_id)))
     LEFT JOIN public.unitinformation um ON ((issue.unit_id = um.unit_id)))
  WHERE (admdetails.admission_details_id = ( SELECT t_admission_details.admission_details_id
           FROM adt.t_admission_details
          WHERE (t_admission_details.admission_id = admission.admission_id)
          ORDER BY t_admission_details.admission_details_id DESC
         LIMIT 1));


