CREATE VIEW procedure.get_salesforipd AS
 SELECT DISTINCT t_sale.id,
    t_sale.bill_no,
    t_sale.added_date,
    t_sale.total_amount,
    t_sale.discount,
    t_sale.net_amount,
    t_sale.tax_amount,
    t_sale_detail.quantity,
    t_sale_detail.rate,
    t_sale_detail.total_amount AS total_amount_details,
    t_sale_detail.tax_percentage,
    t_sale_detail.tax_amount AS tax_amount_detail,
    t_sale_detail.discount_amount,
    t_sale_detail.net_amount AS net_amount_detail,
    t_sale.sale_type_id,
    concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patient_name,
    m_item.name,
    t_batch.batch_no,
    t_batch.expiry_date,
    m_item.hsn_code,
    t_batch.cop,
    COALESCE(t_sale.bill_id, 0) AS bill_id,
    t_sale.admission_id,
    t_batch.id AS batch_id,
    m_item.id AS itemid,
    t_sale.unit_id,
    t_sale.outstanding_amount,
    t_sale.paid_amount,
    COALESCE(ord.net_amount, (0)::numeric) AS netrefund,
    t_sale_detail.id AS saledetailid,
    pim.uhid_number,
    concat('Dr.', '', dm.first_name, ' ', dm.last_name) AS doctorname,
    pimd.address
   FROM (((((((((pharmacy.t_sale
     JOIN pharmacy.t_sale_detail ON ((t_sale.id = t_sale_detail.sale_id)))
     JOIN public.t_order_details ordd ON (((ordd.sale_detail_id = t_sale_detail.id) AND (ordd.ord_cancelled = 'N'::bpchar) AND (ordd.status = 'A'::bpchar) AND (ordd.is_drug = 'Y'::bpchar) AND (ordd.service_is_billed = 1))))
     JOIN patient.t_patient_registration pim ON ((t_sale.patient_id = pim.patient_id)))
     LEFT JOIN patient.t_patient_details pimd ON ((pim.patient_id = pimd.patient_id)))
     LEFT JOIN public.m_prefix_master prefix ON ((pim.prefix_id = prefix.prefix_id)))
     JOIN doctor.m_doctor_master dm ON ((t_sale.doctor_id = dm.doctor_id)))
     JOIN inventory.t_batch ON ((t_batch.id = t_sale_detail.batch_id)))
     JOIN public.m_item ON (((t_batch.item_id = m_item.id) AND (t_sale.is_active = true))))
     LEFT JOIN ( SELECT od.net_amount,
            od.sale_detail_id
           FROM public.t_order_details od
          WHERE ((od.order_qty < 0) AND (od.ord_cancelled = 'N'::bpchar) AND (od.status = 'A'::bpchar) AND (od.is_drug = 'Y'::bpchar) AND (od.service_is_billed = 1))) ord ON ((ord.sale_detail_id = t_sale_detail.id)))
  WHERE ((t_sale.patient_id IS NOT NULL) AND (t_sale.is_deleted = false));


