    sale.total_amount,
    sale.tax_amount,
    sale.total_discount_amount,
    sale.net_amount,
    issuereturn.added_date AS salesdate,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_id,
    unitinformation.image,
        CASE
            WHEN (sale.temp_patient_id IS NULL) THEN ((((pt.first_name)::text || ' '::text) || (pt.last_name)::text))::character varying
            ELSE ptt.patient_name
        END AS patient_name,
    ( SELECT sum(batchm.amount) AS sum
           FROM ((((pharmacy.t_issue_detail issued
             JOIN pharmacy.t_issue_detail_batch_mapper batchm ON ((batchm.issue_detail_id = issued.id)))
             JOIN pharmacy.t_patient_issue_return_detail rd ON ((rd.issue_batch_mapper_id = batchm.id)))
             JOIN pharmacy.t_sale_detail saledet ON ((saledet.id = issued.sale_detail_id)))
             JOIN pharmacy.t_sale sa ON ((sa.id = saledet.sale_id)))
          WHERE (sa.id = sale.id)) AS total_return_amt,
    sale.tax_amount AS totaltax,
    COALESCE(tax5.taxamount, (0)::double precision) AS tax5,
    COALESCE(tax12.taxamount, (0)::double precision) AS tax12,
    COALESCE(tax18.taxamount, (0)::double precision) AS tax18,
    COALESCE(tax28.taxamount, (0)::double precision) AS tax28,
    COALESCE(tax5.taxable, (0)::double precision) AS taxable5,
    COALESCE(tax12.taxable, (0)::double precision) AS taxable12,
    COALESCE(tax18.taxable, (0)::double precision) AS taxable18,
    COALESCE(tax28.taxable, (0)::double precision) AS taxable28,
    sale.sale_type_id,
    saletype.type AS saletype,
    sale.bill_no AS salesno
   FROM (((((((((((((pharmacy.t_patient_issue_return issuereturn
     JOIN pharmacy.t_patient_issue_return_detail issueretrundetails ON ((issuereturn.id = issueretrundetails.patient_issue_return_id)))
     JOIN pharmacy.t_issue_detail_batch_mapper issuebatchmapper ON ((issueretrundetails.issue_batch_mapper_id = issuebatchmapper.id)))
     JOIN pharmacy.t_issue_detail issuedetails ON ((issuebatchmapper.issue_detail_id = issuedetails.id)))
     JOIN pharmacy.t_sale_detail salesdetail ON ((salesdetail.id = issuedetails.sale_detail_id)))
     JOIN pharmacy.t_sale sale ON ((salesdetail.sale_id = sale.id)))
     JOIN pharmacy.m_sale_type saletype ON ((sale.sale_type_id = saletype.id)))
     JOIN public.m_unit_master unitinformation ON ((issuereturn.unit_id = unitinformation.unit_id)))
     LEFT JOIN pharmacy.t_temp_patient_registration ptt ON ((ptt.id = sale.temp_patient_id)))
     LEFT JOIN patient.t_patient_registration pt ON ((pt.patient_id = sale.patient_id)))
     LEFT JOIN ( SELECT ((((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) * issued.tax_percentage) / (100)::double precision) AS taxamount,
            ((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) AS taxable,
            issued.tax_percentage,
            sa.id,
            rd.patient_issue_return_id
           FROM ((((pharmacy.t_issue_detail issued
             JOIN pharmacy.t_issue_detail_batch_mapper batchm ON ((batchm.issue_detail_id = issued.id)))
             JOIN pharmacy.t_patient_issue_return_detail rd ON ((rd.issue_batch_mapper_id = batchm.id)))
             JOIN pharmacy.t_sale_detail saledet ON ((saledet.id = issued.sale_detail_id)))
             JOIN pharmacy.t_sale sa ON ((sa.id = saledet.sale_id)))
          WHERE (issued.tax_percentage = (5)::double precision)
          GROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax5 ON ((tax5.id = sale.id)))
     LEFT JOIN ( SELECT ((((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) * issued.tax_percentage) / (100)::double precision) AS taxamount,
            ((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) AS taxable,
            issued.tax_percentage,
            sa.id,
            rd.patient_issue_return_id
           FROM ((((pharmacy.t_issue_detail issued
             JOIN pharmacy.t_issue_detail_batch_mapper batchm ON ((batchm.issue_detail_id = issued.id)))
             JOIN pharmacy.t_patient_issue_return_detail rd ON ((rd.issue_batch_mapper_id = batchm.id)))
             JOIN pharmacy.t_sale_detail saledet ON ((saledet.id = issued.sale_detail_id)))
             JOIN pharmacy.t_sale sa ON ((sa.id = saledet.sale_id)))
          WHERE (issued.tax_percentage = (12)::double precision)
          GROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax12 ON ((tax12.id = sale.id)))
     LEFT JOIN ( SELECT ((((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) * issued.tax_percentage) / (100)::double precision) AS taxamount,
            ((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) AS taxable,
            issued.tax_percentage,
            sa.id,
            rd.patient_issue_return_id
           FROM ((((pharmacy.t_issue_detail issued
             JOIN pharmacy.t_issue_detail_batch_mapper batchm ON ((batchm.issue_detail_id = issued.id)))
             JOIN pharmacy.t_patient_issue_return_detail rd ON ((rd.issue_batch_mapper_id = batchm.id)))
             JOIN pharmacy.t_sale_detail saledet ON ((saledet.id = issued.sale_detail_id)))
             JOIN pharmacy.t_sale sa ON ((sa.id = saledet.sale_id)))
          WHERE (issued.tax_percentage = (18)::double precision)
          GROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax18 ON ((tax18.id = sale.id)))
     LEFT JOIN ( SELECT ((((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) * issued.tax_percentage) / (100)::double precision) AS taxamount,
            ((sum(batchm.amount) * (100)::double precision) / ((100)::double precision + issued.tax_percentage)) AS taxable,
            issued.tax_percentage,
            sa.id,
            rd.patient_issue_return_id
           FROM ((((pharmacy.t_issue_detail issued
             JOIN pharmacy.t_issue_detail_batch_mapper batchm ON ((batchm.issue_detail_id = issued.id)))
             JOIN pharmacy.t_patient_issue_return_detail rd ON ((rd.issue_batch_mapper_id = batchm.id)))
             JOIN pharmacy.t_sale_detail saledet ON ((saledet.id = issued.sale_detail_id)))
             JOIN pharmacy.t_sale sa ON ((sa.id = saledet.sale_id)))
          WHERE (issued.tax_percentage = (28)::double precision)
          GROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax28 ON ((tax28.id = sale.id)));


