   FROM (((((((((pharmacy.t_sale
     LEFT JOIN pharmacy.t_temp_patient_registration ON ((t_temp_patient_registration.id = t_sale.temp_patient_id)))
     LEFT JOIN patient.registration ON ((registration.patient_id = t_sale.patient_id)))
     LEFT JOIN pharmacy.t_temp_doctor ON ((t_temp_doctor.id = t_sale.temp_doctor_id)))
     LEFT JOIN doctor.m_doctor_master ON ((m_doctor_master.doctor_id = t_sale.doctor_id)))
