     JOIN public.m_store ON ((t_sale.store_id = m_store.store_id)))
     LEFT JOIN public.m_counter_master ON ((m_counter_master.counter_id = t_sale.counter_id)))
     LEFT JOIN public.m_user_master ON ((m_user_master.user_id = t_sale.added_by)))
     LEFT JOIN public.m_employee_master ON ((m_employee_master.user_id = m_user_master.user_id)));


