--
-- TOC entry 2751 (class 1259 OID 2980488)
-- Name: admbarcode; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admbarcode AS
 SELECT adm.admission_id,
    pr.first_name,
    pr.middle_name,
    pr.last_name,
    (pr.dob)::date AS birthdate,
    adm.admission_number,
    public.createbarcodecode128((adm.admission_id)::character varying) AS barcode,
    cm.company_desc
   FROM (((patient.t_patient_registration pr
     JOIN adt.t_admission adm ON ((pr.patient_id = adm.patient_id)))
     LEFT JOIN opd.t_patient_sponsor_details sponsor ON ((adm.admission_id = sponsor.admission_id)))
     LEFT JOIN public.t_company_master cm ON ((sponsor.payee_id = cm.company_id)));


--
-- TOC entry 2752 (class 1259 OID 2980493)
-- Name: advanceconsumed; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.advanceconsumed AS
 SELECT DISTINCT dm.deposit_master_id,
    ((vm.visit_type_code)::text || 'D Advance'::text) AS deposit,
    vm.visit_type_code,
    vm.visit_type_id,
    pmm.payment_mode_desc,
    dd.amount,
    dd.consumed_amount,
    0 AS tdsamt,
    um.user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    dd.created_date AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Income'::text AS amttype,
    dm.deposit_no AS reciptno,
    countermaster.counter_id,
    countermaster.counter_desc,
    dm.payee_id,
    payee.company_desc,
    umm.image
   FROM ((((((((billing.t_payment_deposit_details dd
     JOIN billing.m_deposit_master dm ON ((dm.deposit_master_id = dd.deposit_id)))
     JOIN public.m_visit_type_master vm ON ((dm.visit_type_id = vm.visit_type_id)))
     JOIN public.m_payment_mode_master pmm ON ((dd.payment_mode_id = pmm.payment_mode_id)))
     JOIN public.m_user_master um ON ((dd.created_by = um.user_id)))
     JOIN public.m_unit_master umm ON ((dm.unit_id = umm.unit_id)))
     JOIN patient.patientinformation pm ON ((dm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((dm.counter_id = countermaster.counter_id)))
     LEFT JOIN public.t_company_master payee ON ((dm.payee_id = payee.company_id)))
UNION
 SELECT DISTINCT dm.deposit_master_id,
    'patient Advance'::text AS deposit,
    'patient'::character varying AS visit_type_code,
    3 AS visit_type_id,
    pmm.payment_mode_desc,
    dd.amount,
    dd.consumed_amount,
    0 AS tdsamt,
    um.user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    dd.created_date AS depositdate,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    'Income'::text AS amttype,
    dm.deposit_no AS reciptno,
    countermaster.counter_id,
    countermaster.counter_desc,
    dm.payee_id,
    payee.company_desc,
    umm.image
   FROM ((((((((billing.t_payment_deposit_details dd
     JOIN billing.m_deposit_master dm ON ((dm.deposit_master_id = dd.deposit_id)))
     JOIN patient.t_patient_registration pr ON ((pr.patient_id = dm.patient_id)))
     JOIN public.m_payment_mode_master pmm ON ((dd.payment_mode_id = pmm.payment_mode_id)))
     JOIN public.m_user_master um ON ((dd.created_by = um.user_id)))
     JOIN public.m_unit_master umm ON ((dm.unit_id = umm.unit_id)))
     JOIN patient.patientinformation pm ON ((dm.patient_id = pm.patient_id)))
     LEFT JOIN public.m_counter_master countermaster ON ((dm.counter_id = countermaster.counter_id)))
     LEFT JOIN public.t_company_master payee ON ((dm.payee_id = payee.company_id)))
  WHERE ((dm.encounter_id IS NULL) AND (dm.admission_id IS NULL) AND (dm.visit_type_id IS NULL));


--
-- TOC entry 3639 (class 1259 OID 4109533)
-- Name: advanceconsumed_againstbills; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.advanceconsumed_againstbills AS
 SELECT DISTINCT bm.billing_master_id,
    deptcons.consumed_amount,
    um.user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    deptcons.dep_consumption_date,
    pr.patientname,
    pr.patient_id,
    pr.uhid_number,
    deptcons.deposite_consumption_number,
    bm.bill_number,
    bm.bill_date_time,
    umm.image
   FROM ((((billing.m_billing_master bm
     JOIN billing.t_payment_deposite_consumption deptcons ON ((bm.billing_master_id = deptcons.bill_id)))
     JOIN public.patientinformation pr ON ((pr.patient_id = bm.patient_id)))
     JOIN public.m_user_master um ON ((deptcons.created_by = um.user_id)))
     JOIN public.m_unit_master umm ON ((bm.unit_id = umm.unit_id)));


--
-- TOC entry 3614 (class 1259 OID 4004174)
-- Name: anil_allcollectionsummary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.anil_allcollectionsummary AS
 SELECT image_opdipdcollectionsummary.deposit_master_id,
    image_opdipdcollectionsummary.deposit,
    image_opdipdcollectionsummary.visit_type_code,
        CASE
            WHEN (COALESCE(image_opdipdcollectionsummary.outstanding, (0)::double precision) <> (0)::double precision) THEN 1
            ELSE image_opdipdcollectionsummary.visit_type_id
        END AS visit_type_id,
    image_opdipdcollectionsummary.user_name,
    image_opdipdcollectionsummary.user_id,
    image_opdipdcollectionsummary.unit_id,
    COALESCE(image_opdipdcollectionsummary.organization_id, 0) AS organization_id,
    image_opdipdcollectionsummary.unit_name,
    image_opdipdcollectionsummary.patientname,
    image_opdipdcollectionsummary.patient_id,
    image_opdipdcollectionsummary.uhid_number,
        CASE
            WHEN (COALESCE(image_opdipdcollectionsummary.outstanding, (0)::double precision) <> (0)::double precision) THEN image_opdipdcollectionsummary.bill_date_time
            ELSE image_opdipdcollectionsummary.depositdate
        END AS depositdate,
    image_opdipdcollectionsummary.unit_address,
    image_opdipdcollectionsummary.unit_contact_2,
    image_opdipdcollectionsummary.unit_contact,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Cash'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS cash,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Cheque'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS cheque,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Card Payment'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS creditcard,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Debit Card'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS debitcard,
    COALESCE(sum(image_opdipdcollectionsummary.consumed_amount), (0)::double precision) AS patadvused,
    COALESCE((sum(image_opdipdcollectionsummary.tdsamt))::double precision, (0)::double precision) AS tdsamt,
    image_opdipdcollectionsummary.amttype,
    image_opdipdcollectionsummary.reciptno,
    COALESCE(image_opdipdcollectionsummary.counter_id, 0) AS counter_id,
    image_opdipdcollectionsummary.counter_desc,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Mpesa'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS mpesa,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Loyalty Card'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS loyaltycard,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'E-Transfer'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS e_transfer,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Available Fund'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS availablefund,
    COALESCE(sum(
        CASE
            WHEN (image_opdipdcollectionsummary.payment_mode_desc = 'Doctor Credit'::text) THEN image_opdipdcollectionsummary.amount
            ELSE NULL::double precision
        END), (0)::double precision) AS doctorcredit,
    image_opdipdcollectionsummary.total_bill_amount,
    image_opdipdcollectionsummary.discount_amount,
    image_opdipdcollectionsummary.net_amount,
    image_opdipdcollectionsummary.outstanding,
    image_opdipdcollectionsummary.paidamount,
    image_opdipdcollectionsummary.transaction_type_desc,
    image_opdipdcollectionsummary.bill_date_time,
    image_opdipdcollectionsummary.referral_name
   FROM public.image_opdipdcollectionsummary
  GROUP BY image_opdipdcollectionsummary.deposit_master_id, image_opdipdcollectionsummary.deposit, image_opdipdcollectionsummary.visit_type_code, image_opdipdcollectionsummary.user_name, image_opdipdcollectionsummary.user_id, image_opdipdcollectionsummary.unit_id, image_opdipdcollectionsummary.organization_id, image_opdipdcollectionsummary.unit_name, image_opdipdcollectionsummary.patientname, image_opdipdcollectionsummary.patient_id, image_opdipdcollectionsummary.uhid_number, image_opdipdcollectionsummary.depositdate, image_opdipdcollectionsummary.unit_address, image_opdipdcollectionsummary.unit_contact_2, image_opdipdcollectionsummary.unit_contact, image_opdipdcollectionsummary.amttype, image_opdipdcollectionsummary.reciptno, image_opdipdcollectionsummary.visit_type_id, image_opdipdcollectionsummary.counter_id, image_opdipdcollectionsummary.counter_desc, image_opdipdcollectionsummary.total_bill_amount, image_opdipdcollectionsummary.discount_amount, image_opdipdcollectionsummary.net_amount, image_opdipdcollectionsummary.outstanding, image_opdipdcollectionsummary.paidamount, image_opdipdcollectionsummary.transaction_type_desc, image_opdipdcollectionsummary.bill_date_time, image_opdipdcollectionsummary.referral_name;


