-- TOC entry 2762 (class 1259 OID 2980531)
-- Name: bedoccupancy_test; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bedoccupancy_test AS
 SELECT bedcategor0_.organization_id,
    bedcategor0_.unit_id,
    bedcategor0_.bed_category_id,
    bedcategor0_.bed_category_desc,
    ( SELECT count(bedmaster1_.bed_id) AS count
           FROM (adt.m_bed_master bedmaster1_
             JOIN adt.t_bed_log_status listbedlog2_ ON ((bedmaster1_.bed_id = listbedlog2_.bed_id)))
          WHERE ((listbedlog2_.bed_status_id = 3) AND (bedmaster1_.bed_category_id = bedcategor0_.bed_category_id) AND (bedmaster1_.unit_id = 1) AND (listbedlog2_.status = 'A'::bpchar) AND ((listbedlog2_.updated_date)::date = '2019-09-24'::date))) AS vacantandready,
    ( SELECT count(bedmaster3_.bed_id) AS count
           FROM (adt.m_bed_master bedmaster3_
             JOIN adt.t_bed_log_status listbedlog4_ ON ((bedmaster3_.bed_id = listbedlog4_.bed_id)))
          WHERE ((listbedlog4_.bed_status_id = 2) AND (bedmaster3_.bed_category_id = bedcategor0_.bed_category_id) AND (bedmaster3_.unit_id = 1) AND (listbedlog4_.status = 'A'::bpchar) AND ((listbedlog4_.updated_date)::date = '2019-09-24'::date))) AS underhousekeeping,
    ( SELECT count(bedmaster5_.bed_id) AS count
           FROM (adt.m_bed_master bedmaster5_
             JOIN adt.t_bed_log_status listbedlog6_ ON ((bedmaster5_.bed_id = listbedlog6_.bed_id)))
          WHERE ((listbedlog6_.bed_status_id = 5) AND (bedmaster5_.bed_category_id = bedcategor0_.bed_category_id) AND (bedmaster5_.unit_id = 1) AND (listbedlog6_.status = 'A'::bpchar) AND ((listbedlog6_.updated_date)::date = '2019-09-24'::date))) AS occupied,
    ( SELECT count(bedmaster5_.bed_id) AS count
           FROM (adt.m_bed_master bedmaster5_
             JOIN adt.t_bed_log_status listbedlog6_ ON ((bedmaster5_.bed_id = listbedlog6_.bed_id)))
          WHERE ((listbedlog6_.bed_status_id = 6) AND (bedmaster5_.bed_category_id = bedcategor0_.bed_category_id) AND (bedmaster5_.unit_id = 1) AND (listbedlog6_.status = 'A'::bpchar) AND ((listbedlog6_.updated_date)::date = '2019-09-24'::date))) AS vacants,
    unitinformation.unit_name,
    unitinformation.unit_address
   FROM (adt.m_bed_category_master bedcategor0_
     LEFT JOIN public.unitinformation ON ((bedcategor0_.unit_id = unitinformation.unit_id)))
  WHERE ((bedcategor0_.unit_id = 1) AND (bedcategor0_.status = 'A'::bpchar))
  ORDER BY bedcategor0_.bed_category_id;


