-- Name: billingreport; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billingreport AS
 SELECT DISTINCT bm.billing_master_id,
    bm.bill_number,
    bm.bill_date_time,
    bm.total_bill_amount,
    (bm.concession_amount + bm.discount_amount) AS totaldiscount,
    bm.net_amount,
    bm.cr_amount,
    bm.outstanding,
    vm.visit_type_id,
    (concat(emp.first_name, ' ', emp.last_name))::character varying(100) AS user_name,
    um.user_id,
    umm.unit_id,
    umm.organization_id,
    umm.unit_name,
    umm.unit_address,
    umm.unit_contact,
    umm.unit_contact_2,
    pm.patientname,
    pm.patient_id,
    pm.uhid_number,
    bm.gst,
        CASE
            WHEN (bm.visit_type_id = 1) THEN public.billconsultantdoctorname(bm.encounter_id, 1)
            WHEN (bm.visit_type_id = 2) THEN public.billconsultantdoctorname(bm.admission_id, 2)
            ELSE NULL::character varying
        END AS doctorname,
    pm.patient_category,
    pr.patient_category_id,
    umm.image,
    m_refferel.referral_name AS doctornamenew,
    pm.patientaddress,
    pm.patientmobile,
    pm.email,
    pm.ageyear,
    pm.gender_name,
    bm.bill_remark
   FROM (((((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bdet ON ((bm.billing_master_id = bdet.billing_master_id)))
     JOIN public.m_visit_type_master vm ON ((bm.visit_type_id = vm.visit_type_id)))
     LEFT JOIN public.m_user_master um ON ((bm.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
     JOIN public.m_unit_master umm ON ((bm.unit_id = umm.unit_id)))
     JOIN public.patientinformation pm ON ((bm.patient_id = pm.patient_id)))
     JOIN patient.t_patient_registration pr ON ((bm.patient_id = pr.patient_id)))
     LEFT JOIN public.t_referal_details admreff ON ((bm.encounter_id = admreff.encounter_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
  WHERE ((bm.bill_cancelled = 'N'::bpchar) AND (bm.status = 'A'::"char") AND (bdet.status = 'A'::"char"));


