--
-- TOC entry 2778 (class 1259 OID 2980589)
-- Name: dischargeslip; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dischargeslip AS
 SELECT DISTINCT pim.patient_id,
    pim.uhid_number,
    pim.patientname,
    pim.age,
    pim.gender_name,
    pim.patientaddress,
    um.unit_id,
    um.unit_name,
    um.unit_contact,
    um.unit_contact_2,
    um.unit_address,
    um.unit_address_2,
    um.unit_logo,
    um.unit_website,
    om.organization_id,
    om.organization_name,
    ad.admission_id,
    ad.admission_number,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    om.organization_address,
    adet.doa,
    wm.ward_name,
    dc.discharge_date,
    dc.discharge_time,
    (abs(date_part('Year'::text, age(pim.patientdob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageyear,
    bm.bed_desc,
    temp.template_transaction_id,
    temp.template_object,
    um.image
   FROM ((((((((((adt.t_discharge dc
     JOIN adt.t_admission ad ON ((ad.admission_id = dc.admission_id)))
     JOIN patient.patientinformation pim ON ((pim.patient_id = ad.patient_id)))
     JOIN public.unitinformation um ON ((dc.unit_id = um.unit_id)))
     JOIN public.m_organization_master om ON ((dc.organization_id = om.organization_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((dm.doctor_id = ad.doctor_id)))
     JOIN public.m_user_master udm ON ((dc.created_by = udm.user_id)))
     JOIN adt.t_admission_details adet ON ((dc.admission_id = adet.admission_id)))
     JOIN adt.m_ward_master wm ON ((adet.ward_id = wm.ward_id)))
     JOIN adt.m_bed_master bm ON ((adet.bed_id = bm.bed_id)))
     LEFT JOIN public.t_template_transaction temp ON ((dc.admission_id = temp.admission_id)))
  WHERE ((dc.status = 'A'::bpchar) AND (adet.admission_details_id = ( SELECT t_admission_details.admission_details_id
           FROM adt.t_admission_details
          WHERE (t_admission_details.admission_id = ad.admission_id)
          ORDER BY t_admission_details.admission_details_id DESC
         LIMIT 1)));


--
-- TOC entry 2779 (class 1259 OID 2980594)
-- Name: dischargesummaryreport; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dischargesummaryreport AS
 SELECT DISTINCT dissumm.discharge_summary_id,
    pim.patient_id,
    pim.uhid_number,
    pim.patientname,
    pim.age,
    pim.gender_name,
    pim.patientaddress,
    fieldmaster.discharge_field_id,
    fieldmaster.discharge_field_desc AS fieldname,
    disdetail.discharge_field_description AS dissummary,
    dissumm.discharge_template_id,
    dtm.discharge_desc AS templatename,
    um.unit_id,
    um.unit_name,
    um.unit_contact,
    um.unit_contact_2,
    um.unit_address,
    um.unit_address_2,
    um.unit_logo,
    um.unit_website,
    om.organization_id,
    om.organization_name,
    ad.admission_id,
    ad.admission_number,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    om.organization_address,
    spm.speciality_name,
    adet.doa,
    wm.ward_name,
    dc.discharge_date,
    dc.discharge_time,
    um.image
   FROM (((((((((((((adt.m_discharge_summary_detail disdetail
     JOIN adt.m_discharge_summary dissumm ON ((disdetail.discharge_summary_id = dissumm.discharge_summary_id)))
     JOIN adt.m_discharge_summary_field_master fieldmaster ON ((disdetail.discharge_field_id = fieldmaster.discharge_field_id)))
     JOIN adt.m_discharge_summary_template_master dtm ON ((dtm.discharge_id = dissumm.discharge_template_id)))
     JOIN patient.patientinformation pim ON ((pim.patient_id = dissumm.patient_id)))
     JOIN public.unitinformation um ON ((dissumm.unit_id = um.unit_id)))
     JOIN public.m_organization_master om ON ((dissumm.organization_id = om.organization_id)))
     JOIN adt.t_admission ad ON ((ad.admission_id = dissumm.admission_id)))
     JOIN doctor.m_doctor_master dm ON ((dm.doctor_id = ad.doctor_id)))
     JOIN public.m_user_master udm ON ((dissumm.created_by = udm.user_id)))
     JOIN doctor.m_speciality_master spm ON ((dissumm.department_id = spm.speciality_id)))
     JOIN adt.t_admission_details adet ON ((dissumm.admission_id = adet.admission_id)))
     JOIN adt.m_ward_master wm ON ((adet.ward_id = wm.ward_id)))
     LEFT JOIN adt.t_discharge dc ON ((ad.admission_id = dc.admission_id)))
  WHERE ((dc.status = 'A'::bpchar) AND (adet.admission_details_id = ( SELECT t_admission_details.admission_details_id
           FROM adt.t_admission_details
          WHERE (t_admission_details.admission_id = ad.admission_id)
          ORDER BY t_admission_details.admission_details_id DESC
         LIMIT 1)));


