-- TOC entry 3515 (class 1259 OID 3695294)
-- Name: get_haemodailysisdetails; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.get_haemodailysisdetails AS
 SELECT DISTINCT orderdetail.order_details_id AS orderdetailsid,
    sm.slot_id AS slotid,
    admission.admission_id AS admissionid,
    appmstr.appointment_id AS appointmentid,
    orderdetail.ord_doc_id AS orddoctorid,
    orderdetail.status,
    orderdetail.service_rendered AS servicerendered,
    patientreg.patient_id AS patientid,
    patientreg.uhid_number AS uhidnumber,
    patientreg.gender_id AS genderid,
    gendermaster.gender_code AS gendercode,
    to_char(patientreg.dob, 'DD-MM-YYYY HH:mm:ss'::text) AS dob,
    concat(date_part('year'::text, age(CURRENT_TIMESTAMP, (patientreg.dob)::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, (patientreg.dob)::timestamp with time zone)), 'M ', date_part('day'::text, age(CURRENT_TIMESTAMP, (patientreg.dob)::timestamp with time zone)), 'D ') AS agestring,
    encountermaster.encounter_id AS encounterid,
    encountermaster.doctor_id AS doctorid,
    ((((('Dr. '::text || (COALESCE(doctormaster.first_name))::text) || ' '::text) || (COALESCE(doctormaster.middle_name))::text) || ' '::text) || (COALESCE(doctormaster.last_name))::text) AS doctorname,
    (((((COALESCE(doctormasterip.first_name))::text || ' '::text) || (COALESCE(doctormasterip.middle_name))::text) || ' '::text) || (COALESCE(doctormasterip.last_name))::text) AS admittingdoctorname,
    encountermaster.dept_id AS specialityid,
    specmaster.speciality_name AS specialityname,
    servicemaster.service_standard_name AS servicename,
    servicemaster.service_master_id AS serviceid,
    servicemaster.service_standard_code AS servicecode,
    orderdetail.priority_id AS priorityid,
    ordermaster.order_no AS orderno,
    to_char(dtl.doa, 'DD/MM/YYYY'::text) AS doa,
    to_char(dtl.pdd, 'DD/MM/YYYY'::text) AS pdd,
    to_char(orderdetail.order_date, 'dd/mm/yyyy'::text) AS orderdate,
    (((((((prefixmaster.prefix_code)::text || ' '::text) || (COALESCE(patientreg.first_name))::text) || ' '::text) || (COALESCE(patientreg.middle_name))::text) || ' '::text) || (COALESCE(patientreg.last_name))::text) AS patientname,
    bedmstr.bed_number AS bednumber,
    0 AS frombedid,
    orderdetail.accession_number AS accessionnumber,
    ordermaster.visit_type_id AS visittypeid,
    patientreg.identification_number AS identificationnumber,
    vm.visit_type_name AS visitname,
    pcm.patient_category AS patientcategory,
    encountermaster.encounter_number AS visitnumber,
    cm.country_code AS countrycode,
    sm.bed_id AS tobedid,
    bm.bed_number AS tobednumber,
    to_char((sm.from_time)::interval, 'HH:MI'::text) AS appointmenttime,
    bm.ward_id AS towardid,
    bm.room_id AS toroomid,
    bedmstr.ward_id AS fromwardid,
    bedmstr.room_id AS fromroomid,
    to_char(orderdetail.order_date, 'DD/MM/YYYY'::text) AS appointmentdate,
    wm.ward_name AS wardname,
    hemodialysismapper.dialysis_app_mapper_id AS dialysisappmapperid,
    hemodialysismapper.chair_id AS chairid,
    hemodialysismapper.doctor_id AS dialysisdoctorid,
    hemodialysismapper.workbench_acceptance AS hemodialysisworkbenchacceptance,
    bm.bed_number AS chairname,
    hemodialysismapper.technician_acceptance AS technicianacceptance,
    hemodialysismapper.technician_id AS technicianid,
    concat(employeemaster.first_name, ' ', employeemaster.middle_name, ' ', employeemaster.last_name) AS technicianname,
    hemodialysismapper.machine_id AS machineid,
    itemmaster.name AS machinename,
    hemodialysismapper.dialysis_status_id AS dialysisstatusid,
    ( SELECT to_char(pdr.dialysis_start_date, 'DD/MM/YYYY'::text) AS to_char
           FROM patient.t_patient_dialysis_record pdr
          WHERE (pdr.appointment_id = hemodialysismapper.appointment_id)
          ORDER BY pdr.patient_dialysis_rec_id
         LIMIT 1) AS dialysisstartdate,
    ( SELECT to_char(pdr.dialysis_start_time, 'HH24:MI'::text) AS to_char
           FROM patient.t_patient_dialysis_record pdr
          WHERE (pdr.appointment_id = hemodialysismapper.appointment_id)
          ORDER BY pdr.patient_dialysis_rec_id
         LIMIT 1) AS dialysisstarttime,
    ( SELECT to_char(pdr.created_date, 'DD/MM/YYYY'::text) AS to_char
           FROM patient.t_patient_dialysis_record pdr
          WHERE (pdr.appointment_id = hemodialysismapper.appointment_id)
          ORDER BY pdr.patient_dialysis_rec_id DESC
         LIMIT 1) AS dialysisenddate,
    ( SELECT to_char(pdr.dialysis_end_time, 'HH24:MI'::text) AS to_char
           FROM patient.t_patient_dialysis_record pdr
          WHERE (pdr.appointment_id = hemodialysismapper.appointment_id)
          ORDER BY pdr.patient_dialysis_rec_id DESC
         LIMIT 1) AS dialysisendtime,
    admission.admission_number,
    ( SELECT pdr.dialysis_event_id
           FROM patient.t_patient_dialysis_record pdr
          WHERE (pdr.appointment_id = hemodialysismapper.appointment_id)
