     LEFT JOIN adt.t_admission admission ON ((ordermaster.admission_id = admission.admission_id)))
     LEFT JOIN billing.t_billing_details billingdet ON ((orderdetail.order_details_id = billingdet.order_details_id)))
     LEFT JOIN billing.m_billing_master billmaster ON (((orderdetail.service_bill_id = billmaster.billing_master_id) AND (billmaster.bill_cancelled = 'N'::bpchar))))
     LEFT JOIN doctor.m_doctor_master doctormaster ON ((hemodialysismapper.doctor_id = doctormaster.doctor_id)))
     LEFT JOIN doctor.m_speciality_master specmaster ON ((orderdetail.ord_doc_spl_id = specmaster.speciality_id)))
     JOIN opd.m_appointment_master appmstr ON ((appmstr.appointment_id = hemodialysismapper.appointment_id)))
     LEFT JOIN opd.m_slot_master sm ON ((sm.slot_id = appmstr.slot_id)))
