     LEFT JOIN adt.m_bed_master bm ON ((bm.bed_id = sm.bed_id)))
     LEFT JOIN adt.t_admission_details dtl ON (((dtl.admission_id = admission.admission_id) AND (admission.status = 'A'::bpchar) AND (dtl.status = 'A'::bpchar))))
     LEFT JOIN doctor.m_doctor_master doctormasterip ON ((doctormasterip.doctor_id = admission.doctor_id)))
     LEFT JOIN adt.m_bed_master bedmstr ON ((dtl.bed_id = bedmstr.bed_id)))
     LEFT JOIN adt.m_ward_master wm ON ((wm.ward_id = dtl.ward_id)))
     LEFT JOIN public.m_employee_master employeemaster ON ((employeemaster.user_id = hemodialysismapper.technician_id)))
     LEFT JOIN public.m_item itemmaster ON ((itemmaster.id = hemodialysismapper.machine_id)))
     LEFT JOIN public.m_unit_master um ON ((hemodialysismapper.unit_id = um.unit_id)))
  WHERE ((orderdetail.status = 'A'::bpchar) AND (hemodialysismapper.workbench_acceptance = 'A'::bpchar));


