            ELSE uomtype.type
        END AS uomtype,
        CASE
            WHEN (COALESCE(issue_detail.store_indent_detail_id, 0) = 0) THEN uomunitmapper.unit
            ELSE uomunit.unit
        END AS uomunit,
    issue.id,
    priority.priority_desc,
    indenttype.type AS indenttype,
    m_status.status,
    m_item.code,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.image
   FROM ((((((((((((((((inventory.t_material_issue issue
     JOIN inventory.t_material_issue_detail issue_detail ON ((issue.id = issue_detail.material_issue_id)))
     LEFT JOIN inventory.t_store_indent indent ON ((issue.store_indent_id = indent.id)))
     LEFT JOIN inventory.t_store_indent_detail indent_detail ON ((issue_detail.store_indent_detail_id = indent_detail.id)))
     LEFT JOIN public.m_store fromstore ON ((issue.from_store_id = fromstore.store_id)))
     LEFT JOIN public.m_store tostore ON ((issue.to_store_id = tostore.store_id)))
     LEFT JOIN public.m_status ON ((issue.status_id = m_status.id)))
     LEFT JOIN public.m_item ON ((issue_detail.item_id = m_item.id)))
     LEFT JOIN public.m_generic ON ((m_item.generic_id = m_generic.id)))
     LEFT JOIN public.m_uom_type uomtype ON ((indent_detail.uom_type_id = uomtype.id)))
     LEFT JOIN public.m_uom_unit uomunit ON ((indent_detail.uom_unit_id = uomunit.id)))
     LEFT JOIN inventory.t_material_issue_batch_mapper materialmapper ON ((issue_detail.id = materialmapper.material_issue_detail_id)))
     LEFT JOIN public.m_uom_type uomtypemapper ON ((materialmapper.uom_type_id = uomtypemapper.id)))
     LEFT JOIN public.m_uom_unit uomunitmapper ON ((materialmapper.uom_unit_id = uomunitmapper.id)))
     LEFT JOIN adt.m_priority_master priority ON ((indent.priority_id = priority.priority_id)))
     LEFT JOIN inventory.m_indent_type indenttype ON ((indent.indent_type_id = indenttype.id)))
     LEFT JOIN public.unitinformation ON ((issue.unit_id = unitinformation.unit_id)));


