CREATE VIEW public.get_misexpenses_list AS
 SELECT DISTINCT me.expense_id,
    me.bill_number,
    me.bill_date_time,
    me.amount AS meamount,
    me.name AS expencesname,
    me.account_head,
    er.expense_reciept_id,
    er.reciept_number,
    er.date_of_reciept,
    er.amount,
    er.reciept_cancelled,
    erd.payment_mode_id,
    paymode.payment_mode_desc,
    erd.amount AS amountdetail,
    acc.general_ledger_name AS hospital_account_desc,
    um.unit_name,
    um.unit_address,
    um.unit_contact,
    um.unit_email_id,
    um.unit_website,
    usermaster.user_name,
    usermaster.user_id,
    um.unit_id,
    me.org_id,
    acc.general_ledger_id,
        CASE
            WHEN (me.bill_type = 1) THEN 'Income'::text
            WHEN (me.bill_type = 2) THEN 'Expense'::text
            ELSE NULL::text
        END AS bill_type,
        CASE
            WHEN (me.bill_status = 1) THEN 'Pending'::text
            WHEN (me.bill_status = 2) THEN 'Completed'::text
            WHEN (me.bill_status = 3) THEN 'Cancelled'::text
            ELSE NULL::text
        END AS status,
    0 AS outstanding,
    concat(empreq.first_name, ' ', empreq.last_name) AS empreq,
        CASE
            WHEN (trd.req_status = 1) THEN 'Pending'::text
            WHEN (trd.req_status = 2) THEN 'Completed'::text
            ELSE NULL::text
        END AS req_status,
    me.bill_type AS billtypeid,
    me.bill_status AS billstatusid,
    me.remark,
    um.image,
    org.organization_name
   FROM ((((((((((billing.t_miscellaneous_expense me
     JOIN billing.t_miscellaneous_expense_reciept er ON ((me.expense_id = er.expense_id)))
     JOIN billing.t_miscellaneous_expense_reciept_details erd ON ((er.expense_reciept_id = erd.expense_reciept_id)))
     LEFT JOIN public.m_payment_mode_master paymode ON ((erd.payment_mode_id = paymode.payment_mode_id)))
     LEFT JOIN public.m_general_ledger_master acc ON ((me.account_head = acc.general_ledger_id)))
     LEFT JOIN public.m_unit_master um ON ((me.unit_id = um.unit_id)))
     LEFT JOIN public.m_organization_master org ON ((um.organization_id = org.organization_id)))
     LEFT JOIN public.m_user_master usermaster ON ((me.created_by = usermaster.user_id)))
     LEFT JOIN billing.t_request_discount trd ON ((me.expense_id = trd.expense_id)))
     LEFT JOIN public.m_user_master umreqto ON ((trd.request_sent_to = umreqto.user_id)))
     LEFT JOIN public.m_employee_master empreq ON ((umreqto.user_id = empreq.user_id)))
  WHERE ((me.is_cancelled = 'N'::bpchar) AND (er.reciept_cancelled = 'N'::bpchar));


