    ( SELECT COALESCE(sum(storestock.available_qty), (0)::bigint) AS "coalesce"
           FROM (((inventory.t_batch batch
             JOIN inventory.t_store_stock storestock ON (((storestock.batch_id = batch.id) AND (storestock.is_deleted = false) AND (storestock.is_active = true) AND (storestock.unit_id = um.unit_id))))
