CREATE VIEW public.get_patientconsumableissue AS
 SELECT DISTINCT t_issue.id,
    t_issue.issue_no,
    t_issue.added_date,
    patindent.indent_no,
    visittype.visit_type_name,
    adm.admission_number,
    patinfo.uhid_number,
    patinfo.patientname,
    (((('Dr.'::text || ' '::text) || (dm.first_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    sm.speciality_name,
    reqstore.store_name AS reqstore,
    tostore.store_name AS tostore,
    ward.ward_name,
    bed.bed_desc,
    item.code,
    item.name AS itemname,
    generic.name AS generic,
    batch.batch_no,
    uomtype.type AS uomtype,
    uom.unit AS uomunit,
    indentdetail.indent_quantity,
    stock.available_qty,
    batchmap.issue_quantity,
    um.unit_name,
    um.unit_address
   FROM (((((((((((((((((((((pharmacy.t_issue t_issue
     JOIN pharmacy.t_issue_detail issuedetail ON ((issuedetail.issue_id = t_issue.id)))
     JOIN pharmacy.t_patient_indent patindent ON ((t_issue.patient_indent_id = patindent.id)))
     JOIN pharmacy.t_patient_indent_detail indentdetail ON (((patindent.id = indentdetail.patient_indent_id) AND (indentdetail.id = issuedetail.patient_indent_detail_id))))
     JOIN public.m_item item ON ((indentdetail.item_id = item.id)))
     LEFT JOIN public.m_generic generic ON ((item.generic_id = generic.id)))
     JOIN pharmacy.t_issue_detail_batch_mapper batchmap ON ((issuedetail.id = batchmap.issue_detail_id)))
     JOIN inventory.t_batch batch ON ((batchmap.batch_id = batch.id)))
     LEFT JOIN public.m_uom_type uomtype ON ((indentdetail.uom_type_id = uomtype.id)))
     LEFT JOIN public.m_uom_unit uom ON ((indentdetail.uom_unit_id = uom.id)))
     LEFT JOIN public.m_store reqstore ON ((patindent.store_id = reqstore.store_id)))
     LEFT JOIN public.m_store tostore ON ((patindent.to_store_id = tostore.store_id)))
     JOIN inventory.t_store_stock stock ON (((batch.id = stock.batch_id) AND (stock.store_id = tostore.store_id))))
     LEFT JOIN public.m_visit_type_master visittype ON ((t_issue.visit_type_id = visittype.visit_type_id)))
     JOIN adt.t_admission adm ON ((t_issue.admission_id = adm.admission_id)))
     JOIN adt.t_admission_details admdetail ON ((adm.admission_id = admdetail.admission_id)))
     LEFT JOIN adt.m_ward_master ward ON ((admdetail.ward_id = ward.ward_id)))
     LEFT JOIN adt.m_bed_master bed ON ((admdetail.bed_id = bed.bed_id)))
     JOIN public.patientinformation patinfo ON ((adm.patient_id = patinfo.patient_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((t_issue.doctor_id = dm.doctor_id)))
     LEFT JOIN doctor.m_speciality_master sm ON ((dm.speciality_id = sm.speciality_id)))
     JOIN public.m_unit_master um ON ((t_issue.unit_id = um.unit_id)))
  WHERE (admdetail.admission_details_id = ( SELECT t_admission_details.admission_details_id
           FROM adt.t_admission_details
          WHERE (t_admission_details.admission_id = adm.admission_id)
          ORDER BY t_admission_details.admission_details_id DESC
         LIMIT 1));


