CREATE VIEW public.get_patientcount AS
 WITH cte AS (
         SELECT (pt.created_date)::date AS created_date,
            'IP'::text AS type,
            count(*) AS total
           FROM patient.t_patient_registration pt
          WHERE (pt.patient_id IN ( SELECT t_admission.patient_id
                   FROM adt.t_admission))
          GROUP BY ((pt.created_date)::date), 'IP'::text
        UNION
         SELECT (pt.created_date)::date AS created_date,
            'OP'::text AS type,
            count(*) AS total
           FROM patient.t_patient_registration pt
          GROUP BY ((pt.created_date)::date), 'OP'::text
        )
 SELECT cte.created_date,
    cte.type,
    cte.total
   FROM cte
  ORDER BY cte.created_date;


