           FROM patient.t_patient_registration pt
          WHERE (( SELECT count(em.patient_id) AS count
                   FROM opd.t_encounter_master em
                  WHERE (em.patient_id = pt.patient_id)) <= 1)
          GROUP BY ((pt.created_date)::date), 'NewReg'::text, pt.unit_id, pt.organization_id
