                     LEFT JOIN billing.m_transaction_type_master trantype ON ((t_sale_payment_mode.transaction_type_id = trantype.transaction_type_id)))) mode1 ON ((t_sale.id = mode1.sale_id)))
          WHERE ((t_sale.temp_patient_id IS NOT NULL) AND (t_sale.is_deleted = false))
) UNION ALL
 SELECT DISTINCT t_return.id,
