CREATE VIEW public.get_variance_approval AS
 SELECT va.id,
    stoptran.request_no,
    stoptran.added_date,
    stoptran.start_date_time,
    stoptran.stop_date_time,
    stoptran.added_by,
    m_store.store_name,
    m_status.status,
    um.user_name,
    m_item.code,
    m_item.name AS itemname,
    batch.cop,
    batch.rate,
    usd.approved_upload_quantity,
    csd.variance_cop,
    csd.variance_price,
    csd.approved_quantity,
    unit.unit_name,
    unit.unit_address,
    batch.current_quantity,
    batch.batch_no,
    usd.qty,
    ((batch.cop * (usd.approved_upload_quantity)::double precision) - (batch.cop * (usd.qty)::double precision)) AS vcop,
    ((batch.rate * (usd.approved_upload_quantity)::double precision) - (batch.rate * (usd.qty)::double precision)) AS vmrp,
    batch.quantity AS batchqty,
    va.added_date AS vadate,
    m_item.id AS itemid,
    m_store.store_id,
    unit.unit_id,
    unit.image
   FROM (((((((((((inventory.t_variance_approval va
     JOIN inventory.t_variance_approval_detail vad ON ((va.id = vad.variance_approval_id)))
     JOIN inventory.t_upload_stock uploadstock ON ((va.upload_stock_id = uploadstock.id)))
     JOIN inventory.t_stop_transaction stoptran ON ((uploadstock.stop_transaction_id = stoptran.id)))
     JOIN inventory.t_upload_stock_detail usd ON ((vad.upload_stoock_detail_id = usd.id)))
     JOIN inventory.t_compute_stock_detail csd ON ((vad.compute_stock_detail_id = csd.id)))
     JOIN inventory.t_batch batch ON ((usd.batch_id = batch.id)))
     LEFT JOIN public.m_item ON ((batch.item_id = m_item.id)))
     JOIN public.m_store ON ((stoptran.store_id = m_store.store_id)))
     LEFT JOIN public.m_status ON ((stoptran.status_id = m_status.id)))
     LEFT JOIN public.m_user_master um ON ((stoptran.added_by = um.user_id)))
     LEFT JOIN public.m_unit_master unit ON ((va.unit_id = unit.unit_id)))
  WHERE (vad.is_deleted = false);


