--

CREATE VIEW public.getadmissiondetails AS
 SELECT DISTINCT pr.uhid_number,
    adde.doa AS admission_date,
    dis.discharge_date,
    (((((pr.first_name)::text || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS name,
    pd.address,
    gm.gender_name,
    (abs(date_part('Year'::text, age(pr.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageyear,
    (abs(date_part('month'::text, age(pr.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS agemonth,
    (abs(date_part('Day'::text, age(pr.dob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageday,
    pr.mobile_number,
    bm.bed_number,
    um.user_name,
    ( SELECT cm_1.company_desc
           FROM (opd.t_patient_sponsor_details psd_1
             JOIN public.t_company_master cm_1 ON ((psd_1.payee_id = cm_1.company_id)))
          WHERE (ad.admission_id = psd_1.admission_id)
          ORDER BY psd_1.patient_sponsor_details_id DESC
         LIMIT 1) AS company_desc,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS docname,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_logo,
    public.advforadmission((ad.admission_id)::double precision) AS deposit,
    public.orderedamountforadmittedpatient((ad.admission_id)::double precision) AS orderamount,
    ad.admission_id,
    m_refferel.referral_contact_person,
    ad.admission_number,
    m_floor.floor_name,
    pr.first_name,
    dm.first_name AS docfirstname,
    dm.middle_name AS docmiddlename,
    dm.last_name AS doclastname,
    dm.doctor_id,
    vtm.visit_type_name,
    vtm.visit_type_id,
    ad.speciality_id,
    sp.speciality_name,
    m_ward.ward_name,
    unitinformation.unit_id,
    unitinformation.image,
    ((now())::date - (adde.doa)::date) AS staydays,
    m_ward.ward_id,
    pim.gender_id,
        CASE
            WHEN ((dis.discharge_date)::date IS NULL) THEN 0
            ELSE ((dis.discharge_date)::date - (adde.doa)::date)
        END AS disstaydays
   FROM ((((((((((((((((((adt.t_admission ad
