   FROM ((((((((((((((((adt.t_admission ad
     JOIN patient.t_patient_registration pr ON ((ad.patient_id = pr.patient_id)))
     JOIN adt.t_admission_details adde ON ((ad.admission_id = adde.admission_id)))
