     LEFT JOIN doctor.m_doctor_master dm ON ((ad.doctor_id = dm.doctor_id)))
     JOIN adt.m_bed_master bm ON ((adde.bed_id = bm.bed_id)))
     LEFT JOIN public.m_user_master um ON ((ad.updated_by = um.user_id)))
     LEFT JOIN opd.t_patient_sponsor_details psd ON ((ad.admission_id = psd.admission_id)))
     LEFT JOIN public.t_company_master cm ON ((psd.payee_id = cm.company_id)))
