    um.image
   FROM ((((((((((((lab.t_template_result ltr
     JOIN lab.t_lab_sample_dtls lsdel ON ((ltr.lab_sample_dtls_id = lsdel.lab_sample_dtls_id)))
     JOIN lab.t_lab_sample_master lsm ON ((lsdel.lab_sample_id = lsm.lab_sample_id)))
