     LEFT JOIN doctor.m_doctor_master dm ON ((om.ord_doctor_id = dm.doctor_id)))
     LEFT JOIN public.unitinformation um ON ((um.unit_id = lsm.org_unit_id)))
     JOIN public.m_user_master utm ON ((ltr.created_by = utm.user_id)))
     LEFT JOIN lab.m_test_master testmaster ON ((lsdel.test_id = testmaster.test_id)))
     LEFT JOIN doctor.m_sub_speciality_master labdept ON ((lsdel.sub_dept_id = labdept.sub_speciality_id)));


