     LEFT JOIN public.t_associated_company_master ON ((m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_id)))
     LEFT JOIN billing.m_preauth_request_master ON ((billmst.admission_id = m_preauth_request_master.admission_id)))
     LEFT JOIN doctor.m_doctor_master servicedoc ON ((billdtls.ord_doc_id = servicedoc.doctor_id)))
     LEFT JOIN doctor.m_speciality_master groupmaster ON ((servmst.speciality_id = groupmaster.speciality_id)))
     LEFT JOIN doctor.m_sub_speciality_master subgroupmaster ON ((servmst.sub_speciality_id = subgroupmaster.sub_speciality_id)))
     LEFT JOIN doctor.m_doctor_master admdoctor ON ((am.admitting_doctor_id = admdoctor.doctor_id)))
     LEFT JOIN public.t_referal_details admreff ON ((am.admission_id = admreff.admission_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
     LEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON ((billdtls.billing_details_id = payeemapper.bill_details_id)))
