           FROM (billing.t_payment_reciept_master prm
             JOIN billing.m_billing_master bm ON ((prm.billing_master_id = bm.billing_master_id)))
          WHERE ((COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar) OR (prm.reciept_cancelled IS NULL))
          GROUP BY prm.billing_master_id) payment ON ((billmst.billing_master_id = payment.billing_master_id)))
