-- Name: getipdbilldetails_distinct; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.getipdbilldetails_distinct AS
 SELECT DISTINCT getipdbilldetails.payeeidnew,
    getipdbilldetails.billing_master_id,
    getipdbilldetails.patient_id,
    getipdbilldetails.unit_id,
    getipdbilldetails.unit_name,
    getipdbilldetails.unit_address,
    getipdbilldetails.total_bill_amount,
    COALESCE(
        CASE
            WHEN (getipdbilldetails.payeeidnew = 1) THEN sum(getipdbilldetails.payee_amount)
            ELSE NULL::numeric
        END, (0)::numeric) AS payeeself,
    COALESCE(
        CASE
            WHEN (getipdbilldetails.payeeidnew = 119) THEN sum(getipdbilldetails.payee_amount)
            ELSE NULL::numeric
        END, (0)::numeric) AS infh,
    COALESCE(
        CASE
            WHEN (getipdbilldetails.payeeidnew <> ALL (ARRAY[1, 119])) THEN sum(getipdbilldetails.payee_amount)
            ELSE NULL::numeric
        END, (0)::numeric) AS othercompinsurance,
    getipdbilldetails.admission_id
   FROM public.getipdbilldetails
  GROUP BY getipdbilldetails.payeeidnew, getipdbilldetails.billing_master_id, getipdbilldetails.patient_id, getipdbilldetails.unit_id, getipdbilldetails.unit_name, getipdbilldetails.unit_address, getipdbilldetails.total_bill_amount, getipdbilldetails.admission_id;


