    od.order_details_id,
    packagemapper.package_id,
    billmst.bill_number,
    billmst.bill_date_time
   FROM ((((((billing.t_billing_details billdtls
     JOIN billing.m_billing_master billmst ON ((billmst.billing_master_id = billdtls.billing_master_id)))
     JOIN public.t_order_details_package_mapper packagemapper ON ((billdtls.order_details_id = packagemapper.order_details_id)))
     JOIN service.m_service_master servmst ON ((servmst.service_master_id = billdtls.service_id)))
     JOIN opd.t_encounter_master encmst ON ((billmst.encounter_id = encmst.encounter_id)))
     JOIN billing.t_bill_details_payee_mapper payeemapper ON ((billdtls.billing_details_id = payeemapper.bill_details_id)))
     JOIN public.t_order_details od ON ((billdtls.order_details_id = od.order_details_id)))
  WHERE ((billmst.visit_type_id = 1) AND (payeemapper.status = 'A'::bpchar) AND (od.is_package_service = 'Y'::"char") AND (packagemapper.is_package_service = 'Y'::bpchar));


