     LEFT JOIN lab.m_test_master testmaster ON ((labsampledetails.test_id = testmaster.test_id)))
     LEFT JOIN lab.t_test_parameter_mppr testmapper ON (((testmaster.test_id = testmapper.test_id) AND (testmapper.is_deleted = 'N'::bpchar))))
     JOIN lab.m_parameter_master parametermaster ON ((parametermaster.parameter_id = testmapper.parameter_id)))
