    age(pim.dob) AS age,
    gender.gender_name,
        CASE
            WHEN (admreff.admission_id IS NULL) THEN concat(m_refferel.referral_name)
            ELSE concat(m_reffereladm.referral_name)
        END AS doctername,
    om.order_no,
    lsdel.sample_collection_datetime,
    lrm.result_authorised_datetime,
        CASE
            WHEN (om.admission_id IS NULL) THEN em.encounter_number
            WHEN (om.admission_id IS NOT NULL) THEN adm.admission_number
            ELSE NULL::character varying
        END AS opipdno,
    lsm.sample_no,
    lhm.header_code,
    lhm.header_desc,
    lhm.header_status,
    ldel.param_name,
    ldel.final_result AS result,
    ldel.parameter_min,
    ldel.parameter_max AS param_abnrml_max,
    ldel.param_unit,
    ldel.result_type_flag,
    um.unit_id,
