    om.org_id,
    utm.user_id,
    utm.user_name,
    ldel.textual_range_id,
    ldel.textual_range_name,
    ldel.multitextaul_range,
    ldel.refrange_type_id,
    labdept.sub_speciality_name AS department_name,
    lrm.foot_notes,
    um.unit_name,
    lrm.lab_sample_dtls_id,
    ltm.foot_note,
    (abs(date_part('Year'::text, age((to_char(pim.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS ageyear,
    param_textual.remark,
    pim.gender_id,
    ldel.parameter_id,
    sequenceno.para_sequence,
    ltm.test_id,
    lrm.sample_status_id,
    um.image,
    tm.technique_name,
    (abs(date_part('Month'::text, age((to_char(pim.dob, 'YYYY-MM-DD'::text))::timestamp with time zone))))::integer AS months,
    agegroupid.age_type_grp_name,
    param_multitext.remark AS multitextremark,
    um.unit_email_id,
