--

CREATE VIEW public.getpendingissuesdetails AS
 SELECT DISTINCT issue.id,
    issue.unit_id,
    issue.issue_no,
    issue.prescription_id,
    pres.prescription_no,
    pres.prescription_date,
    pim.patientname,
    concat('Dr. ', COALESCE(docmaster.first_name, ''::character varying), ' ', COALESCE(docmaster.middle_name, ''::character varying), ' ', COALESCE(docmaster.last_name, ''::character varying)) AS "doctorName",
    ward.ward_name,
    bed.bed_desc,
    priority.priority_desc,
    m_item.name AS itemname,
    m_generic.name AS genericname,
    m_manufacturer.name AS manufacture,
    presd.order_qty,
    presd.pending_qty,
    m_status.status,
    presd.remark,
    m_instruction.instruction_desc,
    unitinformation.unit_name,
    unitinformation.unit_address,
    issue.added_date,
    m_store.store_name,
    issuedetail.issue_quantity
   FROM (((((((((((((((((pharmacy.t_issue issue
     JOIN pharmacy.t_issue_detail issuedetail ON ((issuedetail.issue_id = issue.id)))
     LEFT JOIN pharmacy.t_prescription pres ON ((issue.prescription_id = pres.id)))
     JOIN pharmacy.t_prescription_detail presd ON (((pres.id = presd.prescription_id) AND (presd.id = issuedetail.prescription_detail_id))))
     JOIN public.m_item ON ((presd.item_id = m_item.id)))
     LEFT JOIN public.m_status ON ((presd.status_id = m_status.id)))
     LEFT JOIN public.m_instruction ON ((presd.instruction_id = m_instruction.instruction_id)))
     JOIN public.m_generic ON ((m_item.generic_id = m_generic.id)))
     LEFT JOIN public.m_manufacturer ON ((m_item.manufacturer_id = m_manufacturer.id)))
     LEFT JOIN adt.t_admission adm ON ((issue.admission_id = adm.admission_id)))
     LEFT JOIN public.patientinformation pim ON ((adm.patient_id = pim.patient_id)))
     LEFT JOIN doctor.m_doctor_master docmaster ON ((issue.doctor_id = docmaster.doctor_id)))
     LEFT JOIN adt.t_admission_details admdetails ON ((admdetails.admission_id = adm.admission_id)))
     LEFT JOIN adt.m_ward_master ward ON ((admdetails.ward_id = ward.ward_id)))
     LEFT JOIN adt.m_bed_master bed ON ((admdetails.bed_id = bed.bed_id)))
     LEFT JOIN adt.m_priority_master priority ON ((pres.priority_id = priority.priority_id)))
     LEFT JOIN public.unitinformation ON ((issue.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.m_store ON ((issue.store_id = m_store.store_id)))
  WHERE (admdetails.admission_details_id = ( SELECT t_admission_details.admission_details_id
           FROM adt.t_admission_details
          WHERE (t_admission_details.admission_id = adm.admission_id)
          ORDER BY t_admission_details.admission_details_id DESC
         LIMIT 1));


