CREATE VIEW public.getreferralconsultatation AS
 SELECT DISTINCT m_billing_master.billing_master_id,
    t_patient_registration.uhid_number,
    (((t_patient_registration.first_name)::text || ' '::text) || (t_patient_registration.last_name)::text) AS patientname,
    t_patient_registration.mobile_number,
    t_patient_details.address,
    t_encounter_master.encounter_number,
    t_encounter_master.encounter_date,
    m_billing_master.bill_number,
    m_billing_master.bill_date_time,
    ''::text AS doctorname,
    ''::text AS first_name,
    ''::text AS last_name,
    m_billing_master.total_bill_amount,
    m_billing_master.discount_amount,
    m_billing_master.net_amount,
    m_service_master.service_standard_name AS new_visit_service,
    0 AS doctor_id,
    (((m_employee_master.first_name)::text || ' '::text) || (m_employee_master.last_name)::text) AS username,
    m_user_master.user_id,
    t_encounter_master.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    patientinformation.age,
    patientinformation.gender_name,
    t_encounter_master.encounter_time,
    0 AS new_visit_service_id,
    sp.speciality_name,
    sp.speciality_id,
    t_encounter_master.user_defined_visit_type_id,
    t_patient_registration.organization_id,
    t_billing_details.gross_amount,
    t_billing_details.discount,
    t_billing_details.net_amt,
    m_refferel.referral_name,
    m_refferel.referral_id,
    payment.amount AS paidamount,
    unitinformation.image,
    m_refferel.referral_contact
   FROM (((((((((((((patient.t_patient_registration
     JOIN patient.t_patient_details ON ((t_patient_registration.patient_id = t_patient_details.patient_id)))
     JOIN opd.t_encounter_master ON ((t_patient_details.patient_id = t_encounter_master.patient_id)))
     JOIN billing.m_billing_master ON ((m_billing_master.encounter_id = t_encounter_master.encounter_id)))
     JOIN billing.t_billing_details ON ((m_billing_master.billing_master_id = t_billing_details.billing_master_id)))
     JOIN service.m_service_master ON ((t_billing_details.service_id = m_service_master.service_master_id)))
     JOIN doctor.m_speciality_master sp ON ((m_service_master.speciality_id = sp.speciality_id)))
     LEFT JOIN public.m_user_master ON ((m_user_master.user_id = m_billing_master.created_by)))
     LEFT JOIN public.unitinformation ON ((m_billing_master.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.m_employee_master ON ((m_employee_master.user_id = m_user_master.user_id)))
     JOIN patient.patientinformation ON ((t_encounter_master.patient_id = patientinformation.patient_id)))
     JOIN public.t_referal_details admreff ON ((t_encounter_master.encounter_id = admreff.encounter_id)))
     JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
     JOIN ( SELECT prm.billing_master_id,
            sum(prd.amount) AS amount
           FROM ((billing.t_payment_reciept_master prm
             JOIN billing.t_payment_reciept_details prd ON ((prm.payment_reciept_id = prd.payment_receipt_master_id)))
             JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
          GROUP BY prm.billing_master_id) payment ON ((m_billing_master.billing_master_id = payment.billing_master_id)))
  WHERE ((m_billing_master.visit_type_id = 1) AND (m_billing_master.bill_status_id = 3) AND (m_billing_master.bill_cancelled = 'N'::bpchar));


