    concat('Dr.', ' ', dm.first_name, ' ', dm.last_name) AS doctername,
    om.order_no,
    lsdel.sample_collection_datetime,
    slrm.result_enter_date,
        CASE
            WHEN (om.admission_id IS NULL) THEN em.encounter_number
            WHEN (om.admission_id IS NOT NULL) THEN adm.admission_number
            ELSE NULL::character varying
        END AS opipdno,
    lsm.sample_no,
    um.unit_id,
