    um.unit_name,
    (abs(date_part('Year'::text, age(pim.patientdob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageyear,
    techmaster.technique_name,
    ltm.foot_note,
    concat('Dr.', '', m_refferel.referral_name) AS docname,
    um.image,
    um.unit_email_id,
    paramaster.parameter_name,
    slrm.result_validated_date
   FROM (((((((((((((((((lab.t_serology_test_result slrm
     JOIN lab.t_lab_sample_dtls lsdel ON ((slrm.lab_sample_dtls_id = lsdel.lab_sample_dtls_id)))
     LEFT JOIN lab.m_test_master ltm ON ((lsdel.test_id = ltm.test_id)))
     JOIN lab.t_lab_sample_master lsm ON ((lsdel.lab_sample_id = lsm.lab_sample_id)))
     JOIN public.t_order_master om ON ((om.order_id = lsm.order_id)))
     LEFT JOIN adt.t_admission adm ON ((om.admission_id = adm.admission_id)))
     LEFT JOIN opd.t_encounter_master em ON ((om.encounter_id = em.encounter_id)))
     LEFT JOIN lab.t_panel_master plm ON ((plm.panel_id = lsdel.profile_id)))
     LEFT JOIN patient.patientinformation pim ON ((lsm.patient_id = pim.patient_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((om.ord_doctor_id = dm.doctor_id)))
     LEFT JOIN public.unitinformation um ON ((um.unit_id = slrm.org_unit_id)))
     JOIN public.m_user_master utm ON ((slrm.result_enter_by = utm.user_id)))
     LEFT JOIN doctor.m_sub_speciality_master labdept ON ((lsdel.sub_dept_id = labdept.sub_speciality_id)))
     LEFT JOIN lab.t_serology_result_test_mppr serology_result ON ((slrm.serology_test_result_id = serology_result.serology_test_result_id)))
     LEFT JOIN lab.m_technique_master techmaster ON ((serology_result.technique_id = techmaster.technique_id)))
     LEFT JOIN lab.m_parameter_master paramaster ON ((serology_result.parameter_id = paramaster.parameter_id)))
     LEFT JOIN public.t_referal_details admreff ON ((em.encounter_id = admreff.encounter_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)));


