    od.order_date,
    bm.bill_date_time,
    bm.billing_master_id,
    bm.bill_number,
    bd.quantity,
    docinfor.speciality_name AS docspeciality,
    ( SELECT pmode.payment_mode_desc
           FROM ((billing.t_payment_reciept_master pr_1
             JOIN billing.t_payment_reciept_details prd ON ((pr_1.payment_reciept_id = prd.payment_receipt_master_id)))
             JOIN public.m_payment_mode_master pmode ON ((prd.payment_mode_id = pmode.payment_mode_id)))
          WHERE (pr_1.billing_master_id = bm.billing_master_id)
         LIMIT 1) AS payment_mode_desc,
    od.order_details_id,
    payment.amount AS paidamount,
    bm.outstanding,
    bd.billing_details_id,
    docmaper.doctor_id
   FROM (((((((((((((((((public.t_order_details od
     JOIN public.t_order_master om ON ((od.order_id = om.order_id)))
     LEFT JOIN patient.t_patient_registration pr ON ((om.patient_id = pr.patient_id)))
     JOIN service.m_service_master sm ON ((od.service_id = sm.service_master_id)))
     LEFT JOIN doctor.m_speciality_master sp ON ((sm.speciality_id = sp.speciality_id)))
     LEFT JOIN doctor.m_sub_speciality_master ssm ON ((sm.sub_speciality_id = ssm.sub_speciality_id)))
     LEFT JOIN public.unitinformation u ON ((od.org_unit_id = u.unit_id)))
