     LEFT JOIN public.t_referal_details admreff ON ((bm.encounter_id = admreff.encounter_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
     LEFT JOIN opd.t_encounter_master en ON ((bm.encounter_id = en.encounter_id)))
     LEFT JOIN doctor.m_doctor_master consdoctor ON ((en.doctor_id = consdoctor.doctor_id)))
     LEFT JOIN doctor.t_doctor_speciality_mapper docmaper ON (((en.doctor_id = docmaper.doctor_id) AND (docmaper.status = 'A'::bpchar))))
     LEFT JOIN doctor.m_speciality_master docinfor ON ((docmaper.speciality_id = docinfor.speciality_id)))
