     LEFT JOIN lab.t_panel_master plm ON ((plm.panel_id = lsdel.profile_id)))
     LEFT JOIN lab.m_header_master lhm ON ((ldel.header_id = lhm.header_id)))
     LEFT JOIN patient.patientinformation pim ON ((om.patient_id = pim.patient_id)))
     LEFT JOIN doctor.m_doctor_master dm ON ((om.ord_doctor_id = dm.doctor_id)))
     LEFT JOIN public.unitinformation um ON ((um.unit_id = lrm.org_unit_id)))
     JOIN public.m_user_master utm ON ((lrm.created_by = utm.user_id)))
     LEFT JOIN doctor.m_sub_speciality_master labdept ON ((lsdel.sub_dept_id = labdept.sub_speciality_id)))
