    approvedby.user_name AS approvedby
   FROM ((((((((((procurement.t_work_order wo
     JOIN procurement.t_work_order_detail wod ON ((wo.id = wod.work_order_id)))
     JOIN public.m_store ON ((wo.store_id = m_store.store_id)))
     JOIN public.m_item ON ((wod.item_id = m_item.id)))
     JOIN public.unitinformation ON ((wo.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.m_vendor ON ((wod.current_vendor_id = m_vendor.id)))
     LEFT JOIN public.m_status ON ((wo.status_id = m_status.id)))
     LEFT JOIN public.m_status approvalstatus ON ((wo.approval_status_id = approvalstatus.id)))
     LEFT JOIN procurement.m_contract_type contract ON ((wo.contract_type_id = contract.id)))
     LEFT JOIN public.m_user_master usermaster ON ((wo.added_by = usermaster.user_id)))
     LEFT JOIN public.m_user_master approvedby ON ((wo.approved_by = approvedby.user_id)));


