--
-- TOC entry 3168 (class 1259 OID 2982582)
-- Name: m_view_bed_variable_factor; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.m_view_bed_variable_factor AS
 SELECT mstm.service_tarrif_master_id,
    mstm.visit_type_id,
    mstm.unit_id,
    mstm.organisation_id,
    tstbedtype.bed_type_id,
    tstbedtype.multiplication_factor,
    1 AS type_diff
   FROM (service.m_service_tarrif_master mstm
     JOIN service.t_service_tarrif_bed_type_manager tstbedtype ON ((mstm.service_tarrif_master_id = tstbedtype.service_tarrif_id)))
  WHERE (mstm.status = 'A'::"char")
UNION ALL
 SELECT mstm.service_tarrif_master_id,
    mstm.visit_type_id,
    mstm.unit_id,
    mstm.organisation_id,
    tstpatienttype.patient_category_id AS bed_type_id,
    tstpatienttype.multiplication_factor,
    2 AS type_diff
   FROM (service.m_service_tarrif_master mstm
     LEFT JOIN service.t_service_tarrif_patient_category_manager tstpatienttype ON ((mstm.service_tarrif_master_id = tstpatienttype.service_tarrif_master_id)))
  WHERE (mstm.status = 'A'::"char")
UNION ALL
 SELECT mstm.service_tarrif_master_id,
    mstm.visit_type_id,
    mstm.unit_id,
    mstm.organisation_id,
    tstpaymenttype.payment_entitlement_id AS bed_type_id,
    tstpaymenttype.multiplication_factor,
    3 AS type_diff
   FROM (service.m_service_tarrif_master mstm
     LEFT JOIN service.t_service_tarrif_payment_entitlement_manager tstpaymenttype ON ((mstm.service_tarrif_master_id = tstpaymenttype.service_tarrif_master_id)))
  WHERE (mstm.status = 'A'::"char")
  WITH NO DATA;


