-- Name: mis_sales_credit_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mis_sales_credit_report AS
 SELECT DISTINCT sle.id,
    sle.bill_no,
    sle.encounter_id,
    sle.admission_id,
    slt.type AS sale_type,
    sle.added_date,
    s.status,
    sle.total_amount,
    sle.discount,
    sle.total_discount_amount,
    sle.net_amount,
    sle.tax_amount,
    sle.outstanding_amount,
    sle.paid_amount,
    sle.round_off,
    sle.total_self_payable,
    sle.total_credit_payable,
    sle.patient_id,
    sle.temp_patient_id,
        CASE
            WHEN (sle.patient_id IS NULL) THEN sle.temp_patient_id
            ELSE sle.patient_id
        END AS merge_patient_id,
        CASE
            WHEN (sle.temp_patient_id IS NOT NULL) THEN ((pm1.prefix_desc || '. '::text) || (pr1.patient_name)::text)
            ELSE ((((((pm.prefix_desc || ' '::text) || (pr.first_name)::text) || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text)
        END AS patient_name,
    sle.visit_type_id,
    vtm.visit_type_name,
    u.unit_id,
    u.unit_name,
    u.unit_address
   FROM ((((((((((pharmacy.t_sale sle
     LEFT JOIN public.m_sale_type slt ON ((sle.sale_type_id = slt.id)))
     LEFT JOIN patient.t_patient_registration pr ON ((sle.patient_id = pr.patient_id)))
     LEFT JOIN pharmacy.t_temp_patient_registration pr1 ON ((sle.temp_patient_id = pr1.id)))
     LEFT JOIN public.m_prefix_master pm ON ((pr.prefix_id = pm.prefix_id)))
     LEFT JOIN public.m_prefix_master pm1 ON ((pr1.prefix_id = pm1.prefix_id)))
     LEFT JOIN public.m_status s ON ((sle.status_id = s.id)))
     LEFT JOIN opd.t_encounter_master enc ON ((sle.encounter_id = enc.encounter_id)))
     LEFT JOIN adt.t_admission adm ON ((sle.admission_id = adm.admission_id)))
     LEFT JOIN public.m_visit_type_master vtm ON ((sle.visit_type_id = vtm.visit_type_id)))
     LEFT JOIN public.unitinformation u ON ((sle.unit_id = u.unit_id)))
  WHERE (sle.outstanding_amount <> (0)::double precision)
  ORDER BY sle.id;


