CREATE VIEW public.mis_supplier_address_report AS
 SELECT DISTINCT v.id,
    u.unit_id,
    u.unit_name,
    u.unit_address,
    mnf.name AS manufacturer,
    v.code,
    v.name AS vendor_name,
    v.contact_person_name,
    v.drug_license_no,
    v.gst_no,
    v.address,
    coun.country_name,
    st.state_name,
    cty.city_name,
    ar.area_name,
    v.phone_number,
    v.email_id,
    pmm.payment_mode_desc,
    v.payment_term,
    v.zip_code
   FROM (((((((public.m_vendor v
     LEFT JOIN public.m_manufacturer mnf ON ((v.manufacturer_id = mnf.id)))
     LEFT JOIN public.unitinformation u ON ((v.unit_id = u.unit_id)))
     LEFT JOIN public.m_country_master coun ON ((v.country_id = coun.country_id)))
     LEFT JOIN public.m_state_master st ON ((v.state_id = st.state_id)))
     LEFT JOIN public.m_city_master cty ON ((v.city_id = cty.city_id)))
     LEFT JOIN public.m_area_master ar ON ((v.area_id = ar.area_id)))
     LEFT JOIN public.m_payment_mode_master pmm ON ((v.payment_mode_id = pmm.payment_mode_id)));


