    st.store_name,
    s.status,
    woc.added_date,
    woc.added_by,
    woc.total_amount,
    woc.total_discount,
    woc.total_tax,
    woc.net_amount,
    con.description AS contract_type,
    u.unit_name,
    u.unit_address,
    ((((pm.prefix_desc || ' '::text) || (emp.first_name)::text) || ' '::text) || (emp.last_name)::text) AS user_name,
    usm.user_id,
    v.name,
    woc.vendor_id,
    wocd.item_id,
    it.name AS item_name,
    t.name AS tax_description,
    wocd.wo_quantity,
    wocd.qo_bonus_quantity,
    wocd.amount AS details_amount,
    wocd.discount_amount AS details_discount,
    wocd.tax_amount AS details_tax,
    wocd.total_amount AS details_total_amount,
    wocd.net_amount AS details_net_amount,
    wocd.remark AS details_remarks,
    bat.batch_no,
    woc.work_order_no,
    wo.added_date AS work_order_date
   FROM (((((((((((((procurement.t_work_order_creation woc
     LEFT JOIN public.unitinformation u ON ((woc.unit_id = u.unit_id)))
     LEFT JOIN public.m_store st ON ((woc.store_id = st.store_id)))
     LEFT JOIN public.m_vendor v ON ((woc.vendor_id = v.id)))
     LEFT JOIN public.m_status s ON ((woc.status_id = s.id)))
     LEFT JOIN procurement.m_contract_type con ON ((woc.contract_type_id = con.id)))
     LEFT JOIN public.m_user_master usm ON ((woc.added_by = usm.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((usm.user_id = emp.user_id)))
     LEFT JOIN public.m_prefix_master pm ON ((emp.prefix_id = pm.prefix_id)))
     LEFT JOIN procurement.t_work_order_creation_detail wocd ON ((woc.id = wocd.wo_creation_id)))
     LEFT JOIN public.m_item it ON ((wocd.item_id = it.id)))
     LEFT JOIN public.m_tax t ON ((wocd.tax_id = t.id)))
     LEFT JOIN inventory.t_batch bat ON ((wocd.batch_id = bat.id)))
     LEFT JOIN procurement.t_work_order wo ON ((woc.work_order_id = wo.id)));


