    um.unit_description,
    COALESCE(public.pharmacyservice_id(billmst.billing_master_id), 0) AS pharmacyservice_id
   FROM (((((((((((((((((((((((((((((billing.t_billing_details billdtls
     LEFT JOIN billing.m_billing_master billmst ON ((billmst.billing_master_id = billdtls.billing_master_id)))
     LEFT JOIN service.m_service_master servmst ON ((servmst.service_master_id = billdtls.service_id)))
     LEFT JOIN doctor.m_speciality_master spc ON ((spc.speciality_id = servmst.speciality_id)))
     LEFT JOIN public.m_general_ledger_master genledmst ON ((genledmst.general_ledger_id = spc.general_ledger_id)))
