     LEFT JOIN public.patientinformation pim ON ((encmst.patient_id = pim.patient_id)))
     LEFT JOIN public.m_prefix_master pm ON ((pntmst.prefix_id = pm.prefix_id)))
     LEFT JOIN public.m_organization_master ON ((billmst.organisation_id = m_organization_master.organization_id)))
     LEFT JOIN doctor.m_doctor_master ON ((encmst.doctor_id = m_doctor_master.doctor_id)))
     LEFT JOIN doctor.m_speciality_master docsp ON ((m_doctor_master.speciality_id = docsp.speciality_id)))
     LEFT JOIN public.m_user_master ON ((billmst.created_by = m_user_master.user_id)))
