     LEFT JOIN doctor.doctorinformation ON ((billmst.encounter_id = doctorinformation.encounter_id)))
     LEFT JOIN public.t_company_master company ON ((billdtls.payee_id = company.company_id)))
     LEFT JOIN doctor.m_speciality_master speciality ON ((encmst.dept_id = speciality.speciality_id)))
     LEFT JOIN doctor.m_doctor_master doctorm ON ((encmst.doctor_id = doctorm.doctor_id)))
     LEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON ((billdtls.billing_details_id = payeemapper.bill_details_id)))
     LEFT JOIN public.t_company_master companynew ON ((payeemapper.payee_id = companynew.company_id)))
     LEFT JOIN service.m_company_contract_master contractmaster ON ((payeemapper.contract_id = contractmaster.contract_id)))
     LEFT JOIN public.t_order_details od ON ((billdtls.order_details_id = od.order_details_id)))
     LEFT JOIN billing.m_billing_status_master billstatusmaster ON ((billmst.bill_status_id = billstatusmaster.bill_status_id)))
     LEFT JOIN public.t_referal_details admreff ON ((encmst.encounter_id = admreff.encounter_id)))
     LEFT JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
