-- Name: non_formulary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.non_formulary AS
 SELECT 0 AS srno,
    pinfo.patientname,
    pinfo.age,
    pinfo.gender_name,
    pinfo.uhid_number,
        CASE
            WHEN (pres.admission_id IS NULL) THEN em.encounter_number
            ELSE adm.admission_number
        END AS visitnumber,
        CASE
            WHEN (pres.admission_id IS NULL) THEN em.encounter_date
            ELSE adm.created_date
        END AS visitdate,
    um.unit_id,
    um.unit_name,
    um.image AS unit_logo,
    um.unit_address,
    um.organization_id,
    presdtl.item_id AS "itemId",
    presdtl.item_name AS "itemName",
    prefredtl.dose AS "doseDesc",
    su.unit AS "strengthDesc",
    prefredtl.frequency_id AS "frequencyId",
    freq.description AS "frequencyDesc",
    prefredtl.route_id AS "roaId",
    presdtl.statflag,
    roa.description AS "roaDesc",
    prefredtl.start_date AS startdate,
    prefredtl.stop_date AS enddate,
    presdtl.instruction_id AS "instructionId",
    instr.instruction_desc AS "instructionDesc",
    presdtl.generic_name AS "genericName",
    pres.encounter_id,
    presdtl.order_qty AS qty,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    dm.registration_number,
    pinfo.patient_id,
    ''::text AS unit_address_2,
    pres.id,
    pres.prescription_no,
    pres.prescription_date,
    pinfo.patientaddress,
    pinfo.mobile_number,
    pinfo.patientdob,
    (abs(date_part('Year'::text, age(pinfo.patientdob, (('now'::text)::date)::timestamp without time zone))))::integer AS ageyear,
    '0'::text AS is_medication_stop,
    '2019-11-22 09:54:34'::timestamp without time zone AS updated_date,
    ''::text AS justification_stop,
    pres.visit_type_id,
    true AS is_narcotic,
    um.unit_contact,
    um.unit_email_id,
    um.image,
    dm.doctor_id,
    ''::text AS instruction_desc,
    ''::text AS converted_text,
    1 AS language_id
   FROM (((((((((((pharmacy.t_prescription pres
     JOIN pharmacy.t_prescription_detail presdtl ON ((presdtl.prescription_id = pres.id)))
     LEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON ((prefredtl.prescription_detail_id = presdtl.id)))
     LEFT JOIN public.m_route_of_administration roa ON ((roa.id = prefredtl.route_id)))
     LEFT JOIN public.m_frequency freq ON ((freq.id = prefredtl.frequency_id)))
     LEFT JOIN public.m_instruction instr ON ((instr.instruction_id = presdtl.instruction_id)))
     LEFT JOIN public.m_strength_unit su ON ((prefredtl.dose_unit_id = su.id)))
     JOIN public.patientinformation pinfo ON ((pres.patient_id = pinfo.patient_id)))
     LEFT JOIN opd.t_encounter_master em ON ((em.encounter_id = pres.encounter_id)))
     LEFT JOIN adt.t_admission adm ON ((adm.admission_id = pres.admission_id)))
     JOIN public.m_unit_master um ON ((um.unit_id = pres.unit_id)))
     JOIN doctor.m_doctor_master dm ON ((dm.doctor_id = pres.doctor_id)))
  WHERE (presdtl.is_non_formulary = 'Y'::bpchar);


