-- TOC entry 3705 (class 1259 OID 4569559)
-- Name: op_ip_pathology; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.op_ip_pathology AS
 SELECT DISTINCT bm.bill_number,
    bm.bill_date_time,
        CASE
            WHEN (bm.admission_id IS NULL) THEN em.encounter_number
            ELSE adm.admission_number
        END AS opipnumber,
    pim.uhid_number,
    pim.patientname,
    pim.patientaddress,
    pim.patientmobile,
    concat('Dr. ', dmopd.first_name, ' ', dmopd.last_name) AS doctorname,
        CASE
            WHEN (bm.admission_id IS NULL) THEN spopd.speciality_name
            ELSE spipd.speciality_name
        END AS department,
    0 AS consultation,
    0 AS followup_visit,
    dsp.speciality_name,
    dssp.sub_speciality_name,
    sm.service_standard_name,
    bd.quantity,
    bd.rate,
    bd.gross_amount,
    COALESCE((bd.discount + bd.concession), (0)::double precision) AS discount,
    bd.net_amt,
    bm.outstanding,
    um.unit_name,
    um.unit_address,
    um.unit_id,
    um.image,
    visit.visit_type_id,
    COALESCE((bm.discount_amount + bm.concession_amount), (0)::double precision) AS discount_amount,
    bm.total_bill_amount,
    bm.net_amount,
    bm.billing_master_id,
    prr.amount,
    bd.billing_details_id,
    bm.bill_cancelled,
    ward.ward_name,
    prr.reciept_number,
    prr.date_of_reciept,
    dsp.speciality_id,
    bm.patient_id,
        CASE
            WHEN (bm.admission_id IS NULL) THEN ( SELECT cm_1.company_desc
               FROM (opd.t_patient_sponsor_details psd_1
                 JOIN public.t_company_master cm_1 ON (((psd_1.payee_id = cm_1.company_id) AND (psd_1.priority_id = 1) AND (bm.encounter_id = psd_1.encounter_id))))
             LIMIT 1)
            ELSE ( SELECT cm_1.company_desc
               FROM (opd.t_patient_sponsor_details psd_1
                 JOIN public.t_company_master cm_1 ON (((psd_1.payee_id = cm_1.company_id) AND (psd_1.priority_id = 1) AND (bm.admission_id = psd_1.admission_id))))
             LIMIT 1)
        END AS company_desc,
        CASE
            WHEN (bm.admission_id IS NULL) THEN ( SELECT cm_1.company_id
               FROM (opd.t_patient_sponsor_details psd_1
                 JOIN public.t_company_master cm_1 ON (((psd_1.payee_id = cm_1.company_id) AND (psd_1.priority_id = 1) AND (bm.encounter_id = psd_1.encounter_id))))
             LIMIT 1)
            ELSE ( SELECT cm_1.company_id
               FROM (opd.t_patient_sponsor_details psd_1
                 JOIN public.t_company_master cm_1 ON (((psd_1.payee_id = cm_1.company_id) AND (psd_1.priority_id = 1) AND (bm.admission_id = psd_1.admission_id))))
             LIMIT 1)
        END AS payee_id
   FROM (((((((((((((((((billing.m_billing_master bm
     JOIN billing.t_billing_details bd ON ((bm.billing_master_id = bd.billing_master_id)))
     JOIN public.t_order_details od ON ((bd.order_details_id = od.order_details_id)))
     JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     JOIN doctor.m_speciality_master dsp ON ((sm.speciality_id = dsp.speciality_id)))
     JOIN doctor.m_sub_speciality_master dssp ON ((sm.sub_speciality_id = dssp.sub_speciality_id)))
     LEFT JOIN opd.t_encounter_master em ON ((bm.encounter_id = em.encounter_id)))
     LEFT JOIN adt.t_admission adm ON ((bm.admission_id = adm.admission_id)))
     LEFT JOIN public.patientinformation pim ON ((bm.patient_id = pim.patient_id)))
     LEFT JOIN doctor.m_doctor_master dmopd ON ((od.ord_doc_id = dmopd.doctor_id)))
     LEFT JOIN public.t_referal_details referop ON ((em.encounter_id = referop.encounter_id)))
     LEFT JOIN public.t_referal_details referip ON ((adm.admission_id = referip.admission_id)))
     LEFT JOIN public.m_visit_type_master visit ON ((bm.visit_type_id = visit.visit_type_id)))
     LEFT JOIN doctor.m_speciality_master spopd ON ((em.dept_id = spopd.speciality_id)))
     LEFT JOIN doctor.m_speciality_master spipd ON ((adm.speciality_id = spipd.speciality_id)))
     LEFT JOIN public.unitinformation um ON ((bm.unit_id = um.unit_id)))
     LEFT JOIN adt.m_ward_master ward ON ((ward.ward_id = od.ward_id)))
     LEFT JOIN ( SELECT sum(prd.amount) AS amount,
            pr.reciept_number,
            pr.date_of_reciept,
            pr.billing_master_id
           FROM (billing.t_payment_reciept_master pr
             JOIN billing.t_payment_reciept_details prd ON ((pr.payment_reciept_id = prd.payment_receipt_master_id)))
          WHERE ((pr.reciept_cancelled = 'N'::bpchar) AND (prd.payment_mode_id <> 10))
          GROUP BY pr.billing_master_id, pr.reciept_number, pr.date_of_reciept) prr ON ((bm.billing_master_id = prr.billing_master_id)))
  WHERE ((bm.bill_cancelled = 'N'::bpchar) AND (bm.bill_status_id = 3));


