 SELECT package.package_master_id,
    pim.uhid_number,
    pim.patientname,
    sm.service_standard_name,
    visit.visit_type_name,
    ptype.package_type,
    smtest.service_standard_name AS testservice,
    om.order_date,
    ssp.sub_speciality_name,
    om.order_id,
    samplemaster.sample_id,
    labsampledetails.test_id,
    testmaster.test_desc,
    um.unit_id,
    um.unit_name,
    um.unit_address
   FROM ((((((((((((((service.m_package_master package
     LEFT JOIN billing.t_package_consumption_master pcm ON ((package.package_master_id = pcm.package_id)))
     JOIN service.m_service_master sm ON ((package.service_id = sm.service_master_id)))
     LEFT JOIN public.patientinformation pim ON ((pcm.patient_id = pim.patient_id)))
     LEFT JOIN public.m_visit_type_master visit ON ((pcm.visit_type = visit.visit_type_id)))
     LEFT JOIN service.m_package_type_master ptype ON ((pcm.package_type_id = ptype.package_type_id)))
     LEFT JOIN public.t_order_details od ON ((pcm.order_detail_id = od.order_details_id)))
     LEFT JOIN public.t_order_master om ON ((od.order_id = om.order_id)))
     LEFT JOIN service.m_service_master smtest ON ((od.service_id = smtest.service_master_id)))
     LEFT JOIN doctor.m_sub_speciality_master ssp ON ((smtest.sub_speciality_id = ssp.sub_speciality_id)))
     LEFT JOIN lab.t_lab_sample_master samplemaster ON ((om.order_id = samplemaster.order_id)))
     JOIN lab.t_lab_sample_dtls labsampledetails ON ((samplemaster.lab_sample_id = labsampledetails.lab_sample_id)))
     LEFT JOIN lab.m_test_master testmaster ON ((labsampledetails.test_id = testmaster.test_id)))
     LEFT JOIN doctor.m_sub_speciality_master labsubdept ON ((labsampledetails.sub_dept_id = labsubdept.sub_speciality_id)))
     LEFT JOIN public.unitinformation um ON ((pcm.unit_id = um.unit_id)));


