CREATE VIEW public.patient_ledger AS
 SELECT 1 AS rno,
    'Appointment'::text AS lebel,
    am.patient_id,
    (am.token_number)::character varying AS receiptno,
    am.appointment_date AS trdate,
    0 AS amount,
    am.unit_id
   FROM opd.m_appointment_master am
UNION
 SELECT 2 AS rno,
    'Encounter'::text AS lebel,
    em.patient_id,
    em.encounter_number AS receiptno,
    em.encounter_date AS trdate,
    0 AS amount,
    em.unit_id
   FROM opd.t_encounter_master em
UNION
 SELECT 3 AS rno,
    'Deposit'::text AS lebel,
    dm.patient_id,
    dm.deposit_no AS receiptno,
    dm.deposit_date AS trdate,
    dm.deposit_amount AS amount,
    dm.unit_id
   FROM billing.m_deposit_master dm
UNION
 SELECT 4 AS rno,
    'OPBILL'::text AS lebel,
    bm.patient_id,
    bm.bill_number AS receiptno,
    bm.bill_date_time AS trdate,
    bm.net_amount AS amount,
    bm.unit_id
   FROM billing.m_billing_master bm
  WHERE ((bm.is_dr_note = 'N'::bpchar) AND (bm.visit_type_id = 1))
UNION
 SELECT 5 AS rno,
    'IPBILL'::text AS lebel,
    bm.patient_id,
    bm.bill_number AS receiptno,
    bm.bill_date_time AS trdate,
    bm.net_amount AS amount,
    bm.unit_id
   FROM billing.m_billing_master bm
  WHERE ((bm.is_dr_note = 'N'::bpchar) AND (bm.visit_type_id = 2))
UNION
 SELECT 6 AS rno,
    'Credit Note'::text AS lebel,
    bm.patient_id,
    crnote.credit_note_no AS receiptno,
    crnote.credit_note_date AS trdate,
    crnote.cr_net_amount AS amount,
    crnote.unit_id
   FROM (billing.m_credit_note_master crnote
     JOIN billing.m_billing_master bm ON ((crnote.bill_id = bm.billing_master_id)))
UNION
 SELECT 7 AS rno,
    'Debit Note'::text AS lebel,
    bm.patient_id,
    bm.bill_number AS receiptno,
    bm.bill_date_time AS trdate,
    bm.net_amount AS amount,
    bm.unit_id
   FROM billing.m_billing_master bm
  WHERE ((bm.billing_master_id IN ( SELECT bm_1.billing_master_id
           FROM billing.m_billing_master bm_1)) AND (bm.is_dr_note = 'Y'::bpchar))
UNION
 SELECT 8 AS rno,
    'Payments'::text AS lebel,
    bm.patient_id,
    prm.reciept_number AS receiptno,
    prm.date_of_reciept AS trdate,
    prm.amount,
    prm.unit_id
   FROM (billing.t_payment_reciept_master prm
     JOIN billing.m_billing_master bm ON ((prm.billing_master_id = bm.billing_master_id)))
UNION
 SELECT 9 AS rno,
    'Sales'::text AS lebel,
    sales.patient_id,
    sales.bill_no AS receiptno,
    sales.added_date AS trdate,
    sales.net_amount AS amount,
    sales.unit_id
   FROM pharmacy.t_sale sales
UNION
 SELECT 10 AS rno,
    'Sales Return'::text AS lebel,
    sales.patient_id,
    rn.return_no AS receiptno,
    rn.added_date AS trdate,
    rn.total_return_amt AS amount,
    rn.unit_id
   FROM (pharmacy.t_return rn
     JOIN pharmacy.t_sale sales ON ((rn.sale_id = sales.id)))
  ORDER BY 1, 5;


