--

CREATE VIEW public.patientadvancereport AS
 SELECT DISTINCT um.unit_name,
    um.unit_address,
    um.registration_number,
    um.unit_contact,
    um.unit_contact_2,
    um.unit_country_code,
    um.currency_name,
    um.sub_currency,
    pr.patient_id,
    pr.uhid_number,
    dep.admission_id,
    (((((pr.first_name)::text || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS patientname,
    (dep.deposit_date)::date AS date,
    dep.deposit_master_id AS depositid,
    dep.org_id AS orgid,
    dep.unit_id AS unitid,
    userm.user_id,
    userm.user_name,
    dep.visit_type_id,
    public.advamount(dep.deposit_master_id, 1) AS cash,
    public.advamount(dep.deposit_master_id, 2) AS cheque,
    public.advamount(dep.deposit_master_id, 3) AS credit_card,
    public.advamount(dep.deposit_master_id, 4) AS debit_card,
    counter.counter_desc,
        CASE
            WHEN (dep.visit_type_id = 1) THEN 'Encoungter'::text
            ELSE 'Active'::text
        END AS diposittype,
    um.unit_address_2,
    public.advamount(dep.deposit_master_id, 6) AS loyalty_card,
    public.advamount(dep.deposit_master_id, 5) AS mpesa,
    public.advamount(dep.deposit_master_id, 8) AS etransfer,
    0 AS payment_mode_id,
    dep.deposit_no,
    um.image
   FROM ((((((patient.t_patient_registration pr
     LEFT JOIN billing.m_deposit_master dep ON ((pr.patient_id = dep.patient_id)))
     JOIN billing.t_payment_deposit_details depdt ON ((depdt.deposit_id = dep.deposit_master_id)))
     LEFT JOIN public.m_payment_mode_master pmode ON ((pmode.payment_mode_id = depdt.payment_mode_id)))
     LEFT JOIN public.unitinformation um ON ((um.unit_id = dep.unit_id)))
     LEFT JOIN public.m_user_master userm ON ((dep.created_by = userm.user_id)))
     LEFT JOIN public.m_counter_master counter ON ((dep.counter_id = counter.counter_id)));


