CREATE VIEW public.patientwisewiselabservice AS
 SELECT DISTINCT m_billing_master.billing_master_id,
    pim.uhid_number,
    t_encounter_master.encounter_number,
    t_encounter_master.encounter_date,
    m_billing_master.bill_number,
    m_billing_master.bill_date_time,
    concat('Dr.', m_doctor_master.first_name, ' ', m_doctor_master.last_name) AS doctorname,
    m_billing_master.total_bill_amount,
    m_billing_master.discount_amount,
    m_billing_master.net_amount,
    sm.service_standard_name,
    sm.service_master_id,
    m_doctor_master.doctor_id,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.image,
    bd.net_amt,
    bd.gross_amount,
    bd.discount,
    pim.ageyear,
    pim.gender_name,
    pim.patientname,
    pim.patientmobile,
    concat(emp.first_name, ' ', emp.last_name) AS empname,
    pim.patient_id,
    sm.speciality_id
   FROM ((((((((billing.m_billing_master
     JOIN billing.t_billing_details bd ON ((m_billing_master.billing_master_id = bd.billing_master_id)))
     JOIN opd.t_encounter_master ON ((m_billing_master.encounter_id = t_encounter_master.encounter_id)))
     LEFT JOIN doctor.m_doctor_master ON ((m_doctor_master.doctor_id = t_encounter_master.doctor_id)))
     JOIN service.m_service_master sm ON ((sm.service_master_id = bd.service_id)))
     JOIN public.m_unit_master unitinformation ON ((m_billing_master.unit_id = unitinformation.unit_id)))
     JOIN public.patientinformation pim ON ((m_billing_master.patient_id = pim.patient_id)))
     JOIN public.m_user_master um ON ((t_encounter_master.created_by = um.user_id)))
     LEFT JOIN public.m_employee_master emp ON ((um.user_id = emp.user_id)))
  WHERE ((m_billing_master.visit_type_id = 1) AND (m_billing_master.bill_status_id = 3) AND (m_billing_master.bill_cancelled = 'N'::bpchar));


