CREATE VIEW public.pl_deposit AS
 SELECT 3 AS rno,
    'Deposit'::text AS lebel,
    dm.patient_id,
    dm.deposit_no AS receiptno,
    dm.deposit_date AS trdate,
    dm.unit_id,
    cm.company_desc,
    deposittype.deposite_type_desc,
    dm.deposit_amount,
    dm.available_deposit,
    dm.consumed_deposit,
    dm.remarks,
    paymode.payment_mode_desc,
    depositpay.amount,
    bank.bank_desc,
    depositpay.account_number,
    depositpay.cheque_date,
    depositpay.cheque_number,
    depositpay.card_no,
    depositpay.card_holder_name,
    depositpay.expiry_date,
    cardtype.card_type_name,
    dm.refund_amount
   FROM (((((((billing.m_deposit_master dm
     LEFT JOIN public.m_visit_type_master visittype ON ((dm.visit_type_id = visittype.visit_type_id)))
     LEFT JOIN public.t_company_master cm ON ((dm.payee_id = cm.company_id)))
     LEFT JOIN billing.m_deposite_type_master deposittype ON ((dm.deposit_type_id = deposittype.deposite_type_id)))
     JOIN billing.t_payment_deposit_details depositpay ON ((dm.deposit_master_id = depositpay.deposit_id)))
     LEFT JOIN public.m_payment_mode_master paymode ON ((depositpay.payment_mode_id = paymode.payment_mode_id)))
     LEFT JOIN billing.m_bank_master bank ON ((depositpay.bank_id = bank.bank_id)))
     LEFT JOIN billing.m_card_type_master cardtype ON ((depositpay.card_type_id = cardtype.card_type_id)));


