CREATE VIEW public.pl_payments AS
 SELECT 8 AS rno,
    'Payments'::text AS lebel,
    bm.patient_id,
    prm.reciept_number AS receiptno,
    prm.date_of_reciept AS trdate,
    prm.amount,
    prm.unit_id,
    prm.receipt_type,
    prm.received_from,
    prm.remark,
    prm.status AS payment_status,
    prm.created_date AS payment_created_date,
    bm.bill_number,
    bm.bill_date_time,
    bm.net_amount,
    bm.discount_amount,
    bm.created_date,
    bm.concession_amount,
    bm.gst,
    bm.total_bill_amount,
    bm.settlement_date,
    bm.bill_cancelled,
    bm.bill_cancel_reason_id,
    bm.bill_cancel_datetime,
    bm.bill_cancel_by,
    bm.bill_cancel_remark,
    bm.is_interim_or_final_bill,
    m_payment_mode_master.payment_mode_desc,
    prd.payment_mode_id,
    prd.amount AS paymentamount,
    m_bank_master.bank_name,
    prd.check_number,
    prd.cheque_date,
    prd.card_holder_name,
    prd.date_of_transaction,
    prd.card_number,
    prd.expiry_date,
    m_visit_type_master.visit_type_name,
    prd.transaction_no,
    prm.payment_reciept_id
   FROM (((((billing.t_payment_reciept_master prm
     JOIN billing.t_payment_reciept_details prd ON ((prm.payment_reciept_id = prd.payment_receipt_master_id)))
     JOIN billing.m_billing_master bm ON ((prm.billing_master_id = bm.billing_master_id)))
     LEFT JOIN public.m_payment_mode_master ON ((prd.payment_mode_id = m_payment_mode_master.payment_mode_id)))
     LEFT JOIN billing.m_bank_master ON ((prd.bank_id = m_bank_master.bank_id)))
     LEFT JOIN public.m_visit_type_master ON ((bm.visit_type_id = m_visit_type_master.visit_type_id)))
  WHERE (prd.payment_mode_id <> 10);


