    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    dm.registration_number,
    pinfo.patient_id,
    um.unit_address_2,
    pres.id,
    pres.prescription_no,
    pres.prescription_date
   FROM ((((((((((((pharmacy.t_prescription pres
     JOIN pharmacy.t_prescription_detail presdtl ON ((presdtl.prescription_id = pres.id)))
     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON ((prefredtl.prescription_detail_id = presdtl.id)))
     JOIN public.m_strength_unit su ON ((prefredtl.dose_unit_id = su.id)))
     JOIN public.m_item itm ON ((itm.id = presdtl.item_id)))
     JOIN public.m_route_of_administration roa ON ((roa.id = prefredtl.route_id)))
     JOIN public.m_generic gen ON ((itm.generic_id = gen.id)))
     JOIN public.m_frequency freq ON ((freq.id = prefredtl.frequency_id)))
     LEFT JOIN public.m_instruction instr ON ((instr.instruction_id = presdtl.instruction_id)))
     JOIN patient.patientinformation pinfo ON ((pinfo.patient_id = pres.patient_id)))
     JOIN opd.t_encounter_master em ON ((em.encounter_id = pres.encounter_id)))
     JOIN public.m_unit_master um ON ((um.unit_id = pres.unit_id)))
     JOIN doctor.m_doctor_master dm ON ((dm.doctor_id = pres.doctor_id)))
  WHERE (pres.is_medication_stop = 'N'::bpchar)
UNION
 SELECT DISTINCT 0 AS srno,
    pinfo.patientname,
    pinfo.age,
    pinfo.gender_name,
    pinfo.uhid_number,
    em.admission_number AS visitnumber,
    em.created_date AS visitdate,
    um.unit_id,
