--

CREATE VIEW public.radiologyreport AS
 SELECT template.template_transaction_id,
    template.created_date,
    template.created_by,
    template.encounter_id,
    template.patient_id,
    template.template_object,
    patientinformation.uhid_number,
    patientinformation.patientname,
    patientinformation.gender_name,
    patientinformation.age,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_website,
    (((doctormaster.first_name)::text || ' '::text) || (doctormaster.last_name)::text) AS doctorname,
    doctormaster.doctor_id,
    (((m_employee_master.first_name)::text || ' '::text) || (m_employee_master.last_name)::text) AS username,
    m_user_master.user_id,
    servicemaster.service_standard_name,
    m_user_master.user_name
   FROM ((((((((public.t_template_transaction template
     JOIN public.patientinformation ON ((template.patient_id = patientinformation.patient_id)))
     LEFT JOIN public.unitinformation ON ((template.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.m_user_master ON ((m_user_master.user_id = template.created_by)))
     LEFT JOIN public.m_employee_master ON ((m_employee_master.user_id = m_user_master.user_id)))
     JOIN public.t_order_details orderdetail ON ((template.order_details_id = orderdetail.order_details_id)))
     JOIN public.t_order_master ordermaster ON ((orderdetail.order_id = ordermaster.order_id)))
     LEFT JOIN doctor.m_doctor_master doctormaster ON ((ordermaster.ord_doctor_id = doctormaster.doctor_id)))
     JOIN service.m_service_master servicemaster ON ((orderdetail.service_id = servicemaster.service_master_id)));


