--

CREATE VIEW public.refferaldoctorshare AS
 SELECT share.doctor_share_id,
    share.bill_dtl_id,
    share.ord_dtl_id,
    share.service_id,
    share.total_amount,
    share.concession,
    share.discount,
    share.tax_amt,
    share.net_amount,
    share.share_per,
    share.due_share_amt,
    share.hosp_share,
    share.doc_share,
    share.doc_id,
    ''::text AS alise_name,
    bm.bill_number,
    sm.service_standard_name,
    share.visit_type_id,
    ((((prefix.prefix_desc || ' '::text) || (registration.first_name)::text) || ' '::text) || (registration.last_name)::text) AS patientname,
    share.processed_share_date,
    registration.uhid_number,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_id,
    sm.service_master_id,
    em.encounter_number AS op_ip_number,
    m_refferel.referral_name AS doctorname,
    bm.bill_status_id,
    ssp.sub_speciality_name,
    bm.bill_date_time,
    ssp.sub_speciality_id,
    m_refferel.referral_id,
    bm.billing_master_id,
    sp.speciality_id,
    ssp.refdocper
   FROM ((((((((((((billing.t_doctor_share share
     JOIN public.t_referal_details admreff ON ((share.visit_id = admreff.encounter_id)))
     JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
     JOIN billing.t_billing_details bd ON ((share.bill_dtl_id = bd.billing_details_id)))
     JOIN billing.m_billing_master bm ON ((bd.billing_master_id = bm.billing_master_id)))
     JOIN service.m_service_master sm ON ((share.service_id = sm.service_master_id)))
     JOIN opd.t_encounter_master em ON ((share.visit_id = em.encounter_id)))
     JOIN patient.t_patient_registration registration ON ((em.patient_id = registration.patient_id)))
     LEFT JOIN public.m_prefix_master prefix ON ((registration.prefix_id = prefix.prefix_id)))
     LEFT JOIN public.unitinformation ON ((share.org_unit_id = unitinformation.unit_id)))
     JOIN public.t_order_details od ON ((share.ord_dtl_id = od.order_details_id)))
     JOIN doctor.m_speciality_master sp ON ((sm.speciality_id = sp.speciality_id)))
     JOIN doctor.m_sub_speciality_master ssp ON ((sm.sub_speciality_id = ssp.sub_speciality_id)));


--
-- TOC entry 3520 (class 1259 OID 3695324)
-- Name: refferaldoctorsharebills; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.refferaldoctorsharebills AS
 SELECT DISTINCT bm.billing_master_id AS doctor_share_id,
    bd.billing_details_id AS bill_dtl_id,
    od.order_details_id AS ord_dtl_id,
    bd.service_id,
    bd.gross_amount AS total_amount,
    bd.concession,
    bd.discount,
    bd.tax_amount AS tax_amt,
    bd.net_amt AS net_amount,
    0 AS share_per,
    0 AS due_share_amt,
    0 AS hosp_share,
    od.ref_doc_share_per AS doc_share,
    od.ord_doc_id AS doc_id,
    ''::text AS alise_name,
    bm.bill_number,
    sm.service_standard_name,
    em.visit_type_id,
    concat(registration.first_name, ' ', registration.last_name) AS patientname,
    od.created_date AS processed_share_date,
    registration.uhid_number,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_id,
    sm.service_master_id,
    em.encounter_number AS op_ip_number,
    concat(m_refferel.referral_name) AS doctorname,
    bm.bill_status_id,
    ssp.sub_speciality_name,
    bm.bill_date_time,
    ssp.sub_speciality_id,
    m_refferel.referral_id,
    bm.billing_master_id,
    sp.speciality_id,
    ssp.refdocper,
    mapperd.ref_share_per AS refsharedocper,
    mapperd.unit_id AS unit_idd,
    bm.unit_id AS unit_idb,
    payment.amount AS paidamount,
    bm.outstanding
   FROM ((((((((((((((billing.m_billing_master bm
     JOIN opd.t_encounter_master em ON ((bm.encounter_id = em.encounter_id)))
     JOIN public.t_referal_details admreff ON ((em.encounter_id = admreff.encounter_id)))
     JOIN adt.m_referral_master m_refferel ON ((admreff.referral_id = m_refferel.referral_id)))
     JOIN billing.t_billing_details bd ON ((bm.billing_master_id = bd.billing_master_id)))
     JOIN public.t_order_details od ON ((bd.order_details_id = od.order_details_id)))
     JOIN service.m_service_master sm ON ((bd.service_id = sm.service_master_id)))
     JOIN patient.t_patient_registration registration ON ((em.patient_id = registration.patient_id)))
     LEFT JOIN public.m_prefix_master prefix ON ((registration.prefix_id = prefix.prefix_id)))
     JOIN public.m_unit_master unitinformation ON ((bm.unit_id = unitinformation.unit_id)))
     JOIN doctor.m_speciality_master sp ON ((sm.speciality_id = sp.speciality_id)))
     JOIN doctor.m_sub_speciality_master ssp ON ((sm.sub_speciality_id = ssp.sub_speciality_id)))
     JOIN service.t_unit_service_mapper mapper ON ((bd.service_id = mapper.service_id)))
     JOIN service.t_unit_service_master_details mapperd ON ((mapper.service_id = mapperd.service_master_id)))
     LEFT JOIN ( SELECT prm.billing_master_id,
            sum(prm.amount) AS amount
           FROM (billing.t_payment_reciept_master prm
             JOIN billing.m_billing_master bm_1 ON ((prm.billing_master_id = bm_1.billing_master_id)))
          WHERE ((COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar) OR (prm.reciept_cancelled IS NULL))
          GROUP BY prm.billing_master_id) payment ON ((bm.billing_master_id = payment.billing_master_id)))
  WHERE ((bm.bill_status_id = 3) AND (od.service_rendered = 1));


