--
-- TOC entry 3312 (class 1259 OID 2983308)
-- Name: tokennumberprint; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tokennumberprint AS
 SELECT COALESCE((m_appointment_master.token_number)::text, 'Please pick a token number within an hour prior to the appointment time.'::text) AS token_number,
    m_appointment_master.appointment_date,
    m_appointment_master.arrival_time,
    unitinformation.unit_id,
    unitinformation.unit_name,
    unitinformation.unit_address,
    unitinformation.unit_address_2,
    unitinformation.unit_email_id,
    unitinformation.unit_logo,
    unitinformation.post_code,
    unitinformation.unit_contact,
    unitinformation.unit_contact_2,
    unitinformation.unit_contact_3,
    unitinformation.unit_country_code,
    unitinformation.registration_number,
    unitinformation.unit_website,
    unitinformation.currency_name,
    unitinformation.sub_currency,
    m_appointment_master.appointment_id
   FROM (opd.m_appointment_master
     JOIN public.unitinformation ON ((m_appointment_master.unit_id = unitinformation.unit_id)))
  ORDER BY m_appointment_master.appointment_id DESC;


