--
-- TOC entry 3321 (class 1259 OID 2983340)
-- Name: v_transation_log; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_transation_log AS
 SELECT 'Billing'::text AS transtype,
    bm.bill_number AS transno,
    bm.created_date,
    (bm.created_date)::date AS crdate,
    um.user_id AS createduserid,
    um.user_name AS createdusername,
    bm.updated_date,
    (bm.updated_date)::date AS udate,
    uum.user_id AS updateduserid,
    uum.user_name AS updatedusername
   FROM ((billing.m_billing_master bm
     LEFT JOIN public.m_user_master um ON ((um.user_id = bm.created_by)))
     LEFT JOIN public.m_user_master uum ON ((uum.user_id = bm.updated_by)))
UNION
 SELECT 'CreditNote'::text AS transtype,
    cm.credit_note_no AS transno,
    cm.created_date,
    (cm.created_date)::date AS crdate,
    um.user_id AS createduserid,
    um.user_name AS createdusername,
    cm.updated_date,
    (cm.updated_date)::date AS udate,
    uum.user_id AS updateduserid,
    uum.user_name AS updatedusername
   FROM ((billing.m_credit_note_master cm
     LEFT JOIN public.m_user_master um ON ((um.user_id = cm.created_by)))
     LEFT JOIN public.m_user_master uum ON ((uum.user_id = cm.updated_by)))
UNION
 SELECT 'Deposit'::text AS transtype,
    depo.deposit_no AS transno,
    depo.created_date,
    (depo.created_date)::date AS crdate,
    um.user_id AS createduserid,
    um.user_name AS createdusername,
    depo.updated_date,
    (depo.updated_date)::date AS udate,
    uum.user_id AS updateduserid,
    uum.user_name AS updatedusername
   FROM ((billing.m_deposit_master depo
     LEFT JOIN public.m_user_master um ON ((um.user_id = depo.created_by)))
     LEFT JOIN public.m_user_master uum ON ((uum.user_id = depo.updated_by)))
UNION
 SELECT 'Refund'::text AS transtype,
    refund.payment_refund_voucher_no AS transno,
    refund.created_date,
    (refund.created_date)::date AS crdate,
    um.user_id AS createduserid,
    um.user_name AS createdusername,
    refund.updated_date,
    (refund.updated_date)::date AS udate,
    uum.user_id AS updateduserid,
    uum.user_name AS updatedusername
   FROM ((billing.t_payment_refund_master refund
     LEFT JOIN public.m_user_master um ON ((um.user_id = refund.created_by)))
     LEFT JOIN public.m_user_master uum ON ((uum.user_id = refund.updated_by)));


--
-- TOC entry 3683 (class 1259 OID 4203605)
-- Name: vaccination_master_chart; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vaccination_master_chart AS
 SELECT DISTINCT mapper.remarks,
    mapper.planned_date,
    mapper.actual_date,
    mapper.location,
    mapper.calculated_date,
    vmaster.abbreviation,
    patientinformation.age,
    vmaster.max_age,
    vmaster.min_age,
    vmaster.max_day,
    vmaster.min_day,
    m_generic.name AS generic,
    site.site_name,
    concat(vmaster.dose_id, '', dose.unit) AS dose_desc,
    m_item.name AS itemname,
    route.description AS route,
    unitinformation.unit_name,
    unitinformation.unit_address,
    patientinformation.uhid_number,
    patientinformation.patientname,
    patientinformation.gender_name,
    patientinformation.patientdob,
    patientinformation.patientmobile,
    vmaster.uom_id,
    mapper.patient_id,
    mapper.vaccine_immunization_mapper_id,
    unitinformation.image
   FROM ((((((((opd.t_vaccine_immunization_mapper mapper
     LEFT JOIN lab.m_vaccination_master vmaster ON ((mapper.vaccination_id = vmaster.vaccination_id)))
     LEFT JOIN public.m_generic ON ((m_generic.id = vmaster.generic_id)))
     LEFT JOIN public.m_site_of_admininstration site ON ((vmaster.site_id = site.site_id)))
     LEFT JOIN public.m_strength_unit dose ON ((vmaster.uom_id = dose.id)))
     LEFT JOIN public.m_item ON ((vmaster.vaccine_code = m_item.id)))
     LEFT JOIN public.m_route_of_administration route ON ((vmaster.administration_id = route.id)))
     LEFT JOIN public.unitinformation ON ((mapper.unit_id = unitinformation.unit_id)))
     LEFT JOIN public.patientinformation ON ((mapper.patient_id = patientinformation.patient_id)))
  WHERE (m_item.is_vaccin = true);


--
-- TOC entry 3685 (class 1259 OID 4245687)
-- Name: view_index; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_index AS
 SELECT n.nspname AS schema,
    t.relname AS "table",
    c.relname AS index,
    pg_get_indexdef(i.indexrelid) AS def
   FROM (((pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     JOIN pg_index i ON ((i.indexrelid = c.oid)))
     JOIN pg_class t ON ((i.indrelid = t.oid)))
  WHERE ((c.relkind = 'i'::"char") AND (n.nspname <> ALL (ARRAY['pg_catalog'::name, 'pg_toast'::name])) AND pg_table_is_visible(c.oid))
  ORDER BY n.nspname, t.relname, c.relname;


--
-- TOC entry 3322 (class 1259 OID 2983345)
-- Name: vw_labinvestprescrition; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_labinvestprescrition AS
 SELECT pr.patient_id,
    pr.uhid_number,
    (((((pr.first_name)::text || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS fullname,
    pim.age,
    um.unit_address,
    um.unit_logo,
    em.encounter_number AS visitno,
    em.encounter_date AS visitdate,
    am.allergy_desc,
    um.unit_id,
    um.organization_id,
    em.encounter_id,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    dm.registration_number
   FROM ((((((patient.t_patient_registration pr
     JOIN opd.t_encounter_master em ON ((pr.patient_id = em.patient_id)))
     JOIN public.m_unit_master um ON ((pr.unit_id = um.unit_id)))
     JOIN patient.t_allergy_patient_mapper pam ON ((pr.patient_id = pam.patient_id)))
     JOIN emr.m_allergy_master am ON ((pam.allergy_id = am.allergy_id)))
     JOIN patient.patientinformation pim ON ((pr.patient_id = pim.patient_id)))
     JOIN doctor.m_doctor_master dm ON ((em.doctor_id = dm.doctor_id)));


--
-- TOC entry 3323 (class 1259 OID 2983350)
-- Name: vw_newprescriptioncasesheet; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_newprescriptioncasesheet AS
 SELECT row_number() OVER (PARTITION BY pr.patient_id ORDER BY im.name) AS srno,
    pr.patient_id,
    pr.uhid_number,
    (((((pr.first_name)::text || ' '::text) || (pr.middle_name)::text) || ' '::text) || (pr.last_name)::text) AS fullname,
    pim.age,
    um.unit_address,
    um.unit_logo,
    em.encounter_number AS visitno,
    em.encounter_date AS visitdate,
    um.unit_id,
    um.organization_id,
    em.encounter_id,
    (((((dm.first_name)::text || ' '::text) || (dm.middle_name)::text) || ' '::text) || (dm.last_name)::text) AS doctorname,
    dm.registration_number,
    upper((im.name)::text) AS brandname,
    upper((gn.name)::text) AS genric,
    pfd.dose,
    stu.unit,
    pfd.start_date,
    pfd.stop_date,
    pfd.instructions,
    upper((fry.description)::text) AS frequency,
    pd.order_qty AS qty
   FROM (((((((((((patient.t_patient_registration pr
     JOIN opd.t_encounter_master em ON ((pr.patient_id = em.patient_id)))
     JOIN public.m_unit_master um ON ((pr.unit_id = um.unit_id)))
     JOIN patient.patientinformation pim ON ((pr.patient_id = pim.patient_id)))
     JOIN doctor.m_doctor_master dm ON ((em.doctor_id = dm.doctor_id)))
     JOIN pharmacy.t_prescription pres ON ((pres.encounter_id = em.encounter_id)))
     LEFT JOIN pharmacy.t_prescription_detail pd ON ((pres.id = pd.prescription_id)))
     JOIN public.m_item im ON ((pd.item_id = im.id)))
     JOIN public.m_generic gn ON ((im.generic_id = gn.id)))
     JOIN pharmacy.t_prescription_frequency_detail pfd ON ((pd.prescription_id = pfd.prescription_detail_id)))
     JOIN public.m_frequency fry ON ((pfd.frequency_id = fry.id)))
     LEFT JOIN public.m_strength_unit stu ON ((pfd.dose_unit_id = stu.id)));


