   FROM ((((patient.t_patient_registration pr
     JOIN opd.t_encounter_master em ON ((pr.patient_id = em.patient_id)))
     JOIN patient.t_allergy_patient_mapper pam ON ((em.encounter_id = pam.encounter_id)))
     LEFT JOIN emr.m_allergy_master am ON ((pam.allergy_id = am.allergy_id)))
     LEFT JOIN public.m_generic ON ((pam.generic_id = m_generic.id)));


