-- Name: get_departmentwise_revenue_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.get_departmentwise_revenue_summary AS
 SELECT DISTINCT billmst.unit_id,
    u.unit_name,
    u.unit_address,
    u.unit_contact,
        CASE
            WHEN (emm.dept_id <> 0) THEN smopd.speciality_name
            ELSE smipd.speciality_name
        END AS speciality_name,
        CASE
            WHEN (emm.dept_id <> 0) THEN smopd.speciality_id
            ELSE smipd.speciality_id
        END AS speciality_id,
    sum(prd.amount) AS net_amt,
    prm.date_of_reciept,
    u.image
   FROM (((((((((billing.m_billing_master billmst
     LEFT JOIN billing.t_billing_details billdtls ON ((billmst.billing_master_id = billdtls.billing_master_id)))
     LEFT JOIN service.m_service_master servmst ON ((servmst.service_master_id = billdtls.service_id)))
     LEFT JOIN public.unitinformation u ON ((billmst.unit_id = u.unit_id)))
     JOIN billing.t_payment_reciept_master prm ON ((billmst.billing_master_id = prm.billing_master_id)))
     JOIN billing.t_payment_reciept_details prd ON ((prm.payment_reciept_id = prd.payment_receipt_master_id)))
     LEFT JOIN opd.t_encounter_master emm ON ((billmst.encounter_id = emm.encounter_id)))
     LEFT JOIN adt.t_admission ON ((billmst.admission_id = t_admission.admission_id)))
     LEFT JOIN doctor.m_speciality_master smopd ON ((smopd.speciality_id = emm.dept_id)))
     LEFT JOIN doctor.m_speciality_master smipd ON ((smipd.speciality_id = t_admission.speciality_id)))
  WHERE (billmst.bill_status_id = ANY (ARRAY[3, 2]))
  GROUP BY billmst.unit_id, u.unit_name, u.unit_address, u.unit_contact, prm.date_of_reciept, smipd.speciality_name, smipd.speciality_id, smopd.speciality_id, emm.dept_id, u.image
UNION
 SELECT billdeposit.unit_id,
    u.unit_name,
    u.unit_address,
    u.unit_contact,
    'Deposit'::text AS speciality_name,
    0 AS speciality_id,
    sum(billdeposit.deposit_amount) AS net_amt,
    billdeposit.created_date AS date_of_reciept,
    u.image
   FROM (((billing.m_deposit_master billdeposit
     JOIN patient.t_patient_registration pr ON ((billdeposit.patient_id = pr.patient_id)))
     LEFT JOIN public.unitinformation u ON ((billdeposit.unit_id = u.unit_id)))
     LEFT JOIN public.m_employee_master em ON ((billdeposit.created_by = em.user_id)))
  GROUP BY billdeposit.unit_id, u.unit_name, u.unit_address, u.unit_contact, billdeposit.created_date, u.image;


