     JOIN public.t_order_details od ON (((billdtls.order_details_id = od.order_details_id) AND (od.package_consumption_amt = (0)::numeric) AND (od.status = 'A'::bpchar))))
     LEFT JOIN adt.m_bed_master mbm ON ((od.bed_id = mbm.bed_id)))
     LEFT JOIN billing.m_billing_status_master billstatusmaster ON ((billmst.bill_status_id = billstatusmaster.bill_status_id)))
     LEFT JOIN adt.m_bed_category_master mbcm ON ((mbm.bed_category_id = mbcm.bed_category_id)))
